export const ABILITY_TRANSLATIONS_EN: Record<string, string> = {
  'Fuerza o Destreza': 'Strength or Dexterity',
  'Fuerza y Carisma': 'Strength & Charisma',
  'Destreza y Sabiduría': 'Dexterity & Wisdom',
  'Fuerza': 'Strength',
  'Destreza': 'Dexterity',
  'Constitución': 'Constitution',
  'Inteligencia': 'Intelligence',
  'Sabiduría': 'Wisdom',
  'Carisma': 'Charisma',
  'int': 'Intelligence',
  'wis': 'Wisdom',
  'cha': 'Charisma',
  'str': 'Strength',
  'dex': 'Dexterity',
  'con': 'Constitution',
  'FUE': 'STR',
  'DES': 'DEX',
  'CON': 'CON',
  'INT': 'INT',
  'SAB': 'WIS',
  'CAR': 'CHA',
  'Elección': 'Choice',
};

export function translateAbilityText(text: string): string {
  if (!text) return '';
  if (ABILITY_TRANSLATIONS_EN[text]) return ABILITY_TRANSLATIONS_EN[text];
  let out = text;
  const pairs: [string, string][] = [
    ['Fuerza o Destreza', 'Strength or Dexterity'],
    ['Fuerza y Carisma', 'Strength & Charisma'],
    ['Destreza y Sabiduría', 'Dexterity & Wisdom'],
    ['Fuerza', 'Strength'],
    ['Destreza', 'Dexterity'],
    ['Constitución', 'Constitution'],
    ['Inteligencia', 'Intelligence'],
    ['Sabiduría', 'Wisdom'],
    ['Carisma', 'Charisma'],
  ];
  for (const [es, en] of pairs) {
    out = out.replaceAll(es, en);
  }
  return out;
}

export const PROFICIENCY_TRANSLATIONS_EN: Record<string, string> = {
  'Ninguna': 'None',
  'Armaduras ligeras': 'Light armor',
  'Armaduras medias': 'Medium armor',
  'Armaduras pesadas': 'Heavy armor',
  'Todas las armaduras': 'All armor',
  'Escudos': 'Shields',
  'Armaduras ligeras, Armaduras medias, Escudos (no de metal)': 'Light & Medium armor, Shields (nonmetal)',
  'Armas simples': 'Simple weapons',
  'Armas marciales': 'Martial weapons',
  'Dagas': 'Daggers',
  'Dardos': 'Darts',
  'Hondas': 'Slings',
  'Bastones': 'Quarterstaffs',
  'Ballestas ligeras': 'Light crossbows',
  'Ballestas de mano': 'Hand crossbows',
  'Espadas largas': 'Longswords',
  'Espadas cortas': 'Shortswords',
  'Estoques': 'Rapiers',
  'Cimitarras': 'Scimitars',
  'Clavas': 'Clubs',
  'Hachas de mano': 'Handaxes',
  'Jabalinas': 'Javelins',
  'Mazas': 'Maces',
  ' hoces': 'Sickles',
  'Hoces': 'Sickles',
  'Lanzas': 'Spears',
  'Armas improvisadas': 'Improvised weapons',
  'Armas de fuego (opcional)': 'Firearms (optional)',
};

export function translateProficiencyText(text: string): string {
  if (!text) return 'None';
  if (PROFICIENCY_TRANSLATIONS_EN[text]) return PROFICIENCY_TRANSLATIONS_EN[text];
  let out = text;
  for (const [es, en] of Object.entries(PROFICIENCY_TRANSLATIONS_EN)) {
    out = out.replaceAll(es, en);
  }
  out = out
    .replace(/no de metal/gi, 'nonmetal')
    .replace(/espadas cortas/gi, 'shortswords')
    .replace(/espadas largas/gi, 'longswords')
    .replace(/ballestas de mano/gi, 'hand crossbows')
    .replace(/estoques/gi, 'rapiers')
    .replace(/armas simples/gi, 'simple weapons')
    .replace(/armas marciales/gi, 'martial weapons')
    .replace(/armaduras ligeras/gi, 'light armor')
    .replace(/armaduras medias/gi, 'medium armor')
    .replace(/armaduras pesadas/gi, 'heavy armor')
    .replace(/escudos/gi, 'shields');
  return out;
}

