export function translateTableColumnLabel(label: string): string {
  return TABLE_COLUMN_LABELS_EN[label] || translateDndTitle(label);
}

export function translateTableSpecificValue(val: string | number): string {
  const s = String(val);
  return s
    .replace(/conjuros/gi, 'spells')
    .replace(/Ilimitada/gi, 'Unlimited')
    .replace(/Ilimitado/gi, 'Unlimited')
    .replace(/usos/gi, 'uses')
    .replace(/uso/gi, 'use')
    .replace(/pies/gi, 'ft.')
    .replace(/VD /g, 'CR ')
    .replace(/\(nadar\)/gi, '(swim)')
    .replace(/\(volar\)/gi, '(fly)')
    .replace(/^1\.º$/, '1st')
    .replace(/^2\.º$/, '2nd')
    .replace(/^3\.º$/, '3rd')
    .replace(/^4\.º$/, '4th')
    .replace(/^5\.º$/, '5th');
}

