export function translateProgressionFeature(featStr: string): string {
  if (!featStr) return '';
  if (PROGRESSION_FEATURE_MAP_EN[featStr]) return PROGRESSION_FEATURE_MAP_EN[featStr];
  if (featStr.includes(',')) {
    return featStr
      .split(',')
      .map((part) => translateProgressionFeature(part.trim()))
      .join(', ');
  }
  return translateDndTitle(featStr);
}

