const CLEAN_DIRECT_TITLE_MAP_EN = new Map<string, string>();
for (const [es, en] of Object.entries(DIRECT_TITLE_MAP_EN)) {
  const clean = es.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  CLEAN_DIRECT_TITLE_MAP_EN.set(clean, en);
}

export function translateDndTitle(title: string): string {
  if (!title) return '';
  const trimmed = title.trim();
  if (DIRECT_TITLE_MAP_EN[trimmed]) return DIRECT_TITLE_MAP_EN[trimmed];
  const cleanKey = trimmed.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  if (CLEAN_DIRECT_TITLE_MAP_EN.has(cleanKey)) return CLEAN_DIRECT_TITLE_MAP_EN.get(cleanKey)!;

  // Check pattern: "Conjuros [de X / X] de Y.º Nivel"
  const spellLvlMatch = trimmed.match(/^Conjuros(?:\s+de\s+[A-Za-záéíóúÁÉÍÓÚñÑ]+|\s+[A-Za-záéíóúÁÉÍÓÚñÑ]+)?\s+de\s+(\d+)\.(?:º|er)\s+Nivel(.*)$/i);
  if (spellLvlMatch) {
    const lvl = Number(spellLvlMatch[1]);
    const ord = lvl === 1 ? '1st' : lvl === 2 ? '2nd' : lvl === 3 ? '3rd' : `${lvl}th`;
    return `${ord}-Level Spells`;
  }
  const pactSlotMatch = trimmed.match(/^Ranuras de Pacto de (\d+)\.(?:º|er) Nivel(.*)$/i);
  if (pactSlotMatch) {
    const lvl = Number(pactSlotMatch[1]);
    const ord = lvl === 1 ? '1st' : lvl === 2 ? '2nd' : lvl === 3 ? '3rd' : `${lvl}th`;
    return `${ord}-Level Pact Magic Slots`;
  }
  const arcanumMatch = trimmed.match(/^Arcan[o|u]m? Místico \(?de? ?(?:Nivel )?(\d+)(?:\.º Nivel)?\)?$/i);
  if (arcanumMatch) {
    return `Mystic Arcanum (${arcanumMatch[1]}th level)`;
  }
  const destroyUndeadMatch = trimmed.match(/^Destruir Muertos Vivientes \(VD ([^)]+)\)$/i);
  if (destroyUndeadMatch) {
    return `Destroy Undead (CR ${destroyUndeadMatch[1]})`;
  }

  // If title has embedded English name in parentheses: e.g. "Escuela de Abjuración (School of Abjuration)" or "Furia (Rage)"
  const parenMatch = trimmed.match(/^(.+?)\s*\(([^)]+)\)$/);
  if (parenMatch) {
    const inside = parenMatch[2].trim();
    const isMetaNote = /^(Subclase|Opcional|Reemplazo|Vida|Guerra|Luz|Tempestad|Naturaleza|Conocimiento|Engaño|Forja|Tumba|Orden|Paz|Crepúsculo|Arcano|Muerte|Estándar|Clásico|Versátil|Fuego|Frío|Relámpago|Veneno|Ácido|Gema|Inteligencia|Sabiduría|Carisma|Fuerza|Destreza|Constitución|Doble|Túnicas|Monte|Mar|Historia|Matemáticas|Canino|Soldado|Acosador|\d+\s*(dado|dados|uso|usos|ataques|invocaciones|pies|ft|conjuros|puntos)|Oso|1d\d+|VD\s|Nivel\s|\d+$)/i.test(inside) || /[áéíóúñ¡¿]/i.test(inside);
    if (!isMetaNote && /[A-Za-z]/.test(inside)) {
      // Clean up " - 1 uso", " - Reemplazo", etc.
      const cleanedInside = inside
        .replace(/\s*-\s*1 uso/i, ' (1 use)')
        .replace(/\s*-\s*2 opciones/i, ' (2 options)')
        .replace(/\s*-\s*Opcional/i, ' (Optional)')
        .replace(/\s*-\s*Reemplazo/i, ' (Replacement)')
        .replace(/\s*-\s*1d6/i, ' (1d6)');
      return cleanedInside;
    }
  }

  return translateDndText(trimmed);
}

