export const EXACT_DESCRIPTION_MAP_EN: Record<string, string> = {
  "El oro y tiempo necesarios para copiar un conjuro de abjuración en tu libro de conjuros se reducen a la mitad.": "The gold and time you must spend to copy an abjuration spell into your spellbook is halved.",
  "El oro y tiempo necesarios para copiar un conjuro de conjuración se reducen a la mitad.": "The gold and time you must spend to copy a conjuration spell into your spellbook is halved.",
  "El oro y tiempo necesarios para copiar un conjuro de adivinación se reducen a la mitad.": "The gold and time you must spend to copy a divination spell into your spellbook is halved.",
  "El oro y tiempo necesarios para copiar un conjuro de encantamiento se reducen a la mitad.": "The gold and time you must spend to copy an enchantment spell into your spellbook is halved.",
  "El oro y tiempo necesarios para copiar un conjuro de evocación se reducen a la mitad.": "The gold and time you must spend to copy an evocation spell into your spellbook is halved.",
  "El oro y tiempo necesarios para copiar un conjuro de ilusión se reducen a la mitad.": "The gold and time you must spend to copy an illusion spell into your spellbook is halved.",
  "El oro y tiempo necesarios para copiar un conjuro de nigromancia se reducen a la mitad.": "The gold and time you must spend to copy a necromancy spell into your spellbook is halved.",
  "El oro y tiempo necesarios para copiar un conjuro de transmutación se reducen a la mitad.": "The gold and time you must spend to copy a transmutation spell into your spellbook is halved.",
  "Añades tu modificador de Inteligencia a tus tiradas de iniciativa.": "You add your Intelligence modifier to your initiative rolls.",
  "Especialistas supremos en magia destructiva elemental (fuego, rayo, hielo) y protección milimétrica de aliados.": "Supreme specialists in elemental destructive magic (fire, lightning, cold) and pinpoint protection of allies.",
  "Preparas Sabiduría + nivel de clérigo conjuros cada día a partir de toda la lista divina.": "You prepare Wisdom + cleric level spells each day from the entire divine list.",
  "Especialización marcial: Duelo (+2 daño a una mano), Gran Arma (repetir 1 y 2 en dados de daño a 2 manos), Defensa (+1 CA), Tiro con Arco (+2 a ataques a distancia), Protección o Combate con Dos Armas.": "Martial specialization: Dueling (+2 one-handed damage), Great Weapon Fighting (reroll 1 and 2 on two-handed damage), Defense (+1 AC), Archery (+2 to ranged attacks), Protection, or Two-Weapon Fighting.",
  "Eliges dos de tus competencias de habilidad (o una habilidad y tus herramientas de ladrón): tu bonificador de competencia se duplica para ellas.": "Choose two of your skill proficiencies (or one skill and your thieves' tools): your proficiency bonus is doubled for any ability check that uses either choice.",

  "Tus seis puntuaciones de característica aumentan en +1 cada una (+1 FUE, +1 DES, +1 CON, +1 INT, +1 SAB, +1 CAR).": "Your six ability scores each increase by +1 (+1 STR, +1 DEX, +1 CON, +1 INT, +1 WIS, +1 CHA).",
  "Puedes usar tu acción para exhalar energía destructiva elemental (2d6 daño a nivel 1, 3d6 a nivel 6, 4d6 a nivel 11, 5d6 a nivel 16). CD 8 + prof + Con. 1/descanso corto.": "You can use your action to exhale destructive elemental energy (2d6 damage at 1st level, 3d6 at 6th, 4d6 at 11th, 5d6 at 16th). DC 8 + prof + CON. 1/short rest.",
  "Veneno - Cono 15 pies (Salvación CON).": "Poison - 15-foot cone (CON save).",
  "Frío - Cono 15 pies (Salvación CON).": "Cold - 15-foot cone (CON save).",
  "Como acción adicional muerdes a un enemigo y ganas PG temporales iguales a tu Con (1/descanso corto).": "As a bonus action, you make a special bite attack against an enemy and gain temporary HP equal to your CON modifier (1/short rest).",
  "Cuando recibes daño, usas tu reacción para tirar 1d12 + Con y reducir el daño en esa cantidad (1/descanso corto o usos = bono comp).": "When you take damage, you can use your reaction to roll 1d12 + CON and reduce the damage by that total (1/short rest, or uses equal to your proficiency bonus).",
  "Puedes realizar la acción de Destrabarse o Esconderse como una acción adicional en cada uno de tus turnos.": "You can take the Disengage or Hide action as a bonus action on each of your turns.",
  "Cuando infliges daño a una criatura de un tamaño mayor que el tuyo, puedes causarle daño adicional igual a tu nivel de personaje (1 vez por descanso corto).": "When you deal damage to a creature of a size larger than yours, you can deal extra damage to it equal to your character level (once per short rest).",
  "Cuando realizas un ataque cuerpo a cuerpo durante tu turno, tu alcance para ese ataque aumenta en 5 pies.": "When you make a melee attack on your turn, your reach for it is 5 feet greater than normal.",
  "Cuentas como un tamaño Grande para determinar tu capacidad de carga y levantamiento.": "You count as one size larger (Large) when determining your carrying capacity and the weight you can push, drag, or lift.",
  "Tienes competencia en Sigilo. Si golpeas a una criatura que aún no ha actuado en el combate, infliges 2d6 daño extra.": "You have proficiency in Stealth. If you hit a creature that hasn't taken a turn yet in the combat, the attack deals an extra 2d6 damage.",
  "Cuando te mueves en tu turno de combate, puedes duplicar tu velocidad hasta el final del turno. Recuperas este rasgo al pasar 1 turno completo con velocidad 0.": "When you move on your turn in combat, you can double your speed until the end of the turn. Once you use this trait, you can't use it again until you move 0 feet on one of your turns.",
  "Tu caparazón te otorga una CA base fija de 17 (tu Destreza no la afecta). Puedes usar un escudo para aumentarla a 19.": "Your shell provides you a fixed base AC of 17 (your Dexterity modifier doesn't affect this number). You can wield a shield to increase it to 19.",
  "Puedes imitar cualquier sonido o voz que hayas escuchado con total fidelidad (Perspicacia vs Engaño).": "You can accurately mimic any sound or voice you have heard (contested by Insight vs. Deception).",
  "Como acción adicional te vuelves mágicamente invisible hasta el inicio de tu siguiente turno o hasta que ataques o lances un conjuro (1/descanso corto o usos = bono comp).": "As a bonus action, you can magically turn invisible until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw (1/short rest or uses equal to your proficiency bonus).",
  "Como acción adicional adoptas rasgos bestiales durante 1 minuto. Ganas PG temporales iguales a tu nivel + Con (1/descanso corto o usos = bono comp).": "As a bonus action, you can assume a bestial appearance for 1 minute. You gain temporary HP equal to your level + your CON modifier (1/short rest, or uses equal to your proficiency bonus).",
  "Puedes hablar telepáticamente con cualquier criatura que veas hasta 10 pies x tu nivel.": "You can speak telepathically to any creature you can see within a number of feet of you equal to 10 times your level.",
  "Como acción adicional emites un rugido: enemigos a 10 pies superan salvación de Sabiduría (CD 8 + prof + Con) o quedan Asustados (1/descanso corto).": "As a bonus action, you can let out a menacing roar: creatures of your choice within 10 feet of you must succeed on a Wisdom saving throw (DC 8 + prof + CON) or become Frightened of you until the end of your next turn (1/short rest).",
  "Eres completamente inmune a la condición de Asustado. Tienes ventaja en salvaciones contra cualquier efecto de terror sobrenatural.": "You are completely immune to the Frightened condition, and you have advantage on saving throws you make to avoid or end the frightened condition on yourself.",
  "Como acción adicional desatas una retahíla de burlas mordaces contra una criatura a 60 pies. Si falla salvación de Sabiduría, tiene desventaja en ataques contra cualquiera que no seas tú (usos = bono comp).": "As a bonus action, you can unleash a string of warding, provocative taunts at a creature within 60 feet of you. If it fails a Wisdom saving throw, it has disadvantage on attack rolls against targets other than you (uses equal to your proficiency bonus).",
  "Como acción adicional en tu turno, puedes realizar la acción de Usar un Objeto, manipular un objeto o usar herramientas simples utilizando tus pies prensiles.": "As a bonus action on your turn, you can use your prehensile feet to take the Use an Object action, manipulate a simple object, or use simple tools.",
  "Cuando caes y no estás incapacitado, puedes usar tu reacción para desplegar tus membranas patagiales y planear. Restas hasta 100 pies de la caída al calcular el daño, y puedes moverte horizontalmente 5 pies por cada 1 pie que desciendas.": "When you fall at least 10 feet and aren't incapacitated, you can use your reaction to extend your skin membranes to glide. You subtract up to 100 feet from the fall when calculating falling damage, and you can move up to 5 feet horizontally for every 1 foot you descend.",
  "Tienes ventaja en tiradas de salvación contra ser hechizado, asustado, paralizado, envenenado, aturdido o dormido mágicamente.": "You have advantage on saving throws against being charmed, frightened, paralyzed, poisoned, stunned, or magically put to sleep.",
  "La sangre oscura que corre por tus venas acelera tu regeneración. Cuando tiras un dado de golpe para recuperar puntos de golpe durante un descanso corto y obtienes un 1 o un 2, puedes relanzar el dado y debes usar el nuevo resultado.": "The dark blood coursing through your veins accelerates your recovery. When you roll a Hit Die to regain hit points during a short rest and roll a 1 or 2, you can reroll the die and must use the new roll.",
  "Tu conexión mental te alerta ante intrusiones y engaños. Tienes ventaja en todas las tiradas de salvación de Sabiduría y Carisma.": "Your mental link alerts you to intrusions and deceptions. You have advantage on all Wisdom and Charisma saving throws.",
  "Canalizan la violencia desatada en un frenesí sanguinario imparable.": "They channel unleashed violence into an unstoppable bloodthirsty frenzy.",
  "Guerreros imbuidos de fervor divino por deidades de la batalla, que canalizan su ira como castigo sagrado imparable.": "Warriors imbued with divine fervor by battle deities, channeling their rage as unstoppable sacred punishment.",
  "Llaman a los espíritus de sus ancestros guerreros para proteger a sus aliados y desviar los ataques del enemigo.": "They call upon the spirits of their warrior ancestors to protect their allies and deflect enemy attacks.",
  "Canalizan la esencia primigenia de depredadores totémicos, mutando su propia carne en garras, fauces o colas mortíferas.": "They channel the primal essence of totemic predators, mutating their own flesh into deadly claws, fangs, or tails.",
  "Imbuidos con las energías caóticas del Feywild o planos mágicos, cada estallido de furia desata fenómenos arcanos impredecibles.": "Imbued with the chaotic energies of the Feywild or magical planes, every outburst of rage unleashes unpredictable arcane phenomena.",
  "Encarnan la furia climatológica de los elementos primordiales: el calor abrasador del desierto, el rayo marino o la escarcha invernal.": "They embody the weather fury of the primordial elements: scorching desert heat, sea lightning, or winter frost.",
  "Extraen su fuerza titánica del Ordenamiento de los Gigantes, creciendo en tamaño descomunal y lanzando armas o enemigos por el campo.": "They draw titanic strength from the Ordning of the Giants, growing to massive size and hurling weapons or enemies across the battlefield.",
  "Guerreros enanos que visten pesadas armaduras cubiertas de púas de hierro afiladas y se arrojan contra sus enemigos como torbellinos de púas.": "Dwarven warriors who wear heavy armor covered in sharp iron spikes and hurl themselves at their foes like whirling dervishes of spikes.",
  "Dunamantes que doblegan los campos gravitatorios, aumentando el peso de los enemigos o haciéndolos ingrávidos.": "Dunamancers who bend gravitational fields, increasing the weight of enemies or rendering them weightless.",
  "Artífices del engaño visual, espejismos y sombras que confunden los sentidos y desafían la realidad.": "Artificers of visual deception, mirages, and shadows that confound the senses and defy reality.",
  "Dominan las energías oscuras de la vida y la muerte, drenando la vitalidad de enemigos y alzando ejércitos no muertos.": "They master the dark energies of life and death, draining the vitality of enemies and raising undead armies.",
  "Eruditos venerables que despiertan el alma viva de su libro de conjuros, transformándolo en un artefacto consciente.": "Venerable scholars who awaken the living soul of their spellbook, transforming it into a sentient artifact.",
  "Alquimistas y moldeadores de la materia capaces de alterar las propiedades físicas y biológicas del mundo.": "Alchemists and shapers of matter capable of altering the physical and biological properties of the world.",
  "Combinan principios tácticos de evocación y abjuración para dominar los campos de batalla y anular hechiceros enemigos.": "They combine tactical principles of evocation and abjuration to dominate battlefields and neutralize enemy spellcasters.",
  "Clérigos marciales bendecidos con ferocidad e impactos certeros.": "Martial clerics blessed with ferocity and unerring strikes.",
  "Canalizan el resplandor radiante del sol para cegar enemigos e incinerar tinieblas.": "They channel the radiant brilliance of the sun to blind enemies and incinerate darkness.",
  "Clérigos devotos de dioses de los herreros y artesanos como Moradin o Gond. Su piel y martillos resisten el calor más abrasador.": "Devout clerics of gods of smiths and artisans like Moradin or Gond. Their skin and hammers withstand the most scorching heat.",
  "Señores del trueno, el relámpago y las tormentas implacables como Talos o Thor, que castigan a quien ose acercarse.": "Lords of thunder, lightning, and relentless storms like Talos or Thor, who punish anyone who dares draw near.",
  "Emisarios de deidades de la astucia, el sigilo y la traición como Tymora o Loki, expertos en crear duplicados ilusorios.": "Emissaries of deities of cunning, stealth, and treachery like Tymora or Loki, experts at creating illusory duplicates.",
  "Vigilantes de la delgada línea entre la vida y la muerte, como la Reina de los Cuervos o Kelemvor. Destruyen no muertos y rescatan a los moribundos.": "Watchers of the thin line between life and death, like the Raven Queen or Kelemvor. They destroy the undead and rescue the dying.",
  "Buscadores de secretos arcanos e historia cósmica como Oghma o Boccob, capaces de dominar habilidades al instante.": "Seekers of arcane secrets and cosmic history like Oghma or Boccob, capable of mastering skills in an instant.",
  "Protectores de los bosques, bestias y elementos como Silvanus o Chauntea, uniendo la fe con la magia druídica.": "Protectors of forests, beasts, and elements like Silvanus or Chauntea, uniting faith with druidic magic.",
  "Guardianes de la penumbra y el paso entre el día y la noche como Selûne o Ilmater, que protegen a los caminantes de los horrores de la oscuridad.": "Guardians of twilight and the passage between day and night like Selûne or Ilmater, who shield travelers from the horrors of the dark.",
  "Diplomáticos y pacificadores sagrados como Eldath o Rao, capaces de forjar lazos místicos que unen el destino y la salud de sus camaradas.": "Sacred diplomats and peacemakers like Eldath or Rao, capable of forging mystic bonds that unite the fate and health of their comrades.",
  "Sacerdotes dedicados a los misterios de la Urdimbre y la magia suprema como Mystra, entrelazando magia divina y arcana.": "Priests dedicated to the mysteries of the Weave and supreme magic like Mystra, interweaving divine and arcane magic.",
  "Clérigos oscuros de deidades de la nigromancia y el fin de los días como Myrkul o Velsharoon, maestros en desgarrar la fuerza vital.": "Dark clerics of deities of necromancy and the end of days like Myrkul or Velsharoon, masters at tearing away life force.",
  "Magistrados y tiranos de la ley cósmica como Tyr o Bane, cuya voz comanda ataques aliados inmediatos y somete la anarquía.": "Magistrates and tyrants of cosmic law like Tyr or Bane, whose voice commands immediate allied attacks and subjugates anarchy.",
  "Perfecciona la potencia física pura logrando impactos críticos demoledores con mayor frecuencia.": "Perfects raw physical might, scoring devastating critical hits with greater frequency.",
  "Guerreros tácticos que controlan el campo de batalla mediante maniobras y dados de superioridad.": "Tactical warriors who control the battlefield through maneuvers and superiority dice.",
  "Combina el dominio del acero con conjuros arcanos de abjuración y evocación.": "Combines mastery of steel with arcane spells of abjuration and evocation.",
  "Guerreros que dominan la dunamancia para desgarrar las líneas temporales y manifestar ecos traslúcidos de sí mismos en combate.": "Warriors who master dunamancy to tear through timelines and manifest translucent echoes of themselves in combat.",
  "Hábiles artesanos que aprendieron el lenguaje secreto de las runas de los gigantes, grabando magia ancestral en sus armaduras y creciendo a estaturas colosales.": "Skilled artisans who learned the secret language of giant runes, inscribing ancestral magic onto their armor and growing to colossal stature.",
  "Guerreros que despiertan el poder psiónico latente de sus mentes para mover objetos, proteger aliados y propinar golpes de telequinesis.": "Warriors who awaken the latent psionic power of their minds to move objects, shield allies, and deliver telekinetic strikes.",
  "Luchadores de disciplina marcial inquebrantable, cortesía refinada y una fuerza de voluntad que desafía a la mismísima muerte.": "Fighters of unbreakable martial discipline, refined courtesy, and a willpower that defies death itself.",
  "Maestros del tiro con arco élfico que entretejen magia en cada flecha arrojada para desterrar, enredar o perforar murallas.": "Masters of elven archery who weave magic into every loosed arrow to banish, entangle, or pierce through walls.",
  "Expertos en combate montado y baluartes defensivos infalibles que marcan y bloquean a los enemigos para proteger a sus camaradas.": "Experts in mounted combat and unyielding defensive bulwarks who mark and lock down enemies to protect their comrades.",
  "Líderes inspiradores y campeones de la caballería de Cormyr que guían a sus aliados con valor inquebrantable, táctica y devoción al honor.": "Inspiring leaders and champions of Cormyr's knighthood who guide their allies with unwavering valor, tactics, and devotion to honor.",
  "Ágiles maestros de la infiltración, el hurto rápido y el uso de objetos mágicos.": "Agile masters of infiltration, quick pilfering, and the use of magic items.",
  "Mezcla hurtos con magia de ilusión y encantamiento.": "Blends thievery with illusion and enchantment magic.",
  "Duelistas ágiles, elegantes y teatrales que sobresalen en el combate cuerpo a cuerpo uno contra uno y en la iniciativa veloz.": "Agile, elegant, and theatrical duelists who excel at one-on-one melee combat and swift initiative.",
  "Detectives y sabuesos expertos en descubrir mentiras, notar detalles imperceptibles y exponer los puntos débiles de sus enemigos.": "Expert detectives and sleuths skilled at uncovering lies, noticing imperceptible details, and exposing their enemies' weak points.",
  "Estrategas fríos, espías e intrigantes que manipulan el campo de batalla dando órdenes a distancia y descifrando los secretos de sus rivales.": "Cool-headed strategists, spies, and schemers who manipulate the battlefield by issuing orders from afar and deciphering their rivals' secrets.",
  "Asesinos vinculados íntimamente a la muerte que recolectan almas de los difuntos para consultar sus recuerdos y desgarrar la carne enemiga.": "Assassins intimately bound to death who harvest the souls of the departed to consult their memories and rend enemy flesh.",
  "Asesinos psiónicos que materializan dagas de energía mental luminosa en sus manos para asesinar en silencio absoluto y comunicarse telepáticamente.": "Psionic assassins who materialize daggers of luminous mental energy in their hands to kill in absolute silence and communicate telepathically.",
  "Pícaros de la espesura expertos en supervivencia y guerrilla que se retiran ágilmente de los enemigos para acribillarlos a distancia.": "Wilderness rogues skilled in survival and guerrilla warfare who nimbly disengage from enemies to pepper them from afar.",
  "El clásico caballero de brillante armadura dedicado al honor, la verdad y la piedad.": "The classic knight in shining armor dedicated to honor, truth, and righteousness.",
  "Castigadores inflexibles que persiguen a los culpables sin descanso.": "Relentless punishers who pursue the guilty without rest.",
  "Caballeros verdes y campeones de la luz natural que juran preservar la alegría, la belleza y la vida contra el avance de las sombras.": "Green knights and champions of natural light who swear to preserve joy, beauty, and life against the encroaching shadows.",
  "Luchadores implacables que sirven a deidades tiránicas o a la ley marcial estricta, aplastando toda disidencia mediante el terror absoluto.": "Implacable fighters who serve tyrannical deities or strict martial law, crushing all dissent through absolute terror.",
  "Pacificadores que creen que cualquier alma extraviada puede salvarse mediante la compasión, pero descargan justicia cuando la maldad rehúsa la paz.": "Peacemakers who believe any wayward soul can be saved through compassion, yet mete out justice when evil refuses peace.",
  "Héroes legendarios impulsados por el destino y la épica, que inspiran a sus camaradas a hazañas sobrehumanas.": "Legendary heroes driven by destiny and epic deeds, inspiring their comrades to superhuman feats.",
  "Centinelas juramentados para proteger el Plano Material contra invasiones extraplanares de aberraciones, demonios, fatas y seres cósmicos.": "Sworn sentinels who protect the Material Plane against extraplanar invasions by aberrations, fiends, fey, and cosmic beings.",
  "Paladines dedicados a la soberanía, la ley y la lealtad inquebrantable a su reino o monarca por encima de todo código moral personal.": "Paladins dedicated to sovereignty, law, and unwavering loyalty to their realm or monarch above any personal moral code.",
  "Paladines caídos que han quebrado sus votos sagrados en pos de ambiciones oscuras, sirviendo a poderes siniestros o a la nigromancia pura.": "Fallen paladins who have broken their sacred vows in pursuit of dark ambitions, serving sinister powers or pure necromancy.",
  "Controlan el cuerpo del enemigo derribándolo, empujándolo o negando sus reacciones con su Ki.": "They control the enemy's body by knocking them prone, pushing them, or denying their reactions with their Ki.",
  "Ninjas sigilosos que se teletransportan entre las sombras y usan oscuridad mágica.": "Stealthy ninjas who teleport between shadows and wield magical darkness.",
  "Monjes que doblegan los cuatro elementos primordiales: aire cortante, tierra inamovible, fuego devorador y agua fluida usando su Ki.": "Monks who bend the four primordial elements—slicing air, unyielding earth, devouring fire, and flowing water—using their Ki.",
  "Imitan los tambaleos y quiebros impredecibles de un ebrio para esquivar ataques mortales y golpear desde ángulos imposibles.": "They mimic the unpredictable stumbles and sways of a drunkard to dodge deadly attacks and strike from impossible angles.",
  "Maestros absolutos de la espada y el arco que consideran sus armas como extensiones espirituales de su propio cuerpo y Ki.": "Absolute masters of sword and bow who regard their weapons as spiritual extensions of their own body and Ki.",
  "Médicos encapuchados que manipulan la energía vital de otros: traen sanación milagrosa a los inocentes o muerte piadosa e indolora a los caídos.": "Hooded physicians who manipulate the life energy of others: bringing miraculous healing to the innocent or a merciful, painless death to the fallen.",
  "Monjes que proyectan la forma auténtica de su espíritu, manifestando brazos espectrales, máscaras y armaduras de energía psíquica pura.": "Monks who project the true form of their spirit, manifesting spectral arms, visages, and armor of pure psychic energy.",
  "Canalizan la luz incandescente de su espíritu en ráfagas de energía radiante que deslumbran e incineran a la oscuridad.": "They channel the incandescent light of their spirit into bolts of radiant energy that dazzle and incinerate the darkness.",
  "Monjes que canalizan la majestuosidad y los elementos primigenios de los dragones cromáticos y metálicos.": "Monks who channel the majesty and primordial elements of chromatic and metallic dragons.",
  "Monjes obsesionados con el significado y la mecánica del fin vital que manipulan la energía de la muerte para absorber vitalidad y esquivar la tumba.": "Monks obsessed with the meaning and mechanics of dying who manipulate the energy of death to absorb vitality and cheat the grave.",
  "Poetas guerreros que visten armaduras medias, portan armas marciales y potencian el combate de sus camaradas.": "Warrior poets who wear medium armor, wield martial weapons, and bolster their comrades in combat.",
  "Danzarines del filo y duelistas acrobáticos que convierten el combate cuerpo a cuerpo en un espectáculo letal.": "Blade dancers and acrobatic duelists who turn melee combat into a lethal spectacle.",
  "Herederos de la gracia y el terror cautivador de la corte Feérica. Su arte doblega voluntades y deslumbra a ejércitos enteros.": "Heirs to the captivating grace and terror of the Feywild courts. Their art bends wills and dazzles entire armies.",
  "Espías consumados e ilusionistas que usan secretos, venenos y terror psicológico como sus más afiladas melodías.": "Consummate spies and illusionists who wield secrets, poisons, and psychological terror as their sharpest melodies.",
  "Maestros del debate, la dialéctica y el peso de las palabras. Su retórica infunde coraje inquebrantable o quiebra la determinación enemiga.": "Masters of debate, dialectics, and the weight of words. Their rhetoric instills unshakable courage or shatters enemy resolve.",
  "Canalizan la Canción de la Creación original que dio forma al cosmos, animando materia inerte y materializando objetos de la nada.": "They channel the primeval Song of Creation that shaped the cosmos, animating inert matter and materializing objects out of thin air.",
  "Conjuradores y adivinos que entonan historias de almas difuntas usando cartas de tarokka, dados o calaveras para invocar milagros.": "Conjurors and diviners who chant tales of departed souls using tarokka cards, dice, or skulls to invoke miracles.",
  "Místicos vinculados a un bioma que recuperan magia en descansos cortos y dominan hechizos del entorno.": "Mystics bound to a specific biome who recover magic on short rests and master terrain spells.",
  "Guerreros salvajes que se transforman en bestias poderosas (Oso pardo, Lobo terrible, Elementales) como acción adicional.": "Fierce guardians who transform into powerful beasts (brown bear, dire wolf, elementals) as a bonus action.",
  "Druidas que hallan belleza en la putrefacción y los hongos, tejiendo la muerte y el renacimiento en una armadura fúngica letal.": "Druids who find beauty in decay and fungi, weaving death and rebirth into a lethal fungal armor.",
  "Astrónomos y navegantes que leen el telón de las constelaciones para canalizar la luz celestial y alterar la suerte cósmica.": "Astronomers and navigators who read the curtain of constellations to channel celestial light and alter cosmic fortune.",
  "Protectores de las criaturas salvajes y guardianes de las bestias, que invocan espíritus tótems para resguardar a su manada.": "Protectors of wild creatures and wardens of beasts who summon totem spirits to safeguard their pack.",
  "Vinculados a los enclaves idílicos del Feywild, curan heridas mediante rocío onírico y abren portales a través de sueños diáfanos.": "Bound to the idyllic enclaves of the Feywild, they heal wounds with dreamlike dew and open portals through gossamer dreams.",
  "Comprenden que la destrucción ardiente es el primer paso necesario para el renacimiento exuberante de la naturaleza.": "They understand that fiery destruction is the necessary first step toward nature's lush rebirth.",
  "La magia fluye de forma caótica e impredecible a su alrededor.": "Magic flows chaotically and unpredictably all around them.",
  "La sangre de los dragones corre por sus venas, otorgándoles escamas y magia elemental.": "The blood of dragons courses through their veins, granting them scales and elemental magic.",
  "Bendecidos con una chispa celestial de los dioses en su sangre, combinan la hechicería con los milagros sagrados de los clérigos.": "Blessed with a celestial spark of the gods in their blood, they combine sorcery with the sacred miracles of clerics.",
  "Nacidos tocados por el Páramo Sombrío, controlan tinieblas impenetrables y sabuesos espectrales forjados con pura oscuridad.": "Born touched by the Shadowfell, they command impenetrable darkness and spectral hounds forged from pure shadow.",
  "Imbuidos del poder de los huracanes, vendavales y truenos marinos, vuelan con ráfagas de aire y azotan a sus agresores con rayos.": "Imbued with the power of hurricanes, gales, and sea thunder, they fly on gusts of wind and lash their attackers with lightning.",
  "Mentes tocadas por los horrores del Reino Lejano o un renacuajo de azotamentes, capaces de desatar psicosis y lanzar conjuros psiónicos invisibles.": "Minds touched by the horrors of the Far Realm or a mind flayer tadpole, capable of unleashing psychosis and casting invisible psionic spells.",
  "Canalizan la armonía y simetría matemática inmutable de Mechanus y Primus, neutralizando el caos y restableciendo el orden en el tejido arcano.": "They channel the immutable mathematical harmony and symmetry of Mechanus and Primus, neutralizing chaos and restoring order to the arcane weave.",
  "Canalizan la magia mística de las fases lunares (Luna Llena, Luna Nueva y Luna Menguante), adaptando sus conjuros y metamagia a los ciclos del cielo nocturno.": "They channel the mystic magic of the lunar phases (Full Moon, New Moon, and Crescent Moon), adapting their spells and Metamagic to the cycles of the night sky.",
  "Un pacto forjado con un señor de los Nueve Infiernos o el Abismo.": "A pact forged with a lord of the Nine Hells or the Abyss.",
  "Vinculado a un arma consciente forjada con sombras del Páramo Sombrío.": "Bound to a sentient weapon forged from the shadows of the Shadowfell.",
  "Pactantes con entidades insondables de más allá del tiempo y las estrellas como Cthulhu o Hadar, cuyas mentes rompen la cordura de los mortales.": "Warlocks bound to unfathomable entities from beyond time and the stars like Cthulhu or Hadar, whose minds shatter mortal sanity.",
  "Pactantes con señores y damas del Feywild como Titania o la Reina del Aire y la Oscuridad, expertos en ilusiones, encanto y evasiones etéreas.": "Warlocks bound to lords and ladies of the Feywild like Titania or the Queen of Air and Darkness, experts in illusions, charm, and ethereal escapes.",
  "Vinculados a seres de los planos superiores como solares, ki-rins o unicornios, canalizan luz purificadora y fuegos sagrados sanadores.": "Bound to beings of the Upper Planes such as solars, ki-rin, or unicorns, they channel purifying light and healing sacred flames.",
  "Pactos con nobles señores de las ciudadelas elementales: Dao (tierra), Djinni (aire), Efreeti (fuego) o Marid (agua), que otorgan riquezas y santuarios portátiles.": "Pacts with noble lords of the elemental citadels—Dao (earth), Djinni (air), Efreeti (fire), or Marid (water)—who grant riches and portable sanctuaries.",
  "Sirvientes de archiliches, vampiros milenarios o momias supremas como Acererak o Strahd, transformando su fisonomía en un terror cadavérico inmortal.": "Servants of archliches, ancient vampires, or supreme mummies like Acererak or Strahd, transforming their visage into an immortal cadaverous terror.",
  "Pactantes con las profundidades abisales de los mares y kraken titánicos, manifestando tentáculos espectrales de agua helada.": "Warlocks bound to the abyssal depths of the seas and titanic krakens, manifesting spectral tentacles of freezing water.",
  "Has forjado un pacto con un ser que ha conquistado la muerte misma, como Vecna, Larloch o Acererak, aprendiendo los secretos de la no-muerte y la longevidad eterna.": "You have forged a pact with a being that has conquered death itself, such as Vecna, Larloch, or Acererak, learning the secrets of undeath and eternal longevity.",
  "Desarrolla técnicas letales para exterminar hordas o monstruos colosales.": "Develops lethal techniques for slaying hordes or colossal monsters.",
  "Especialista en emboscadas en cuevas oscuras y el Inframundo.": "Specialist in ambushes within dark caves and the Underdark.",
  "Forjan un lazo espiritual y empático supremo con una bestia compañera primigenia de la tierra, el cielo o el mar.": "They forge a supreme spiritual and empathic bond with a primal beast companion of the land, sky, or sea.",
  "Guardianes de las fronteras planares que detectan portales extradimensionales y se teletransportan entre golpes para infligir daño de fuerza pura.": "Guardians of planar borders who detect extradimensional portals and teleport between strikes to deal pure force damage.",
  "Cazadores entrenados en la anatomía y las debilidades de las criaturas de la noche, vampiros, demonios y magos oscuros.": "Hunters trained in the anatomy and weaknesses of creatures of the night, vampires, fiends, and dark mages.",
  "Viven rodeados de un enjambre continuo de espíritus diminutos de la naturaleza (abejas, ramitas, polillas o geckos) que atacan y los transportan.": "They live surrounded by a constant swarm of tiny nature spirits (bees, twigs, moths, or geckos) that attack foes and carry them aloft.",
  "Guerreros vinculados a la majestuosidad dracónica que crían y comandan a un fiel Draco que crece hasta convertirse en una montura alada colosal.": "Warriors bound to draconic majesty who raise and command a loyal Drake that grows into a colossal winged mount.",
  "Viajeros tocados por el encanto caprichoso y peligroso del Feywild, que infunden a sus ataques con pavor fey y engaños hipnóticos.": "Travelers touched by the capricious and perilous charm of the Feywild, infusing their attacks with fey dread and hypnotic deceptions.",
  "Especialista en juego de piernas veloz, fintas y mantener las distancias con reflejos relámpago.": "Specialist in swift footwork, feints, and keeping distance with lightning reflexes.",
  "Lanza ráfagas incesantes a quemarropa que abruman las defensas enemigas con una lluvia de combinaciones.": "Unleashes relentless close-quarters flurries that overwhelm enemy defenses with a hail of combinations.",
  "Especialistas en combinar reactivos químicos y magia para elaborar pociones sanadoras, elixires mutágenos y vapores cáusticos.": "Specialists in combining chemical reagents and magic to brew healing potions, mutagenic elixirs, and caustic vapors.",
  "Modifican sus armaduras pesadas convirtiéndolas en exotrajes arcanos potenciados con rayos de energía o guanteletes de trueno demoledores.": "They modify their heavy armor into arcane exosuits powered by energy bolts or devastating thunder gauntlets.",
  "Protectores marciales que combinan armas imbuidas con su mente y la leal asistencia de un Defensor de Acero mecánico.": "Martial protectors who combine mind-infused weapons with the loyal assistance of a mechanical Steel Defender.",
  "Eliges una senda que moldea la naturaleza de tu furia (Berserker, Guerrero Totémico, etc.), obteniendo rasgos a niveles 3, 6, 10 y 14.": "You choose a path that shapes the nature of your rage (Berserker, Totem Warrior, etc.), gaining features at 3rd, 6th, 10th, and 14th level.",
  "Tu velocidad terrestre aumenta en 10 pies mientras no lleves armadura pesada.": "Your walking speed increases by 10 feet while you aren't wearing heavy armor.",
  "Obtienes un nuevo rasgo otorgado por la senda primitiva elegida a nivel 3.": "You gain a new feature granted by the Primal Path you chose at 3rd level.",
  "Ganas ventaja en tiradas de Iniciativa. Si estás sorprendido al inicio del combate, puedes actuar normalmente si entras en furia de inmediato.": "You have advantage on initiative rolls. Additionally, if you are surprised at the beginning of combat and aren't incapacitated, you can act normally on your first turn, but only if you enter your rage before doing anything else on that turn.",
  "Tiras un dado de daño de arma adicional al determinar el daño adicional por un impacto crítico cuerpo a cuerpo.": "You can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack.",
  "Si caes a 0 puntos de golpe mientras estás en furia y no mueres, puedes hacer una salvación de Constitución CD 10 para quedar a 1 PG. La CD aumenta en 5 por uso sucesivo.": "If you drop to 0 hit points while you're raging and don't die outright, you can make a DC 10 Constitution saving throw to drop to 1 hit point instead. Each time you use this feature after the first, the DC increases by 5.",
  "Tiras dos dados de daño de arma adicionales al determinar el daño adicional por un impacto crítico cuerpo a cuerpo.": "You can roll two additional weapon damage dice when determining the extra damage for a critical hit with a melee attack.",
  "Obtienes un nuevo rasgo legendario otorgado por la senda primitiva elegida a nivel 3.": "You gain a new legendary feature granted by the Primal Path you chose at 3rd level.",
  "Tu furia es tan intensa que solo termina antes de su tiempo si caes inconsciente o decides terminarla tú mismo.": "Your rage is so fierce that it ends early only if you fall unconscious or if you choose to end it.",
  "Tiras tres dados de daño de arma adicionales al determinar el daño adicional por un impacto crítico cuerpo a cuerpo.": "You can roll three additional weapon damage dice when determining the extra damage for a critical hit with a melee attack.",
  "Si el resultado total de una prueba de Fuerza es menor que tu puntuación de característica de Fuerza, puedes usar tu puntuación en lugar del resultado.": "If your total for a Strength check is less than your Strength score, you can use that score in place of the total.",
  "Encarnas la ferocidad pura de la naturaleza. Tus puntuaciones de Fuerza y Constitución aumentan en 4 (máximo 24), y tus usos de furia pasan a ser ilimitados.": "You embody the pure ferocity of the wilds. Your Strength and Constitution scores increase by 4 (to a maximum of 24), and you can rage an unlimited number of times.",
  "Al entrar en furia, puedes hacer un ataque cuerpo a cuerpo adicional con tu acción adicional en cada turno. Sufres 1 nivel de agotamiento al terminar la furia.": "When you enter a rage, you can make a single melee weapon attack as a bonus action on each of your turns. When your rage ends, you suffer one level of exhaustion.",
  "No puedes ser hechizado ni asustado mientras estés en furia.": "You can't be charmed or frightened while raging.",
  "Como acción, atemorizas a una criatura a 30 pies si falla una salvación de Sabiduría (CD 8 + prof + Car).": "As an action, you can frighten a creature within 30 feet of you if it fails a Wisdom saving throw (DC 8 + proficiency bonus + Charisma modifier).",
  "Reacción: cuando una criatura a 5 pies te inflija daño, realizas un ataque cuerpo a cuerpo con arma contra ella.": "Reaction: When you take damage from a creature that is within 5 feet of you, you can make a melee weapon attack against that creature.",
  "Puedes lanzar Sentido Bestial y Hablar con Animales como rituales.": "You can cast the Beast Sense and Speak with Animals spells, but only as rituals.",
  "Oso: resistencia a todo el daño excepto psíquico. Águila: correr como acción adicional. Lobo: aliados tienen ventaja contra enemigos adyacentes a ti.": "Bear: Resistance to all damage except psychic damage. Eagle: Dash as a bonus action. Wolf: Allies have advantage on melee attack rolls against enemies within 5 feet of you.",
  "Oso: capacidad de carga duplicada. Águila: ves a 1 milla sin problemas y sin desventaja con luz tenue. Lobo: rastreas a paso rápido.": "Bear: Your carrying capacity is doubled. Eagle: You can see up to 1 mile away with no difficulty, and dim light doesn't impose disadvantage on your Perception checks. Wolf: You can track other creatures while traveling at a fast pace.",
  "Puedes lanzar Comunión con la Naturaleza como un ritual.": "You can cast the Commune with Nature spell, but only as a ritual.",
  "Oso: enemigos a 5 pies tienen desventaja al atacar a otros. Águila: vuelas en breves ráfagas. Lobo: derribas enemigos con acción adicional.": "Bear: Enemies within 5 feet of you have disadvantage on attack rolls against targets other than you. Eagle: You can fly in short bursts during your turn. Wolf: You can knock a Large or smaller creature prone as a bonus action when you hit it.",
  "El primer impacto de arma cuerpo a cuerpo que asestas en cada uno de tus turnos mientras estás en Furia inflige 1d6 + la mitad de tu nivel de bárbaro de daño radiante o necrótico adicional (a tu elección al elegir la senda).": "The first creature you hit on each of your turns with a weapon attack while raging takes extra radiant or necrotic damage (your choice when you choose this path) equal to 1d6 + half your barbarian level.",
  "Si un conjuro tiene el único propósito de devolverte a la vida (como Revivir o Alzamiento de los Muertos), quien lo lance no necesita gastar ningún componente material de valor para traer tu alma de vuelta.": "If a spell, such as Raise Dead or Revivify, has the sole effect of restoring you to life, the caster doesn't need material components to cast the spell on you.",
  "Si fallas una tirada de salvación mientras estás en Furia, puedes volver a tirarla con ventaja. Debes usar el nuevo resultado y puedes usar este rasgo una vez por furia.": "If you fail a saving throw while you're raging, you can reroll it, and you must use the new roll. You can use this ability only once per rage.",
  "Como acción adicional, desatas un grito de guerra sobrecogedor. Hasta 10 criaturas aliadas a tu elección a menos de 60 pies ganan ventaja en tiradas de ataque y tiradas de salvación hasta el comienzo de tu siguiente turno (1/descanso largo).": "As a bonus action, you unleash a battle cry infused with divine energy. Up to ten other creatures of your choice within 60 feet of you gain advantage on attack rolls and saving throws until the start of your next turn (1/long rest).",
  "Estar a 0 puntos de golpe no te deja inconsciente mientras estés en furia. Sigues haciendo salvaciones de muerte normalmente y sufres los efectos normales del daño. Solo mueres por fallos en salvaciones de muerte si tu furia termina y continúas a 0 PG.": "Having 0 hit points doesn't knock you unconscious while you're raging. You still must make death saving throws, and you suffer the normal effects of taking damage while at 0 hit points. However, if you would die due to failing death saving throws, you don't die until your rage ends, and you die then only if you still have 0 hit points.",
  "La primera criatura que golpeas con un ataque con arma en tu turno mientras estás en furia queda marcada por espíritus. Hasta tu siguiente turno, esa criatura tiene desventaja en tiradas de ataque contra cualquiera que no seas tú, y si impacta a otro, ese objetivo tiene resistencia al daño del ataque.": "The first creature you hit with an attack on your turn while raging becomes the target of spiritual warriors. Until the start of your next turn, that target has disadvantage on any attack roll that isn't against you, and when the target hits a creature other than you with an attack, that creature has resistance to the damage dealt by the attack.",
  "Si otra criatura que puedes ver a 30 pies o menos sufre daño mientras estás en furia, puedes usar tu reacción para reducir ese daño en 2d6 (aumenta a 3d6 a nivel 10 y 4d6 a nivel 14).": "If you are raging and another creature you can see within 30 feet of you takes damage, you can use your reaction to reduce that damage by 2d6 (increases to 3d6 at 10th level and 4d6 at 14th level).",
  "Puedes invocar a tus ancestros para obtener sabiduría, lanzando el conjuro Augurio o Clarividencia sin gastar ranura de conjuro ni componentes de valor (1/descanso corto o largo).": "You can consult your ancestral spirits for guidance, casting the Augury or Clairvoyance spell without using a spell slot or material components (1/short or long rest).",
  "Cuando usas tu Escudo Espiritual para reducir daño, el atacante sufre daño de fuerza igual a la cantidad de daño que redujiste.": "When you use your Spirit Shield to reduce the damage of an attack, the attacker takes an amount of force damage equal to the damage that your Spirit Shield prevents.",
  "Al entrar en furia manifiestas un arma natural a elegir: Mordisco (1d8 perforante, recuperas PG iguales a tu bonificador de competencia si estás por debajo de la mitad), Garras (1d6 cortante, puedes hacer un ataque adicional gratis por turno si atacas con garras), o Cola (1d8 perforante con alcance 10 pies, como reacción añades 1d8 a tu CA si te van a impactar).": "When you enter your rage, you manifest a natural weapon of your choice: Bite (1d8 piercing, regain hit points equal to your proficiency bonus once per turn when below half hit points), Claws (1d6 slashing, make one additional claw attack as part of the Attack action once per turn), or Tail (1d8 piercing with 10-foot reach, add 1d8 to your AC as a reaction when hit by an attack roll within 10 feet).",
  "Tus armas naturales cuentan como mágicas para superar resistencias. Además, tras cada descanso eliges una adaptación: velocidad de nado igual a tu velocidad terrestre y respirar bajo agua, velocidad de escalada igual a tu velocidad terrestre y caminar por techos, o saltar sumando una prueba de Atletismo a la distancia.": "Your natural weapons count as magical for the purpose of overcoming resistance and immunity. Additionally, when you finish a short or long rest, you can choose one adaptation: a swimming speed equal to your walking speed and the ability to breathe underwater, a climbing speed equal to your walking speed and the ability to climb difficult surfaces and ceilings without ability checks, or extending your jump distance by making an Athletics check.",
  "Al impactar a una criatura con tus armas naturales en furia, puedes forzar una salvación de Sabiduría (CD 8 + prof + Con). Si falla, la criatura sufre 2d12 de daño psíquico o usa su reacción para golpear a uno de sus aliados.": "When you hit a creature with your natural weapons while you are raging, you can force it to make a Wisdom saving throw (DC 8 + proficiency bonus + Constitution modifier). On a failed save, the target takes 2d12 psychic damage or must use its reaction to make a melee attack against another creature of your choice.",
  "Al entrar en furia puedes elegir un número de criaturas aliadas a 30 pies igual a tu bonificador de Con. Cada una gana 5 PG temporales por aliado potenciado, y tú ganas 1d6 de daño adicional por cada aliado que te acompañe.": "When you enter your rage, you can choose a number of willing creatures within 30 feet of you equal to your Constitution modifier. You gain 5 temporary hit points for each creature that accepts this feature, and each of them gains a 1d6 bonus to damage rolls once per turn while your rage lasts.",
  "Como acción, puedes abrir tu mente para detectar la presencia de magia concentrada o conjuros a menos de 60 pies hasta el final de tu siguiente turno.": "As an action, you can open your awareness to the presence of concentrated magic, detecting spells and magic items within 60 feet of you until the end of your next turn.",
  "Al entrar en furia tiras 1d8 en la tabla de magia salvaje: 1: teletransporte como acción adicional; 2: rayos necróticos que curan; 3: espíritus fey que explotan con daño de fuerza; 4: armas imbuidas de energía radiante y arrojadizas; 5: proyectiles de fuego al recibir daño; 6: armadura protectora que ciega; 7: terreno difícil de flores espinosas; 8: rayo de energía arcana que ciega.": "When you enter your rage, roll 1d8 on the Wild Magic table: 1: shadow tendrils deal necrotic damage and grant temporary hit points; 2: teleport as a bonus action; 3: exploding flumph or pixie spirits deal force damage; 4: weapon infused with force energy gains the light and thrown properties; 5: retaliatory beam deals force damage when you are hit; 6: protective aura grants +1 AC to you and allies; 7: flowers and vines create difficult terrain around you; 8: bolt of light deals radiant damage and blinds a target.",
  "Como acción tocas a un aliado para bendecirlo: gana 1d3 en tiradas de ataque y pruebas durante 10 minutos, o recupera una ranura de conjuro gastada de nivel hasta 1d3.": "As an action, you can touch one creature and confer a blessing: for 10 minutes, the target can roll 1d3 and add the number rolled to attack rolls and ability checks, or it regains one expended spell slot of level 1d3 or lower.",
  "Cuando sufres daño o fallas una salvación en furia, puedes usar tu reacción para volver a tirar en la tabla de magia salvaje, reemplazando el efecto actual de inmediato.": "When you are imperiled during your rage by taking damage or failing a saving throw, you can use your reaction to roll on the Wild Magic table and immediately produce the new effect, replacing your current Wild Magic effect.",
  "Cada vez que tiras en la tabla de Magia Salvaje, tiras dos dados y puedes elegir cuál de los dos resultados deseas manifestar.": "Whenever you roll on the Wild Magic table, you can roll the die twice and choose which of the two effects to unleash.",
  "Generas un aura de 10 pies al enfurecerte. Puedes activarla como acción adicional en cada turno: Desierto (2 a 6 de daño de fuego a todas las criaturas adyacentes), Mar (1d6 a 4d6 de daño de relámpago con salvación de Des a un objetivo), o Tundra (2 a 6 PG temporales a cada aliado en tu aura).": "You emanate a stormy, magical aura in a 10-foot radius while raging. You can activate its effect as a bonus action on each turn: Desert (2 to 6 fire damage to all other creatures in your aura), Sea (1d6 to 4d6 lightning damage on a failed Dexterity save to one creature in your aura), or Tundra (2 to 6 temporary hit points to each creature of your choice in your aura).",
  "Ganas resistencia permanente según tu ambiente: Fuego (Desierto), Relámpago y respirar bajo agua (Mar), o Frío e inmunidad al frío extremo (Tundra).": "You gain permanent benefits based on your chosen environment: Fire resistance and immunity to extreme heat (Desert), Lightning resistance, a 30-foot swimming speed, and underwater breathing (Sea), or Cold resistance, immunity to extreme cold, and the ability to freeze water by touch (Tundra).",
  "Cada criatura a tu elección dentro de tu Aura de Tormenta gana la resistencia al daño concedida por tu rasgo Alma de la Tormenta.": "Each creature of your choice within your Storm Aura gains the damage resistance granted by your Storm Soul feature.",
  "Efectos supremos para tu aura: Desierto (reacción cuando alguien te golpea para infligir la mitad de tu nivel en daño de fuego), Mar (reacción para derribar a quien te golpee si falla salvación de Fue), o Tundra (reacción para congelar y reducir la velocidad a 0 de un enemigo en tu aura).": "Supreme effects for your aura: Desert (use your reaction when hit by a creature in your aura to force a Dexterity save or deal fire damage equal to half your barbarian level), Sea (use your reaction when you hit a creature in your aura to force a Strength save or knock it prone), or Tundra (whenever your aura is activated, force a creature in your aura to make a Strength save or have its speed reduced to 0).",
  "Al entrar en furia creces a tamaño Grande si hay espacio, tu alcance aumenta en 5 pies, y añades tu bonificador de furia al daño de ataques arrojadizos con armas.": "When you enter a rage, you become Large if there is room, your reach increases by 5 feet, and you add your Rage Damage bonus to ranged weapon attacks using thrown weapons.",
  "Imbuyes tu arma con energía de Gigante (ácido, frío, fuego, relámpago o trueno) que añade 1d6 de daño elemental. El arma gana la propiedad arrojadiza (alcance 20/60) y regresa mágicamente a tu mano al instante.": "You infuse your weapon with primordial giant energy (acid, cold, fire, lightning, or thunder), dealing an extra 1d6 damage of the chosen type. The weapon gains the thrown property (range 20/60 feet) and reappears in your hand immediately after an attack.",
  "Como acción adicional puedes levantar a una criatura Mediana o menor a 5 pies de ti y lanzarla hasta 30 pies. Si es un enemigo y falla una salvación de Fuerza, sufre 1d6 de daño por cada 10 pies de caída y queda derribado.": "As a bonus action while raging, you can choose one Medium or smaller creature within your reach and move it to an unoccupied space you can see within 30 feet of you (an unwilling creature must succeed on a Strength saving throw to avoid the effect), taking falling damage and landing prone if it doesn't land on a surface.",
  "Al entrar en furia puedes crecer a tamaño Enorme, tu alcance aumenta en 10 pies, el daño elemental de tu Arma Elemental aumenta a 2d6, y puedes lanzar criaturas Grandes con Estatura Imponente.": "When you rage, your reach increases by 10 feet, your size can increase to Large or Huge, the extra damage of your Elemental Cleaver increases to 2d6, and you can hurl Large creatures with Mighty Impel.",
  "Ganas la capacidad de usar armadura de púas como arma. Mientras estás en Furia y llevas armadura de púas, puedes usar una acción adicional en cada uno de tus turnos para realizar un ataque cuerpo a cuerpo con las púas (1d4 perforante + mod Fuerza). Además, al agarrar a una criatura con éxito mientras llevas tu armadura, le infliges 3 puntos de daño perforante.": "You gain the ability to use spiked armor as a weapon. While you are wearing spiked armor and are raging, you can use a bonus action to make one melee weapon attack with your armor spikes (1d4 piercing + Strength modifier). Additionally, when you successfully grapple a creature, the target takes 3 piercing damage if you are wearing spiked armor.",
  "Cuando utilizas Ataque Temerario mientras estás en Furia, ganas un número de puntos de golpe temporales igual a tu modificador de Constitución (mínimo 1). Estos PG temporales desaparecen al terminar tu furia.": "When you use Reckless Attack while raging, you also gain temporary hit points equal to your Constitution modifier (minimum of 1). They vanish if any of them are left when your rage ends.",
  "Puedes tomar la acción de Carrera (Dash) como acción adicional en tu turno mientras estés en Furia.": "You can take the Dash action as a bonus action while you are raging.",
  "Cuando una criatura a menos de 5 pies de ti te impacta con un ataque cuerpo a cuerpo mientras llevas tu armadura de púas y no estás incapacitado, recibe automáticamente 3 puntos de daño perforante.": "When a creature within 5 feet of you hits you with a melee attack, the attacker takes 3 piercing damage if you are raging, aren't incapacitated, and are wearing spiked armor.",
  "Desbloqueas el acceso a ranuras y conjuros arcanos de 2.º nivel (Imagen Espejada, Paso Brumoso, Telaraña, etc.).": "You unlock access to 2nd-level arcane spell slots and spells (Mirror Image, Misty Step, Web, etc.).",
  "Desbloqueas ranuras y conjuros arcanos de 3.er nivel (Bola de Fuego, Contrahechizo, Relámpago, Volar, etc.).": "You unlock 3rd-level arcane spell slots and spells (Fireball, Counterspell, Lightning Bolt, Fly, etc.).",
  "Obtienes un nuevo rasgo otorgado por tu Escuela de Magia (por ejemplo, Ataque Adicional Mejorado en Canto de la Hoja, Guarda Proyectada en Abjuración o Truco Potente en Evocación).": "You gain a new feature granted by your Arcane Tradition (for example, Extra Attack in Bladesinging, Projected Ward in Abjuration, or Potent Cantrip in Evocation).",
  "Desbloqueas el acceso a ranuras y conjuros arcanos de 4.º nivel (Polimorfar, Puerta Dimensional, Ojo Arcano, Muro de Fuego).": "You unlock access to 4th-level arcane spell slots and spells (Polymorph, Dimension Door, Arcane Eye, Wall of Fire).",
  "Desbloqueas el acceso a ranuras y conjuros arcanos de 5.º nivel (Telequinesis, Muro de Fuerza, Cono de Frío, Dominar Persona).": "You unlock access to 5th-level arcane spell slots and spells (Telekinesis, Wall of Force, Cone of Cold, Dominate Person).",
  "Obtienes un rasgo avanzado de tu Tradición Arcana elegida a nivel 2.": "You gain an advanced feature from the Arcane Tradition you chose at 2nd level.",
  "Desbloqueas poderosos conjuros arcanos de 6.º nivel (Desintegrar, Cadena de Relámpagos, Globo de Invulnerabilidad).": "You unlock powerful 6th-level arcane spells (Disintegrate, Chain Lightning, Globe of Invulnerability).",
  "Desbloqueas conjuros de 7.º nivel capaces de alterar la realidad física (Teletransporte, Jaula de Fuerza, Forma de Simulacro).": "You unlock 7th-level spells capable of altering physical reality (Teleport, Forcecage, Simulacrum).",
  "Alcanzas la cúspide de maestría en tu Escuela de Magia elegida a nivel 2.": "You reach the pinnacle of mastery in the Arcane Tradition you chose at 2nd level.",
  "Desbloqueas conjuros arcanos legendarios de 8.º nivel (Antimagia, Laberinto, Dominar Monstruo, Semiplano).": "You unlock legendary 8th-level arcane spells (Antimagic Field, Maze, Dominate Monster, Demiplane).",
  "Desbloqueas la magia definitiva de 9.º nivel: Deseo (Wish), Parar el Tiempo (Time Stop), Polimorfia Verdadera, Tromba de Meteoros.": "You unlock ultimate 9th-level magic: Wish, Time Stop, True Polymorph, Meteor Swarm.",
  "Eliges un conjuro de mago de 1.er nivel y uno de 2.º nivel que estén en tu libro de conjuros. Puedes lanzar esos dos conjuros a su nivel más bajo a voluntad, sin gastar ninguna ranura de conjuro.": "You choose a 1st-level wizard spell and a 2nd-level wizard spell that are in your spellbook. You can cast those spells at their lowest level without expending a spell slot when you have them prepared.",
  "Eliges dos conjuros de mago de 3.er nivel en tu libro de conjuros como tus conjuros insignia. Siempre los tienes preparados sin contar contra tu límite y puedes lanzar cada uno una vez a 3.er nivel sin gastar ranura de conjuro por descanso corto o largo.": "You choose two 3rd-level wizard spells in your spellbook as your signature spells. You always have these spells prepared, they don't count against the number of spells you have prepared, and you can cast each of them once at 3rd level without expending a spell slot per short or long rest.",
  "Ganas competencia con armaduras ligeras, un tipo de arma cuerpo a cuerpo de una mano y la habilidad Actuación.": "You gain proficiency with light armor, one type of one-handed melee weapon of your choice, and the Performance skill.",
  "Como acción adicional invocas el Canto de la Hoja por 1 minuto: sumas tu Mod. Inteligencia a tu CA, tu velocidad aumenta 10 pies, tienes ventaja en Acrobacias y sumas tu Mod. Inteligencia a las tiradas de salvación de Constitución para mantener la concentración.": "As a bonus action, you invoke the Bladesong for 1 minute: you gain a bonus to your AC equal to your Intelligence modifier, your walking speed increases by 10 feet, you have advantage on Dexterity (Acrobatics) checks, and you gain a bonus to any Constitution saving throw you make to maintain concentration on a spell equal to your Intelligence modifier.",
  "Puedes atacar dos veces al tomar la acción de Atacar, y puedes lanzar uno de tus trucos en lugar de uno de esos ataques.": "You can attack twice, instead of once, whenever you take the Attack action on your turn. Moreover, you can cast one of your cantrips in place of one of those attacks.",
  "Mientras el Canto de la Hoja esté activo, puedes usar tu reacción y gastar una ranura de conjuro para absorber daño igual a 5 x el nivel de la ranura gastada.": "While your Bladesong is active, you can use your reaction to expend one spell slot and reduce damage to you by an amount equal to five times the spell slot's level.",
  "Añades tu modificador de Inteligencia al daño de tus ataques con arma cuerpo a cuerpo mientras tu Canto de la Hoja está activo.": "You add your Intelligence modifier (minimum of +1) to the damage of your melee weapon attacks while your Bladesong is active.",
  "Reacción: después de que tú o una criatura a 30 pies tire un d20, puedes forzarle a volver a tirar y elegir el nuevo resultado (2 usos por descanso largo).": "Reaction: After you or a creature you can see within 30 feet of you makes an attack roll, an ability check, or a saving throw, you can force the creature to reroll and use the second roll (2 uses per long rest).",
  "Acción: una criatura Grande o menor a 60 pies debe superar salvación de Con contra tu CD de conjuro o quedar Incapacitada hasta el final de tu siguiente turno.": "Action: A Large or smaller creature you can see within 60 feet of you must succeed on a Constitution saving throw against your spell save DC or be incapacitated and have its speed reduced to 0 until the end of your next turn.",
  "Al lanzar un conjuro de nivel 4 o menor, puedes condensarlo en una pequeña cuenta durante 1 hora. Cualquier criatura que la sostenga puede usar su acción para liberar el conjuro usando tus estadísticas.": "When you cast a spell using a spell slot of 4th level or lower, you can condense the spell's magic into a mote (a Tiny bead) for 1 hour. A creature holding the bead can use its action to release the spell within, using your spell attack bonus and save DC.",
  "Reacción: cuando una criatura a 60 pies haga una tirada de ataque, salvación o prueba, decides si tiene éxito o falla automáticamente. Sufres un nivel de agotamiento al usarlo.": "Reaction: When you or a creature you can see within 60 feet of you makes an attack roll, an ability check, or a saving throw, you can ignore the die roll and decide whether the number rolled is the minimum needed to succeed or one less than that number. When you use this feature, you gain one level of exhaustion.",
  "Acción: creas un objeto inanimado no mágico en tu mano o en el suelo a 10 pies (máximo 10 libras y 3 pies). Desaparece tras 1 hora o al recibir daño.": "Action: You conjure an inanimate, nonmagical object in your hand or on the ground within 10 feet of you (no larger than 3 feet on a side and weighing no more than 10 pounds). It disappears after 1 hour or if it takes or deals any damage.",
  "Acción: te teletransportas hasta 30 pies a un espacio desocupado o intercambias posición con un aliado dispuesto. Se recarga con un descanso largo o al lanzar un conjuro de conjuración de nivel 1+.": "Action: You teleport up to 30 feet to an unoccupied space that you can see, or swap places with a willing Small or Medium creature within 30 feet. You regain the use of this feature when you finish a long rest or when you cast a conjuration spell of 1st level or higher.",
  "Tu concentración en un conjuro de conjuración no puede romperse como resultado de recibir daño.": "While you are concentrating on a conjuration spell, your concentration can't be broken as a result of taking damage.",
  "Cualquier criatura que invoques o crees con un conjuro de conjuración gana 30 puntos de golpe temporales.": "Any creature that you summon or create with a conjuration spell has 30 temporary hit points.",
  "Copiar conjuros de adivinación cuesta la mitad de oro y tiempo.": "The gold and time you must spend to copy a divination spell into your spellbook is halved.",
  "Al terminar un descanso largo tiras dos d20 y anotas los resultados. Puedes reemplazar cualquier tirada de ataque, salvación o prueba tuya o de una criatura visible por uno de esos números.": "When you finish a long rest, roll two d20s and record the numbers rolled. You can replace any attack roll, saving throw, or ability check made by you or a creature that you can see with one of these foretelling rolls.",
  "Lanzar un conjuro de adivinación de nivel 2 o superior te devuelve una ranura de conjuro gastada de menor nivel (máximo nivel 5).": "When you cast a divination spell of 2nd level or higher using a spell slot, you regain one expended spell slot of a level lower than the spell you cast (up to 5th level).",
  "Acción: obtienes uno de los siguientes beneficios hasta descansar: Visión en la Oscuridad (60 pies), Visión Etérea (60 pies), Leer Cualquier Idioma, o Ver Invisibilidad (10 pies).": "Action: You gain one of the following benefits until you are incapacitated or take a short or long rest: Darkvision (60 feet), Ethereal Sight (60 feet), Greater Comprehension (read any language), or See Invisibility (within 10 feet).",
  "Tiras tres dados d20 para tu rasgo de Presagio en lugar de dos.": "You roll three d20s for your Portent feature, rather than two.",
  "Copiar conjuros de encantamiento cuesta la mitad de oro y tiempo.": "The gold and time you must spend to copy an enchantment spell into your spellbook is halved.",
  "Acción: hipnotizas a una criatura a 5 pies que falle salvación de Sabiduría, dejándola Incapacitada y con velocidad 0 mientras mantengas la mirada cada turno.": "Action: Choose one creature that you can see within 5 feet of you. If it fails a Wisdom saving throw against your wizard spell save DC, it is charmed by you, incapacitated, and has a speed of 0 while you use your action each turn to maintain the effect.",
  "Reacción: cuando una criatura te ataque, debe superar salvación de Sabiduría o redirigir su ataque a la criatura más cercana.": "Reaction: When a creature you can see within 30 feet of you makes an attack roll against you, you can force it to make a Wisdom saving throw or redirect the attack to the creature closest to it.",
  "Cuando lances un conjuro de encantamiento de nivel 1 o mayor que afecte a una sola criatura, puedes apuntar a una segunda criatura sin gastar más ranuras.": "When you cast an enchantment spell of 1st level or higher that targets only one creature, you can have it target a second creature.",
  "Las criaturas encantadas por ti no se dan cuenta de que fueron encantadas, y puedes borrarles hasta (1 + Mod. Carisma) horas de memoria.": "Creatures charmed by you are unaware that they were charmed when the spell ends, and you can force them to forget up to (1 + your Charisma modifier) hours of the time they spent charmed.",
  "Copiar conjuros de evocación cuesta la mitad de oro y tiempo.": "The gold and time you must spend to copy an evocation spell into your spellbook is halved.",
  "Creas bolsas de seguridad en tus conjuros de área: los aliados elegidos (1 + nivel del conjuro) superan automáticamente su salvación y no reciben daño si normalmente recibirían la mitad.": "You can create pockets of relative safety within the effects of your evocation spells: chosen creatures (up to 1 + the spell's level) automatically succeed on their saving throws against the spell, and take no damage if they would normally take half damage on a successful save.",
  "Tus trucos dañan incluso si el objetivo supera la salvación (sufre la mitad del daño normal).": "Your damaging cantrips affect even creatures that avoid the brunt of the effect: if a target succeeds on a saving throw against your cantrip, it takes half the cantrip's damage.",
  "Añades tu modificador de Inteligencia a una tirada de daño de cualquier conjuro de evocación de mago que lances.": "You can add your Intelligence modifier to one damage roll of any wizard evocation spell you cast.",
  "Maximizas el daño de un conjuro de mago de niveles 1 a 5. El primer uso no tiene coste; usos adicionales antes de un descanso largo te infligen 2d12 de daño necrótico por nivel del conjuro.": "When you cast a wizard spell of 1st through 5th level that deals damage, you can deal maximum damage with that spell. The first time you do so, you suffer no adverse effect; if you use this feature again before you finish a long rest, you take 2d12 necrotic damage for each level of the spell.",
  "Acción: concentras gravedad en una criatura u objeto para duplicar o reducir a la mitad su peso durante 1 minuto, alterando su velocidad, salto y ventajas en Fuerza.": "Action: You alter the weight of one Large or smaller object or creature within 30 feet for up to 1 minute (concentration), either halving or doubling its weight to modify its speed, jump distance, and Strength checks and saving throws.",
  "Cuando golpees a una criatura con un ataque o conjuro, puedes moverla 5 pies en cualquier dirección hacia un espacio desocupado.": "Whenever you cast a spell on a creature, you can move the target 5 feet to an unoccupied space of your choice if the target is willing, the spell hits it with an attack, or it fails a saving throw against the spell.",
  "Reacción: aumentas el daño de impacto de una criatura que cae cerca de ti en 2d10, o aumentas el daño de un ataque con arma en 1d10.": "Reaction: When another creature you can see within 60 feet hits with a weapon attack, you can add 1d10 to the attack's damage; or when a creature within 60 feet takes damage from a fall, you can increase the fall's damage by 2d10.",
  "Acción: emites un campo gravitatorio de 30 pies durante 1 minuto. Los enemigos en el área sufren 2d10 de daño de fuerza y su velocidad se reduce a 0 si fallan salvación de Fuerza.": "Action: You emit a powerful field of gravitational energy in a 30-foot radius for 1 minute (concentration). Hostile creatures that start their turn in the area must make a Strength saving throw, taking 2d10 force damage and having their speed reduced to 0 on a failed save.",
  "Copiar conjuros de ilusión cuesta la mitad de oro y tiempo.": "The gold and time you must spend to copy an illusion spell into your spellbook is halved.",
  "Aprendes el truco Ilusión Menor. Al lanzarlo, puedes crear tanto un sonido como una imagen visual en el mismo conjuro.": "You learn the Minor Illusion cantrip. When you cast Minor Illusion, you can create both a sound and an image with a single casting of the spell.",
  "Acción: mientras una ilusión tuya con duración de 1 minuto o más esté activa, puedes alterar completamente su apariencia y naturaleza.": "Action: When you cast an illusion spell that has a duration of 1 minute or longer, you can use your action to change the nature of that illusion (using the spell's normal parameters for the illusion), provided that you can see the illusion.",
  "Reacción: cuando una criatura te ataque, creas un duplicado ilusorio que hace que ese ataque falle automáticamente (1 uso por descanso corto/largo).": "Reaction: When a creature makes an attack roll against you, you can interpose an illusory duplicate between the attacker and yourself. The attack automatically misses you, then the illusion dissipates (1 use per short or long rest).",
  "Acción adicional: puedes hacer que un objeto inanimado no mágico que forme parte de una de tus ilusiones se vuelva real durante 1 minuto.": "Bonus action: When you cast an illusion spell of 1st level or higher, you can choose one inanimate, nonmagical object that is part of the illusion and make that object real for 1 minute.",
  "Copiar conjuros de nigromancia cuesta la mitad de oro y tiempo.": "The gold and time you must spend to copy a necromancy spell into your spellbook is halved.",
  "Una vez por turno al matar una criatura con un conjuro de nivel 1+, recuperas puntos de golpe iguales al doble del nivel del conjuro (o el triple si es de nigromancia).": "Once per turn when you kill one or more creatures with a spell of 1st level or higher, you regain hit points equal to twice the spell's level, or three times its level if the spell belongs to the School of Necromancy.",
  "Aprendes Animar a los Muertos. Al lanzarlo, creas un no muerto adicional, y todos tus no muertos tienen sus puntos de golpe máximos aumentados por tu nivel de mago y añaden tu competencia a su daño.": "You add the Animate Dead spell to your spellbook. When you cast Animate Dead, you can target one additional corpse or pile of bones, and any undead you create with a necromancy spell has its hit point maximum increased by your wizard level and adds your proficiency bonus to its weapon damage rolls.",
  "Ganas resistencia al daño necrótico y tu total de puntos de golpe máximos no puede ser reducido.": "You have resistance to necrotic damage, and your hit point maximum can't be reduced.",
  "Acción: intentas poner bajo tu control permanente a un no muerto a 60 pies si falla una salvación de Carisma contra tu CD de conjuros.": "Action: Choose one undead that you can see within 60 feet of you. That creature must make a Charisma saving throw against your wizard spell save DC. If it fails, it becomes friendly to you and obeys your commands.",
  "Creas una pluma mágica que no gasta tinta y te permite copiar conjuros en tu libro en tan solo 2 minutos por nivel de conjuro.": "As a bonus action, you can Conjure a Tiny quill in your free hand. It doesn't require ink to write, and the time you must spend to copy a spell into your spellbook equals 2 minutes per spell level.",
  "Tu libro de conjuros despierta: puedes usarlo como foco arcano, puedes cambiar el tipo de daño de cualquier conjuro por el tipo de daño de otro conjuro en tu libro, y puedes lanzar un conjuro ritual con su tiempo normal de acción 1 vez por descanso largo.": "Your spellbook awakens with a sentient consciousness: you can use the book as a spellcasting focus, you can replace a spell's damage type with a damage type from another spell of the same level in your spellbook, and once per long rest you can cast a wizard ritual spell using its normal casting time rather than adding 10 minutes.",
  "Proyectas la mente de tu libro de conjuros como un avatar espectral flotante a 60 pies. Puedes ver y oír a través de él y lanzar conjuros como si estuvieras en su posición.": "As a bonus action, you can cause the mind of your Awakened Spellbook to manifest as a Tiny spectral object within 60 feet of you. You can see and hear through its senses and cast wizard spells as if you were in its space.",
  "Al terminar un descanso largo, fabricas un pergamino mágico de nivel 1 o 2 que cualquiera puede leer sin gastar componentes materiales.": "Whenever you finish a long rest, you can create one magic scroll by touching your Wizardly Quill to a blank piece of paper or parchment and choosing a 1st- or 2nd-level spell from your Awakened Spellbook.",
  "Si vas a recibir daño letal, tu libro se sacrifica para absorber todo el daño, borrando temporalmente páginas de conjuros que recuperas tras varios descansos.": "If you take damage while your spellbook's mind is manifested, you can prevent all of that damage to you by using your reaction to dismiss the spectral mind, temporarily losing access to 3d6 spell levels of spells in your book until 1d6 long rests pass.",
  "Copiar conjuros de transmutación cuesta la mitad de oro y tiempo.": "The gold and time you must spend to copy a transmutation spell into your spellbook is halved.",
  "Transmutas temporalmente madera, piedra, hierro, cobre o plata en otro de estos materiales durante 1 hora.": "You can temporarily alter the physical properties of one nonmagical object, changing it from one substance into another (wood, stone, iron, copper, or silver) for up to 1 hour.",
  "Creas una piedra mágica que otorga a quien la porte: Visión en la Oscuridad (60 pies), Velocidad +10 pies, Competencia en tiradas de salvación de Constitución, o Resistencia a un daño elemental.": "You can spend 8 hours creating a Transmuter's Stone that stores transmutation magic, granting its bearer one benefit of your choice: Darkvision (60 feet), an increase to speed of 10 feet, proficiency in Constitution saving throws, or resistance to acid, cold, fire, lightning, or thunder damage.",
  "Añades Polimorfar a tu libro de conjuros y puedes lanzarlo sobre ti mismo sin gastar ranura de conjuro una vez por descanso corto.": "You add the Polymorph spell to your spellbook. You can cast Polymorph without expending a spell slot to transform yourself into a beast whose challenge rating is 1 or lower once per short or long rest.",
  "Consumes tu piedra para ejecutar una proeza legendaria: Transformar un objeto en otro de igual tamaño, Restaurar vida y curar todas las maldiciones y enfermedades, o Resucitar a una criatura muerta recientemente.": "You can use your action to consume the reserve of transmutation magic stored within your Transmuter's Stone in a single burst: Major Transformation (transmute a 5-foot cube of nonmagical material), Panacea (remove all curses, diseases, and poisons and restore all hit points), Restore Life (cast Raise Dead without expending a spell slot), or Restore Youth.",
  "Reacción al ser atacado o fallar una salvación: obtienes +2 a la CA contra ese ataque o +4 a esa tirada de salvación.": "Reaction when you are hit by an attack or fail a saving throw: You gain a +2 bonus to your AC against that attack or a +4 bonus to that saving throw.",
  "Cada vez que termines un descanso o neutralices un conjuro con Contconjuro o Disipar Magia, almacenas energía para infligir daño de fuerza adicional igual a la mitad de tu nivel de mago.": "Whenever you finish a rest or successfully end a spell with Dispel Magic or Counterspell, you gain power surges that can deal extra force damage equal to half your wizard level.",
  "Mientras mantengas la concentración en un conjuro, ganas un bonificador de +2 a tu CA y +2 a todas tus tiradas de salvación.": "While you maintain concentration on a spell, you have a +2 bonus to AC and all saving throws.",
  "Cuando uses tu Deflexión Arcana, desatas chispas mágicas que infligen daño de fuerza a hasta tres criaturas a 60 pies igual a la mitad de tu nivel de mago.": "When you use your Arcane Deflection feature, magical energy arcs from you: up to three creatures of your choice within 60 feet of you each take force damage equal to half your wizard level.",
  "Canalizas energía de tu deidad para Expulsar Muertos Vivientes o activar el poder especial de tu Dominio Divino. Recarga en descanso corto.": "You channel divine energy directly from your deity to Turn Undead or fuel the special effect granted by your Divine Domain. Recharges on a short or long rest.",
  "Cada muerto viviente a 30 pies debe superar salvación de Sabiduría o huir aterrorizado durante 1 minuto.": "Each undead that can see or hear you within 30 feet of you must succeed on a Wisdom saving throw or be turned for 1 minute.",
  "Desbloqueas ranuras y conjuros divinos de 2.º nivel (Restauración Menor, Plegaria de Curación, Ayuda, Arma Espiritual).": "You unlock 2nd-level divine spell slots and spells (Lesser Restoration, Prayer of Healing, Aid, Spiritual Weapon).",
  "Cuando un muerto viviente falle su salvación contra tu Expulsar Muertos Vivientes, es destruido al instante si su Valor de Desafío es 1/2 o menor.": "When an undead fails its saving throw against your Turn Undead feature, the creature is instantly destroyed if its challenge rating is at or below 1/2.",
  "Desbloqueas conjuros divinos de 3.er nivel (Revivir, Guardianes Espirituales, Disipar Magia, Faro de Esperanza).": "You unlock 3rd-level divine spells (Revivify, Spirit Guardians, Dispel Magic, Beacon of Hope).",
  "Puedes usar Canalizar Divinidad 2 veces entre descansos cortos o largos, y obtienes un rasgo adicional de tu Dominio Divino.": "You can use your Channel Divinity twice between short or long rests, and you gain an additional feature from your Divine Domain.",
  "Desbloqueas conjuros divinos de 4.º nivel (Guardián de la Fe, Destierro, Protección contra la Muerte).": "You unlock 4th-level divine spells (Guardian of Faith, Banishment, Death Ward).",
  "Destruye instantáneamente muertos vivientes de VD 1 o menor al expulsarlos.": "Instantly destroys undead of CR 1 or lower when they fail their saving throw against your Turn Undead feature.",
  "Obtienes Golpe Divino (+1d8 de daño en armas) o Lanzamiento Potente (+Sabiduría a trucos) según tu dominio.": "You gain Divine Strike (+1d8 weapon damage) or Potent Spellcasting (+Wisdom modifier to cantrip damage) depending on your domain.",
  "Desbloqueas conjuros de 5.º nivel (Golpe Flamígero, Restauración Mayor, Curar Heridas en Masa, Revivir a los Muertos).": "You unlock 5th-level divine spells (Flame Strike, Greater Restoration, Mass Cure Wounds, Raise Dead).",
  "Pides ayuda a tu deidad en una situación desesperada. Tiras un d100: si el resultado es menor o igual a tu nivel de clérigo, la deidad interviene con el efecto de cualquier conjuro de clérigo o milagro a discreción del DM (1/7 días si tiene éxito).": "You can call on your deity to intervene on your behalf when your need is great. Roll percentile dice; if you roll a number equal to or lower than your cleric level, your deity intervenes with the effect of any cleric spell or domain spell as determined by the DM (usable again after 7 days on a success).",
  "Destruye instantáneamente muertos vivientes de VD 2 o menor al expulsarlos.": "Instantly destroys undead of CR 2 or lower when they fail their saving throw against your Turn Undead feature.",
  "Desbloqueas conjuros de 6.º nivel (Sanar, Festín de los Héroes, Dañar, Prohibición).": "You unlock 6th-level divine spells (Heal, Heroes' Feast, Harm, Forbiddance).",
  "Desbloqueas conjuros de 7.º nivel (Resurrección, Palabra Sagrada, Templo de los Dioses).": "You unlock 7th-level divine spells (Resurrection, Divine Word, Temple of the Gods).",
  "Destruye instantáneamente muertos vivientes de VD 3 o menor al expulsarlos.": "Instantly destroys undead of CR 3 or lower when they fail their saving throw against your Turn Undead feature.",
  "Desbloqueas conjuros de 8.º nivel (Aura Sagrada, Terremoto, Controlar el Clima).": "You unlock 8th-level divine spells (Holy Aura, Earthquake, Control Weather).",
  "Destruye instantáneamente muertos vivientes de VD 4 o menor al expulsarlos.": "Instantly destroys undead of CR 4 or lower when they fail their saving throw against your Turn Undead feature.",
  "Alcanzas el pináculo de poder y devoción de tu Dominio Divino.": "You reach the pinnacle of power and devotion of your Divine Domain.",
  "Desbloqueas conjuros legendarios de 9.º nivel (Sanar en Masa, Resurrección Verdadera, Portal Divino).": "You unlock legendary 9th-level divine spells (Mass Heal, True Resurrection, Gate).",
  "Puedes usar Canalizar Divinidad 3 veces entre descansos cortos o largos.": "You can use your Channel Divinity three times between short or long rests.",
  "Tu devoción es absoluta. Cuando uses Intervención Divina, tu llamada a la deidad tiene éxito automáticamente sin necesidad de tirar dados.": "Your devotion is absolute. When you use Divine Intervention, your call for intervention succeeds automatically; no dice roll is required.",
  "Competencia con armadura pesada.": "You gain proficiency with heavy armor.",
  "Tus conjuros de curación sanan 2 + nivel del conjuro puntos de golpe adicionales.": "Whenever you use a spell of 1st level or higher to restore hit points to a creature, the creature regains additional hit points equal to 2 + the spell's level.",
  "Sanas un pool de 5 x nivel de clérigo repartido entre aliados heridos a 30 pies.": "You restore a pool of hit points equal to five times your cleric level, divided as you choose among injured creatures within 30 feet of you (up to half a creature's hit point maximum).",
  "Cuando lanzas un conjuro de curación sobre otra criatura, tú también recuperas 2 + nivel del conjuro PG.": "When you cast a spell of 1st level or higher that restores hit points to a creature other than you, you regain hit points equal to 2 + the spell's level.",
  "Una vez por turno al impactar con arma sumas +1d8 de daño radiante (+2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage (increases to 2d8 at 14th level).",
  "En lugar de tirar dados para curar, usas el resultado máximo posible de cada dado.": "When you would normally roll one or more dice to restore hit points with a spell, you instead use the highest number possible for each die.",
  "Competencia con armas marciales y armaduras pesadas.": "You gain proficiency with martial weapons and heavy armor.",
  "Puedes realizar un ataque con arma como acción adicional (usos = Mod Sabiduría por descanso largo).": "When you use the Attack action, you can make one weapon attack as a bonus action (uses equal to your Wisdom modifier per long rest).",
  "Ganas un bonificador de +10 a una tirada de ataque que acabas de realizar.": "When you make an attack roll, you can use your Channel Divinity to gain a +10 bonus to the roll.",
  "Reacción: otorgas un bonificador de +10 a una tirada de ataque de un aliado a 30 pies.": "Reaction: When a creature within 30 feet of you makes an attack roll, you can use your Channel Divinity to grant that creature a +10 bonus to the roll.",
  "Una vez por turno al impactar con arma sumas +1d8 de daño del tipo del arma (+2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 damage of the same type dealt by the weapon (increases to 2d8 at 14th level).",
  "Ganas resistencia permanente al daño contundente, perforante y cortante de armas no mágicas.": "You gain resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks.",
  "Impones desventaja al ataque de un enemigo cercano usando tu reacción (usos = Mod. Sabiduría).": "When you are attacked by a creature within 30 feet of you that you can see, you can use your reaction to impose disadvantage on the attack roll (uses equal to your Wisdom modifier per long rest).",
  "Disipas oscuridad mágica a 30 pies e infliges 2d10 + nivel de daño radiante a enemigos en el área.": "You dispel any magical darkness within 30 feet of you and force each hostile creature within 30 feet to make a Constitution saving throw, taking radiant damage equal to 2d10 + your cleric level on a failed save, or half as much on a success.",
  "Puedes usar tu Destello Protector cuando un enemigo ataque a un aliado visible a 30 pies de ti.": "You can also use your Warding Flare feature when a creature that you can see within 30 feet of you attacks a creature other than you.",
  "Añades tu modificador de Sabiduría al daño de cualquier truco de clérigo.": "You add your Wisdom modifier to the damage you deal with any cleric cantrip.",
  "Emites un aura de luz solar de 60 pies que impone desventaja en salvaciones contra tus conjuros de fuego y radiantes.": "As an action, you activate an aura of sunlight in a 60-foot radius for 1 minute; enemies in the bright light have disadvantage on saving throws against any spell that deals fire or radiant damage.",
  "Al final de un descanso largo tocas un arma no mágica o armadura no mágica: gana un bonificador de +1 a las tiradas de ataque y daño, o un +1 a la CA si es una armadura, hasta tu siguiente descanso largo.": "At the end of a long rest, you can touch one nonmagical object that is a suit of armor or a simple or martial weapon: until the end of your next long rest, the object becomes a magic item, granting a +1 bonus to AC if it's armor or a +1 bonus to attack and damage rolls if it's a weapon.",
  "Realizas un ritual de 1 hora transmutando metales para fabricar cualquier objeto no mágico (armas, armaduras, herramientas, cadenas o llaves) cuyo valor no exceda 100 po.": "You conduct an hour-long ritual that crafts a nonmagical item that must include some metal (a weapon, a suit of armor, ten pieces of ammunition, a set of tools, or another metal object) worth no more than 100 gp.",
  "Ganas resistencia al daño de fuego permanente. Además, mientras lleves una armadura pesada ganas un bonificador de +1 a tu Clase de Armadura.": "You gain resistance to fire damage, and while wearing heavy armor, you gain a +1 bonus to AC.",
  "Una vez en cada uno de tus turnos cuando impactas a una criatura con un ataque de arma, infliges 1d8 de daño de fuego adicional (aumenta a 2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 fire damage to the target (increases to 2d8 at 14th level).",
  "Ganas inmunidad total al daño de fuego. Además, mientras lleves armadura pesada ganas resistencia al daño contundente, perforante y cortante de ataques no mágicos.": "You gain immunity to fire damage, and while wearing heavy armor, you have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks.",
  "Cuando una criatura a 5 pies de ti te impacte con un ataque, puedes usar tu reacción para infligirle 2d8 de daño de relámpago o trueno (a tu elección) si falla una salvación de Destreza (Sab mod veces/descanso largo).": "When a creature within 5 feet of you that you can see hits you with an attack, you can use your reaction to cause the creature to make a Dexterity saving throw, taking 2d8 lightning or thunder damage (your choice) on a failed save, or half as much on a success (Wisdom modifier uses per long rest).",
  "Cuando tires daño de relámpago o trueno, puedes usar Canalizar Divinidad para infligir el daño máximo posible en lugar de tirar los dados.": "When you roll lightning or thunder damage, you can use your Channel Divinity to deal maximum damage, instead of rolling.",
  "Cuando inflijas daño de relámpago a una criatura Grande o menor, puedes empujarla mágicamente hasta 10 pies lejos de ti.": "When you deal lightning damage to a Large or smaller creature, you can also push it up to 10 feet away from you.",
  "Una vez en cada uno de tus turnos al impactar con un arma, infliges 1d8 de daño de trueno adicional (aumenta a 2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 thunder damage to the target (increases to 2d8 at 14th level).",
  "Ganas una velocidad de vuelo igual a tu velocidad terrestre actual siempre que no estés bajo tierra ni en interiores sin cielo abierto.": "You have a flying speed equal to your current walking speed whenever you are not underground or indoors.",
  "Como acción tocas a una criatura dispuesta que no seas tú para otorgarle ventaja en pruebas de Destreza (Sigilo) durante 1 hora o hasta que vuelvas a usar este rasgo.": "As an action, you can touch a willing creature other than yourself to give it advantage on Dexterity (Stealth) checks for 1 hour or until you use this feature again.",
  "Como acción creas una ilusión perfecta de ti mismo a 30 pies durante 1 minuto. Puedes moverla hasta 30 pies como acción adicional, lanzar conjuros a través de su posición y ganar ventaja en ataques contra enemigos adyacentes a ambos.": "As an action, you create a perfect illusion of yourself within 30 feet of you that lasts for 1 minute (concentration). As a bonus action, you can move the illusion up to 30 feet, cast spells as though you were in its space, and gain advantage on attack rolls against a creature if both you and your illusion are within 5 feet of it.",
  "Como acción puedes volverte invisible hasta el final de tu siguiente turno o hasta que ataques o lances un conjuro.": "As an action, you can use your Channel Divinity to become invisible until the end of your next turn, or until you attack or cast a spell.",
  "Una vez en cada uno de tus turnos al golpear con un arma, infliges 1d8 de daño de veneno adicional (aumenta a 2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 poison damage to the target (increases to 2d8 at 14th level).",
  "Puedes crear hasta cuatro duplicados ilusorios con Invocar Duplicidad a la vez y mover cualquiera de ellos libremente en tu turno.": "You can create up to four duplicates of yourself, instead of one, when you use Invoke Duplicity, and as a bonus action on your turn, you can move any number of them up to 30 feet.",
  "Al lanzar un conjuro de curación sobre una criatura que tenga 0 puntos de golpe, cada dado de curación obtiene su resultado máximo posible. Además, aprendes el truco Piedad con los Moribundos y puedes lanzarlo como acción adicional con alcance de 30 pies.": "When you would normally roll one or more dice to restore hit points with a spell to a creature at 0 hit points, you instead use the highest number possible for each die. In addition, you learn the Spare the Dying cantrip, which has a range of 30 feet for you, and you can cast it as a bonus action.",
  "Como acción puedes detectar la presencia de cualquier criatura no muerta a 60 pies que no esté bajo cobertura total (Sab mod veces/descanso largo).": "As an action, you can open your awareness to magically detect undead within 60 feet of you that aren't behind total cover (Wisdom modifier uses per long rest).",
  "Como acción marcas a una criatura a 30 pies. El siguiente impacto que sufra de ti o de un aliado antes del final de tu siguiente turno vuelve a la criatura vulnerable a todo el daño infligido por ese ataque.": "As an action, you choose one creature you can see within 30 feet of you, cursing it until the end of your next turn. The next time you or an ally of yours hits the cursed creature with an attack, the creature has vulnerability to all of that attack's damage, and then the curse ends.",
  "Como reacción cuando tú o un aliado a 30 pies sufra un impacto crítico, anulas el crítico y conviertes el impacto en un golpe normal (Sab mod veces/descanso largo).": "As a reaction when you or a creature you can see within 30 feet of you suffers a critical hit, you can turn that hit into a normal hit (Wisdom modifier uses per long rest).",
  "Añades tu modificador de Sabiduría al daño que infliges con cualquier truco de clérigo.": "You add your Wisdom modifier to the damage you deal with any cleric cantrip.",
  "Cuando un enemigo muere a 60 pies de ti, tú o un aliado a 60 pies recupera puntos de golpe iguales al número de Dados de Golpe de la criatura caída.": "When an enemy you can see dies within 60 feet of you, you or one creature of your choice that is within 60 feet of you regains hit points equal to the enemy's number of Hit Dice.",
  "Aprendes dos idiomas adicionales y ganas competencia en dos habilidades entre Conocimiento Arcano, Historia, Naturaleza o Religión, duplicando tu bonificador de competencia en ellas.": "You learn two languages of your choice, and you become proficient in your choice of two of the following skills: Arcana, History, Nature, or Religion. Your proficiency bonus is doubled for any ability check you make that uses either of those skills.",
  "Como acción puedes canalizar sabiduría divina para obtener competencia con cualquier habilidad o herramienta a tu elección durante 10 minutos.": "As an action, you can use your Channel Divinity to tap into a divine well of knowledge, gaining proficiency with one skill or tool of your choice for 10 minutes.",
  "Como acción lees los pensamientos superficiales de una criatura a 60 pies si falla una salvación de Sabiduría, o lanzas Sugestión sobre ella sin gastar ranura.": "As an action, choose one creature that you can see within 60 feet of you; if it fails a Wisdom saving throw, you can read its surface thoughts for 1 minute, and during that time you can use your action to end this effect and cast the Suggestion spell on the creature without expending a spell slot.",
  "Añades tu modificador de Sabiduría al daño de tus trucos de clérigo.": "You add your Wisdom modifier to the damage you deal with any cleric cantrip.",
  "Puedes meditar para percibir acontecimientos ocurridos en un objeto o área en los últimos días, semanas o siglos.": "You can call up visions of the past that relate to an object you hold or your immediate surroundings by spending at least 1 minute in meditation and prayer.",
  "Aprendes un truco de druida a tu elección y ganas competencia con armaduras pesadas y una habilidad entre Trato con Animales, Naturaleza o Supervivencia.": "You learn one druid cantrip of your choice, and you gain proficiency with heavy armor and one of the following skills of your choice: Animal Handling, Nature, or Survival.",
  "Como acción puedes encantar a todas las bestias y plantas en un radio de 30 pies si fallan una salvación de Sabiduría durante 1 minuto.": "As an action, you present your holy symbol and invoke the name of your deity: each beast or plant creature that can see you within 30 feet of you must succeed on a Wisdom saving throw or be charmed by you for 1 minute.",
  "Como reacción cuando tú o una criatura a 30 pies reciba daño de ácido, frío, fuego, relámpago o trueno, concedes resistencia a ese tipo de daño contra ese ataque.": "When you or a creature within 30 feet of you takes acid, cold, fire, lightning, or thunder damage, you can use your reaction to grant resistance to the creature against that instance of the damage.",
  "Una vez por turno al golpear con un arma infliges 1d8 de daño adicional de frío, fuego o relámpago (2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 cold, fire, or lightning damage (your choice) to the target (increases to 2d8 at 14th level).",
  "Puedes comandar con acción adicional a cualquier criatura que tengas encantada con Encantar Animales y Plantas para que ataque a tus enemigos.": "You gain the ability to command animals and plant creatures. While creatures are charmed by your Charm Animals and Plants feature, you can take a bonus action on your turn to verbally command what each of those creatures will do on its next turn.",
  "Ganas visión en la oscuridad con un alcance colosal de 300 pies. Además, puedes compartir esta visión con hasta un número de criaturas igual a tu modificador de Sabiduría durante 1 hora.": "You gain darkvision out to a range of 300 feet. In addition, as an action, you can magically share the darkvision of this feature with willing creatures you can see within 10 feet of you, up to a number of creatures equal to your Wisdom modifier, for 1 hour.",
  "Como acción tocas a una criatura (incluyéndote a ti mismo) para concederle ventaja en su siguiente tirada de Iniciativa.": "As an action, you touch one creature (including possibly yourself) and give it advantage on the next initiative roll the creature makes.",
  "Como acción manifiestas una esfera de penumbra protectora de 30 pies de radio centrada en ti durante 1 minuto. Cuando una criatura (tú o un aliado) termine su turno en la esfera, puedes otorgarle 1d6 + tu nivel de clérigo en PG temporales o terminar un efecto que la deje Encantada o Asustada.": "As an action, you present your holy symbol, and a sphere of twilight emanates from you in a 30-foot radius for 1 minute. Whenever a creature (including you) ends its turn in the sphere, you can grant that creature temporary hit points equal to 1d6 plus your cleric level, or end one effect on it causing it to be charmed or frightened.",
  "Como acción adicional en luz tenue u oscuridad, puedes impulsarte místicamente para volar con una velocidad igual a tu velocidad terrestre durante 1 minuto (bono de competencia veces/descanso largo).": "As a bonus action when you are in dim light or darkness, you can magically give yourself a flying speed equal to your walking speed for 1 minute (proficiency bonus uses per long rest).",
  "Una vez por turno al impactar con un arma infliges 1d8 de daño radiante adicional (2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 radiant damage to the target (increases to 2d8 at 14th level).",
  "La penumbra de tu Santuario del Crepúsculo se vuelve tan densa que concede cobertura media (+2 a la CA y a salvaciones de Destreza) a ti y a todos tus aliados dentro de él.": "The twilight that you summon offers a protective embrace: you and your allies have half cover (+2 bonus to AC and Dexterity saving throws) while in the sphere created by your Twilight Sanctuary.",
  "Ganas competencia en la habilidad Persuasión, Perspicacia o Actuación.": "You gain proficiency in the Insight, Performance, or Persuasion skill (your choice).",
  "Como acción vinculas a un número de aliados a 30 pies igual a tu bonificador de competencia durante 10 minutos. Una vez en cada uno de sus turnos mientras estén a 30 pies el uno del otro, pueden sumar 1d4 a una tirada de ataque, prueba de característica o tirada de salvación.": "As an action, you can forge an empowering bond among a number of willing creatures within 30 feet of you (up to your proficiency bonus) for 10 minutes. While any bonded creature is within 30 feet of another, the creature can roll a d4 and add the number rolled to an attack roll, an ability check, or a saving throw it makes once per turn.",
  "Como acción te mueves hasta tu velocidad sin provocar ataques de oportunidad. Cada criatura a la que te acerques a 5 pies recupera 2d6 + tu modificador de Sabiduría en puntos de golpe.": "As an action, you can move up to your speed without provoking opportunity attacks, and when you move within 5 feet of any other creature during this action, you can restore a number of hit points to that creature equal to 2d6 + your Wisdom modifier.",
  "Cuando una criatura afectada por tu Vínculo Reconfortante esté a punto de recibir daño, otra criatura vinculada a 30 pies puede usar su reacción para teletransportarse a un espacio adyacente y absorber todo el daño en su lugar.": "When a creature affected by your Emboldening Bond feature is about to take damage, a second bonded creature within 30 feet of the first can use its reaction to teleport to an unoccupied space within 5 feet of the first creature and take all the damage instead.",
  "Añades tu modificador de Sabiduría al daño que infliges con tus trucos de clérigo.": "You add your Wisdom modifier to the damage you deal with any cleric cantrip.",
  "El alcance de tu Vínculo Protector aumenta a 60 pies, y cuando una criatura absorbe daño mediante el vínculo, gana resistencia a ese daño específico.": "The benefits of your Emboldening Bond and Protective Bond features now work when the creatures are within 60 feet of each other. Moreover, when a creature uses Protective Bond to take someone else's damage, the creature has resistance to that damage.",
  "Ganas competencia en Conocimiento Arcano y aprendes dos trucos de la lista de conjuros del Mago, que cuentan como trucos de clérigo para ti.": "You gain proficiency in the Arcana skill, and you gain two cantrips of your choice from the wizard spell list, which count as cleric cantrips for you.",
  "Puedes usar tu Expulsar No Muertos para afectar también a celestiales, elementales, fatas o infernales.": "As an action, you present your holy symbol and one celestial, elemental, fey, or fiend of your choice within 30 feet must make a Wisdom saving throw or be turned for 1 minute (or banished at higher levels).",
  "Al curar a un aliado con un conjuro de nivel 1 o superior, también terminas un conjuro de nivel igual o inferior sobre él como si lanzaras Disipar Magia.": "When you restore hit points to an ally with a spell of 1st level or higher, you can also end one spell of your choice on that creature whose level is equal to or lower than the level of the spell slot used to cast the healing spell.",
  "Eliges cuatro conjuros de la lista de mago (uno de nivel 6, uno de nivel 7, uno de nivel 8 y uno de nivel 9) y los añades como conjuros de dominio de clérigo siempre preparados.": "You choose four spells from the wizard spell list, one from each of the following levels: 6th, 7th, 8th, and 9th. You add them to your list of domain spells, and they are always prepared.",
  "Ganas competencia con todas las armas marciales.": "You gain proficiency with martial weapons.",
  "Cuando lanzas un truco de Nigromancia que normalmente afecte a un único objetivo (como Toque Helado o Piedad con los Moribundos), puedes elegir dos criaturas adyacentes a menos de 5 pies una de otra.": "You learn one necromancy cantrip of your choice from any spell list. When you cast a necromancy cantrip that normally targets only one creature, the spell can instead target two creatures within range and within 5 feet of each other.",
  "Al golpear con un ataque cuerpo a cuerpo infliges 5 + (2 × tu nivel de clérigo) de daño necrótico adicional.": "When you hit a creature with a melee attack, you can use Channel Divinity to deal extra necrotic damage to the target equal to 5 + twice your cleric level.",
  "Tu daño necrótico de conjuros y Canalizar Divinidad ignora la resistencia al daño necrótico de los enemigos.": "Necrotic damage dealt by your cleric spells and Channel Divinity options ignores resistance to necrotic damage.",
  "Una vez por turno al golpear con un arma infliges 1d8 de daño necrótico adicional (2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 necrotic damage to the target (increases to 2d8 at 14th level).",
  "Cuando lanzas un conjuro de Nigromancia de nivel 1 a 5 que apunte a una sola criatura, puedes hacer que afecte a una segunda criatura a 5 pies sin gastar ranuras adicionales.": "When you cast a necromancy spell of 1st through 5th level that targets only one creature, the spell can instead target two creatures within range and within 5 feet of each other.",
  "Al lanzar un conjuro de nivel 1 o superior sobre un aliado, ese aliado puede usar su reacción inmediatamente para realizar un ataque con arma contra una criatura a su elección.": "If you cast a spell with a spell slot of 1st level or higher and target an ally with the spell, that ally can use their reaction immediately after the spell to make one weapon attack against a creature of your choice that you can see.",
  "Como acción obligas a todas las criaturas a 30 pies a superar una salvación de Sabiduría o soltar lo que sostienen y quedar encantadas hasta tu siguiente turno.": "As an action, you present your holy symbol, and each creature of your choice that can see or hear you within 30 feet of you must succeed on a Wisdom saving throw or drop whatever it is holding and be charmed by you until the end of your next turn.",
  "Si lanzas un conjuro de la escuela de Encantamiento de nivel 1 o superior que requiera una acción, puedes lanzarlo como acción adicional (Sab mod veces/descanso largo).": "If you cast a spell of the enchantment school using a spell slot of 1st level or higher and the spell has a casting time of 1 action, you can change its casting time to 1 bonus action for this casting (Wisdom modifier uses per long rest).",
  "Una vez por turno al golpear con un arma infliges 1d8 de daño psíquico adicional (2d8 a nivel 14).": "Once on each of your turns when you hit a creature with a weapon attack, you can cause the attack to deal an extra 1d8 psychic damage to the target (increases to 2d8 at 14th level).",
  "Cuando inflijas daño con tu Golpe Divino a una criatura, queda maldita hasta tu siguiente turno; la primera vez que un aliado la golpee, sufre 2d8 de daño psíquico adicional.": "If you deal your Divine Strike damage to a creature on your turn, you can curse that creature until the start of your next turn; the next time one of your allies hits the cursed creature with an attack, the target also takes 2d8 psychic damage.",
  "Puedes tomar una acción adicional completa en tu turno, además de tu acción regular y cualquier acción adicional. Recarga tras un descanso corto o largo.": "You can take one additional action on your turn, on top of your regular action and a possible bonus action. Recharges on a short or long rest.",
  "Eliges el arquetipo que modela tu estilo de combate (Campeón, Maestro de Batalla, Caballero Arcano), obteniendo rasgos a niveles 3, 7, 10, 15 y 18.": "You choose an archetype that you strive to emulate in your combat styles and techniques (Champion, Battle Master, Eldritch Knight), gaining features at 3rd, 7th, 10th, 15th, and 18th level.",
  "Los guerreros entrenan más que nadie: ganas un aumento de característica en 2, dos en 1, o una Dote oficial.": "Fighters train more than anyone: you can increase one ability score by 2, two ability scores by 1, or take an official Feat.",
  "Obtienes un rasgo táctico otorgado por tu Arquetipo Marcial elegido a nivel 3.": "You gain a tactical feature granted by the Martial Archetype you chose at 3rd level.",
  "Puedes volver a tirar una tirada de salvación que hayas fallado. Debes usar el nuevo resultado. Recarga en descanso largo.": "You can reroll a saving throw that you fail. If you do so, you must use the new roll. Recharges on a long rest.",
  "Obtienes un rasgo avanzado de tu Arquetipo Marcial.": "You gain an advanced feature from your Martial Archetype.",
  "Puedes atacar tres veces en lugar de dos cuando realizas la acción de Atacar en tu turno.": "You can attack three times, instead of twice, whenever you take the Attack action on your turn.",
  "Puedes usar tu rasgo Indómito dos veces entre descansos largos.": "You can use your Indomitable feature twice between long rests.",
  "Ganas un nuevo aumento de característica en 2, dos en 1, o una Dote oficial.": "You gain a new ability score increase of +2 to one score, +1 to two scores, or an official Feat.",
  "Obtienes un rasgo de alta veteranía de tu Arquetipo Marcial.": "You gain a veteran feature from your Martial Archetype.",
  "Puedes usar Oleada de Acción dos veces antes de descansar, pero solo una vez en el mismo turno.": "You can use Action Surge twice before a rest, but only once on the same turn.",
  "Puedes usar tu rasgo Indómito tres veces entre descansos largos.": "You can use your Indomitable feature three times between long rests.",
  "Alcanzas la cumbre técnica de tu Arquetipo Marcial.": "You reach the technical pinnacle of your Martial Archetype.",
  "Eres la cúspide indiscutible del arte de la guerra. Puedes atacar cuatro veces en lugar de tres cuando realizas la acción de Atacar en tu turno.": "You are the undisputed pinnacle of the art of war. You can attack four times, instead of three, whenever you take the Attack action on your turn.",
  "Tus ataques con arma consiguen un impacto crítico con un resultado de 19 o 20 en el d20.": "Your weapon attacks score a critical hit on a roll of 19 or 20.",
  "Añades la mitad de tu bonificador de competencia a cualquier prueba de Fuerza, Destreza o Constitución que no la tenga ya, y tu distancia de salto en carrera aumenta.": "You can add half your proficiency bonus (round up) to any Strength, Dexterity, or Constitution check you make that doesn't already use your proficiency bonus, and your running long jump distance increases by a number of feet equal to your Strength modifier.",
  "Eliges un segundo Estilo de Combate de la lista de guerrero.": "You can choose a second option from the Fighting Style class feature.",
  "Tus ataques con arma consiguen un impacto crítico con un resultado de 18, 19 o 20 en el d20.": "Your weapon attacks score a critical hit on a roll of 18–20.",
  "Al inicio de cada uno de tus turnos recuperas 5 + Modificador de Constitución puntos de golpe si tienes menos de la mitad de tus PG máximos y no tienes 0 PG.": "At the start of each of your turns, you regain hit points equal to 5 + your Constitution modifier if you have no more than half of your hit points left and don't have 0 hit points.",
  "Ganas 4 dados de superioridad (d8) para ejecutar maniobras tácticas (Ataque con Finta, Barrido, Desarmar, Empujar, Maniobra Táctica, Parada, Provocación, Precisión).": "You gain four superiority dice (d8s) to fuel tactical maneuvers (Feinting Attack, Sweeping Attack, Disarming Attack, Pushing Attack, Maneuvering Attack, Parry, Goading Attack, Precision Attack).",
  "Ganas competencia con un tipo de herramientas de artesano de tu elección.": "You gain proficiency with one type of artisan's tools of your choice.",
  "Si observas o interactúas con una criatura fuera de combate durante al menos 1 minuto, el DM te revela si es igual, superior o inferior a ti en ciertas características (CA, PG, Fuerza, etc.).": "If you spend at least 1 minute observing or interacting with another creature outside combat, the DM tells you if the creature is your equal, superior, or inferior in regard to two characteristics of your choice (AC, hit points, Strength, etc.).",
  "Cuando tiras iniciativa y no te quedan dados de superioridad, recuperas 1 dado de superioridad.": "When you roll initiative and have no superiority dice remaining, you regain 1 superiority die.",
  "Aprendes trucos y conjuros de mago centrados en abjuración y evocación usando Inteligencia.": "You learn wizard cantrips and spells focused on the schools of abjuration and evocation, using Intelligence as your spellcasting ability.",
  "Creas un vínculo mágico con hasta 2 armas: no puedes ser desarmado de ellas y puedes invocarlas a tu mano como acción adicional desde cualquier distancia en el mismo plano.": "You forge a magical bond with up to two weapons: you can't be disarmed of a bonded weapon unless you are incapacitated, and you can summon it as a bonus action on your turn, causing it to teleport instantly to your hand if it is on the same plane of existence.",
  "Cuando usas tu acción para lanzar un truco, puedes realizar un ataque con arma como acción adicional.": "Beginning at 7th level, when you use your action to cast a cantrip, you can make one weapon attack as a bonus action.",
  "Cuando impactas a una criatura con un ataque con arma, esa criatura tiene desventaja en la próxima tirada de salvación que haga contra uno de tus conjuros antes del final de tu siguiente turno.": "When you hit a creature with a weapon attack, that creature has disadvantage on the next saving throw it makes against a spell you cast before the end of your next turn.",
  "Cuando usas tu Oleada de Acción, puedes teletransportarte hasta 30 pies a un espacio desocupado que puedas ver antes o después de la acción adicional.": "When you use your Action Surge, you can teleport up to 30 feet to an unoccupied space you can see before or after the additional action.",
  "Cuando usas tu acción para lanzar un conjuro, puedes realizar un ataque con arma como acción adicional.": "When you use your action to cast a spell, you can make one weapon attack as a bonus action.",
  "Como acción adicional manifiestas un eco traslúcido a 15 pies (CA 14 + prof, 1 PG). Puedes teletransportarte intercambiando posiciones con él por 15 pies de movimiento, realizar tus ataques de arma a través de la posición del eco, y efectuar ataques de oportunidad a través de él.": "As a bonus action, you can magically manifest a translucent echo of yourself in an unoccupied space you can see within 15 feet of you (AC 14 + proficiency bonus, 1 HP). You can use a bonus action to teleport and swap places with it at a cost of 15 feet of movement, make attacks from the echo's space, and make opportunity attacks as if you were in the echo's space.",
  "Cada vez que realizas la acción de Atacar, puedes hacer un ataque cuerpo a cuerpo adicional con arma a través de tu eco (Con mod veces/descanso largo).": "Whenever you take the Attack action, you can make one additional melee attack from the echo's position (Constitution modifier uses per long rest).",
  "Puedes proyectar tus sentidos a través de tu eco, controlándolo hasta una distancia de 1.000 pies de ti durante hasta 10 minutos.": "As an action, you can temporarily transfer your consciousness to your echo, seeing and hearing through it up to 1,000 feet away from you for up to 10 minutes.",
  "Como reacción cuando una criatura a la que puedas ver a 5 pies de tu eco es atacada, puedes hacer que tu eco intercepte el proyectil o golpe, convirtiéndose en el objetivo del ataque.": "Before an attack roll is made against a creature you can see within 5 feet of your echo, you can use your reaction to teleport the echo to an unoccupied space within 5 feet of the targeted creature, making the echo the target of the attack instead.",
  "Cuando tu eco es destruido por daño, ganas 2d6 + tu modificador de Constitución en puntos de golpe temporales.": "When an echo of yours is destroyed by taking damage, you can gain a number of temporary hit points equal to 2d6 + your Constitution modifier.",
  "Puedes manifestar dos ecos simultáneamente con tu rasgo Manifestar Eco. Además, si inicias un combate sin usos de Encarnación Desatada, recuperas un uso al instante.": "You can use a bonus action to create two echoes with your Manifest Echo feature instead of one. In addition, when you roll initiative and have no uses of your Unleash Incarnation feature left, you regain one use of that feature.",
  "Puedes grabar runas de gigante en tus armas y armaduras: Runa de Nube (reacción para redirigir un ataque enemigo a otro objetivo), Runa de Fuego (ataques apresan al enemigo con cadenas ardientes de 2d6 fuego), Runa de Frío (+2 a pruebas de característica de Fuerza/Con), Runa de Piedra (visión en la oscuridad y sumir en estupor a un enemigo), etc.": "You can inscribe magical giant runes onto your weapons, armor, or shield: Cloud Rune (use your reaction to redirect an attack roll to another creature within 30 feet), Fire Rune (shackle a hit target in fiery chains dealing 2d6 fire damage), Frost Rune (+2 bonus to all Strength and Constitution ability checks and saving throws for 10 minutes), Stone Rune (120-foot darkvision and charm a creature into a dreamy stupor as a reaction), etc.",
  "Como acción adicional creces a tamaño Grande durante 1 minuto: ganas ventaja en pruebas de Fuerza y salvaciones de Fuerza, y una vez en cada uno de tus turnos uno de tus ataques inflige 1d6 de daño adicional (aumenta a 1d8 a lvl 10).": "As a bonus action, you magically become Large for 1 minute: you have advantage on Strength checks and Strength saving throws, and once on each of your turns, one of your attacks with a weapon or an unarmed strike deals an extra 1d6 damage to a target on a hit (increases to 1d8 at 10th level).",
  "Como reacción cuando otra criatura a 60 pies sufra un impacto con tirada de ataque, puedes forzar al atacante a volver a tirar el d20 y usar el nuevo resultado (prof veces/descanso largo).": "When another creature you can see within 60 feet of you is hit by an attack roll, you can use your reaction to force the attacker to reroll the d20 and use the new roll (proficiency bonus uses per long rest).",
  "Tu altura aumenta permanentemente en 3d4 pulgadas. El daño extra de tu Poderío de los Gigantes aumenta a 1d8.": "Your height permanently increases by 3d4 inches, and the extra damage you deal with your Giant's Might feature increases to 1d8.",
  "Puedes invocar el poder activo de cada una de tus runas dos veces por cada descanso corto o largo en lugar de una.": "You can invoke each rune you know from your Rune Carver feature twice, rather than once, and you regain all expended uses when you finish a short or long rest.",
  "Con tu Poderío de los Gigantes puedes crecer hasta tamaño Enorme, tu alcance aumenta en 5 pies, y el daño adicional por turno aumenta a 1d10.": "The extra damage you deal with the Giant's Might feature increases to 1d10. Moreover, when you use that feature, your size can increase to Huge, and while you are that size, your reach increases by 5 feet.",
  "Obtienes dados de energía psiónica (d6 a d12). Puedes gastar dados para: Campo Protector (reacción para reducir daño sufrido por ti o un aliado a 30 pies en 1 dado + Int), Golpe Psiónico (una vez por turno tras impactar con arma sumas 1 dado + Int de daño de fuerza), o Movimiento Telequinético (mover objetos o criaturas aliadas hasta 30 pies como acción).": "You harbor a wellspring of Psionic Energy dice (d6 to d12). You can expend dice for: Protective Field (reaction to reduce damage taken by you or a creature within 30 feet by 1 die + your Intelligence modifier), Psionic Strike (once per turn after hitting a target within 30 feet with a weapon, deal extra force damage equal to 1 die + your Intelligence modifier), or Telekinetic Movement (move a Large or smaller loose object or willing creature up to 30 feet as an action).",
  "Como acción adicional te impulsas psiónicamente para ganar una velocidad de vuelo igual al doble de tu velocidad terrestre hasta el final del turno actual.": "As a bonus action, you can propel your body with your mind, gaining a flying speed equal to twice your walking speed until the end of the current turn.",
  "Ganas resistencia al daño psíquico. Si comienzas tu turno encantado o asustado, puedes gastar 1 dado de energía psiónica para disipar el efecto de inmediato.": "You have resistance to psychic damage. Moreover, if you start your turn charmed or frightened, you can expend a Psionic Energy die and end every effect on yourself subjecting you to those conditions.",
  "Como acción adicional puedes resguardar con telequinesis a un número de aliados a 30 pies igual a tu modificador de Inteligencia, concediéndoles cobertura media (+2 CA y salvaciones) durante 1 minuto.": "As a bonus action, you can choose creatures (including yourself) within 30 feet of you, up to a number equal to your Intelligence modifier (minimum of one creature), granting each of them half cover (+2 bonus to AC and Dexterity saving throws) for 1 minute.",
  "Puedes lanzar el conjuro Telequinesis sin componentes mágicos ni gastar ranura de conjuro, y mientras mantienes la concentración puedes realizar un ataque de arma como acción adicional.": "You can cast the Telekinesis spell requiring no components, and while you maintain concentration on the spell, you can make one weapon attack as a bonus action on each of your turns.",
  "Como acción adicional obtienes ventaja en todas tus tiradas de ataque con armas hasta el final del turno actual, y ganas 5 puntos de golpe temporales (aumenta a 10 a lvl 10 y 15 a lvl 15) (3/descanso largo).": "As a bonus action on your turn, you can give yourself advantage on weapon attack rolls until the end of the current turn, and you also gain 5 temporary hit points (increases to 10 at 10th level and 15 at 15th level) (3/long rest).",
  "Ganas competencia en Historia, Perspicacia, Actuación o Persuasión, y añades tu modificador de Sabiduría a cualquier prueba de Carisma (Persuasión). A nivel 7 ganas competencia en salvaciones de Sabiduría.": "You gain proficiency in History, Insight, Performance, or Persuasion, and whenever you make a Charisma (Persuasion) check, you gain a bonus to the check equal to your Wisdom modifier. At 7th level, you also gain proficiency in Wisdom saving throws.",
  "Si tiras Iniciativa y no te queda ningún uso de Espíritu de Lucha, recuperas un uso de inmediato.": "When you roll initiative and have no uses of Fighting Spirit remaining, you regain one use.",
  "Si tienes ventaja en una tirada de ataque con arma en tu turno, puedes renunciar a la ventaja para realizar un ataque adicional con arma contra el mismo u otro objetivo.": "If you take the Attack action on your turn and have advantage on an attack roll against one of the targets, you can forgo the advantage for that roll to make an additional weapon attack against that target, as part of the same action.",
  "Si sufres daño que te reduciría a 0 puntos de golpe y no te mata directamente, puedes usar tu reacción para interrumpir el turno actual y tomar un turno completo de inmediato antes de caer inconsciente.": "If you take damage that reduces you to 0 hit points and doesn't kill you outright, you can use your reaction to delay falling unconscious, and you can immediately take an extra turn, interrupting the current turn.",
  "Una vez por turno al disparar una flecha con arco corto o arco largo puedes desatar una flecha mágica especial (2 usos/descanso corto o largo): Flecha de Destierro (destierra al objetivo a otro plano si falla Car), Flecha Enredadera (enreda con espinas que hacen 2d6 daño si se mueve), Flecha Explosiva (explosión de 2d6 daño de fuerza en área), Flecha Perforante (atraviesa una línea de 30 pies ignorando cobertura), o Flecha Debilitadora (reduce el daño a la mitad).": "Once per turn when you fire an arrow from a shortbow or longbow, you can apply one of your Arcane Shot options to that arrow (2 uses per short or long rest): Banishing Arrow (banishes the target to the Feywild on a failed Charisma save), Grasping Arrow (deals 2d6 poison damage and wraps the target in brambles that deal 2d6 slashing damage when it moves), Bursting Arrow (detonates for 2d6 force damage in a 10-foot radius), Piercing Arrow (passes harmlessly through objects in a 30-foot line), or Enfeebling Arrow (halves the damage dealt by the target's weapon attacks on a failed Constitution save).",
  "Tus flechas no mágicas disparadas con arco cuentan como mágicas. Además, cuando fallas un disparo con flecha, puedes usar tu acción adicional para redirigir la flecha contra otro objetivo a 60 pies.": "Whenever you fire a nonmagical arrow from a shortbow or longbow, you can make it magical for the purpose of overcoming resistance and immunity. In addition, when you make an attack roll with a magic arrow and miss, you can use a bonus action to reroll the attack roll against a different target within 60 feet of the original target.",
  "Si tiras Iniciativa y no te quedan usos de Disparo Arcano, recuperas un uso de inmediato.": "When you roll initiative and have no uses of Arcane Shot remaining, you regain one use of it.",
  "Todos tus Disparos Arcanos aumentan sus dados de daño adicional a 4d6.": "The extra damage of all your Arcane Shot options increases to 4d6.",
  "Montar o desmontar solo te cuesta 5 pies de movimiento en lugar de la mitad, tienes ventaja en salvaciones para no caer de tu montura y caes siempre de pie si eres derribado.": "Mounting or dismounting a creature costs you only 5 feet of movement, rather than half your speed. In addition, you have advantage on saving throws made to avoid falling off your mount, and if you fall off your mount and descend no more than 10 feet, you can land on your feet if you're not incapacitated.",
  "Al golpear a un enemigo cuerpo a cuerpo lo marcas hasta tu siguiente turno: mientras esté a 5 pies de ti tiene desventaja en ataques contra cualquiera que no seas tú. Si daña a otro, en tu turno siguiente puedes hacer un ataque cuerpo a cuerpo adicional con ventaja contra él que añade la mitad de tu nivel al daño.": "When you hit a creature with a melee weapon attack, you can mark the creature until the end of your next turn: while it is within 5 feet of you, a creature marked by you has disadvantage on any attack roll that doesn't target you. In addition, if a creature marked by you deals damage to anyone other than you, you can make a special melee weapon attack against the marked creature as a bonus action on your next turn with advantage and extra damage equal to half your fighter level.",
  "Como reacción cuando tú o una criatura a 5 pies sea impactada, añades 1d8 a la CA del objetivo; si el ataque impacta aun así, el objetivo gana resistencia al daño de ese ataque.": "If you or a creature you can see within 5 feet of you is hit by an attack, you can roll 1d8 as a reaction if you're wielding a melee weapon or a shield, adding the number rolled to the target's AC against that attack; if the attack still hits, the target has resistance against the attack's damage.",
  "Las criaturas provocan ataques de oportunidad de tu parte cuando se mueven a 5 pies o más dentro de tu alcance. Si impactas con un ataque de oportunidad, la velocidad del enemigo se reduce a 0 durante el resto del turno.": "Creatures provoke an opportunity attack from you when they move 5 feet or more while within your reach, and if you hit a creature with an opportunity attack, the target's speed is reduced to 0 until the end of the current turn.",
  "Si te mueves al menos 10 pies en línea recta antes de golpear a una criatura, debe superar una salvación de Fuerza (CD 8 + prof + Fue) o caer derribada.": "If you move at least 10 feet in a straight line right before attacking a creature and you hit it with the attack, that target must succeed on a Strength saving throw (DC 8 + your proficiency bonus + your Strength modifier) or be knocked prone.",
  "En combate ganas una reacción especial en el turno de cada criatura que solo puedes usar para realizar un ataque de oportunidad.": "In combat, you get a special reaction that you can take once on every creature's turn, except your turn, which you can use only to make an opportunity attack.",
  "Cuando utilizas tu rasgo de Segundo Aire, puedes elegir hasta tres criaturas aliadas a menos de 60 pies de ti que puedan verte u oírte. Cada una de ellas recupera un número de puntos de golpe igual a tu nivel de guerrero, siempre que no estén incapacitadas.": "When you use your Second Wind feature, you can choose up to three creatures within 60 feet of you that are allied with you. Each one regains hit points equal to your fighter level, provided that the creature can see or hear you and isn't incapacitated.",
  "Ganas competencia en la habilidad de Persuasión. Si ya tenías competencia en ella, puedes elegir Trato con Animales, Perspicacia, Intimidación o Historia. Además, tu bonificador de competencia se duplica para cualquier prueba de característica que hagas usando Persuasión.": "You gain proficiency in the Persuasion skill. If you are already proficient in it, you gain proficiency in one of the following skills of your choice: Animal Handling, Insight, Intimidation, or Performance. Your proficiency bonus is doubled for any ability check you make that uses Persuasion.",
  "Cuando utilizas tu Oleada de Acción (Action Surge) en tu turno, puedes elegir a un aliado a menos de 60 pies de ti que pueda verte u oírte. Ese aliado puede usar inmediatamente su reacción para realizar un ataque de arma cuerpo a cuerpo o a distancia.": "When you use your Action Surge feature, you can choose one creature within 60 feet of you that is allied with you. That creature can make one melee or ranged weapon attack with its reaction, provided that it can see or hear you.",
  "Cuando utilizas tu rasgo Indomable para relanzar una tirada de salvación de Inteligencia, Sabiduría o Carisma que fallaste, puedes elegir a un aliado a menos de 60 pies de ti que haya fallado su salvación contra el mismo efecto. Si no está incapacitado, puede relanzar su tirada de salvación con ventaja.": "When you use your Indomitable feature to reroll an Intelligence, a Wisdom, or a Charisma saving throw and you aren't incapacitated, you can choose one ally within 60 feet of you that also failed its saving throw against the same effect. If that creature can see or hear you, it can reroll its saving throw and must use the new roll.",
  "Eliges un arquetipo (Asesino, Ladrón, Embaucador Arcano), obteniendo rasgos especiales a niveles 3, 9, 13 y 17.": "You choose an archetype that you emulate in the exercise of your rogue abilities (Assassin, Thief, Arcane Trickster), gaining features at 3rd, 9th, 13th, and 17th level.",
  "El daño de tu Ataque Furtivo aumenta a 2d6.": "Your Sneak Attack damage increases to 2d6.",
  "Reacción: cuando un atacante que puedas ver te impacta con un ataque, reduces el daño recibido a la mitad.": "Reaction: When an attacker that you can see hits you with an attack, you can use your reaction to halve the attack's damage against you.",
  "El daño de tu Ataque Furtivo aumenta a 3d6.": "Your Sneak Attack damage increases to 3d6.",
  "Eliges otras dos de tus competencias de habilidad (o tus herramientas de ladrón) para duplicar tu bonificador de competencia.": "You can choose two more of your skill proficiencies (or one skill proficiency and your proficiency with thieves' tools) to double your proficiency bonus for any ability check you make that uses either of the chosen proficiencies.",
  "Tu agilidad instintiva te permite esquivar efectos de área (como una Bola de Fuego). Si una salvación de Destreza te permite recibir la mitad del daño al tener éxito, no recibes daño si tienes éxito, y solo la mitad si fallas.": "Your instinctive agility lets you dodge out of the way of certain area effects (such as a Fireball spell). When you are subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw, and only half damage if you fail.",
  "El daño de tu Ataque Furtivo aumenta a 4d6.": "Your Sneak Attack damage increases to 4d6.",
  "Obtienes un nuevo rasgo otorgado por el arquetipo elegido a nivel 3.": "You gain a new feature granted by the Roguish Archetype you chose at 3rd level.",
  "El daño de tu Ataque Furtivo aumenta a 5d6.": "Your Sneak Attack damage increases to 5d6.",
  "Los pícaros obtienen una mejora de característica o Dote adicional a nivel 10.": "Rogues gain an additional Ability Score Improvement or Feat at 10th level.",
  "Has perfeccionado tus habilidades hasta la perfección: siempre que hagas una prueba de característica que use tu bonificador de competencia, cualquier resultado de 9 o menos en el d20 cuenta como un 10.": "You have refined your chosen skills until they approach perfection: whenever you make an ability check that lets you add your proficiency bonus, you can treat a d20 roll of 9 or lower as a 10.",
  "El daño de tu Ataque Furtivo aumenta a 6d6.": "Your Sneak Attack damage increases to 6d6.",
  "Obtienes un rasgo avanzado de tu arquetipo de pícaro.": "You gain an advanced feature from your Roguish Archetype.",
  "El daño de tu Ataque Furtivo aumenta a 7d6.": "Your Sneak Attack damage increases to 7d6.",
  "Si puedes oír, eres consciente de la ubicación exacta de cualquier criatura oculta o invisible a 10 pies de ti.": "If you are able to hear, you are aware of the location of any hidden or invisible creature within 10 feet of you.",
  "Has adquirido una gran fuerza mental: ganas competencia en tiradas de salvación de Sabiduría.": "You have acquired greater mental strength: you gain proficiency in Wisdom saving throws.",
  "El daño de tu Ataque Furtivo aumenta a 8d6.": "Your Sneak Attack damage increases to 8d6.",
  "Obtienes el rasgo supremo de tu arquetipo de pícaro.": "You gain the supreme feature of your Roguish Archetype.",
  "El daño de tu Ataque Furtivo aumenta a 9d6.": "Your Sneak Attack damage increases to 9d6.",
  "Eres tan escurridizo que los atacantes rara vez ganan ventaja contra ti: ninguna tirada de ataque contra ti puede tener ventaja mientras no estés incapacitado.": "You are so evasive that attackers rarely gain the upper hand against you: no attack roll has advantage against you while you aren't incapacitated.",
  "Tienes un don infalible para triunfar cuando lo necesitas: si tu ataque falla contra un objetivo a tu alcance, puedes convertir el fallo en un impacto; o si fallas una prueba de característica, puedes tratar la tirada de d20 como un 20 (1 uso por descanso corto o largo).": "You have an uncanny knack for succeeding when you need to: if your attack misses a target within range, you can turn the miss into a hit; alternatively, if you fail an ability check, you can treat the d20 roll as a 20 (1 use per short or long rest).",
  "El daño de tu Ataque Furtivo alcanza su poder máximo de 10d6.": "Your Sneak Attack damage reaches its maximum power of 10d6.",
  "Tienes ventaja en tiradas de ataque contra cualquier criatura que aún no haya actuado en el combate. Además, cualquier impacto que asestes contra una criatura sorprendida es un impacto crítico automático.": "You have advantage on attack rolls against any creature that hasn't taken a turn in the combat yet. In addition, any hit you score against a creature that is surprised is a critical hit.",
  "Ganas competencia con el kit de disfraz y el kit de envenenador.": "You gain proficiency with the disguise kit and the poisoner's kit.",
  "Puedes crear identidades falsas impenetrables con documentación, historia personal e indumentaria.": "You can unfailingly create false identities for yourself, complete with documentation, established acquaintances, and disguises.",
  "Puedes imitar a la perfección el habla, escritura y comportamiento de otra persona tras estudiarla 3 horas.": "You gain the ability to unerringly mimic another person's speech, writing, and behavior after spending at least 3 hours studying them.",
  "Cuando sorprendes y golpeas a una criatura, debe superar salvación de Constitución CD (8 + Des + prof) o el daño de tu ataque se duplica.": "When you attack and hit a creature that is surprised, it must make a Constitution saving throw (DC 8 + your Dexterity modifier + your proficiency bonus). On a failed save, double the damage of your attack against the creature.",
  "Puedes usar la acción adicional de tu Acción Astuta para realizar una prueba de Juego de Manos, usar tus herramientas de ladrón para desarmar trampas o abrir cerraduras, o tomar la acción de Usar un Objeto.": "You can use the bonus action granted by your Cunning Action to make a Dexterity (Sleight of Hand) check, use your thieves' tools to disarm a trap or open a lock, or take the Use an Object action.",
  "Trepar ya no te cuesta movimiento adicional y tu distancia al saltar en carrera aumenta en pies iguales a tu modificador de Destreza.": "Climbing no longer costs you extra movement, and when you make a running jump, the distance you cover increases by a number of feet equal to your Dexterity modifier.",
  "Tienes ventaja en pruebas de Sigilo si no te mueves más de la mitad de tu velocidad en ese turno.": "You have advantage on a Dexterity (Stealth) check if you move no more than half your speed on the same turn.",
  "Ignoras todos los requisitos de clase, raza y nivel para la sintonización y uso de cualquier objeto mágico.": "You ignore all class, race, and level requirements on the use of magic items.",
  "Puedes tomar dos turnos completos durante el primer asalto de cualquier combate (el primero en tu iniciativa y el segundo en iniciativa - 10).": "You can take two turns during the first round of any combat (your first turn at your normal initiative and your second turn at your initiative minus 10).",
  "Aprendes trucos y conjuros de mago de las escuelas de ilusión y encantamiento usando Inteligencia.": "You learn wizard cantrips and spells from the schools of enchantment and illusion, using Intelligence as your spellcasting ability.",
  "Al lanzar Mano de Mago puedes hacerla invisible y usarla como acción adicional para guardar o sustraer objetos de bolsillos o abrir cerraduras a distancia.": "When you cast Mage Hand, you can make the spectral hand invisible, and you can control the hand as a bonus action to stow or retrieve objects or use thieves' tools to pick locks and disarm traps at range.",
  "Si estás oculto cuando lanzas un conjuro a una criatura, esa criatura tiene desventaja en la salvación contra ese conjuro este turno.": "If you are hidden from a creature when you cast a spell on it, the creature has disadvantage on any saving throw it makes against the spell this turn.",
  "Como acción adicional puedes usar tu Mano de Mago para distraer a un objetivo a 5 pies de ella, ganando ventaja en tus ataques contra él hasta el final del turno.": "As a bonus action on your turn, you can designate a creature within 5 feet of the spectral hand created by your Mage Hand spell to distract it, giving you advantage on attack rolls against that creature until the end of the turn.",
  "Reacción cuando una criatura lance un conjuro contra ti: niegas el conjuro si falla salvación de Int y puedes lanzarlo tú durante 8 horas.": "Reaction when a creature casts a spell that targets you or includes you in its area of effect: the creature must make a saving throw against your spell save DC. On a failed save, you negate the spell's effect against you and steal the knowledge of the spell for 8 hours if it is at least 1st level and of a level you can cast.",
  "Durante tu turno, si realizas un ataque de arma cuerpo a cuerpo contra una criatura, esa criatura no puede realizar ataques de oportunidad contra ti durante el resto de tu turno.": "During your turn, if you make a melee attack against a creature, that creature can't make opportunity attacks against you for the rest of your turn.",
  "Añades tu modificador de Carisma a tus tiradas de Iniciativa. Además, ganas una nueva forma de usar tu Ataque Furtivo: puedes usarlo contra un objetivo si estás a 5 pies de él, ninguna otra criatura está a 5 pies de ti, y no tienes desventaja en la tirada.": "You can give yourself a bonus to your initiative rolls equal to your Charisma modifier. You also gain an additional way to use your Sneak Attack: you don't need advantage on the attack roll to use your Sneak Attack against a creature if you are within 5 feet of it, no other creatures are within 5 feet of you, and you don't have disadvantage on the attack roll.",
  "Como acción haces una prueba de Carisma (Persuasión) enfrentada a la Sabiduría (Perspicacia) de un objetivo: fuera de combate queda encantado por 1 minuto; en combate queda provocado y tiene desventaja en ataques contra otros que no seas tú.": "As an action, you can make a Charisma (Persuasion) check contested by a creature's Wisdom (Insight) check: if the creature is not hostile, it is charmed by you for 1 minute; if it is hostile, it has disadvantage on attack rolls against targets other than you and can't make opportunity attacks against targets other than you for 1 minute.",
  "Como acción adicional puedes ganar ventaja en la siguiente prueba de Destreza (Acrobacias) o Fuerza (Atletismo) que realices durante el mismo turno.": "You can use a bonus action on your turn to gain advantage on the next Dexterity (Acrobatics) or Strength (Athletics) check you make during the same turn.",
  "Si fallas una tirada de ataque en tu turno, puedes volver a tirar la tirada con ventaja (1/descanso corto o largo).": "If you miss with an attack roll on your turn, you can roll it again with advantage (1/short or long rest).",
  "Cada vez que realices una prueba de Sabiduría (Perspicacia) para determinar si una criatura miente, puedes tratar cualquier resultado de 7 o menor en el d20 como un 8.": "Whenever you make a Wisdom (Insight) check to determine whether a creature is lying, treat a roll of 7 or lower on the d20 as an 8.",
  "Puedes usar tu acción adicional para hacer una prueba de Sabiduría (Percepción) para detectar una criatura oculta o una prueba de Inteligencia (Investigación) para descubrir pistas.": "You can use a bonus action to make a Wisdom (Perception) check to spot a hidden creature or object or to make an Intelligence (Investigation) check to uncover or decipher clues.",
  "Como acción adicional haces una prueba de Perspicacia enfrentada al Engaño de un enemigo. Si vences, puedes usar tu Ataque Furtivo contra ese objetivo durante 1 minuto incluso si no tienes ventaja en el ataque.": "As a bonus action, you can make a Wisdom (Insight) check against a creature you can see that isn't incapacitated, contested by the target's Charisma (Deception) check. If you succeed, you can use your Sneak Attack against that target even if you don't have advantage on the attack roll, but not if you have disadvantage on it, for 1 minute.",
  "Tienes ventaja en cualquier prueba de Sabiduría (Percepción) o Inteligencia (Investigación) si te mueves a no más de la mitad de tu velocidad durante el mismo turno.": "You have advantage on any Wisdom (Perception) or Intelligence (Investigation) check if you move no more than half your speed on the same turn.",
  "Como acción percibes la presencia de ilusiones mágicas o metamorfos a 30 pies (Sab mod veces/descanso largo).": "As an action, you sense the presence of any illusions, shapechangers not in their original form, and other magic designed to deceive the senses within 30 feet of you (Wisdom modifier uses per long rest).",
  "Tu daño de Ataque Furtivo aumenta en 3d6 adicionales contra el objetivo señalado por tu Lucha Perspicaz.": "Your Sneak Attack damage against a creature targeted by your Insightful Fighting feature increases by 3d6.",
  "Ganas competencia con kit de disfraz, kit de falsificación, un juego de azar y dos idiomas adicionales. Puedes imitar el habla y acentos de otras criaturas tras escucharlas durante 1 minuto.": "You gain proficiency with the disguise kit, the forgery kit, one gaming set of your choice, and two languages of your choice. You can also unerringly mimic the speech patterns and accent of a creature that you hear speak for at least 1 minute.",
  "Puedes usar la acción de Ayudar como acción adicional. Además, cuando usas Ayudar para respaldar el ataque de un aliado, el alcance aumenta de 5 a 30 pies.": "You can use the Help action as a bonus action. Additionally, when you use the Help action to aid an ally in attacking a creature, the target of that attack can be within 30 feet of you, rather than within 5 feet of you.",
  "Si observas a una criatura durante al menos 1 minuto fuera de combate, descubres si su puntuación de Inteligencia, Sabiduría o Carisma es superior, igual o inferior a la tuya.": "If you spend at least 1 minute observing or interacting with another creature outside combat, you can learn whether the creature is your equal, superior, or inferior in regard to two of the following characteristics: Intelligence score, Wisdom score, Charisma score, or class levels.",
  "Como reacción cuando seas el objetivo de un ataque mientras una criatura a 5 pies de ti te proporcione cobertura, puedes hacer que el ataque se dirija a esa criatura en tu lugar.": "When you are targeted by an attack while a creature within 5 feet of you is granting you cover against that attack, you can use your reaction to have the attack target that creature instead of you.",
  "Tus pensamientos no pueden ser leídos por telepatía u otra magia a menos que lo permitas, y los efectos mágicos para determinar si dices la verdad indican siempre que estás diciendo la verdad.": "Your thoughts can't be read by telepathy or other means unless you allow it, you can present false thoughts by succeeding on a Charisma (Deception) check, and magic that would determine if you are telling the truth indicates that you are being truthful if you so choose.",
  "Al terminar un descanso corto o largo adquieres la presencia de un espíritu que te concede competencia en una habilidad o herramienta a tu elección hasta tu siguiente descanso.": "Whenever you finish a short or long rest, you can choose one skill or tool proficiency that you lack and gain it, as a ghostly presence shares its knowledge with you until you use this feature again.",
  "Inmediatamente después de infligir daño con tu Ataque Furtivo a una criatura, una segunda criatura a 30 pies sufre daño necrótico igual a la mitad de tus dados de Ataque Furtivo (prof veces/descanso largo).": "Immediately after you deal your Sneak Attack damage to a creature on your turn, you can target a second creature that you can see within 30 feet of the first creature; roll half the number of Sneak Attack dice for your level (round up), and the second creature takes necrotic damage equal to the roll's total (proficiency bonus uses per long rest).",
  "Cuando una criatura muere a 30 pies de ti, puedes usar tu reacción para capturar su esencia como una baratija de alma. Mientras lleves una ficha tienes ventaja en salvaciones de muerte y de Constitución, y puedes destruir una ficha para hacer una pregunta al espíritu o activar Lamentos de la Tumba sin gastar usos.": "When a life ends in your presence (a creature you can see within 30 feet dies), you can use your reaction to snatch a token of its departing soul in a Tiny trinket. While a soul trinket is on your person, you have advantage on death saving throws and Constitution saving throws, and you can destroy a trinket to use Wails from the Grave without expending a use or to ask its spirit a question.",
  "Como acción adicional adquieres una forma espectral durante 10 minutos: ganas velocidad de vuelo de 10 pies, los ataques contra ti tienen desventaja y puedes atravesar paredes y criaturas sólidas.": "As a bonus action, you phase partially into the realm of the dead, becoming like a ghost for 10 minutes: you gain a flying speed of 10 feet and can hover, attack rolls have disadvantage against you, and you can move through creatures and objects as if they were difficult terrain.",
  "Al usar Lamentos de la Tumba, tanto el primer objetivo como el segundo sufren el daño necrótico completo. Además, si inicias un combate sin fichas de alma, aparece una ficha en tu mano de inmediato.": "When you use your Wails from the Grave, you can deal the necrotic damage to both the first and the second creature. In addition, at the end of a long rest, a soul trinket appears in your hand if you don't have any soul trinkets on your person.",
  "Ganas dados de energía psiónica (d6 a d12). Puedes usarlos para: Truco Psiónico (sumar el dado a una prueba de habilidad fallada en la que tengas competencia sin gastar el dado si sigues fallando) o Vínculo Telepático (establecer enlace telepático mental a millas de distancia con hasta tu bonificador de competencia de aliados durante horas).": "You harbor a wellspring of Psionic Energy dice (d6 to d12). You can use them for: Psi-Bolstered Knack (when your nonpsionic training fails you on an ability check using a skill or tool you are proficient in, roll a Psionic Energy die and add it, expending the die only if the check succeeds) or Psychic Whispers (establish telepathic communication for a number of hours equal to the roll with up to your proficiency bonus in creatures within 1 mile).",
  "Puedes manifestar dagas de energía psiónica reluciente en tus manos vacías: causan 1d6 de daño psíquico (+ mod Des) y tienen alcance arrojadizo 60 pies. Si atacas con una hoja psíquica en tu turno, puedes hacer un segundo ataque con tu acción adicional con otra hoja que inflige 1d4 psíquico.": "Whenever you take the Attack action, you can manifest a psychic blade from your free hand: it is a simple melee weapon with the finesse and thrown properties (range 60 feet) that deals 1d6 psychic damage plus your ability modifier. After you attack with the blade, you can make a melee or ranged weapon attack with a second psychic blade as a bonus action on the same turn, dealing 1d4 psychic damage.",
  "Puedes impulsar tus hojas con dados psiónicos: Ataque Guiado (sumar el dado a un ataque de hoja fallado) o Teletransporte Psiónico (lanzar una hoja como acción adicional y teletransportarte a su ubicación).": "You can aid your knifework with psionic power: Homing Strikes (if you make an attack roll with your Psychic Blades and miss the target, roll one Psionic Energy die and add it to the attack roll, expending the die only if it hits) or Psychic Teleportation (as a bonus action, expend one Psionic Energy die, hurl a blade up to 10 times the number rolled in feet, and teleport to that space).",
  "Como acción puedes volverte invisible mágicamente durante 1 hora (o hasta que inflijas daño o fuerces una salvación) (1/descanso largo o gastando un dado psiónico).": "As an action, you can weave a veil of psychic static to mask yourself, becoming invisible for 1 hour or until you deal damage to a creature or force a creature to make a saving throw (1/long rest or by expending a Psionic Energy die).",
  "Cuando inflijas daño con tu Ataque Furtivo usando tus Hojas Psíquicas, fuerzas a la víctima a una salvación de Sabiduría (CD 8 + prof + Des) o quedará aturdida durante 1 minuto.": "When you use your Psychic Blades to deal Sneak Attack damage to a creature, you can force that target to make a Wisdom saving throw (DC 8 + your proficiency bonus + your Dexterity modifier) or be stunned for 1 minute (1/long rest or by expending three Psionic Energy dice).",
  "Ganas competencia en Naturaleza y Supervivencia, y tu bonificador de competencia se duplica para cualquier prueba de característica que utilice cualquiera de esas dos habilidades.": "You gain proficiency in the Nature and Survival skills, and your proficiency bonus is doubled for any ability check you make that uses either of those proficiencies.",
  "Como reacción cuando un enemigo termine su turno a 5 pies de ti, puedes moverte hasta la mitad de tu velocidad terrestre sin provocar ningún ataque de oportunidad.": "You can move up to half your speed as a reaction when an enemy ends its turn within 5 feet of you. This movement doesn't provoke opportunity attacks.",
  "Tu velocidad terrestre aumenta en 10 pies. Si posees velocidad de escalada o de nado, esas velocidades también aumentan en 10 pies.": "Your walking speed increases by 10 feet. If you have a climbing or swimming speed, this increase applies to that speed as well.",
  "Tienes ventaja en tiradas de Iniciativa. Además, la primera criatura a la que golpees durante la primera ronda de un combate otorga ventaja en tiradas de ataque a todos tus aliados contra ella hasta tu siguiente turno.": "You have advantage on initiative rolls. In addition, the first creature you hit during the first round of a combat becomes easier for you and others to strike; attack rolls against that target have advantage until the start of your next turn.",
  "Si tomas la acción de Atacar en tu turno, puedes realizar un ataque adicional con arma como acción adicional. Este ataque adicional puede beneficiarse de tu Ataque Furtivo incluso si ya lo usaste este turno, siempre que apunte a una criatura diferente.": "If you take the Attack action on your turn, you can make one additional attack as a bonus action. This attack can benefit from your Sneak Attack even if you have already used it this turn, but you can't use your Sneak Attack against the same target more than once in a turn.",
  "Especialización en combate: Defensa (+1 CA), Duelo (+2 daño con una mano), Gran Arma (repetir 1 y 2 en dados de daño) o Protección.": "Combat specialization: Defense (+1 AC while wearing armor), Dueling (+2 damage with a one-handed weapon), Great Weapon Fighting (reroll 1s and 2s on damage dice with two-handed weapons), or Protection.",
  "Preparas la mitad de tu nivel de paladín + Carisma conjuros de paladín cada día usando tu Carisma como aptitud mágica.": "You prepare a number of paladin spells equal to your Charisma modifier + half your paladin level (rounded down) each day, using Charisma as your spellcasting ability.",
  "Cuando impactas a una criatura con un ataque cuerpo a cuerpo con arma, puedes gastar una ranura de conjuro para infligir 2d8 de daño radiante adicional (+1d8 por cada nivel por encima de 1.º, hasta 5d8; +1d8 extra contra infernales o muertos vivientes).": "When you hit a creature with a melee weapon attack, you can expend one spell slot to deal radiant damage to the target, in addition to the weapon's damage. The extra damage is 2d8 for a 1st-level spell slot, plus 1d8 for each spell level higher than 1st, to a maximum of 5d8 (+1d8 extra against an undead or a fiend).",
  "Pronuncias los votos de tu Juramento (Devoción, Venganza, etc.), obteniendo conjuros de juramento siempre preparados y Canalizar Divinidad a niveles 3, 7, 15 y 20.": "You swear the final vows of your Sacred Oath (Devotion, Vengeance, etc.), gaining oath spells that are always prepared and Channel Divinity features at 3rd, 7th, 15th, and 20th level.",
  "La magia divina fluye por tus venas haciéndote completamente inmune a todas las enfermedades.": "The divine magic flowing through you makes you immune to disease.",
  "Desbloqueas ranuras y conjuros de 2.º nivel (Ayuda, Encontrar Corcel, Castigo Abrasador, Zona de Verdad).": "You unlock 2nd-level spell slots and paladin spells (Aid, Find Steed, Branding Smite, Zone of Truth).",
  "Tú y las criaturas aliadas a 10 pies de ti sumáis tu modificador de Carisma (mínimo +1) a todas las tiradas de salvación mientras estés consciente.": "Whenever you or a friendly creature within 10 feet of you must make a saving throw, the creature gains a bonus to the saving throw equal to your Charisma modifier (with a minimum bonus of +1) while you are conscious.",
  "Obtienes un aura sagrada o rasgo protector concedido por tu juramento a nivel 7.": "You gain a sacred aura or protective feature granted by your Sacred Oath at 7th level.",
  "Desbloqueas conjuros de 3.er nivel (Revivir, Luz del Día, Castigo Cegador, Disipar Magia).": "You unlock 3rd-level paladin spells (Revivify, Daylight, Blinding Smite, Dispel Magic).",
  "Tú y los aliados a 10 pies de ti no podéis quedar Asustados mientras estés consciente.": "You and friendly creatures within 10 feet of you can't be frightened while you are conscious.",
  "Tus ataques marciales están permanentemente imbuidos de energía radiante: cada impacto cuerpo a cuerpo con arma inflige +1d8 de daño radiante pasivo automático.": "You are so suffused with righteous might that all your melee weapon strikes carry divine power with them: whenever you hit a creature with a melee weapon, the creature takes an extra 1d8 radiant damage.",
  "Desbloqueas conjuros de 4.º nivel (Destierro, Protección contra la Muerte, Castigo Estupefaciente).": "You unlock 4th-level paladin spells (Banishment, Death Ward, Staggering Smite).",
  "Como acción tocas a una criatura voluntaria para terminar un conjuro activo sobre ella (usos = Mod. Carisma por descanso largo).": "You can use your action to end one spell on yourself or on one willing creature that you touch (uses equal to your Charisma modifier per long rest).",
  "Obtienes un rasgo avanzado de tu juramento de paladín.": "You gain an advanced feature from your Sacred Oath.",
  "Desbloqueas conjuros supremos de 5.º nivel (Castigo Desterrador, Disipar el Mal y el Bien, Ola Destructiva).": "You unlock supreme 5th-level paladin spells (Banishing Smite, Dispel Evil and Good, Destructive Wave).",
  "El alcance de tu Aura de Protección, Aura de Coraje y aura de tu Juramento aumenta de 10 pies a 30 pies.": "The range of your Aura of Protection, Aura of Courage, and Sacred Oath aura increases from 10 feet to 30 feet.",
  "Te transformas en el avatar definitivo de tu causa durante 1 hora, desatando el poder legendario de tu Juramento Sagrado.": "You transform into the ultimate avatar of your cause, unleashing the legendary capstone power of your Sacred Oath.",
  "Canalizar Divinidad: Imbuyes tu arma con luz (+Carisma a tiradas de ataque durante 1 minuto e iluminación mágica).": "Channel Divinity: As an action, you imbue one weapon that you are holding with positive energy for 1 minute, adding your Charisma modifier to attack rolls made with that weapon and causing it to emit bright light in a 20-foot radius.",
  "Canalizar Divinidad: Fuerzas a infernales y muertos vivientes a 30 pies a huir si fallan salvación de Sabiduría.": "Channel Divinity: As an action, you present your holy symbol, and each fiend or undead within 30 feet of you must succeed on a Wisdom saving throw or be turned for 1 minute.",
  "Tú y tus aliados a 10 pies no podéis ser hechizados mientras estés consciente (aumenta a 30 pies a nivel 18).": "You and friendly creatures within 10 feet of you can't be charmed while you are conscious (increases to 30 feet at 18th level).",
  "Estás permanentemente bajo los efectos de Protección contra el Mal y el Bien.": "You are always under the effects of a Protection from Evil and Good spell.",
  "Como acción emites un halo de luz solar durante 1 minuto: 10 de daño radiante por turno a infernales/muertos vivientes y ventaja en salvaciones contra conjuros.": "As an action, you emanate an aura of sunlight for 1 minute: enemy creatures that start their turn in the bright light take 10 radiant damage, and you have advantage on saving throws against spells cast by fiends or undead.",
  "Canalizar Divinidad: Como acción adicional ganas ventaja en todas las tiradas de ataque contra un enemigo a 30 pies durante 1 minuto.": "Channel Divinity: As a bonus action, you utter a vow of enmity against a creature you can see within 10 feet of you, gaining advantage on attack rolls against the creature for 1 minute.",
  "Canalizar Divinidad: Aterrorizas a una criatura a 60 pies reduciendo su velocidad a 0.": "Channel Divinity: As an action, you force one creature within 60 feet of you to make a Wisdom saving throw; on a failed save, it is frightened and its speed is 0 for 1 minute or until it takes damage.",
  "Cuando golpeas a una criatura con un ataque de oportunidad, puedes moverte hasta la mitad de tu velocidad como parte de la misma reacción sin provocar ataques de oportunidad.": "When you hit a creature with an opportunity attack, you can move up to half your speed immediately after the attack and as part of the same reaction, without provoking opportunity attacks.",
  "Cuando una criatura bajo tu Voto de Enemistad realice un ataque, puedes usar tu reacción para hacer un ataque cuerpo a cuerpo contra ella si está a tu alcance.": "When a creature under the effect of your Vow of Enmity makes an attack, you can use your reaction to make a melee weapon attack against that creature if it is within range.",
  "Como acción asumes la forma de un ángel vengador durante 1 hora: alas que te dan velocidad de vuelo de 60 pies y un aura de terror de 30 pies.": "As an action, you transform into an angelic avenger for 1 hour: wings sprout from your back granting you a flying speed of 60 feet, and you emanate an aura of menace in a 30-foot radius.",
  "Como acción invocas enredaderas espectrales que brotan del suelo para apresar a un enemigo a 10 pies si falla una salvación de Fuerza o Destreza.": "As an action, you invoke spectral vines to spring up and reach for a creature within 10 feet of you that you can see, restraining it on a failed Strength or Dexterity saving throw.",
  "Como acción alzas tu símbolo sagrado: cada fata o infernal a 30 pies que te escuche debe superar una salvación de Sabiduría o quedará expulsado durante 1 minuto.": "As an action, you present your holy symbol, and each fey or fiend within 30 feet of you that can hear you must succeed on a Wisdom saving throw or be turned for 1 minute.",
  "Tú y las criaturas aliadas a 10 pies o menos de ti tenéis resistencia al daño infligido por conjuros (el aura aumenta a 30 pies a nivel 18).": "You and friendly creatures within 10 feet of you have resistance to damage from spells (the aura increases to 30 feet at 18th level).",
  "Cuando tus puntos de golpe se reduzcan a 0 y no mueras directamente, puedes elegir quedar a 1 punto de golpe en su lugar (1/descanso largo). Además, no sufres penalizaciones por envejecer y no puedes ser envejecido mágicamente.": "When you are reduced to 0 hit points and are not killed outright, you can choose to drop to 1 hit point instead (1/long rest). Additionally, you suffer none of the drawbacks of old age, and you can't be aged magically.",
  "Como acción te transformas en una fuerza encarnada de la naturaleza durante 1 minuto: recuperas 10 puntos de golpe al inicio de cada uno de tus turnos, puedes lanzar conjuros de paladín con tiempo de 1 acción como acción adicional, y los enemigos a 10 pies tienen desventaja en salvaciones contra tus conjuros.": "As an action, you assume the form of an ancient force of nature for 1 minute: at the start of each of your turns, you regain 10 hit points; whenever you cast a paladin spell that has a casting time of 1 action, you can cast it using a bonus action instead; and enemy creatures within 10 feet of you have disadvantage on saving throws against your paladin spells and Channel Divinity options.",
  "Como acción fuerzas a cada criatura a tu elección a 30 pies a superar una salvación de Sabiduría o quedar asustada de ti durante 1 minuto.": "As an action, you force each creature of your choice that you can see within 30 feet of you to make a Wisdom saving throw. On a failed save, a creature becomes frightened of you for 1 minute.",
  "Cuando realizas una tirada de ataque, puedes usar tu Canalizar Divinidad para ganar un bonificador de +10 a la tirada de ataque.": "When you make an attack roll, you can use your Channel Divinity to gain a +10 bonus to the roll.",
  "Emanas un aura opresiva de 10 pies (30 pies a lvl 18). Cualquier criatura asustada de ti que empiece su turno en tu aura ve su velocidad reducida a 0 y sufre daño psíquico igual a la mitad de tu nivel de paladín.": "You emanate a menacing aura in a 10-foot radius (30 feet at 18th level). If a creature is frightened of you, its speed is reduced to 0 while in the aura, and that creature takes psychic damage equal to half your paladin level if it starts its turn there.",
  "Cada vez que una criatura te impacte con un ataque, sufre daño psíquico igual a tu modificador de Carisma siempre que no estés incapacitado.": "Whenever a creature hits you with an attack, that creature takes psychic damage equal to your Charisma modifier (minimum of 1) if you're not incapacitated.",
  "Como acción ganas una armadura titánica durante 1 minuto: ganas resistencia a todo el daño de armas, puedes realizar un ataque adicional cada vez que tomes la acción de Atacar, y tus ataques con arma consiguen impacto crítico con un resultado de 19 o 20.": "As an action, you gain extraordinary martial prowess for 1 minute: you have resistance to all damage, when you take the Attack action on your turn you can make one additional attack as part of that action, and your melee weapon attacks score a critical hit on a roll of 19 or 20.",
  "Como acción adicional otorgas a tus palabras un peso celestial, ganando un bonificador de +5 a tus pruebas de Carisma (Persuasión) durante los próximos 10 minutos.": "As a bonus action, you grant yourself a +5 bonus to Charisma (Persuasion) checks for the next 10 minutes.",
  "Como reacción cuando un atacante a 30 pies inflija daño a otra criatura, fuerzas al atacante a superar una salvación de Sabiduría o sufrir la misma cantidad de daño radiante que acaba de infligir.": "Immediately after an attacker within 30 feet of you deals damage with an attack against a creature other than you, you can use your reaction to force the attacker to make a Wisdom saving throw, taking radiant damage equal to the damage it just dealt on a failed save, or half as much damage on a successful one.",
  "Cuando una criatura a 10 pies de ti (30 pies a lvl 18) sufra daño, puedes usar tu reacción para absorber mágicamente todo ese daño tú mismo.": "When a creature within 10 feet of you (30 feet at 18th level) takes damage, you can use your reaction to magically take that damage, instead of that creature taking it.",
  "Recuperas puntos de golpe iguales a 1d6 + la mitad de tu nivel de paladín al final de cada uno de tus turnos en combate si tienes menos de la mitad de tus PG máximos.": "You regain hit points equal to 1d6 + half your paladin level if you end your turn in combat with fewer than half of your hit points remaining and you aren't incapacitated.",
  "Ganas resistencia a todo el daño infligido por otras criaturas y reflejas la mitad del daño a los atacantes como daño radiante mientras no las ataques primero ni les lances conjuros dañinos.": "You have resistance to all damage dealt by other creatures, and whenever a creature hits you with an attack, it takes radiant damage equal to half the damage you take from the attack, as long as you haven't attacked, damaged, or forced a saving throw on that creature.",
  "Como acción adicional ganas ventaja en pruebas de Atletismo y Acrobacias, tu distancia de salto se duplica y tu capacidad de carga se duplica durante 10 minutos.": "As a bonus action, you gain advantage on Strength (Athletics) and Dexterity (Acrobatics) checks, you can carry, push, drag, and lift twice as much weight as normal, and the distance of your long and high jumps increases by 10 feet for the next 10 minutes.",
  "Inmediatamente después de infligir daño con tu Castigo Divino, puedes otorgar puntos de golpe temporales iguales a 2d8 + tu nivel de paladín repartidos entre aliados a 30 pies.": "Immediately after you deal damage to a creature with your Divine Smite feature, you can use your Channel Divinity as a bonus action and distribute temporary hit points equal to 2d8 + your paladin level among creatures of your choice within 30 feet of you.",
  "Tu velocidad terrestre aumenta en 10 pies. Cualquier aliado que comience su turno a 5 pies de ti (10 pies a lvl 18) gana +10 pies de velocidad durante ese turno.": "Your walking speed increases by 10 feet. In addition, if you aren't incapacitated, the walking speed of any ally who starts their turn within 5 feet of you (10 feet at 18th level) increases by 10 feet until the end of that turn.",
  "Como reacción cuando tú o una criatura a 10 pies sea atacada, añades tu bonificador de Carisma a la CA de ese objetivo; si el ataque falla, puedes hacer un ataque con arma inmediato contra el atacante.": "When you or another creature you can see within 10 feet of you is hit by an attack roll, you can use your reaction to grant a bonus to the target's AC against that attack equal to your Charisma modifier; if the attack misses, you can make one weapon attack against the attacker as part of this reaction.",
  "Durante 1 minuto emanas carisma divino: ganas ventaja en todas las pruebas de Carisma, puedes relanzar un ataque fallado cada turno, y las salvaciones falladas se pueden superar usando tu reacción.": "As a bonus action, you empower yourself with legends for 1 minute: you gain advantage on all Charisma checks, once on each of your turns when you make a weapon attack and miss you can cause that attack to hit instead, and if you fail a saving throw you can use your reaction to reroll it.",
  "Como acción otorgas ventaja en tiradas de salvación de Inteligencia, Sabiduría y Carisma a ti mismo y a un número de aliados a 30 pies igual a tu modificador de Carisma durante 1 minuto.": "As an action, you can choose a number of creatures you can see within 30 feet of you, up to a number equal to your Charisma modifier (minimum of one creature). For 1 minute, you and the chosen creatures have advantage on Intelligence, Wisdom, and Charisma saving throws.",
  "Como acción fuerzas a cada aberración, celestial, elemental, fata o infernal a 30 pies a superar una salvación de Sabiduría o quedar expulsado durante 1 minuto.": "As an action, you present your holy symbol, and each aberration, celestial, elemental, fey, or fiend within 30 feet of you that can hear you must succeed on a Wisdom saving throw or be turned for 1 minute.",
  "Emanas un aura de vigilancia a 10 pies (30 pies a lvl 18). Tú y cualquier aliado en el aura sumáis vuestro bonificador de competencia a las tiradas de Iniciativa.": "You emit an aura of alertness within 10 feet of you (30 feet at 18th level). Whenever you or a creature you choose in the aura rolls initiative, that creature gains a bonus to the initiative roll equal to your proficiency bonus.",
  "Cuando tú o una criatura protegida por tu Voluntad del Vigilante supere una tirada de salvación contra un conjuro, el lanzador sufre 2d8 + tu modificador de Carisma en daño de fuerza.": "Whenever you or a creature you can see within 30 feet of you succeeds on an Intelligence, a Wisdom, or a Charisma saving throw, you can use your reaction to deal 2d8 + your Charisma modifier force damage to the creature that forced the saving throw.",
  "Durante 1 minuto ganas visión verdadera a 120 pies, ventaja en tiradas de ataque contra seres extraplanares y cuando los golpeas con un arma puedes desterrarlos inmediatamente de vuelta a su plano de origen.": "As a bonus action, you manifest a spark of divine power for 1 minute: you gain truesight with a range of 120 feet, you have advantage on attack rolls against aberrations, celestials, elementals, fey, and fiends, and when you hit a creature with an attack roll you can force it to make a Charisma saving throw or be banished to its native plane of existence.",
  "Como acción desafías a todas las criaturas a tu elección a 30 pies: si fallan una salvación de Sabiduría, no pueden alejarse voluntariamente a más de 30 pies de ti.": "As a bonus action, you issue a challenge that compels other creatures to do battle with you: each creature of your choice that you can see within 30 feet of you must make a Wisdom saving throw, and on a failed save, it can't willingly move more than 30 feet away from you.",
  "Como acción adicional cada criatura a tu elección a 30 pies que tenga menos de la mitad de sus PG máximos recupera 1d6 + tu modificador de Carisma en puntos de golpe.": "As a bonus action, you can bolster injured creatures with your Channel Divinity: each creature of your choice that can see or hear you within 30 feet of you regains hit points equal to 1d6 + your Charisma modifier if it has no more than half of its hit points.",
  "Como reacción cuando una criatura a 5 pies sufra daño, puedes absorber mágicamente todo ese daño tú mismo en su lugar.": "When a creature within 5 feet of you takes damage, you can use your reaction to magically substitute your own health for that of the target creature, causing that creature not to take the damage and taking the damage yourself instead.",
  "Durante 1 hora ganas resistencia al daño contundente, cortante y perforante no mágico, tus aliados a 30 pies tienen ventaja en salvaciones de muerte y tú ganas ventaja en salvaciones de Sabiduría.": "As an action, you gain the following benefits for 1 hour: you have resistance to bludgeoning, piercing, and slashing damage from nonmagical weapons, your allies have advantage on death saving throws while within 30 feet of you, and you and your allies have advantage on Wisdom saving throws while within 30 feet of you.",
  "Como acción intentas someter a un no muerto a 30 pies cuyo VD sea menor que tu nivel de paladín (falla salvación de Sabiduría y obedece tus órdenes durante 24 horas).": "As an action, you target one undead creature you can see within 30 feet of you whose challenge rating is lower than your paladin level. The target must make a Wisdom saving throw; on a failed save, the target must obey your commands for the next 24 hours.",
  "Como acción obligas a cada criatura a 30 pies a superar una salvación de Sabiduría o quedar asustada de ti durante 1 minuto.": "As an action, you channel the darkest emotions and focus them into a burst of magical menace: each creature of your choice within 30 feet of you must succeed on a Wisdom saving throw or be frightened of you for 1 minute.",
  "Tú, así como cualquier infernal o no muerto a 10 pies de ti (30 pies a lvl 18), sumáis vuestro modificador de Carisma a todas las tiradas de daño con armas cuerpo a cuerpo.": "You, as well as any fiends and undead within 10 feet of you (30 feet at 18th level), gain a bonus to melee weapon damage rolls equal to your Charisma modifier (minimum of +1).",
  "Ganas resistencia permanente al daño contundente, perforante y cortante infligido por armas no mágicas.": "You gain resistance to bludgeoning, piercing, and slashing damage from nonmagical weapons.",
  "Durante 1 minuto emanas un manto de sombras fúnebres de 30 pies: el área es penumbra, los enemigos en el manto sufren 4d10 de daño psíquico al comenzar su turno y puedes atacar a través de las sombras con tu acción adicional.": "As an action, you surround yourself with an aura of gloom in a 30-foot radius for 1 minute: bright light is reduced to dim light, enemies frightened of you take 4d10 psychic damage if they start their turn in the aura, and you can use a bonus action to make a melee spell attack with the shadows.",
  "Obtienes tantos puntos de Ki como tu nivel de monje. Puedes gastar Ki para activar: Ráfaga de Golpes (2 ataques desarmados adicionales), Defensa Paciente (Esquivar como acción adicional) o Paso del Viento (Destrabarse o Correr con salto doble). Recarga en descanso corto.": "You gain a number of Ki points equal to your monk level. You can spend Ki points to fuel: Flurry of Blows (two additional unarmed strikes as a bonus action), Patient Defense (take the Dodge action as a bonus action), or Step of the Wind (take the Disengage or Dash action as a bonus action, with doubled jump distance). Recharges on a short or long rest.",
  "Tu velocidad aumenta en 10 pies mientras no lleves armadura ni escudo (aumenta según tu nivel).": "Your speed increases by 10 feet while you are not wearing armor or wielding a shield (this bonus increases as you gain monk levels).",
  "Te consagras a una orden monástica (Palma Abierta, Sombra, etc.), obteniendo rasgos a niveles 3, 6, 11 y 17.": "You commit yourself to a monastic tradition (Way of the Open Hand, Way of Shadow, etc.), gaining features at 3rd, 6th, 11th, and 17th level.",
  "Reacción al ser alcanzado por un proyectil a distancia: reduces el daño en 1d10 + Des + nivel de monje. Si reduces el daño a 0, puedes atraparlo y gastar 1 Ki para devolverlo inmediatamente como ataque.": "Reaction when hit by a ranged weapon attack: reduce the damage by 1d10 + your Dexterity modifier + your monk level. If you reduce the damage to 0, you can catch the missile and spend 1 Ki point to make a ranged attack with it as part of the same reaction.",
  "Reacción al caer: reduces cualquier daño que sufras por una caída en una cantidad igual a 5 veces tu nivel de monje.": "Reaction when you fall: reduce any falling damage you take by an amount equal to five times your monk level.",
  "Cuando impactas a una criatura con un ataque cuerpo a cuerpo con arma, puedes gastar 1 punto de Ki para forzarle a superar una salvación de Constitución (CD 8 + prof + Sab) o quedar Aturdida hasta el final de tu siguiente turno.": "When you hit another creature with a melee weapon attack, you can spend 1 Ki point to force the target to succeed on a Constitution saving throw (DC 8 + your proficiency bonus + your Wisdom modifier) or be stunned until the end of your next turn.",
  "El dado de tus ataques desarmados y armas de monje aumenta a d6.": "Your Martial Arts die for unarmed strikes and monk weapons increases to a d6.",
  "Tus ataques desarmados cuentan como mágicos a efectos de superar la resistencia e inmunidad a los ataques no mágicos.": "Your unarmed strikes count as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.",
  "Tu velocidad sin armadura aumenta a +15 pies.": "Your Unarmored Movement bonus increases to +15 feet.",
  "Obtienes un nuevo rasgo otorgado por la tradición elegida a nivel 3.": "You gain a new feature granted by the Monastic Tradition you chose at 3rd level.",
  "Tu agilidad instintiva te permite esquivar efectos de área (como un Aliento de Dragón). Si tienes éxito en una salvación de Destreza no sufres daño, y si fallas solo sufres la mitad.": "Your instinctive agility lets you dodge out of the way of certain area effects (such as a dragon's fiery breath). When you are subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw, and only half damage if you fail.",
  "Puedes usar tu acción para poner fin a un efecto sobre ti mismo que te esté causando estar Hechizado o Asustado.": "You can use your action to end one effect on yourself that is causing you to be charmed or frightened.",
  "Obtienes la capacidad de moverte a lo largo de superficies verticales y a través de líquidos en tu turno sin caer.": "You gain the ability to move along vertical surfaces and across liquids on your turn without falling during the move.",
  "Tu dominio del Ki te hace completamente inmune al veneno y a las enfermedades.": "Your mastery of the Ki flowing through you makes you immune to disease and poison.",
  "Tu velocidad sin armadura aumenta a +20 pies.": "Your Unarmored Movement bonus increases to +20 feet.",
  "El dado de tus ataques desarmados y armas de monje aumenta a d8.": "Your Martial Arts die for unarmed strikes and monk weapons increases to a d8.",
  "Obtienes un rasgo avanzado de tu Tradición Monástica.": "You gain an advanced feature from your Monastic Tradition.",
  "Aprendes a tocar el Ki de otras mentes: entiendes todos los idiomas hablados, y cualquier criatura que entienda un idioma comprende lo que dices.": "You learn to touch the Ki of other minds so that you understand all spoken languages. Moreover, any creature that can understand a language can understand what you say.",
  "Tu dominio del Ki te otorga competencia en todas las tiradas de salvación. Además, cuando fallas una salvación, puedes gastar 1 Ki para volver a tirarla y quedarte con el nuevo resultado.": "Your mastery of Ki grants you proficiency in all saving throws. Additionally, whenever you make a saving throw and fail, you can spend 1 Ki point to reroll it and take the second result.",
  "Tu velocidad sin armadura aumenta a +25 pies.": "Your Unarmored Movement bonus increases to +25 feet.",
  "Tu Ki sostiene tu organismo: no sufres la fragilidad de la vejez y no puedes envejecer mágicamente (sigues pudiendo morir de viejo), y ya no necesitas comida ni agua.": "Your Ki sustains you so that you suffer none of the frailty of old age, and you can't be aged magically (you can still die of old age). In addition, you no longer need food or water.",
  "El dado de tus ataques desarmados y armas de monje aumenta a d10.": "Your Martial Arts die for unarmed strikes and monk weapons increases to a d10.",
  "Alcanzas el poder supremo de tu orden monástica.": "You reach the supreme power of your Monastic Tradition.",
  "Puedes gastar 4 puntos de Ki como acción para volverte invisible durante 1 minuto, obteniendo además resistencia a todo daño excepto fuerza. Por 8 Ki puedes lanzar Proyección Astral sobre ti mismo.": "You can use your action to spend 4 Ki points to become invisible for 1 minute, during which time you also have resistance to all damage except force damage. Additionally, you can spend 8 Ki points to cast the Astral Projection spell on yourself without needing material components.",
  "Tu velocidad sin armadura alcanza su máximo de +30 pies.": "Your Unarmored Movement bonus reaches its maximum of +30 feet.",
  "Al tirar iniciativa al comienzo de un combate, si no te queda ningún punto de Ki, recuperas inmediatamente 4 puntos de Ki.": "When you roll for initiative and have no Ki points remaining, you regain 4 Ki points.",
  "Al golpear con Ráfaga de Golpes puedes: derribar al objetivo (salvación FUE), empujarlo 15 pies o anular sus reacciones hasta el final de tu siguiente turno.": "Whenever you hit a creature with one of the attacks granted by your Flurry of Blows, you can impose one of the following effects on that target: knock it prone (Dexterity save), push it up to 15 feet away from you (Strength save), or prevent it from taking reactions until the end of your next turn.",
  "Como acción recuperas puntos de golpe iguales al triple de tu nivel de monje una vez por descanso largo.": "As an action, you can regain hit points equal to three times your monk level once per long rest.",
  "Al final de un descanso largo quedas bajo el efecto del conjuro Santuario hasta tu próximo descanso largo o hasta que ataques.": "At the end of a long rest, you gain the effect of a Sanctuary spell that lasts until the start of your next long rest (the spell can end early as normal).",
  "Gastas 3 Ki al golpear para establecer vibraciones letales: como acción posterior liberas la vibración forzando salvación de Con o la criatura cae a 0 PG (o sufre 10d10 daño necrótico si tiene éxito).": "When you hit a creature with an unarmed strike, you can spend 3 Ki points to start imperceptible vibrations: as an action while on the same plane of existence, you can end the vibrations, forcing the creature to make a Constitution saving throw; it is reduced to 0 hit points on a failed save, or takes 10d10 necrotic damage on a successful save.",
  "Gastas 2 Ki para lanzar Oscuridad, Pasar sin Huella, Silencio o Visión en la Oscuridad, y aprendes el truco Ilusión Menor.": "As an action, you can spend 2 Ki points to cast Darkness, Darkvision, Pass without Trace, or Silence without providing material components. Additionally, you gain the Minor Illusion cantrip.",
  "Como acción adicional puedes teletransportarte hasta 60 pies de una sombra o luz tenue a otra, ganando ventaja en tu siguiente ataque cuerpo a cuerpo.": "When you are in dim light or darkness, as a bonus action you can teleport up to 60 feet to an unoccupied space you can see that is also in dim light or darkness. You then have advantage on the first melee attack you make before the end of the turn.",
  "Como acción puedes volverte invisible mientras estés en luz tenue u oscuridad hasta que ataques, lances un conjuro o estés en luz brillante.": "When you are in an area of dim light or darkness, you can use your action to become invisible until you make an attack, cast a spell, or are in an area of bright light.",
  "Reacción: cuando una criatura a 5 pies de ti sea golpeada por un ataque de otra criatura, puedes hacer un ataque cuerpo a cuerpo contra ella.": "Reaction: Whenever a creature within 5 feet of you is hit by an attack made by a creature other than you, you can use your reaction to make a melee attack against that creature.",
  "Aprendes la disciplina Sintonía Elemental y otras disciplinas elementales gastando Puntos de Ki: Colmillos de la Serpiente de Fuego (ataques desarmados a 10 pies con daño de fuego extra), Látigo de Agua (tirar y derribar al enemigo), Puño de Cuatro Truenos (lanzar Onda Atronadora), Barrido de Cenizas (Manos Ardientes), etc.": "You learn the Elemental Attunement discipline and one other elemental discipline of your choice that spends Ki points: Fangs of the Fire Snake (unarmed strikes with 10-foot reach and extra fire damage), Water Whip (pull or knock a target prone and deal bludgeoning damage), Fist of Four Thunders (cast Thunderwave), Sweeping Cinder Strike (cast Burning Hands), etc.",
  "Puedes aprender disciplinas avanzadas como Aliento del Dragón (cono de fuego), Puño de Aire Inquebrantable, o Postura de Niebla (Forma Gaseosa).": "You can learn advanced elemental disciplines such as Clench of the North Wind (Hold Person), Gong of the Summit (Shatter), or Mist Stance (Gaseous Form).",
  "Acceso a magias mayores: Cabalgar el Viento (Volar), Llamas del Fénix (Bola de Fuego), o Coraza de Piedra (Piel Pétrea).": "You unlock greater elemental disciplines such as Ride the Wind (Fly) and Flames of the Phoenix (Fireball).",
  "Poder de cataclismo elemental: Ola del Río (Cono de Frío) y Forma de las Mil Tormentas.": "You unlock supreme elemental disciplines such as Breath of Winter (Cone of Cold), Eternal Mountain Defense (Stoneskin), River of Hungry Flame (Wall of Fire), and Wave of Rolling Earth (Wall of Stone).",
  "Ganas competencia en Actuación e Instrumentos de Cervecero. Además, cada vez que uses Ráfaga de Golpes ganas los beneficios de la acción de Retirada y tu velocidad terrestre aumenta en 10 pies hasta el final de tu turno.": "You gain proficiency in the Performance skill and with brewer's supplies. Whenever you use Flurry of Blows, you gain the benefit of the Disengage action, and your walking speed increases by 10 feet until the end of the current turn.",
  "Levantarte de estar derribado solo te cuesta 5 pies de movimiento en lugar de la mitad. Además, cuando una criatura falle un ataque de arma cuerpo a cuerpo contra ti, puedes gastar 1 punto de Ki y tu reacción para hacer que ese ataque golpee a otra criatura a 5 pies de ti.": "Standing up from prone uses only 5 feet of your movement, rather than half your speed. In addition, when a creature misses you with a melee attack roll, you can spend 1 Ki point as a reaction to cause that attack to hit one creature of your choice, other than the attacker, that you can see within 5 feet of you.",
  "Cuando hagas una tirada de salvación o prueba de característica con desventaja, puedes gastar 2 puntos de Ki para cancelar la desventaja en esa tirada.": "When you make an ability check, an attack roll, or a saving throw and have disadvantage on the roll, you can spend 2 Ki points to cancel the disadvantage for that roll.",
  "Cuando uses tu Ráfaga de Golpes, puedes realizar hasta tres ataques desarmados adicionales (un total de 5 ataques adicionales) siempre que cada ataque impacte a un objetivo diferente.": "When you use your Flurry of Blows, you can make up to three additional attacks with it (up to a total of five Flurry of Blows attacks), provided that each Flurry of Blows attack targets a different creature this turn.",
  "Eliges dos armas (una cuerpo a cuerpo y una a distancia sin las propiedades pesada ni especial) que se convierten en armas de monje para ti. Bloqueo Ágil (+2 CA si atacas desarmado sosteniendo tu arma kensei cuerpo a cuerpo) y Tiro Kensei (+1d4 de daño adicional con acción adicional en ataques a distancia).": "You choose two types of weapons to be your kensei weapons (one melee and one ranged, neither with the heavy or special property), which count as monk weapons for you. You also gain Agile Parry (+2 AC if you make an unarmed strike as part of the Attack action while holding a kensei melee weapon) and Kensei's Shot (bonus action to deal an extra 1d4 damage on ranged attacks with a kensei weapon).",
  "Tus armas kensei cuentan como mágicas para superar resistencias. Además, una vez por turno al impactar con un arma kensei puedes gastar 1 Ki para infligir daño adicional igual a tu dado de artes marciales.": "Your attacks with your kensei weapons count as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage. In addition, once on each of your turns when you hit a target with a kensei weapon, you can spend 1 Ki point to cause the weapon to deal extra damage to the target equal to your Martial Arts die.",
  "Como acción adicional gastas hasta 3 puntos de Ki para otorgar a un arma kensei no mágica un bonificador de hasta +3 a tiradas de ataque y daño durante 1 minuto.": "As a bonus action, you can expend up to 3 Ki points to grant one kensei weapon you touch a bonus to attack and damage rolls equal to the number of Ki points you spent for 1 minute.",
  "Una vez en cada uno de tus turnos si fallas una tirada de ataque con un arma de monje o arma kensei, puedes volver a tirar la tirada de ataque.": "If you miss with an attack roll using a monk weapon on your turn, you can reroll it once per turn.",
  "Ganas competencia en Perspicacia, Medicina y el kit de herboristería, y adquieres una máscara tradicional que oculta tu rostro.": "You gain proficiency in the Insight and Medicine skills, and you gain proficiency with the herbalism kit. You also receive a special mask, which you often wear when using the features of this subclass.",
  "Como acción puedes gastar 1 punto de Ki para tocar a una criatura y curarle puntos de golpe iguales a 1 dado de artes marciales + tu modificador de Sabiduría. Cuando usas Ráfaga de Golpes, puedes reemplazar uno de los golpes desarmados por este toque sin gastar Ki adicional.": "As an action, you can spend 1 Ki point to touch a creature and restore a number of hit points equal to a roll of your Martial Arts die + your Wisdom modifier. When you use your Flurry of Blows, you can replace one of the unarmed strikes with a use of this feature without spending a Ki point for the healing.",
  "Cuando golpeas a una criatura con un golpe desarmado, puedes gastar 1 punto de Ki para infligir daño necrótico adicional igual a 1 dado de artes marciales + tu modificador de Sabiduría.": "When you hit a creature with an unarmed strike, you can spend 1 Ki point to deal extra necrotic damage equal to one roll of your Martial Arts die + your Wisdom modifier.",
  "Tus Manos de Sanación ahora también curan una enfermedad o eliminan la condición Cegado, Ensordecido, Paralizado, Envenenado o Aturdido. Además, tus Manos del Daño envenenan al objetivo hasta el final de tu siguiente turno.": "When you use Hands of Healing on a creature, you can also end one disease or one of the following conditions affecting the creature: blinded, deafened, paralyzed, poisoned, or stunned. When you use Hands of Harm on a creature, you can subject that creature to the poisoned condition until the end of your next turn.",
  "Puedes reemplazar ambos ataques de tu Ráfaga de Golpes con Manos de Sanación sin coste de Ki extra. Y tus Manos del Daño no requieren gastar Ki si las usas durante Ráfaga de Golpes.": "You can now mete out a flurry of comfort and hurt: when you use Flurry of Blows, you can now replace each of the unarmed strikes with a use of your Hands of Healing without spending Ki points for the healing. In addition, when you make an unarmed strike with Flurry of Blows, you can use Hands of Harm with that strike without spending the Ki point for Hands of Harm.",
  "Como acción tocas a una criatura que haya muerto en las últimas 24 horas y gastas 5 puntos de Ki para devolverla a la vida con puntos de golpe iguales a 4d10 + tu modificador de Sabiduría.": "As an action, you can touch the corpse of a creature that died within the past 24 hours and expend 5 Ki points. The creature then returns to life, regaining a number of hit points equal to 4d10 + your Wisdom modifier.",
  "Como acción adicional gastas 1 Ki para manifestar brazos astrales durante 10 minutos: al aparecer infligen daño de fuerza a enemigos a 10 pies. Tienen alcance de 10 pies, puedes usar tu Sabiduría en lugar de Fuerza para pruebas y salvaciones, y tus ataques desarmados usan Sabiduría e infligen daño de fuerza.": "As a bonus action, you can spend 1 Ki point to summon the arms of your astral self for 10 minutes: when summoned, each creature of your choice within 10 feet must make a Dexterity save or take force damage. While active, you can use your Wisdom modifier in place of your Strength modifier for Strength checks and saving throws, and your unarmed strikes with the arms have a 10-foot reach, use Wisdom for attack and damage rolls, and deal force damage.",
  "Como acción adicional gastas 1 Ki para manifestar una máscara espectral: ves normalmente en oscuridad mágica hasta 120 pies, tienes ventaja en pruebas de Perspicacia e Intimidación, y puedes proyectar tu voz a grandes distancias.": "As a bonus action, or as part of the bonus action you take to activate Arms of the Astral Self, you can spend 1 Ki point to summon the spectral visage for 10 minutes: you can see normally in darkness (both magical and nonmagical) to a distance of 120 feet, you have advantage on Wisdom (Insight) and Charisma (Intimidation) checks, and you can direct your words to a creature within 60 feet or amplify your voice up to 600 feet.",
  "Manifiestas una armadura de torso astral: como reacción reduces daño de ácido, frío, fuego, relámpago o fuerza en 1d10 + Sab. Además, una vez por turno tu ataque con brazos astrales inflige daño adicional igual a tu dado de artes marciales.": "When you have both your astral arms and visage summoned, you can cause the body of your astral self to appear: as a reaction when you take acid, cold, fire, force, lightning, or thunder damage, you can deflect it to reduce the damage by 1d10 + your Wisdom modifier. Additionally, once on each of your turns when you hit a target with your Arms of the Astral Self, you can deal extra damage equal to your Martial Arts die.",
  "Gastas 5 Ki para manifestar la armadura astral completa: ganas +2 a la CA y puedes hacer hasta tres ataques con los Brazos del Yo Astral cada vez que uses la acción de Atacar en tu turno.": "As a bonus action, you can spend 5 Ki points to summon the arms, visage, and body of your astral self and awaken it for 10 minutes: you gain a +2 bonus to AC, and whenever you use the Extra Attack feature to attack twice, you can instead attack three times if all the attacks are made with your astral arms.",
  "Puedes disparar proyectiles de energía radiante a distancia (alcance 30 pies) como ataques de conjuro usando tu bonificador de ataque de artes marciales y daño radiante igual a tu dado de artes marciales + Des. Tras disparar, puedes gastar 1 Ki para disparar dos proyectiles más con tu acción adicional.": "You gain a new attack option that you can use with the Attack action: a ranged spell attack with a range of 30 feet using Dexterity, dealing radiant damage equal to your Martial Arts die + your Dexterity modifier. When you take the Attack action on your turn and use this special attack as part of it, you can spend 1 Ki point to make the special attack twice as a bonus action.",
  "Inmediatamente después de tomar la acción de Atacar en tu turno, puedes gastar 2 puntos de Ki para lanzar Manos Ardientes como acción adicional.": "Immediately after you take the Attack action on your turn, you can spend 2 Ki points to cast the Burning Hands spell as a bonus action.",
  "Como acción creas una esfera de luz radiante a 150 pies: cada criatura en un radio de 20 pies sufre 2d6 de daño radiante (puedes gastar hasta 3 Ki para aumentar el daño en 2d6 por punto).": "As an action, you magically create an orb and hurl it at a point you choose within 150 feet, where it erupts into a 20-foot-radius sphere of radiant light: each creature in that sphere must succeed on a Constitution saving throw or take 2d6 radiant damage (you can spend up to 3 Ki points to increase the damage by 2d6 per point).",
  "Emanas luz brillante en 30 pies. Como reacción cuando una criatura a 5 pies te impacte con un ataque cuerpo a cuerpo, le infliges daño radiante igual a 5 + tu modificador de Sabiduría.": "You shed bright light in a 30-foot radius and dim light for an additional 30 feet. If a creature hits you with a melee attack while this light shines, you can use your reaction to deal radiant damage to the creature equal to 5 + your Wisdom modifier.",
  "Puedes cambiar el daño de tus golpes desarmados a ácido, frío, fuego, relámpago o veneno. Además, aprendes dracónico y ganas Presencia Dracónica para relanzar una prueba fallada de Intimidación o Persuasión.": "When you damage a target with an unarmed strike, you can change the damage type to acid, cold, fire, lightning, or poison. Additionally, you learn Draconic and can use Draconic Presence to reroll a failed Charisma (Intimidation) or Charisma (Persuasion) check once per long rest.",
  "Cuando tomas la acción de Atacar, puedes reemplazar uno de tus ataques por un cono de 20 pies o línea de 30 pies de energía dracónica que inflige dos dados de daño de artes marciales (prof veces/descanso largo o por 2 Ki).": "When you take the Attack action on your turn, you can replace one of the attacks with an exhalation of draconic energy in either a 20-foot cone or a 30-foot line that is 5 feet wide, dealing acid, cold, fire, lightning, or poison damage equal to two rolls of your Martial Arts die on a failed Dexterity save (proficiency bonus uses per long rest, or by spending 2 Ki points).",
  "Cuando usas Paso del Viento, manifiestas alas dracónicas temporales que te otorgan una velocidad de vuelo igual a tu velocidad terrestre hasta el final de tu turno.": "When you use your Step of the Wind, you can unfurl spectral draconic wings from your back that vanish at the end of your turn, giving you a flying speed equal to your walking speed.",
  "Como acción adicional emanas un aura dracónica de 10 pies durante 1 minuto: tú y tus aliados en el aura ganan resistencia al tipo de daño dracónico elegido, y los enemigos que fallen salvación de Sabiduría quedan asustados.": "As a bonus action, you can create a 10-foot-radius aura of draconic power for 1 minute: you and your allies in the aura gain resistance to acid, cold, fire, lightning, or poison damage, or you can frighten one creature in the aura that fails a Wisdom saving throw.",
  "Ganas visión ciega a 30 pies, tu Aliento del Dragón inflige daño masivo y cuando activas tu Aspecto del Dragón desatas una explosión que inflige 3d10 de daño a enemigos cercanos.": "You gain blindsight out to 10 feet, your Breath of the Dragon deals four rolls of your Martial Arts die in a larger area, and when you activate Aspect of the Wyrm, draconic fury erupts from you to deal 3d10 acid, cold, fire, lightning, or poison damage to chosen creatures in the aura.",
  "Tu estudio de la mortalidad te permite extraer energía vital de quienes caen ante ti. Cuando reduces a una criatura a 0 puntos de golpe a 5 pies de ti o menos, ganas puntos de golpe temporales iguales a tu modificador de Sabiduría + tu nivel de monje (mínimo 1).": "Your study of death allows you to extract vitality from another creature as it nears its demise. When you reduce a creature within 5 feet of you to 0 hit points, you gain temporary hit points equal to your Wisdom modifier + your monk level (minimum of 1 temporary hit point).",
  "Como acción en tu turno, muestras un atisbo de la muerte a quienes te rodean. Todas las criaturas a 30 pies de ti que puedan verte deben superar una tirada de salvación de Sabiduría contra tu CD de salvación de Ki o quedarán asustadas de ti hasta el final de tu siguiente turno.": "As an action on your turn, you can unsettle or terrify those around you. When you take this action, each creature within 30 feet of you that can see you must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn.",
  "Usas tu familiaridad con la parca para escapar de su abrazo. Cuando quedas reducido a 0 puntos de golpe, puedes gastar 1 punto de Ki (sin usar ninguna acción) para quedar a 1 punto de golpe en su lugar.": "You use your familiarity with death to escape its grasp. When you are reduced to 0 hit points, you can expend 1 Ki point (no action required) to have 1 hit point instead.",
  "Puedes canalizar la energía letal destructiva directamente en el corazón de otra criatura. Como acción tocas a una criatura a 5 pies y gastas de 1 a 10 puntos de Ki. El objetivo debe hacer una tirada de salvación de Constitución: si falla, recibe 2d10 de daño necrótico por cada punto de Ki gastado; si tiene éxito, recibe la mitad del daño.": "Your touch can channel the energy of death into a creature. As an action, you touch one creature within 5 feet of you, and you expend 1 to 10 Ki points. The target must make a Constitution saving throw, and it takes 2d10 necrotic damage per Ki point spent on a failed save, or half as much damage on a successful one.",
  "Añades la mitad de tu bonificador de competencia (redondeando hacia abajo) a cualquier prueba de característica que no incluya ya tu bonificador de competencia (¡incluye tiradas de iniciativa!).": "You can add half your proficiency bonus, rounded down, to any ability check you make that doesn't already include your proficiency bonus (including initiative rolls!).",
  "Tú y los aliados que escuchen tu música durante un descanso corto recuperáis 1d6 puntos de golpe adicionales al gastar dados de golpe.": "If you or any friendly creatures who can hear your performance regain hit points at the end of a short rest by spending one or more Hit Dice, each of those creatures regains an extra 1d6 hit points.",
  "Te unes a un Colegio Bárdico (Saber, Valor, Espadas, etc.), obteniendo rasgos artísticos y marciales a niveles 3, 6 y 14.": "You delve into the advanced techniques of a Bard College of your choice (Lore, Valor, Swords, etc.), gaining features at 3rd, 6th, and 14th level.",
  "Eliges dos de tus competencias de habilidad: tu bonificador de competencia se duplica para ellas.": "Choose two of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies.",
  "El dado de tu Inspiración Bárdica aumenta a d8.": "Your Bardic Inspiration die changes to a d8.",
  "Recuperas todos tus usos gastados de Inspiración Bárdica tras completar un descanso corto o largo.": "You regain all of your expended uses of Bardic Inspiration when you finish a short or long rest.",
  "Como acción comienzas una melodía que otorga a ti y a los aliados a 30 pies ventaja en tiradas de salvación contra quedar Asustado o Hechizado.": "As an action, you can start a performance that lasts until the end of your next turn, during which you and any friendly creatures within 30 feet of you have advantage on saving throws against being frightened or charmed.",
  "Obtienes un nuevo rasgo otorgado por tu colegio (Ataque Adicional en Colegio del Valor o Colegio de las Espadas; Secretos Mágicos Adicionales en Colegio del Saber).": "You gain a new feature granted by your Bard College (Extra Attack in the College of Valor or College of Swords; Additional Magical Secrets in the College of Lore).",
  "Desbloqueas ranuras y conjuros de 4.º nivel (Polimorfar, Puerta Dimensional, Compulsión).": "You unlock 4th-level spell slots and bard spells (Polymorph, Dimension Door, Compulsion).",
  "La curación adicional de tu Canción de Descanso aumenta a 1d8.": "The extra hit points regained from your Song of Rest increase to 1d8.",
  "Aprendes dos conjuros de cualquier clase de tu elección (incluso conjuros que un mago o clérigo no podría tener todavía). Cuentan como conjuros de bardo para ti.": "You learn two spells of your choice from any class, of a level you can cast or cantrips. The chosen spells count as bard spells for you and are included in the number in the Spells Known column.",
  "Eliges otras dos de tus competencias de habilidad para duplicar tu bonificador de competencia.": "Choose two more of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies.",
  "El dado de tu Inspiración Bárdica aumenta a d10.": "Your Bardic Inspiration die changes to a d10.",
  "Desbloqueas conjuros de 6.º nivel (Danza Irresistible de Otto, Sugestión en Masa, Visión Verdadera).": "You unlock 6th-level bard spells (Otto's Irresistible Dance, Mass Suggestion, True Seeing).",
  "La curación adicional de tu Canción de Descanso aumenta a 1d10.": "The extra hit points regained from your Song of Rest increase to 1d10.",
  "Aprendes otros dos conjuros de cualquier clase de tu elección.": "You learn two additional spells of your choice from any class.",
  "Alcanzas el clímax dramático de tu colegio bárdico.": "You reach the dramatic pinnacle of your Bard College.",
  "El dado de tu Inspiración Bárdica alcanza su valor máximo de d12.": "Your Bardic Inspiration die reaches its maximum size of a d12.",
  "La curación adicional de tu Canción de Descanso alcanza 1d12.": "The extra hit points regained from your Song of Rest increase to 1d12.",
  "Aprendes otros dos conjuros de cualquier clase de tu elección (¡incluyendo Deseo de 9.º nivel!).": "You learn two additional spells of your choice from any class (including 9th-level spells such as Wish!).",
  "Cuando tiras iniciativa y no te queda ningún uso de Inspiración Bárdica, recuperas inmediatamente un uso.": "When you roll initiative and have no uses of Bardic Inspiration left, you regain one use.",
  "Reacción: cuando una criatura a 60 pies haga una tirada de ataque, prueba de característica o tirada de daño, restas tu dado de Inspiración Bárdica al resultado.": "Reaction: When a creature that you can see within 60 feet of you makes an attack roll, an ability check, or a damage roll, you can expend one use of your Bardic Inspiration, roll the die, and subtract the number rolled from the creature's roll.",
  "Aprendes dos conjuros de cualquier clase de tu elección (de un nivel que puedas lanzar). Cuentan como conjuros de bardo para ti.": "You learn two spells of your choice from any class, of a level you can cast or a cantrip. The chosen spells count as bard spells for you.",
  "Cuando haces una prueba de característica, puedes tirar un dado de Inspiración Bárdica y sumarlo a tu prueba.": "When you make an ability check, you can expend one use of Bardic Inspiration, roll a Bardic Inspiration die, and add the number rolled to your ability check.",
  "Una criatura que tenga tu dado de inspiración puede sumarlo a una tirada de daño con arma, o usar su reacción para sumarlo a su CA contra un ataque.": "A creature that has a Bardic Inspiration die from you can roll that die and add the number rolled to a weapon damage roll it just made, or use its reaction when an attack roll is made against it to add the number rolled to its AC against that attack.",
  "Cuando usas tu acción para lanzar un conjuro de bardo, puedes realizar un ataque con arma como acción adicional.": "When you use your action to cast a bard spell, you can make one weapon attack as a bonus action.",
  "Ganas competencia con armaduras medias y la cimitarra. Puedes usar un arma cuerpo a cuerpo simple o marcial con la que seas competente como foco para tus conjuros de bardo.": "You gain proficiency with medium armor and the scimitar. If you're proficient with a simple or martial melee weapon, you can use it as a spellcasting focus for your bard spells.",
  "Eliges el Estilo de Combate Duelo (+2 al daño con una mano) o Combate con Dos Armas (+modificador al daño del ataque adicional).": "You adopt a style of fighting as your specialty, choosing Dueling (+2 to damage rolls with a one-handed weapon) or Two-Weapon Fighting (add ability modifier to the damage of the bonus-action attack).",
  "Al hacer la acción de Atacar, tu velocidad aumenta en 10 pies. Al impactar puedes gastar un dado de Inspiración Bárdica para realizar una floritura: Floritura Defensiva (+CA igual al dado), Deslizante (empujas al blanco 5 pies + dado y te mueves) o Cortante (dañas a un segundo blanco adyacente).": "Whenever you take the Attack action on your turn, your walking speed increases by 10 feet until the end of the turn. If a weapon attack that you make as part of this action hits a creature, you can expend one use of your Bardic Inspiration to perform a flourish: Defensive Flourish (+AC equal to the roll), Slashing Flourish (extra damage to the target and any other creature within 5 feet), or Mobile Flourish (push the target 5 feet + the roll and move to within 5 feet of it).",
  "Siempre que uses una opción de Floritura de Cuchilla, puedes tirar un d6 en lugar de gastar un dado de Inspiración Bárdica de tu reserva.": "Whenever you use a Blade Flourish option, you can roll a d6 and use it instead of expending a Bardic Inspiration die.",
  "Como acción adicional gastas un uso de Inspiración Bárdica: hasta un número de criaturas igual a tu mod de Carisma a 60 pies ganan 5 PG temporales (aumenta a 8 a lvl 5, 11 a lvl 10, 14 a lvl 15) y pueden usar su reacción de inmediato para moverse hasta su velocidad sin provocar ataques de oportunidad.": "As a bonus action, you can expend one use of your Bardic Inspiration to grant yourself a wondrous appearance: choose a number of creatures you can see within 60 feet up to your Charisma modifier; each gains 5 temporary hit points (increases to 8 at 5th level, 11 at 10th level, and 14 at 15th level) and can immediately use its reaction to move up to its speed without provoking opportunity attacks.",
  "Si actúas durante 1 minuto, puedes fascinar a hasta un número de humanoides igual a tu modificador de Carisma. Si fallan una salvación de Sabiduría contra tu CD de conjuros, quedan encantados durante 1 hora y te veneran como a un ídolo.": "If you perform for at least 1 minute, you can attempt to inspire wonder in your audience: choose a number of humanoids within 60 feet up to your Charisma modifier; each must succeed on a Wisdom saving throw against your spell save DC or be charmed by you for 1 hour, idolizing you.",
  "Como acción adicional adquieres una presencia sobrehumana durante 1 minuto. En cada uno de tus turnos puedes lanzar Mando como acción adicional sin gastar ninguna ranura de conjuro. Cualquier criatura encantada por ti falla automáticamente la salvación.": "As a bonus action, you cast Command without expending a spell slot, and you take on an appearance of unearthly beauty for 1 minute. During this time, you can cast Command as a bonus action on each of your turns without expending a spell slot, and any creature charmed by you automatically fails its saving throw against the Command.",
  "Como acción adicional adquieres un aspecto sobrecogedor durante 1 minuto. La primera vez que una criatura intente atacarte en cada uno de sus turnos, debe superar una salvación de Carisma o no podrá atacarte y deberá elegir otro objetivo o perder el ataque.": "As a bonus action, you can assume a magically majestic presence for 1 minute. On any turn that a creature tries to attack you for the first time, the attacker must make a Charisma saving throw against your spell save DC; on a failed save, it can't attack you on this turn and must choose a new target or waste the attack.",
  "Cuando impactas a una criatura con un ataque de arma, puedes gastar un uso de Inspiración Bárdica para infligir 3d6 de daño psíquico adicional a ese objetivo. Este daño aumenta a 5d6 a nivel 5, 8d6 a nivel 10, y 10d6 a nivel 15.": "When you hit a creature with a weapon attack, you can expend one use of your Bardic Inspiration to deal an extra 2d6 psychic damage to that target (increases to 3d6 at 5th level, 5d6 at 10th level, and 8d6 at 15th level).",
  "Si hablas a solas con una criatura durante al menos 1 minuto, puedes sembrar la paranoia en su mente. Debe superar una salvación de Sabiduría o quedará asustada de ti o de un objetivo a tu elección durante 1 hora.": "If you speak to a humanoid alone for at least 1 minute, you can attempt to seed paranoia in its mind: it must succeed on a Wisdom saving throw against your spell save DC or be frightened of you or another creature of your choice for 1 hour.",
  "Cuando un humanoide muere a 30 pies de ti, puedes usar tu reacción para capturar su sombra. Puedes usar esa sombra para disfrazarte mágicamente de esa persona, adquiriendo su apariencia, voz y recuerdos superficiales durante 1 hora.": "When a humanoid dies within 30 feet of you, you can magically capture its shadow using your reaction. You can use this shadow as an action to magically transform into the dead person for 1 hour, gaining access to its surface memories and general information.",
  "Como acción susurras una frase que solo una criatura a 30 pies puede oír. Debe superar una salvación de Sabiduría o creerá que posees su secreto más oscuro y destructivo, obedeciendo cualquier petición tuya que no la lleve al suicidio directo durante 8 horas.": "As an action, you magically whisper a phrase that only one creature of your choice within 30 feet of you can hear. The target must make a Wisdom saving throw against your spell save DC; on a failed save, it is charmed by you for 8 hours and convinced you know its most mortifying secret, obeying your commands.",
  "Cada vez que hagas una prueba de Carisma (Persuasión) o Carisma (Engaño), puedes considerar cualquier resultado de 9 o menor en el d20 como un 10.": "Whenever you make a Charisma (Persuasion) or Charisma (Deception) check, you can treat a d20 roll of 9 or lower as a 10.",
  "Como acción adicional gastas un uso de Inspiración Bárdica y eliges una criatura a 60 pies. Tiras el dado de inspiración y restas el número obtenido a la siguiente tirada de salvación que la criatura realice antes del comienzo de tu próximo turno.": "As a bonus action, you can expend one use of your Bardic Inspiration and choose one creature you can see within 60 feet of you. Roll the Bardic Inspiration die and subtract the number rolled from the next saving throw the creature makes before the start of your next turn.",
  "Cuando una criatura suma uno de tus dados de Inspiración Bárdica a una prueba de característica, tirada de ataque o salvación y fracasa, la criatura conserva el dado de Inspiración Bárdica sin gastarlo.": "When a creature adds one of your Bardic Inspiration dice to its ability check, attack roll, or saving throw and the roll fails, the creature can keep the Bardic Inspiration die.",
  "Como acción puedes hacer que tus palabras sean comprendidas mágicamente por hasta un número de criaturas igual a tu modificador de Carisma durante 1 hora, sin importar qué idiomas conozcan.": "As an action, choose one or more creatures within 60 feet of you, up to a number equal to your Charisma modifier (minimum of one creature). The chosen creatures can magically understand you, regardless of the language you speak, for 1 hour.",
  "Cuando un aliado utiliza tu Inspiración Bárdica con éxito en una tirada, puedes usar tu reacción para otorgar otro dado de Inspiración Bárdica a otra criatura a 60 pies sin consumir tu reserva de usos de inspiración (hasta Car mod veces/descanso largo).": "When a creature within 60 feet of you adds one of your Bardic Inspiration dice to its ability check, attack roll, or saving throw and the roll succeeds, you can use your reaction to encourage a different creature within 60 feet, giving it a Bardic Inspiration die without expending any of your Bardic Inspiration uses (Charisma modifier uses per long rest).",
  "Tus dados de Inspiración Bárdica flotan como motas de luz musical alrededor del aliado y otorgan beneficios adicionales: Si se usa en ataque, explota en daño de trueno en área; si se usa en salvación, otorga PG temporales; si se usa en prueba de característica, permite tirar dos dados y elegir el mayor.": "Whenever you give a creature a Bardic Inspiration die, you can utter a note from the Song of Creation to create a Tiny mote of potential that orbits the creature, granting an additional effect: on an attack roll, it shatters to deal thunder damage to creatures within 5 feet; on a saving throw, it grants temporary hit points equal to the roll + your Charisma modifier; on an ability check, you roll the Bardic Inspiration die twice and choose which roll to use.",
  "Como acción creas un objeto no mágico en un espacio libre a 10 pies de ti (de tamaño Mediano o menor y valor máximo igual a 20 veces tu nivel de bardo en po). El objeto dura un número de horas igual a tu bonificador de competencia.": "As an action, you can channel the magic of the Song of Creation to create one nonmagical item of your choice in an unoccupied space within 10 feet of you (Medium or smaller, worth no more than 20 times your bard level in gp), lasting for a number of hours equal to your proficiency bonus.",
  "Como acción animas mágicamente un objeto Grande o menor a 30 pies. El objeto cobra vida como un Objeto Danzante amigable que vuela, ataca con daño de fuerza y otorga un aura de +10 pies de velocidad a tus aliados adyacentes.": "As an action, you can animate one Large or smaller nonmagical item within 30 feet of you that isn't being worn or carried. The animate item uses the Dancing Item stat block, is friendly to you and your companions, flies, deals force damage, and alters the speed of creatures within 10 feet of it.",
  "Puedes crear múltiples objetos a la vez con tu Actuación de la Creación sin límite de coste en piezas de oro y hasta de tamaño Enorme.": "When you use your Performance of Creation feature, you can create more than one item at once (up to your Charisma modifier), you are no longer limited by gp value, and the items can be up to Huge.",
  "Puedes emplear herramientas de adivinación (mazo de tarokka, huesos o una calavera) como foco de lanzamiento para tus conjuros de bardo. A nivel 6, al lanzar un conjuro que inflija daño o cure mediante este foco, sumas 1d6 adicional.": "You learn the Guidance cantrip (60-foot range) and can use spiritual foci (a candle, crystal ball, skull, spirit board, or tarokka deck) as a spellcasting focus for your bard spells. Starting at 6th level, when you cast a bard spell that deals damage or restores hit points through the Spiritual Focus, roll a d6 and gain a bonus to one damage or healing roll of the spell.",
  "Como acción adicional gastas una Inspiración Bárdica y tiras en la tabla de espíritus (1d6/1d12): bestia (daño y derribo), guerrero (daño de fuerza masivo), sanador (curación múltiple), ilusionista (invisibilidad y teletransporte), dragón (aliento de fuego), o fantasma (atravesar paredes).": "As a bonus action while holding your Spiritual Focus, you can expend one use of your Bardic Inspiration and roll on the Spirit Tales table to retain a spirit tale you can unleash as an action: Clever Animal, Renowned Duelist, Beloved, Avenger, Caleb, Traveler, Beguiler, Phantom, Brute, Dragon, Angel, or Mind-Bender.",
  "Realizas una sesión de espiritismo con tus aliados durante un descanso corto para aprender temporalmente un conjuro de Nigromancia o Adivinación de cualquier clase hasta un nivel igual a tu bonificador de competencia.": "You can conduct an hour-long ritual channeling spirits (which can be done during a short or long rest) with willing creatures up to your proficiency bonus to temporarily learn one spell of your choice from any class from the school of divination or necromancy until you start a long rest.",
  "Al tirar en la tabla de Susurros del Más Allá, tiras 2 dados en lugar de 1 y puedes elegir cuál de los dos relatos espirituales quieres manifestar.": "Whenever you roll on the Spirit Tales table, you can roll the die twice and choose which of the two effects to bestow.",
  "Como acción puedes transformarte mágicamente en una bestia que hayas visto (2 usos por descanso corto). Asumes los PG y atributos físicos de la criatura (VD 1/4 máx, sin nadar ni volar).": "As an action, you can magically assume the shape of a beast that you have seen before (2 uses per short or long rest). You assume the beast's hit points and physical statistics (max CR 1/4, no flying or swimming speed at 2nd level).",
  "Eliges pertenecer a un Círculo Druídico (Tierra, Luna, etc.), obteniendo rasgos mágicos o transformaciones ferales a niveles 2, 6, 10 y 14.": "You choose to identify with a circle of druids (Circle of the Land, Circle of the Moon, etc.), gaining magical or feral features at 2nd, 6th, 10th, and 14th level.",
  "Desbloqueas ranuras y conjuros de 2.º nivel (Crecimiento Espinoso, Rayo de Luna, Pasar sin Huella, Piel de Roble).": "You unlock 2nd-level spell slots and druid spells (Spike Growth, Moonbeam, Pass without Trace, Barkskin).",
  "Puedes transformarte en bestias de hasta VD 1/2 con velocidad de nado (como Cocodrilo).": "You can use Wild Shape to transform into a beast with a challenge rating as high as 1/2 that doesn't have a flying speed (including beasts with a swimming speed, such as a Crocodile).",
  "Desbloqueas conjuros de 3.er nivel (Conjurar Animales, Llamar al Relámpago, Disipar Magia, Crecimiento Vegetal).": "You unlock 3rd-level druid spells (Conjure Animals, Call Lightning, Dispel Magic, Plant Growth).",
  "Obtienes un nuevo rasgo otorgado por el círculo elegido a nivel 2.": "You gain a new feature granted by the Druid Circle you chose at 2nd level.",
  "Desbloqueas conjuros de 4.º nivel (Polimorfar, Confusión, Muro de Fuego, Terreno Alucinatorio).": "You unlock 4th-level druid spells (Polymorph, Confusion, Wall of Fire, Hallucinatory Terrain).",
  "Puedes transformarte en bestias de hasta VD 1 con velocidad de vuelo (como Águila Gigante).": "You can use Wild Shape to transform into a beast with a challenge rating as high as 1, including beasts with a flying speed (such as a Giant Eagle).",
  "Desbloqueas conjuros de 5.º nivel (Comunión con la Naturaleza, Reencarnar, Descarga de Furia Elemental).": "You unlock 5th-level druid spells (Commune with Nature, Reincarnate, Wrath of Nature).",
  "Obtienes un rasgo avanzado de tu Círculo Druídico.": "You gain an advanced feature from your Druid Circle.",
  "Desbloqueas conjuros de 6.º nivel (Muro de Espinas, Curar Heridas en Masa, Rayo Solar).": "You unlock 6th-level druid spells (Wall of Thorns, Heal, Sunbeam).",
  "Desbloqueas conjuros de 7.º nivel (Tormenta de Fuego, Cambiar de Forma).": "You unlock 7th-level druid spells (Fire Storm, Plane Shift, Regenerate).",
  "Alcanzas la comunión suprema de tu Círculo Druídico.": "You reach the supreme communion of your Druid Circle.",
  "Desbloqueas conjuros de 8.º nivel (Terremoto, Explosión Solar, Controlar el Clima).": "You unlock 8th-level druid spells (Earthquake, Sunburst, Animal Shapes).",
  "Desbloqueas conjuros legendarios de 9.º nivel (Forma de Bestia Primigenia, Resurrección Verdadera, Tormenta de la Venganza).": "You unlock legendary 9th-level druid spells (Shapechange, True Resurrection, Storm of Vengeance).",
  "La magia primigenia ralentiza tu envejecimiento: por cada 10 años que pasen, tu cuerpo envejece físicamente solo 1 año.": "The primal magic that you wield causes you to age more slowly. For every 10 years that pass, your body ages only 1 year.",
  "Puedes lanzar muchos de tus conjuros de druida mientras estés en Forma Salvaje, realizando los componentes verbales y somáticos en tu forma bestial.": "You can cast many of your druid spells in any shape you assume using Wild Shape. You can perform the somatic and verbal components of a druid spell while in a beast shape, but you aren't able to provide material components.",
  "Puedes usar tu rasgo de Forma Salvaje un número ilimitado de veces. Además, puedes ignorar los componentes verbales, somáticos y materiales que carezcan de coste y no se consuman al lanzar cualquier conjuro de druida.": "You can use your Wild Shape an unlimited number of times. Additionally, you can ignore the verbal and somatic components of your druid spells, as well as any material components that lack a cost and aren't consumed by a spell.",
  "Aprendes un truco de druida adicional de tu elección.": "You learn one additional druid cantrip of your choice.",
  "Una vez al día tras un descanso corto, puedes recuperar ranuras de conjuro cuya suma de niveles sea menor o igual a la mitad de tu nivel de druida.": "Once per day during a short rest, you can choose expended spell slots to recover with a combined level equal to or less than half your druid level (rounded up), and none of the slots can be 6th level or higher.",
  "Ganas acceso a conjuros asociados a tu bioma (Ártico, Costa, Desierto, Bosque, Montaña, Pantano, etc.) siempre preparados.": "Your mystical connection to the land infuses you with the ability to cast certain spells associated with your chosen land type (Arctic, Coast, Desert, Forest, Grassland, Mountain, Swamp, or Underdark), which are always prepared.",
  "Moverte a través de terreno difícil no mágico no te cuesta movimiento extra ni sufres daño de plantas espinosas.": "Moving through nonmagical difficult terrain costs you no extra movement. You can also pass through nonmagical plants without being slowed by them and without taking damage from them if they have thorns, spines, or a similar hazard.",
  "No puedes ser envenenado ni asustado por elementales o fatas, y eres inmune a venenos y enfermedades.": "You can't be charmed or frightened by elementals or fey, and you are immune to poison and disease.",
  "Las bestias y criaturas vegetales deben superar salvación de Sabiduría contra tu CD para atacarte.": "When a beast or plant creature attacks you, that creature must make a Wisdom saving throw against your druid spell save DC. On a failed save, the creature must choose a different target, or the attack automatically misses.",
  "Puedes usar Forma Salvaje como acción adicional en lugar de una acción normal, y puedes gastar una ranura de conjuro como acción adicional para recuperar 1d8 PG por nivel de ranura mientras estás transformado.": "You gain the ability to use Wild Shape on your turn as a bonus action, rather than as an action. Additionally, while you are transformed by Wild Shape, you can use a bonus action to expend one spell slot to regain 1d8 hit points per level of the spell slot expended.",
  "Puedes transformarte en bestias con un Valor de Desafío de hasta 1 (como un Oso Pardo o Lobo Terrible).": "You can use Wild Shape to transform into a beast with a challenge rating as high as 1 (such as a Brown Bear or Dire Wolf), and starting at 6th level, up to a challenge rating equal to your druid level divided by 3.",
  "Tus ataques en forma de bestia cuentan como mágicos para superar resistencias.": "Your attacks in beast form count as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.",
  "Puedes gastar dos usos de Forma Salvaje a la vez para transformarte en un Elemental de Aire, Tierra, Fuego o Agua.": "You can expend two uses of Wild Shape at the same time to transform into an Air Elemental, an Earth Elemental, a Fire Elemental, or a Water Elemental.",
  "Puedes lanzar el conjuro Alterar el Propio Aspecto a voluntad sin gastar ranura.": "You have learned to use magic to alter your physical form in more subtle ways: you can cast the Alter Self spell at will.",
  "Rodeado de esporas fúngicas invisibles: cuando una criatura comience su turno o se mueva a 10 pies de ti, puedes usar tu reacción para infligirle 1d4 de daño necrótico si falla salvación de Constitución (1d6 a lvl 6, 1d8 a lvl 10, 1d10 a lvl 14).": "You are surrounded by invisible, necrotic spores: when a creature you can see moves into a space within 10 feet of you or starts its turn there, you can use your reaction to deal 1d4 necrotic damage to that creature unless it succeeds on a Constitution saving throw against your spell save DC (increases to 1d6 at 6th level, 1d8 at 10th level, and 1d10 at 14th level).",
  "Como acción consumes un uso de Forma Salvaje para despertar a tus esporas: ganas 4 puntos de golpe temporales por cada nivel de druida, el daño de tu Halo de Esporas se duplica, y tus ataques con arma cuerpo a cuerpo infligen 1d6 de daño necrótico adicional.": "As an action, you can expend a use of your Wild Shape feature to awaken those spores, rather than transforming into a beast: you gain 4 temporary hit points for each level you have in this class, your Halo of Spores damage rolls two dice instead of one, and your melee weapon attacks deal an extra 1d6 necrotic damage to any target they hit.",
  "Cuando una bestia o humanoide Pequeño o Mediano muera a 20 pies de ti, puedes usar tu reacción para animarlo como un Zombi bajo tu control que actúa en tu iniciativa.": "If a beast or a humanoid that is Small or Medium dies within 10 feet of you, you can use your reaction to animate it, causing it to stand up immediately with 1 hit point using the Zombie stat block for 1 hour.",
  "Como acción adicional mientras tu Entidad Simbiótica esté activa, arrojas un cubo de 10 pies de esporas a 30 pies de ti que dura 1 minuto e inflige tu daño de halo a quien empiece su turno allí.": "As a bonus action while your Symbiotic Entity feature is active, you can hurl spores up to 30 feet away, where they swirl in a 10-foot cube for 1 minute; any creature that moves into the cube or starts its turn there takes your Halo of Spores damage unless it succeeds on a Constitution saving throw.",
  "Las esporas alteran tu fisiología biológica: eres inmune a ser cegado, ensordecido, asustado y envenenado, y cualquier impacto crítico contra ti se convierte en impacto normal a menos que estés incapacitado.": "The fungal spores in your body alter you: you can't be blinded, deafened, frightened, or poisoned, and any critical hit against you counts as a normal hit instead, unless you're incapacitated.",
  "Creas una carta celeste minuciosa: conoces el truco Guía y puedes lanzar Rayo Guía sin gastar ranuras de conjuro un número de veces igual a tu bonificador de competencia.": "You've created a star chart that functions as a spellcasting focus for your druid spells: while holding it, you know the Guidance cantrip, you have the Guiding Bolt spell prepared, and you can cast Guiding Bolt without expending a spell slot a number of times equal to your proficiency bonus per long rest.",
  "Como acción adicional gastas un uso de Forma Salvaje para volverte una silueta de constelaciones titilantes durante 10 minutos. Eliges una constelación: Arquero (acción adicional para disparar flecha de luz a 60 pies por 1d8+Sab radiante), Cáliz (al lanzar un conjuro de curación, curas a otra criatura a 30 pies por 1d8+Sab adicional), o Dragón (cualquier tirada de d20 para concentración de conjuros o pruebas de Int/Sab de 9 o menor cuenta como 10).": "As a bonus action, you can expend a use of your Wild Shape feature to take on a starry form for 10 minutes. Choose a constellation: Archer (bonus action to make a ranged spell attack up to 60 feet dealing 1d8 + your Wisdom modifier radiant damage), Chalice (whenever you cast a healing spell using a spell slot, you or another creature within 30 feet regains 1d8 + your Wisdom modifier hit points), or Dragon (treat a roll of 9 or lower on the d20 as a 10 for Intelligence and Wisdom checks and Constitution saving throws to maintain concentration).",
  "Tras cada descanso largo tiras un dado para consultar el cielo: Fortuna (reacción para sumar 1d6 a un ataque, salvación o prueba de un aliado) o Desdicha (reacción para restar 1d6 a la tirada de un enemigo).": "Whenever you finish a long rest, you can consult your Star Map for omens and roll a die: on an even roll (Weal), you can use your reaction when a creature you can see within 30 feet makes an attack roll, ability check, or saving throw to roll a d6 and add it to the total; on an odd roll (Woe), you can use your reaction to roll a d6 and subtract it from the total.",
  "El dado del Arquero y el Cáliz aumenta a 2d8. Además, al inicio de cada uno de tus turnos en Forma Estelar puedes cambiar qué constelación tienes activa.": "The 1d8 of the Archer and the Chalice becomes 2d8, while the Dragon grants a flying speed of 20 feet and hover. Moreover, at the start of each of your turns while in your Starry Form, you can change which constellation glimmers on your body.",
  "En tu Forma Estelar te vuelves parcialmente incorpóreo: ganas resistencia al daño contundente, perforante y cortante.": "While in your Starry Form, you become partially incorporeal, giving you resistance to bludgeoning, piercing, and slashing damage.",
  "Aprendes silvano y puedes comunicarte y entender a cualquier bestia de forma natural sin necesidad de conjuros.": "You learn to speak, read, and write Sylvan. In addition, beasts can understand your speech, and you gain the ability to decipher their noises and motions.",
  "Como acción adicional invocas un espíritu incorpóreo a 60 pies con aura de 30 pies durante 1 minuto: Oso (otorga 5 + nivel de druida en PG temporales a todos los aliados en el aura), Halcón (reacción para dar ventaja en un ataque aliado), o Unicornio (cuando lanzas un conjuro de curación, todos los aliados en el aura recuperan puntos de golpe iguales a tu nivel de druida).": "As a bonus action, you can magically summon an incorporeal spirit to a point you can see within 60 feet of you, creating a 30-foot-radius aura for 1 minute: Bear Spirit (grants 5 + your druid level in temporary hit points and advantage on Strength checks and saves), Hawk Spirit (use your reaction to grant advantage on an attack roll against a target in the aura), or Unicorn Spirit (advantage on Perception checks, and casting a healing spell with a spell slot restores hit points equal to your druid level to each creature of your choice in the aura).",
  "Cualquier bestia o fata que conjures aparece con 2 PG adicionales por cada Dado de Golpe que posea, y sus ataques con armas naturales cuentan como mágicos.": "Any beast or fey summoned or created by a spell that you cast appears with more hit points than normal (2 extra hit points per Hit Die it has), and the damage from its natural weapons is considered magical for the purpose of overcoming immunity and resistance.",
  "Cuando una bestia o fata invocada por ti termine su turno dentro de tu Tótem Espiritual, recupera puntos de golpe iguales a la mitad de tu nivel de druida.": "When a beast or fey that you summoned or created with a spell ends its turn in your Spirit Totem aura, that creature regains a number of hit points equal to half your druid level.",
  "Si caes a 0 puntos de golpe o quedas incapacitado contra tu voluntad, se lanzan automáticamente Conjurar Animales como si usaras una ranura de nivel 9, apareciendo cuatro bestias protectoras para defenderte durante 1 hora.": "If you are reduced to 0 hit points or are incapacitated against your will, you can immediately gain the benefits of Conjure Animals as if it were cast using a 9th-level spell slot, summoning four beasts of your choice that are challenge rating 2 or lower within 20 feet of you for 1 hour without concentration.",
  "Posees una reserva de dados d6 igual a tu nivel de druida. Como acción adicional puedes gastar hasta la mitad de tus dados para curar a una criatura a 120 pies, otorgándole 1 PG temporal por cada dado gastado.": "You have a pool of fey energy represented by a number of d6s equal to your druid level. As a bonus action, you can choose one creature you can see within 120 feet of you and spend a number of those dice equal to half your druid level or less, healing the target for the total rolled and granting 1 temporary hit point per die spent.",
  "Durante un descanso corto o largo generas una esfera mágica de 30 pies que oculta la luz de fogatas y concede un bonificador de +5 a pruebas de Sigilo y Percepción a todos los ocupantes.": "During a short or long rest, you can invoke the shadowy power of the Gloaming Court to create an invisible 30-foot-radius sphere centered on a point you touch: it blocks light from open flames inside and grants you and your allies in the sphere a +5 bonus to Dexterity (Stealth) and Wisdom (Perception) checks.",
  "Como acción adicional te teletransportas hasta 60 pies a un espacio libre que puedas ver, o tocas a un aliado dispuesto para teletransportarlo hasta 30 pies (Sab mod veces/descanso largo).": "As a bonus action on your turn, you can teleport up to 60 feet to an unoccupied space you can see; alternatively, you can use your action to teleport one willing creature you touch up to 30 feet to an unoccupied space you can see (Wisdom modifier uses per long rest).",
  "Al terminar un descanso corto puedes lanzar Sueño, Proyección Astral o Círculo de Teletransporte conectando con enclaves fey salvajes.": "When you finish a short rest, you can cast Dream, Scrying, or Teleportation Circle (opening a portal to the last location where you finished a long rest on your current plane of existence) without expending a spell slot or material components once per long rest.",
  "Como acción gastas un uso de Forma Salvaje para manifestar un Espíritu de Fuego Salvaje a 30 pies: al surgir inflige 2d6 de daño de fuego a enemigos adyacentes. El espíritu puede volar, dispara proyectiles ígneos y puede teletransportarse a sí mismo y a tus aliados a 15 pies como acción adicional.": "As an action, you can expend one use of your Wild Shape feature to summon your wildfire spirit within 30 feet of you: when it appears, each creature within 10 feet of it (other than you) must succeed on a Dexterity saving throw or take 2d6 fire damage. The spirit can fly, hurl flame seeds, and teleport itself and willing creatures within 5 feet of it up to 15 feet.",
  "Mientras tu espíritu esté invocado, cualquier conjuro que lances que inflija daño de fuego o cure puntos de golpe suma 1d8 adicional a una de sus tiradas.": "While your wildfire spirit is summoned, whenever you cast a spell that deals fire damage or restores hit points, roll a d8, and you gain a bonus equal to the number rolled to one damage or healing roll of the spell.",
  "Cuando una criatura Pequeña o mayor muera a 30 pies de ti o de tu espíritu, deja una llama espectral durante 1 minuto. Puedes usar tu reacción para apagar la llama y curar a una criatura o infligir daño de fuego a un enemigo por 2d10 + Sab.": "When a Small or larger creature dies within 30 feet of you or your wildfire spirit, a harmless spectral flame springs forth in the dead creature's space for 1 minute. When a creature you can see enters that space, you can use your reaction to extinguish the spectral flame there and either heal the creature or deal fire damage to it equal to 2d10 + your Wisdom modifier.",
  "Si caes a 0 puntos de golpe mientras tu espíritu esté a 120 pies de ti, puedes reducir a tu espíritu a 0 PG para levantarte inmediatamente con la mitad de tus puntos de golpe máximos.": "If the spirit is within 120 feet of you when you are reduced to 0 hit points and thereby fall unconscious, you can cause the spirit to drop to 0 hit points; you then regain half your hit points and immediately rise to your feet.",
  "Obtienes Puntos de Hechicería iguales a tu nivel de hechicero. Puedes gastar puntos para crear ranuras de conjuro adicionales, o convertir ranuras de conjuro en puntos de hechicería como acción adicional.": "You gain Sorcery Points equal to your sorcerer level. You can expend Sorcery Points to create additional spell slots, or sacrifice a spell slot to gain a number of Sorcery Points equal to the slot's level as a bonus action.",
  "Aprendes a doblar y alterar las reglas de tus conjuros: eliges dos opciones entre Conjuro Acelerado (lanzar con acción adicional), Conjuro Gemelo (afectar a 2 blancos), Conjuro Sutil (sin componentes verbales ni somáticos), Conjuro Potenciado (repetir dados de daño), Conjuro Extendido o Conjuro Cuidadoso.": "You gain the ability to twist your spells to suit your needs: you gain two Metamagic options of your choice, such as Quickened Spell (cast as a bonus action), Twinned Spell (target a second creature), Subtle Spell (cast without verbal or somatic components), Empowered Spell (reroll damage dice), Extended Spell, or Careful Spell.",
  "Desbloqueas ranuras y conjuros arcanos de 2.º nivel (Imagen Espejada, Rayo Abrasador, Paso Brumoso).": "You unlock 2nd-level arcane spell slots and sorcerer spells (Mirror Image, Scorching Ray, Misty Step).",
  "Desbloqueas conjuros de 3.er nivel (Bola de Fuego, Contrahechizo, Relámpago, Acelerar, Volar).": "You unlock 3rd-level sorcerer spells (Fireball, Counterspell, Lightning Bolt, Haste, Fly).",
  "Obtienes un nuevo rasgo elemental o caótico otorgado por tu origen a nivel 1.": "You gain a new feature granted by the Sorcerous Origin you chose at 1st level.",
  "Desbloqueas conjuros arcanos de 4.º nivel (Polimorfar, Puerta Dimensional, Muro de Fuego).": "You unlock 4th-level arcane spells (Polymorph, Dimension Door, Wall of Fire).",
  "Desbloqueas conjuros de 5.º nivel (Telequinesis, Cono de Frío, Dominar Persona).": "You unlock 5th-level sorcerer spells (Telekinesis, Cone of Cold, Dominate Person).",
  "Aprendes una tercera opción de Metamagia de la lista de hechicero.": "You learn a third Metamagic option of your choice.",
  "Desbloqueas conjuros arcanos de 6.º nivel (Desintegrar, Cadena de Relámpagos, Rayo Solar).": "You unlock 6th-level arcane spells (Disintegrate, Chain Lightning, Sunbeam).",
  "Desbloqueas conjuros de 7.º nivel (Teletransporte, Bola de Fuego de Explosión Retardada, Dedo de la Muerte).": "You unlock 7th-level sorcerer spells (Teleport, Delayed Blast Fireball, Finger of Death).",
  "Obtienes un rasgo de movilidad o alteración arcana concedido por tu origen.": "You gain an advanced mobility or arcane alteration feature granted by your Sorcerous Origin.",
  "Desbloqueas conjuros de 8.º nivel (Dominar Monstruo, Terremoto, Palabra de Poder: Aturdir).": "You unlock 8th-level sorcerer spells (Dominate Monster, Earthquake, Power Word Stun).",
  "Aprendes una cuarta opción de Metamagia.": "You learn a fourth Metamagic option of your choice.",
  "Desbloqueas conjuros legendarios de 9.º nivel (Deseo, Tromba de Meteoros, Parar el Tiempo).": "You unlock legendary 9th-level sorcerer spells (Wish, Meteor Swarm, Time Stop).",
  "Desatas el poder supremo del origen de tu magia.": "You unleash the supreme capstone power of your Sorcerous Origin.",
  "Recuperas 4 puntos de hechicería gastados siempre que termines un descanso corto.": "You regain 4 expended Sorcery Points whenever you finish a short rest.",
  "Tras lanzar un conjuro de nivel 1+, el DM puede pedir una tirada de d20: con un 1 ocurre un efecto de la tabla salvaje.": "Immediately after you cast a sorcerer spell of 1st level or higher, the DM can have you roll a d20. If you roll a 1, roll on the Wild Magic Surge table to create a magical effect.",
  "Ganas ventaja en un ataque, prueba o salvación una vez por descanso largo.": "You can manipulate the forces of chance and chaos to gain advantage on one attack roll, ability check, or saving throw once per long rest (or when the DM has you roll on the Wild Magic Surge table).",
  "Reacción: gastas 2 puntos de hechicería para sumar o restar 1d4 a la tirada de d20 de otra criatura.": "Reaction: When another creature you can see makes an attack roll, an ability check, or a saving throw, you can spend 2 Sorcery Points to roll 1d4 and apply the number rolled as a bonus or penalty (your choice) to the creature's roll.",
  "Al tirar en la tabla de magia salvaje tiras dos veces y eliges el resultado que prefieras.": "Whenever you roll on the Wild Magic Surge table, you can roll twice and use either number.",
  "Cuando saques el daño máximo en un dado de conjuro, tiras un dado extra de ese tipo.": "When you roll damage for a spell and roll the highest number possible on any of the dice, choose one of those dice, roll it again, and add that roll to the damage once per turn.",
  "Eliges el tipo de dragón (Rojo, Azul, Dorado, Blanco, etc.) asociado a un tipo de daño elemental y aprendes el idioma Dracónico.": "You choose one type of dragon as your ancestor (Red, Blue, Gold, White, etc.) associated with an elemental damage type, and you can speak, read, and write Draconic.",
  "Tus PG máximos aumentan en 1 por cada nivel de hechicero, y sin armadura tu CA es 13 + Destreza.": "Your hit point maximum increases by 1 for each sorcerer level you have, and when you aren't wearing armor, your AC equals 13 + your Dexterity modifier.",
  "Sumas tu modificador de Carisma al daño de conjuros del elemento de tu ancestro, y gastas 1 punto de hechicería para ganar resistencia a ese elemento durante 1 hora.": "When you cast a spell that deals damage of the type associated with your draconic ancestry, you can add your Charisma modifier to one damage roll of that spell, and you can spend 1 Sorcery Point to gain resistance to that damage type for 1 hour.",
  "Como acción adicional brotan alas dracónicas de tu espalda otorgándote una velocidad de vuelo igual a tu velocidad actual.": "As a bonus action, you can sprout a pair of dragon wings from your back, gaining a flying speed equal to your current speed.",
  "Como acción gastas 5 puntos de hechicería para emitir un aura de 60 pies que deja a los enemigos Hechizados o Asustados durante 1 minuto.": "As an action, you can spend 5 Sorcery Points to exude an aura of awe or fear (your choice) to a distance of 60 feet for 1 minute (concentration), forcing hostile creatures to succeed on a Wisdom saving throw or be charmed or frightened.",
  "Al aprender conjuros de hechicero puedes elegir conjuros de la lista completa del Clérigo además de la del Hechicero. Cuentan como conjuros de hechicero para ti.": "Your link to the divine allows you to learn spells from the cleric class. When your Spellcasting feature lets you learn or replace a sorcerer cantrip or a sorcerer spell of 1st level or higher, you can choose the new spell from the cleric spell list or the sorcerer spell list, and it becomes a sorcerer spell for you.",
  "Si fallas una tirada de ataque o una tirada de salvación, puedes tirar 2d4 y sumarlos al resultado final, pudiendo convertir el fallo en un éxito (1/descanso corto o largo).": "If you fail a saving throw or miss with an attack roll, you can roll 2d4 and add it to the total, possibly changing the outcome (1/short or long rest).",
  "Cuando tú o un aliado a 5 pies tire dados para recuperar puntos de golpe mediante un conjuro, puedes gastar 1 punto de hechicería para relanzar cualquier cantidad de dados de curación.": "Whenever you or an ally within 5 feet of you rolls dice to determine the number of hit points a spell restores, you can spend 1 Sorcery Point to reroll any number of those dice once, provided you aren't incapacitated.",
  "Como acción adicional manifiestas un par de alas angelicales (o demoníacas si tu afinidad es impía) en tu espalda que te otorgan una velocidad de vuelo de 30 pies.": "You can use a bonus action to manifest a pair of spectral wings from your back, giving you a flying speed of 30 feet while the wings are present.",
  "Como acción adicional cuando tengas menos de la mitad de tus puntos de golpe máximos, recuperas puntos de golpe iguales a la mitad de tus PG máximos (1/descanso largo).": "As a bonus action when you have fewer than half of your hit points remaining, you can regain a number of hit points equal to half your hit point maximum (1/long rest).",
  "Ganas visión en la oscuridad a 120 pies. A nivel 3 aprendes el conjuro Oscuridad y puedes lanzarlo gastando 2 puntos de hechicería, permitiéndote ver a través de tu propia oscuridad mágica.": "You have darkvision with a range of 120 feet. When you reach 3rd level in this class, you learn the Darkness spell, which you can cast by spending 2 Sorcery Points or by expending a spell slot; if you cast it with Sorcery Points, you can see through the darkness created by the spell.",
  "Cuando el daño te reduzca a 0 puntos de golpe y no sea daño radiante o un crítico, puedes hacer una salvación de Carisma (CD 5 + daño sufrido). Si tienes éxito, te quedas a 1 punto de golpe.": "When damage reduces you to 0 hit points and isn't radiant damage or from a critical hit, you can make a Charisma saving throw (DC 5 + the damage taken). On a success, you instead drop to 1 hit point (1/long rest).",
  "Como acción adicional gastas 3 puntos de hechicería para invocar a un can espectral tenebroso a 30 pies que persigue a un enemigo objetivo. Mientras el sabueso esté a 5 pies de la víctima, esta tiene desventaja en salvaciones contra cualquiera de tus conjuros.": "As a bonus action, you can spend 3 Sorcery Points to magically summon a hound of ill omen to target one creature you can see within 120 feet of you. While the hound is within 5 feet of the target, the target has disadvantage on saving throws against any spell you cast.",
  "Como acción adicional cuando estés en luz tenue u oscuridad, puedes teletransportarte mágicamente hasta 120 pies a otro espacio desocupado que también esté en luz tenue u oscuridad.": "When you are in dim light or darkness, you can use a bonus action to magically teleport up to 120 feet to an unoccupied space you can see that is also in dim light or darkness.",
  "Como acción adicional gastas 6 puntos de hechicería para transformarte en una silueta de sombra durante 1 minuto: ganas resistencia a todo el daño excepto radiante y de fuerza, y puedes atravesar criaturas y objetos sólidos.": "As a bonus action, you can spend 6 Sorcery Points to magically transform yourself into a shadowy form for 1 minute: you have resistance to all damage except force and radiant damage, and you can move through other creatures and objects as if they were difficult terrain.",
  "Inmediatamente antes o después de lanzar un conjuro de nivel 1 o superior con tu acción, puedes usar una acción adicional para volar hasta 10 pies sin provocar ningún ataque de oportunidad.": "Immediately before or after you cast a spell of 1st level or higher on your turn, you can use a bonus action to cause whirling gusts of elemental air to briefly surround you, allowing you to fly up to 10 feet without provoking opportunity attacks.",
  "Ganas resistencia al daño de relámpago y trueno. Cuando lanzas un conjuro de nivel 1 o superior que inflija daño de relámpago o trueno, una tormenta azota a los enemigos a 10 pies infligiéndoles la mitad de tu nivel de hechicero en daño.": "You have resistance to lightning and thunder damage. In addition, whenever you start casting a spell of 1st level or higher that deals lightning or thunder damage, stormy magic erupts from you, dealing lightning or thunder damage equal to half your sorcerer level to creatures of your choice within 10 feet of you.",
  "Puedes controlar el clima local en un radio de 20 pies: detener o iniciar lluvias leves y alterar la dirección del viento como acción adicional.": "You gain the ability to subtly control the weather around you: if it is raining, you can use an action to cause the rain to stop falling in a 20-foot-radius sphere centered on you, and if it is windy, you can use a bonus action each round to choose the direction that the wind blows in a 100-foot-radius sphere.",
  "Como reacción cuando te impacten con un ataque cuerpo a cuerpo, infliges daño de relámpago igual a tu nivel de hechicero al atacante y debe superar salvación de Fuerza o ser empujado 20 pies.": "When you are hit by a melee attack, you can use your reaction to deal lightning damage to the attacker equal to your sorcerer level, and the attacker must also make a Strength saving throw against your sorcerer spell save DC or be pushed in a straight line up to 20 feet away from you.",
  "Ganas inmunidad total al daño de relámpago y trueno y una velocidad de vuelo permanente de 60 pies. Puedes reducir tu vuelo para conceder vuelo de 30 pies a un grupo de aliados.": "You gain immunity to lightning and thunder damage, and you also gain a magical flying speed of 60 feet. As an action, you can reduce your flying speed to 30 feet for 1 hour and choose up to 3 + your Charisma modifier creatures within 30 feet of you to gain a flying speed of 30 feet for 1 hour.",
  "Como acción adicional estableces un vínculo telepático con una criatura que puedas ver a 30 pies durante un número de minutos igual a tu nivel de hechicero, comunicándoos mentalmente en ambos sentidos.": "As a bonus action, choose one creature you can see within 30 feet of you. You and the chosen creature can speak telepathically with each other for a number of minutes equal to your sorcerer level while the two of you are within a number of miles of each other equal to your Charisma modifier.",
  "Aprendes conjuros psiónicos adicionales temáticos (Brazos de Hadar, Susurros Disonantes, Detectar Pensamientos, Calamar Mental, etc.).": "You learn additional spells when you reach certain levels in this class (Arms of Hadar, Dissonant Whispers, Mind Sliver, Calm Emotions, Detect Thoughts, Hunger of Hadar, Sending, Evard's Black Tentacles, Summon Aberration, Rary's Telepathic Bond, Telekinesis).",
  "Al lanzar cualquiera de tus Conjuros Psiónicos, puedes gastar puntos de hechicería iguales al nivel del conjuro en lugar de una ranura de conjuro. Si lo haces, el conjuro no requiere componentes verbales, somáticos ni materiales.": "When you cast any spell of 1st level or higher from your Psionic Spells feature, you can cast it by expending a spell slot as normal or by spending a number of Sorcery Points equal to the spell's level. If you cast the spell using Sorcery Points, it requires no verbal or somatic components, and it requires no material components unless they are consumed by the spell.",
  "Ganas resistencia al daño psíquico permanente y tienes ventaja en tiradas de salvación contra ser encantado o asustado.": "You gain resistance to psychic damage, and you have advantage on saving throws against being charmed or frightened.",
  "Como acción adicional gastas 1 o más puntos de hechicería para mutar tu cuerpo durante 10 minutos: ver invisibilidad (1 pt), velocidad de vuelo y levitar (1 pt), velocidad de nado y respirar agua (1 pt), o cuerpo viscoso para deslizarte por aberturas diminutas (1 pt).": "As a bonus action, you can spend 1 or more Sorcery Points to magically transform your body for 10 minutes: see invisible creatures within 60 feet (1 pt), gain a flying speed equal to your walking speed and hover (1 pt), gain a swimming speed equal to twice your walking speed and breathe underwater (1 pt), or squeeze through spaces as narrow as 1 inch wide (1 pt).",
  "Como acción te teletransportas hasta 120 pies dejando un vórtice gravitatorio de vacío: cada criatura a 30 pies del punto de partida debe superar salvación de Fuerza o sufrir 3d10 de daño de fuerza y ser succionada hacia el centro.": "As an action, you can teleport to an unoccupied space you can see within 120 feet of you. Immediately after you disappear, a vacuum appears and each creature within 30 feet of the space you left must make a Strength saving throw, taking 3d10 force damage and being pulled straight toward the space on a failed save.",
  "Aprendes conjuros de abjuración y transmutación de orden adicionales (Alarma, Protección contra el Mal, Restaurar, Contrajuro, Muro de Fuerza, etc.).": "You learn additional spells when you reach certain levels in this class (Alarm, Protection from Evil and Good, Aid, Lesser Restoration, Dispel Magic, Protection from Energy, Freedom of Movement, Summon Construct, Greater Restoration, Wall of Force).",
  "Como reacción cuando una criatura a 60 pies esté a punto de tirar un d20 con ventaja o desventaja, puedes cancelar la ventaja o desventaja en esa tirada (prof veces/descanso largo).": "When a creature you can see within 60 feet of you is about to roll a d20 with advantage or disadvantage, you can use your reaction to prevent the roll from being affected by advantage and disadvantage (proficiency bonus uses per long rest).",
  "Gastas de 1 a 5 puntos de hechicería para rodearte a ti o a un aliado de un escudo de engranajes mágicos. El escudo tiene una reserva de dados d8 igual a los puntos gastados; cuando el objetivo sufre daño, gasta dados para reducir el daño en esa cantidad.": "As an action, you can expend 1 to 5 Sorcery Points to create a magical ward around yourself or another creature you can see within 30 feet of you. The ward is represented by a number of d8s equal to the number of Sorcery Points spent; when the warded creature takes damage, it can expend a number of those dice, roll them, and reduce the damage taken by the total rolled.",
  "Como acción adicional entras en un trance de cálculo perfecto durante 1 minuto: los ataques contra ti no pueden tener ventaja, y cualquier tirada de d20 que hagas para ataques, salvaciones o pruebas de característica de 9 o menor cuenta como un 10.": "As a bonus action, you can enter a state of clockwork consciousness for 1 minute: attack rolls against you can't benefit from advantage, and whenever you make an attack roll, an ability check, or a saving throw, you can treat a roll of 9 or lower on the d20 as a 10.",
  "Como acción invocas a espíritus mecánicos de Mechanus en un cubo de 30 pies: reparan objetos al instante, curan hasta 100 puntos de golpe repartidos entre tus aliados y disipan automáticamente cualquier conjuro de nivel 6 o menor en el área.": "As an action, you summon spirits of order in a 30-foot cube originating from you: the spirits restore up to 100 hit points divided as you choose among any number of creatures in the cube, repair all damaged objects in the cube, and end every spell of 6th level or lower of your choice on creatures and objects in the cube.",
  "Aprendes conjuros asociados a las tres fases lunares (Luna Llena: Escudo de Fe, Rayo de Luna; Luna Creciente: Rayo de Enfermedad, Oscuridad; Luna Nueva: Falsa Vida, Ceguera/Sordera). Cada vez que terminas un descanso largo, puedes elegir qué fase lunar encarnas. Puedes lanzar el conjuro de 1er nivel de tu fase activa una vez por descanso largo sin gastar ranura de conjuro.": "You learn additional spells associated with three lunar phases (Full Moon: Shield, Lesser Restoration, Dispel Magic, Death Ward, Rary's Telepathic Bond; New Moon: Ray of Sickness, Blindness/Deafness, Vampiric Touch, Confusion, Mislead; Crescent Moon: Color Spray, Alter Self, Phantom Steed, Hallucinatory Terrain, Mislead). Whenever you finish a long rest, you can choose what lunar phase manifests its power through your magic, and you can cast the 1st-level spell of your current phase once per long rest without expending a spell slot.",
  "Aprendes el truco Llama Sagrada (Sacred Flame). Cuando lo lanzas, puedes elegir a dos criaturas que estén a 5 pies una de otra como objetivos en lugar de a una sola.": "You learn the Sacred Flame cantrip, which doesn't count against the number of sorcerer cantrips you know. When you cast the spell, you can target one creature as normal or target two creatures within range that are within 5 feet of each other.",
  "Las fases lunares potencian tu Metamagia. Cuando usas una opción de Metamagia en un conjuro de la escuela asociada a tu fase lunar activa (Abjuración/Adivinación en Llena, Ilusión/Nigromancia en Nueva, Transmutación/Conjuración en Creciente), puedes reducir el coste en 1 punto de hechicería (mínimo 0). Puedes usar este descuento un número de veces igual a tu bonificador de competencia por descanso largo.": "Your current Lunar Embodiment phase can affect your Metamagic feature: when you use Metamagic on a spell of a school of magic associated with your current phase (Abjuration/Divination in Full Moon, Evocation/Necromancy in New Moon, Illusion/Transmutation in Crescent Moon), you can reduce the Sorcery Points spent by 1 (minimum 0), up to a number of times equal to your proficiency bonus per long rest.",
  "Como acción adicional puedes gastar 1 punto de hechicería para cambiar de inmediato tu fase lunar actual a otra de las tres fases disponibles.": "As a bonus action, you can spend 1 Sorcery Point to change your current Lunar Embodiment phase to a different one.",
  "Ganas beneficios pasivos según tu fase activa: En Luna Llena tienes ventaja en pruebas de Investigación y Percepción; en Luna Nueva tienes ventaja en pruebas de Sigilo; en Luna Creciente ganas resistencia al daño radiante y necrótico.": "You gain passive benefits while in your chosen lunar phase: Full Moon (shed bright light in a 5-foot radius as a bonus action, and you and creatures of your choice have advantage on Intelligence [Investigation] and Wisdom [Perception] checks within the bright light), New Moon (advantage on Dexterity [Stealth] checks, and attack rolls have disadvantage against you in complete darkness), or Crescent Moon (resistance to necrotic and radiant damage).",
  "Como acción adicional desatas el poder culminante de tu luna activa: Luna Llena (aura radiante que ciega a enemigos a 30 pies y cura aliados), Luna Nueva (invisibilidad y teletransporte a 30 pies infligiendo daño necrótico), o Luna Creciente (resistencia universal y reacción para teletransportarse al ser atacado).": "As a bonus action, you can tap into a special power of your current Lunar Embodiment phase: Full Moon (radiate moonlight for a moment, forcing creatures of your choice within 30 feet to succeed on a Constitution save or be blinded, and healing one creature in that area for 3d8 hit points), New Moon (emanate gloom within 30 feet, dealing 3d10 necrotic damage and reducing speed to 0 on a failed Dexterity save, and turning invisible), or Crescent Moon (magically teleport to an unoccupied space within 60 feet, optionally bringing one willing creature within 5 feet, and gaining resistance to all damage until the start of your next turn).",
  "Fragmentos de conocimiento prohibido que te otorgan poderes permanentes (p. ej. Explosión Agónica para sumar Carisma al daño de Eldritch Blast, o Visión del Diablo para ver en oscuridad mágica a 120 pies).": "Fragments of forbidden knowledge that imbue you with an abiding magical ability (e.g., Agonizing Blast to add your Charisma modifier to Eldritch Blast damage, or Devil's Sight to see normally in magical and nonmagical darkness out to 120 feet).",
  "Tu patrón te otorga un regalo de lealtad: Pacto del Filo (arma mágica invocada), Pacto del Tomo (Grimorio de sombras con 3 trucos de cualquier clase) o Pacto de la Cadena (familiar sobrenatural mejorado).": "Your otherworldly patron bestows a gift upon you for your loyal service: Pact of the Blade (create a melee pact weapon in your empty hand), Pact of the Tome (a Book of Shadows granting three cantrips from any class's spell list), or Pact of the Chain (learn Find Familiar and summon an improved special familiar).",
  "Todas tus ranuras de pacto ascienden a 2.º nivel.": "All of your Pact Magic spell slots are now 2nd level.",
  "Desbloqueas una 3.ª invocación sobrenatural (como Sed de Hojas para realizar dos ataques por turno con tu arma de pacto).": "You unlock a 3rd Eldritch Invocation (such as Thirsting Blade, allowing you to attack twice with your pact weapon whenever you take the Attack action).",
  "Todas tus ranuras de pacto ascienden a 3.er nivel.": "All of your Pact Magic spell slots are now 3rd level.",
  "Obtienes un rasgo protector o evasivo otorgado por tu patrón a nivel 6.": "You gain a protective or evasive feature granted by your Otherworldly Patron at 6th level.",
  "Desbloqueas una 4.ª invocación sobrenatural.": "You unlock a 4th Eldritch Invocation.",
  "Todas tus ranuras de pacto ascienden a 4.º nivel.": "All of your Pact Magic spell slots are now 4th level.",
  "Desbloqueas una 5.ª invocación sobrenatural.": "You unlock a 5th Eldritch Invocation.",
  "Todas tus ranuras de pacto alcanzan el 5.º nivel, el límite de potencia para la magia del pacto.": "All of your Pact Magic spell slots reach 5th level, the maximum slot level for Pact Magic.",
  "Obtienes un rasgo de resistencia o defensa planar otorgado por tu patrón.": "You gain a resilience or planar defense feature granted by your Otherworldly Patron.",
  "Tu patrón te confiere un secreto mágico: eliges un conjuro de brujo de 6.º nivel. Puedes lanzarlo una vez sin gastar ranura de conjuro por descanso largo.": "Your patron bestows upon you a magical secret called an arcanum: choose one 6th-level spell from the warlock spell list as this arcanum. You can cast your arcanum spell once without expending a spell slot per long rest.",
  "Desbloqueas una 6.ª invocación sobrenatural.": "You unlock a 6th Eldritch Invocation.",
  "Eliges un conjuro de brujo de 7.º nivel que puedes lanzar una vez por descanso largo sin gastar ranura.": "You choose one 7th-level spell from the warlock spell list that you can cast once per long rest without expending a spell slot.",
  "Desatas el don más temible de tu patrón de otro mundo.": "You unleash the most fearsome capstone gift of your Otherworldly Patron.",
  "Eliges un conjuro de brujo de 8.º nivel que puedes lanzar una vez por descanso largo sin gastar ranura.": "You choose one 8th-level spell from the warlock spell list that you can cast once per long rest without expending a spell slot.",
  "Desbloqueas una 7.ª invocación sobrenatural.": "You unlock a 7th Eldritch Invocation.",
  "Eliges un conjuro definitivo de 9.º nivel (Visión Verdadera, Proyección Astral, Palabra de Poder: Matar) que puedes lanzar una vez por descanso largo.": "You choose one ultimate 9th-level spell from the warlock spell list (True Polymorph, Astral Projection, Power Word Kill, Foresight) that you can cast once per long rest without expending a spell slot.",
  "Tu número de ranuras de pacto de 5.º nivel recargables en descanso corto aumenta a 4.": "Your number of 5th-level Pact Magic spell slots that recharge on a short or long rest increases to 4.",
  "Puedes rogar a tu patrón durante 1 minuto para recuperar de golpe todas tus ranuras de pacto gastadas de 5.º nivel una vez por descanso largo.": "You can spend 1 minute entreating your patron for aid to regain all your expended spell slots from your Pact Magic feature once per long rest.",
  "Cuando reduces a un enemigo a 0 HP, ganas puntos de golpe temporales iguales a Carisma + nivel de brujo.": "When you reduce a hostile creature to 0 hit points, you gain temporary hit points equal to your Charisma modifier + your warlock level (minimum of 1).",
  "Puedes sumar 1d10 a una prueba de característica o tirada de salvación tuya una vez por descanso corto o largo.": "When you make an ability check or a saving throw, you can use this feature to add a d10 to your roll once per short or long rest.",
  "Eliges un tipo de daño al terminar un descanso para ganar resistencia a él hasta el próximo descanso.": "You can choose one damage type when you finish a short or long rest. You gain resistance to that damage type until you choose a different one with this feature.",
  "Al impactar a una criatura con un ataque, la transportas instantáneamente a través de los planos inferiores infligiéndole 10d10 de daño psíquico (1 vez por descanso largo).": "When you hit a creature with an attack, you can use this feature to instantly transport the target through the lower planes; at the end of your next turn, the target returns and takes 10d10 psychic damage if it isn't a fiend (1/long rest).",
  "Eliges un objetivo como acción adicional: crítico con 19-20, daño extra igual a tu bonificador de competencia y te curas si muere.": "As a bonus action, choose one creature you can see within 30 feet of you to curse it for 1 minute: you gain a bonus to damage rolls equal to your proficiency bonus, score a critical hit on a roll of 19 or 20, and regain hit points equal to your warlock level + your Charisma modifier if the cursed target dies.",
  "Ganas competencia con armaduras medias, escudos y armas marciales. Puedes usar Carisma para ataques y daño con tu arma elegida.": "You gain proficiency with medium armor, shields, and martial weapons. Whenever you finish a long rest, you can touch one weapon that lacks the two-handed property to use your Charisma modifier, instead of Strength or Dexterity, for its attack and damage rolls.",
  "Al matar a un humanoide puedes alzar su alma como un espectro sirviente que combate a tu lado hasta tu próximo descanso largo.": "When you slay a humanoid, you can cause its spirit to rise from its corpse as a specter that obeys your verbal commands and gains a bonus to its attack rolls equal to your Charisma modifier until your next long rest.",
  "Cuando tu objetivo maldito te impacte con un ataque, tiras un d6: con un 4 o más, el ataque falla independientemente de la tirada.": "If the target cursed by your Hexblade's Curse hits you with an attack roll, you can use your reaction to roll a d6. On a 4 or higher, the attack instead misses you, regardless of its roll.",
  "Cuando tu objetivo bajo la Maldición del Hexblade muera, puedes transferir inmediatamente la maldición a otra criatura a 30 pies.": "When the creature cursed by your Hexblade's Curse dies, you can apply the curse to a different creature you can see within 30 feet of you, provided you aren't incapacitated.",
  "Puedes comunicarte telepáticamente con cualquier criatura que puedas ver a 30 pies de ti. No necesitas compartir un idioma, pero la criatura debe ser capaz de entender al menos un idioma.": "You can telepathically speak to any creature you can see within 30 feet of you. You don't need to share a language with the creature for it to understand your telepathic utterances, but the creature must be able to understand at least one language.",
  "Como reacción cuando una criatura realice una tirada de ataque contra ti, puedes imponer desventaja en ese ataque. Si el ataque falla, tu siguiente tirada de ataque contra esa criatura tiene ventaja (1/descanso corto o largo).": "When a creature makes an attack roll against you, you can use your reaction to impose disadvantage on that roll. If the attack misses you, your next attack roll against the creature has advantage if you make it before the end of your next turn (1/short or long rest).",
  "Tus pensamientos no pueden ser leídos por ningún medio telepático. Ganas resistencia al daño psíquico, y cuando una criatura te inflija daño psíquico, sufre la misma cantidad de daño de vuelta.": "Your thoughts can't be read by telepathy or other means unless you allow it. You also have resistance to psychic damage, and whenever a creature deals psychic damage to you, that creature takes the same amount of damage that you do.",
  "Como acción tocas a un humanoide incapacitado: queda encantado por ti indefinidamente mientras tú y él permanezcáis en el mismo plano, y puedes comunicarte telepáticamente con él a cualquier distancia.": "You can use your action to touch an incapacitated humanoid. That creature is then charmed by you until a Remove Curse spell is cast on it, the charmed condition is removed from it, or you use this feature again. You can communicate telepathically with the charmed creature as long as the two of you are on the same plane of existence.",
  "Como acción desatas una ola de gracia feérica aterradora: cada criatura en un cubo de 10 pies centrado en ti debe superar una salvación de Sabiduría o quedar encantada o asustada de ti hasta el final de tu siguiente turno (1/descanso corto o largo).": "As an action, you can cause each creature in a 10-foot cube originating from you to make a Wisdom saving throw against your warlock spell save DC. The creatures that fail their saving throws are all charmed or frightened by you (your choice) until the end of your next turn (1/short or long rest).",
  "Como reacción cuando recibas daño, te vuelves invisible y te teletransportas hasta 60 pies a un espacio desocupado que puedas ver, permaneciendo invisible hasta tu siguiente turno (1/descanso corto o largo).": "When you take damage, you can use your reaction to turn invisible and teleport up to 60 feet to an unoccupied space you can see. You remain invisible until the start of your next turn or until you attack or cast a spell (1/short or long rest).",
  "Eres inmune a ser encantado. Cuando una criatura intente encantarte, puedes usar tu reacción para volver su propio efecto en su contra, forzándola a quedar encantada por ti durante 1 minuto.": "You are immune to being charmed, and when another creature attempts to charm you, you can use your reaction to attempt to turn the charm back on that creature: it must succeed on a Wisdom saving throw against your warlock spell save DC or be charmed by you for 1 minute.",
  "Como acción sumes a una criatura a 60 pies en un reino ilusorio de pesadilla: queda cegada, ensordecida y asustada o encantada por ti durante 1 minuto si falla una salvación de Sabiduría (1/descanso corto o largo).": "As an action, choose a creature that you can see within 60 feet of you. It must make a Wisdom saving throw against your warlock spell save DC. On a failed save, it is charmed or frightened by you (your choice) for 1 minute and thinks it is lost in a misty realm, unable to see or hear anything besides itself and you (1/short or long rest).",
  "Aprendes los trucos Luz y Llama Sagrada sin contar contra tu límite de trucos conocidos.": "You learn the Light and Sacred Flame cantrips. They count as warlock cantrips for you, but they don't count against your number of cantrips known.",
  "Posees una reserva de dados d6 igual a 1 + tu nivel de brujo. Como acción adicional puedes gastar dados de tu reserva (hasta tu modificador de Carisma a la vez) para curar a una criatura a 60 pies.": "You have a pool of d6s that you spend to fuel healing, equal to 1 + your warlock level. As a bonus action, you can heal one creature you can see within 60 feet of you, spending dice from the pool (up to your Charisma modifier at once).",
  "Ganas resistencia al daño radiante. Cuando lanzas un conjuro que inflija daño de fuego o radiante, sumas tu modificador de Carisma a una tirada de daño del conjuro.": "You have resistance to radiant damage, and when you cast a spell that deals radiant or fire damage, you can add your Charisma modifier to one radiant or fire damage roll of that spell against one of its targets.",
  "Al terminar un descanso corto o largo, ganas puntos de golpe temporales iguales a tu nivel de brujo + modificador de Carisma, y cada uno de tus aliados gana puntos de golpe temporales iguales a la mitad de tu nivel de brujo + modificador de Carisma.": "Whenever you finish a short or long rest, you gain temporary hit points equal to your warlock level + your Charisma modifier. Additionally, choose up to five creatures you can see at the end of the rest; those creatures each gain temporary hit points equal to half your warlock level + your Charisma modifier.",
  "Cuando debas hacer una salvación de muerte al comienzo de tu turno, puedes levantarte de inmediato con la mitad de tus PG máximos, infligiendo 2d8 + Car en daño radiante y cegando a los enemigos a 30 pies.": "When you have to make a death saving throw at the start of your turn, you can instead spring back to your feet with a burst of radiant energy: you regain hit points equal to half your hit point maximum, and each creature of your choice within 30 feet takes 2d8 + your Charisma modifier radiant damage and is blinded until the end of the current turn (1/long rest).",
  "Recibes un objeto mágico diminuto (lámpara, anillo, frasco). Como acción puedes entrar en la vasija como un refugio extradimensional durante horas. Además, una vez por turno al impactar con un ataque infliges daño adicional según tu patrón (Tierra contundente, Aire trueno, Fuego fuego, o Agua frío) igual a tu bonificador de competencia.": "Your patron gifts you a magical Tiny vessel (an oil lamp, urn, ring, or stoppered bottle). As an action, you can magically vanish and enter your vessel's extradimensional interior for a number of hours equal to twice your proficiency bonus. In addition, once during each of your turns when you hit with an attack roll, you can deal extra damage equal to your proficiency bonus of a type determined by your patron's kind (Dao: bludgeoning; Djinni: thunder; Efreeti: fire; Marid: cold).",
  "Ganas resistencia al tipo de daño asociado a tu patrón elemental. Además, como acción adicional puedes ganar una velocidad de vuelo de 30 pies durante 10 minutos (prof veces/descanso largo).": "You gain resistance to a damage type determined by your patron's kind (Dao: bludgeoning; Djinni: thunder; Efreeti: fire; Marid: cold). In addition, as a bonus action, you can give yourself a flying speed of 30 feet that lasts for 10 minutes, during which you can hover (proficiency bonus uses per long rest).",
  "Puedes llevar contigo a hasta 5 criaturas aliadas dentro de tu Vasija del Genio, y todos los ocupantes obtienen los beneficios de un descanso corto completo en solo 10 minutos.": "When you enter your Genie's Vessel via the Bottled Respite feature, you can now choose up to five willing creatures that you can see within 30 feet of you, and the chosen creatures are drawn into the vessel with you. In addition, anyone who remains within the vessel for at least 10 minutes gains the benefit of finishing a short rest.",
  "Pides un deseo a tu patrón: puedes duplicar el efecto de cualquier conjuro de nivel 6 o menor de cualquier lista de clases que requiera 1 acción, sin componentes costosos (1/1d4 descansos largos).": "As an action, you can speak your desire to your Genie's Vessel, requesting the effect of one spell that is 6th level or lower and has a casting time of 1 action from any class's spell list, taking effect without needing components (usable again after 1d4 long rests).",
  "Como acción adicional adquieres una presencia cadavérica aterradora durante 1 minuto: ganas 1d10 + tu nivel de brujo en PG temporales, inmunidad a la condición Asustado, y una vez en cada uno de tus turnos al golpear a un enemigo puedes forzarlo a superar una salvación de Sabiduría o quedar asustado de ti.": "As a bonus action, you manifest an aspect of your patron's dreadful power for 1 minute: you gain temporary hit points equal to 1d10 + your warlock level, you are immune to the frightened condition, and once during each of your turns when you hit a creature with an attack roll, you can force it to make a Wisdom saving throw or become frightened of you until the end of your next turn.",
  "No necesitas comer, beber ni respirar. Al infligir daño con una tirada de ataque, puedes cambiar el tipo de daño a necrótico, y en Forma de Pavor tiras un dado de daño adicional del ataque.": "You no longer need to eat, drink, or breathe. In addition, once during each of your turns, when you hit a creature with an attack roll and roll damage against the creature, you can replace the damage type with necrotic damage, and while you are using your Form of Dread, you can roll one additional damage die when determining the necrotic damage the target takes.",
  "Ganas resistencia al daño necrótico (inmunidad en Forma de Pavor). Si caes a 0 PG, puedes explotar en energía necrótica de 2d10 + nivel a enemigos a 30 pies y quedar a 1 PG con 1 nivel de agotamiento.": "You have resistance to necrotic damage (or immunity while using Form of Dread). In addition, when you would be reduced to 0 hit points, you can use your reaction to drop to 1 hit point instead and cause your body to erupt with deathly energy: each creature of your choice within 30 feet takes necrotic damage equal to 2d10 + your warlock level, and you gain 1 level of exhaustion.",
  "Como acción proyectas tu espíritu fuera de tu cuerpo durante 1 hora: tu espíritu puede volar, atravesar muros, tus conjuros de nigromancia y trucos no requieren componentes verbales ni somáticos y recuperas PG iguales a la mitad del daño necrótico que inflijas.": "As an action, you can project your spirit from your body for up to 1 hour (concentration): your spirit and body gain resistance to bludgeoning, piercing, and slashing damage, your conjuration and necromancy spells require no verbal, somatic, or non-costly material components, you gain a flying speed equal to your walking speed and can move through creatures and objects, and while in Form of Dread you regain hit points equal to half the necrotic damage you deal once per turn.",
  "Como acción adicional invocas un tentáculo espectral de agua de 10 pies a 60 pies de ti durante 1 minuto. Puedes moverlo 30 pies y atacar con él como acción adicional para infligir 1d8 de daño de frío y reducir la velocidad del enemigo en 10 pies.": "As a bonus action, you create a 10-foot-long spectral tentacle at a point you can see within 60 feet of you for 1 minute. You can move the tentacle up to 30 feet and make a melee spell attack against a creature within 10 feet of it as a bonus action, dealing 1d8 cold damage (2d8 at 10th level) and reducing its speed by 10 feet until the start of your next turn.",
  "Ganas una velocidad de nado de 40 pies y la capacidad de respirar bajo el agua.": "You gain a swimming speed of 40 feet, and you can breathe underwater.",
  "Como reacción cuando tú o un aliado a 10 pies del tentáculo reciba daño, el tentáculo reduce el daño en 1d8 (2d8 a nivel 10).": "When you or a creature you can see takes damage while within 10 feet of the spectral tentacle, you can use your reaction to choose one of those creatures and reduce the damage to that creature by 1d8 (increases to 2d8 at 10th level).",
  "Aprendes el conjuro Tentáculos Negros de Evard sin contar contra tus conjuros conocidos y puedes lanzarlo gratis una vez por descanso largo ganando puntos de golpe temporales iguales a tu nivel de brujo.": "You learn the spell Evard's Black Tentacles; it counts as a warlock spell for you, but it doesn't count against the number of spells you know. You can also cast it once without a spell slot per long rest, gaining temporary hit points equal to your warlock level, and your concentration on it can't be broken by taking damage.",
  "Como acción puedes sumergirte en un estanque de agua y teletransportarte a ti mismo y hasta 5 criaturas dispuestas hasta 1 milla de distancia a cualquier masa de agua conocida.": "As an action, you can magically teleport yourself and up to five other willing creatures that you can see within 30 feet of you. Amid a whirl of tentacles, you all vanish and then reappear up to 1 mile away in a body of water you've seen (pond size or larger) or within 30 feet of it.",
  "Aprendes el truco Piedad con los Moribundos (Spare the Dying). Tienes ventaja en las tiradas de salvación contra cualquier enfermedad. Además, los no muertos deben superar una tirada de salvación de Sabiduría contra tu CD de conjuros para poder atacarte o seleccionarte con un efecto dañino directo.": "You learn the Spare the Dying cantrip, which counts as a warlock cantrip for you, and you have advantage on saving throws against any disease. Additionally, if an undead targets you directly with an attack or a harmful spell, that creature must make a Wisdom saving throw against your warlock spell save DC; on a failed save, it must choose a new target or forfeit targeting someone instead of you.",
  "Puedes engañar a la parca. Recuperas 1d8 + tu modificador de Constitución puntos de golpe cuando tienes éxito en una tirada de salvación de muerte o cuando estabilizas a una criatura con Piedad con los Moribundos (1/descanso largo).": "You can give yourself vitality when you cheat death or when you help someone else cheat it. You can regain hit points equal to 1d8 + your Constitution modifier when you succeed on a death saving throw or when you stabilize a creature with Spare the Dying (1/long rest).",
  "Puedes contener la respiración indefinidamente y no necesitas comer, beber ni dormir (aunque sigues requiriendo reposo para descansar). Además, envejeces a un ritmo diez veces más lento de lo normal (1 año por cada 10 años que transcurren).": "You can hold your breath indefinitely, and you don't require food, water, or sleep, although you still require rest to reduce exhaustion and still benefit from finishing short and long rests. In addition, you age at a slower rate: for every 10 years that pass, your body ages only 1 year, and you are immune to being magically aged.",
  "Como acción adicional en tu turno, puedes canalizar la energía de la vida eterna para recuperar 1d8 + tu nivel de brujo puntos de golpe. Además, si recolocas una extremidad cercenada en tu cuerpo mientras usas este rasgo, la extremidad se vuelve a unir instantáneamente (1/descanso corto o largo).": "On your turn, you can use a bonus action to regain hit points equal to 1d8 + your warlock level. Additionally, if you put a severed body part of yours back in place when you use this feature, the part reattaches (1/short or long rest).",
  "Especialización marcial: Tiro con Arco (+2 a tiradas de ataque con armas a distancia), Defensa (+1 CA), Duelo (+2 daño a una mano) o Combate con Dos Armas (+modificador al daño en ataque adicional).": "Martial specialization: Archery (+2 bonus to attack rolls with ranged weapons), Defense (+1 AC while wearing armor), Dueling (+2 damage with a one-handed weapon), or Two-Weapon Fighting (add ability modifier to the damage of the bonus-action attack).",
  "Lanzas conjuros de la naturaleza basados en Sabiduría. Conoces un número fijo de conjuros y tienes ranuras para lanzarlos.": "You cast nature spells using Wisdom as your spellcasting ability. You know a set number of ranger spells and have spell slots to cast them.",
  "Eliges tu arquetipo de cazador o explorador (Cazador, Acechador Sombrío, etc.), obteniendo rasgos a niveles 3, 7, 11 y 15.": "You choose an archetype that you strive to emulate (Hunter, Gloom Stalker, Beast Master, etc.), gaining features at 3rd, 7th, 11th, and 15th level.",
  "Puedes gastar una ranura de conjuro de explorador como acción para percibir si hay aberraciones, celestiales, dragones, elementales, fatas, infernales o no muertos a 1 milla (o 6 millas en tu terreno predilecto).": "You can use your action and expend one ranger spell slot to focus your awareness on the region around you, sensing whether aberrations, celestials, dragons, elementals, fey, fiends, or undead are present within 1 mile of you (or within up to 6 miles if you are in your favored terrain).",
  "Desbloqueas ranuras y conjuros de 2.º nivel (Pasar sin Huella, Rayo de Luna, Cordón de Flechas, Silencio).": "You unlock 2nd-level spell slots and ranger spells (Pass without Trace, Spike Growth, Cordon of Arrows, Silence).",
  "Eliges un enemigo predilecto adicional y un segundo tipo de terreno predilecto.": "You choose one additional favored enemy, as well as an associated language, and one additional favored terrain.",
  "Obtienes un nuevo rasgo táctico o defensivo otorgado por tu arquetipo a nivel 3.": "You gain a new tactical or defensive feature granted by the Ranger Archetype you chose at 3rd level.",
  "Moverte a través de terreno difícil no mágico no te cuesta movimiento adicional, y pasas a través de plantas no mágicas sin sufrir daño ni quedar impedido.": "Moving through nonmagical difficult terrain costs you no extra movement. You can also pass through nonmagical plants without being slowed by them and without taking damage from them if they have thorns, spines, or a similar hazard.",
  "Desbloqueas conjuros de 3.er nivel (Conjurar Animales, Flecha Relampagueante, Respiración Acuática).": "You unlock 3rd-level ranger spells (Conjure Animals, Lightning Arrow, Water Breathing).",
  "Eliges un tercer tipo de terreno predilecto.": "You choose one additional favored terrain type.",
  "Puedes pasar 1 minuto creando camuflaje con barro, hojas y elementos naturales: obtienes un bonificador de +10 a pruebas de Sigilo mientras permanezcas inmóvil y apoyado contra una superficie natural.": "You can spend 1 minute creating camouflage for yourself with mud, dirt, plants, and other naturally occurring materials: you gain a +10 bonus to Dexterity (Stealth) checks as long as you remain still against a solid surface without moving or taking actions.",
  "Obtienes un rasgo ofensivo o de ataque múltiple otorgado por tu arquetipo.": "You gain an offensive or multiattack feature granted by your Ranger Archetype.",
  "Desbloqueas conjuros de 4.º nivel (Libertad de Movimiento, Localizar Criatura, Acechador Invisible).": "You unlock 4th-level ranger spells (Freedom of Movement, Locate Creature, Conjure Woodland Beings).",
  "Eliges un tercer tipo de enemigo predilecto.": "You choose one additional favored enemy, as well as an associated language.",
  "Puedes usar la acción de Esconderte como acción adicional en tu turno. Además, no puedes ser rastreado por medios no mágicos a menos que decidas dejar un rastro.": "You can use the Hide action as a bonus action on your turn. Also, you can't be tracked by nonmagical means, unless you choose to leave a trail.",
  "Alcanzas la cúspide táctica de tu arquetipo de explorador.": "You reach the tactical pinnacle of your Ranger Archetype.",
  "Desbloqueas conjuros supremos de 5.º nivel (Comunión con la Naturaleza, Aljaba Rápida, Piel Pétrea).": "You unlock supreme 5th-level ranger spells (Commune with Nature, Swift Quiver, Steel Wind Strike).",
  "Ganas sentidos sobrenaturales: cuando atacas a una criatura que no puedes ver, tu falta de visión no impone desventaja en tus tiradas de ataque, y eres consciente de la ubicación de cualquier criatura invisible a 30 pies de ti si no está oculta.": "You gain preternatural senses that help you fight creatures you can't see: when you attack a creature you can't see, your inability to see it doesn't impose disadvantage on your attack rolls against it, and you are also aware of the location of any invisible creature within 30 feet of you, provided that the creature isn't hidden from you.",
  "Te conviertes en un cazador sin rival: una vez en cada uno de tus turnos puedes añadir tu modificador de Sabiduría a la tirada de ataque o a la tirada de daño de un ataque que hagas contra uno de tus enemigos predilectos.": "You become an unparalleled hunter of your enemies: once on each of your turns, you can add your Wisdom modifier to the attack roll or the damage roll of an attack you make against one of your favored enemies.",
  "Eliges Asesino de Colosos (1d8 de daño extra a criaturas heridas), Cortador de Hordas (ataque extra contra enemigo adyacente) o Asesino de Gigantes (reacción para contraatacar a criaturas Grandes).": "You gain one of the following features of your choice: Colossus Slayer (deal an extra 1d8 damage once per turn to a target that is below its hit point maximum), Giant Killer (use your reaction to attack a Large or larger creature within 5 feet that attacks you), or Horde Breaker (once per turn, make another attack against a different creature within 5 feet of the original target).",
  "Eliges Escapar de la Horda (desventaja en ataques de oportunidad contra ti), Defensa contra Ataques Múltiples (+4 CA tras el primer impacto) o Voluntad de Hierro (ventaja en salvaciones contra Asustado).": "You gain one of the following features of your choice: Escape the Horde (opportunity attacks against you are made with disadvantage), Multiattack Defense (+4 bonus to AC against all subsequent attacks made by a creature for the rest of the turn after it hits you), or Steel Will (advantage on saving throws against being frightened).",
  "Eliges Ataque Volátil (ataque a distancia contra cualquier número de criaturas en un cono de 10 pies) o Torbellino (ataque cuerpo a cuerpo contra cualquier número de enemigos a 5 pies).": "You gain one of the following features of your choice: Volley (use your action to make a ranged attack against any number of creatures within 10 feet of a point you can see within your weapon's range) or Whirlwind Attack (use your action to make a melee attack against any number of creatures within 5 feet of you).",
  "Eliges Evasión, Mantenerse en Pie (reducir daño a la mitad como reacción) o Desviar el Golpe.": "You gain one of the following features of your choice: Evasion, Stand Against the Tide (when a hostile creature misses you with a melee attack, use your reaction to force it to repeat the attack against another creature), or Uncanny Dodge (use your reaction to halve an attack's damage against you).",
  "Sumas tu Sabiduría a las tiradas de Iniciativa. En tu primer turno en combate tu velocidad aumenta 10 pies y puedes hacer un ataque adicional que inflige 1d8 de daño extra.": "You can give yourself a bonus to your initiative rolls equal to your Wisdom modifier. At the start of your first turn of each combat, your walking speed increases by 10 feet for that turn, and if you take the Attack action on that turn, you can make one additional weapon attack that deals an extra 1d8 damage on a hit.",
  "Ganas Visión en la Oscuridad (60 pies) o aumenta en 30 pies si ya la tienes. Eres invisible para cualquier criatura que confíe en la visión en la oscuridad para verte en tinieblas.": "You gain darkvision out to a range of 60 feet (or increase its range by 30 feet if you already have darkvision). While in darkness, you are invisible to any creature that relies on darkvision to see you in that darkness.",
  "Ganas competencia en tiradas de salvación de Sabiduría (o Inteligencia/Carisma si ya la tienes).": "You gain proficiency in Wisdom saving throws (or Intelligence or Charisma saving throws if you already have this proficiency).",
  "Una vez en cada uno de tus turnos cuando falles un ataque con arma, puedes hacer otro ataque con arma como parte de la misma acción.": "Once on each of your turns when you miss with a weapon attack, you can make another weapon attack as part of the same action.",
  "Reacción: cuando una criatura te ataque sin tener ventaja, puedes imponer desventaja a esa tirada de ataque.": "Reaction: Whenever a creature makes an attack roll against you and doesn't have advantage on the roll, you can use your reaction to impose disadvantage on it.",
  "Manifiestas una Bestia de la Tierra, el Aire o el Agua que comparte tu iniciativa. Suma tu bonificador de competencia a su CA, tiradas de ataque, salvaciones y daño. Puedes ordenarle atacar o actuar como acción adicional en tu turno o reemplazando uno de tus ataques.": "You mystically summon a primal beast (Beast of the Land, Beast of the Sea, or Beast of the Sky) that shares your initiative. It adds your proficiency bonus to its AC, attack rolls, saving throws, and damage rolls. In combat, you can command the beast to take the Attack action using your bonus action or by sacrificing one of your attacks when you take the Attack action.",
  "En cualquier turno en que no ordenes a tu bestia atacar, puede usar la acción de Correr, Destrabarse o Esquivar como acción adicional.": "On any of your turns when your beast companion doesn't attack, you can use a bonus action to command the beast to take the Dash, Disengage, or Help action on its turn. In addition, the beast's attacks now count as magical for the purpose of overcoming resistance and immunity.",
  "Tu bestia compañera puede realizar dos ataques cada vez que le ordenes atacar en su turno.": "When you command your beast companion to take the Attack action, the beast can make two attacks, or it can take the Multiattack action if it has that action.",
  "Cuando te lanzas un conjuro a ti mismo, el conjuro también afecta a tu bestia si se encuentra a 30 pies o menos de ti.": "When you cast a spell targeting yourself, you can also affect your beast companion with the spell if the beast is within 30 feet of you.",
  "Como acción percibes la distancia y dirección al portal planar más cercano a 1 milla de ti (1/descanso corto o largo).": "As an action, you detect the distance and direction to the closest planar portal within 1 mile of you (1/short or long rest).",
  "Como acción adicional marcas a un objetivo a 30 pies: el siguiente impacto que le asestes con un arma en este turno convierte todo el daño del arma a daño de fuerza e inflige 1d8 de daño de fuerza adicional (2d8 a nivel 11).": "As a bonus action, choose one creature you can see within 30 feet of you: the next time you hit that creature on this turn with a weapon attack, all damage dealt by the attack becomes force damage, and the creature takes an extra 1d8 force damage from the attack (increases to 2d8 at 11th level).",
  "Como acción adicional puedes lanzar el conjuro Forma Etérea sin gastar ranura de conjuro, durando hasta el final de tu turno actual (1/descanso corto o largo).": "As a bonus action, you can cast the Etherealness spell with this feature, without expending a spell slot, but the spell ends at the end of the current turn (1/short or long rest).",
  "Al tomar la acción de Atacar, puedes teletransportarte hasta 10 pies antes de cada ataque a un espacio desocupado que puedas ver. Si atacas a al menos dos criaturas diferentes, ganas un tercer ataque gratis en ese turno.": "When you take the Attack action, you can teleport up to 10 feet before each attack to an unoccupied space you can see. If you attack at least two different creatures with the action, you can make one additional attack with it against a third creature.",
  "Como reacción cuando recibas daño de un ataque, puedes volverte incorpóreo momentáneamente para reducir a la mitad todo el daño de ese ataque.": "When you take damage from an attack, you can use your reaction to give yourself resistance to all of that attack's damage on this turn.",
  "Como acción observas a una criatura a 60 pies para discernir inmediatamente sus inmunidades, resistencias y vulnerabilidades al daño (Sab mod veces/descanso largo).": "As an action, choose one creature you can see within 60 feet of you: you immediately learn whether the creature has any damage immunities, resistances, or vulnerabilities and what they are (Wisdom modifier uses per long rest).",
  "Como acción adicional marcas a una criatura a 60 pies: la primera vez en cada turno que le inflijas daño con un arma, sufre 1d6 de daño adicional.": "As a bonus action, you designate one creature you can see within 60 feet of you as the target of this feature: the first time each turn that you hit that target with a weapon attack, it takes an extra 1d6 damage from the weapon.",
  "Sumas 1d6 a cualquier tirada de salvación que realices contra un efecto o conjuro lanzado por el objetivo de tu Presa del Exterminador.": "Whenever the target of your Slayer's Prey forces you to make a saving throw and whenever you make an ability check to escape that target's grapple, you add 1d6 to your roll.",
  "Como reacción cuando una criatura a 60 pies lance un conjuro o se teletransporte, fuerzas una salvación de Sabiduría contra tu CD: si falla, el conjuro o teletransporte se frustra y se pierde por completo (1/descanso corto o largo).": "When you see a creature casting a spell or teleporting within 60 feet of you, you can use your reaction to try to magically foil it: the creature must succeed on a Wisdom saving throw against your spell save DC, or its spell or teleport fails and is wasted (1/short or long rest).",
  "Si la criatura marcada por tu Presa del Exterminador te fuerza a hacer una tirada de salvación, puedes usar tu reacción para atacarla de inmediato con un arma: si impactas, superas automáticamente la tirada de salvación.": "If the target of your Slayer's Prey forces you to make a saving throw, you can use your reaction to make one weapon attack against the quarry immediately before making the saving throw; if the attack hits, your save automatically succeeds, in addition to the attack's normal effects.",
  "Una vez en cada uno de tus turnos al impactar con un ataque, tu enjambre puede: infligir 1d6 de daño perforante adicional, mover al enemigo hasta 15 pies si falla salvación de Fuerza, o moverte a ti 10 pies sin provocar ataques de oportunidad.": "Once on each of your turns, you can cause the swarm to assist you in one of the following ways immediately after you hit a creature with an attack: deal 1d6 piercing damage to the attack's target, move the target up to 15 feet horizontally if it fails a Strength saving throw, or move yourself 5 feet horizontally in a direction of your choice.",
  "Como acción adicional tu enjambre te eleva otorgándote una velocidad de vuelo de 10 pies y la capacidad de levitar durante 1 minuto (prof veces/descanso largo).": "As a bonus action, you can condense part of your swarm into a focused mass that lifts you up, granting you a flying speed of 10 feet and the ability to hover for 1 minute (proficiency bonus uses per long rest).",
  "El daño de tu Enjambre Recolector aumenta a 1d8 y puede derribar a los enemigos. Además, cuando te mueves con tu enjambre ganas media cobertura (+2 CA y salvaciones) hasta el inicio de tu siguiente turno.": "The damage of your Gathered Swarm increases to 1d8, if a creature fails its saving throw against being moved by the swarm you can also knock it prone, and when you are moved by the swarm it gives you half cover (+2 bonus to AC and Dexterity saving throws) until the start of your next turn.",
  "Como reacción cuando sufras daño, te desmaterializas en tu enjambre ganando resistencia a ese daño y teletransportándote hasta 30 pies (prof veces/descanso largo).": "When you take damage, you can use your reaction to give yourself resistance to that damage, vanishing into your swarm and teleporting to an unoccupied space that you can see within 30 feet of you (proficiency bonus uses per long rest).",
  "Aprendes el truco Taumaturgia y el idioma dracónico.": "You learn the Thaumaturgy cantrip, and you learn to speak, read, and write Draconic.",
  "Como acción invocas a tu compañero Draco (ácido, frío, fuego, relámpago o veneno). Comparte tu iniciativa, ataca con mordisco elemental y puede usar su reacción para imbuir los ataques de tus aliados con 1d6 de daño elemental adicional.": "As an action, you can magically summon the drake that is bound to you (acid, cold, fire, lightning, or poison). It shares your initiative, attacks with an elemental bite, and can use its reaction to infuse a strike within 30 feet with an extra 1d6 damage of its chosen essence type.",
  "Ganas resistencia al tipo de daño elemental de tu draco, tu draco gana alas y velocidad de nado o vuelo, y mientras lo montes puedes usarlo como montura de batalla.": "You gain resistance to the damage type of your drake's Draconic Essence, the drake grows to Medium size so you can use it as a mount if your size is Medium or smaller, its bite deals an extra 1d6 damage, and it gains a swimming or flying speed of 40 feet.",
  "Como acción tú o tu draco desatáis un cono de 30 pies o línea de 60 pies de daño elemental que inflige 8d6 de daño (1/descanso largo o gastando ranura de nivel 3 o superior).": "As an action, you can exhale a 30-foot cone of damaging breath or cause your drake to exhale it, dealing 8d6 acid, cold, fire, lightning, or poison damage (10d6 at 15th level) on a failed Dexterity saving throw (1/long rest, or by expending a spell slot of 3rd level or higher).",
  "Tu draco crece a tamaño Grande, el daño de su mordisco aumenta en 1d6, y como reacción cuando tú o él sufra daño podéis otorgaros resistencia a ese daño.": "Your drake grows to Large size, its bite deals an extra 1d6 damage, and while either you or the drake is within 30 feet of the other, you can use your reaction when you or the drake takes damage to give yourself or the drake resistance to that instance of damage.",
  "Una vez por turno al golpear a una criatura con un arma infliges 1d4 de daño psíquico adicional (1d6 a nivel 11). Puedes aplicar este daño a múltiples criaturas si las golpeas en el mismo turno.": "You can augment your weapon strikes with mind-scarring magic: when you hit a creature with a weapon, you can deal an extra 1d4 psychic damage to the target (increases to 1d6 at 11th level), which can take this extra damage only once per turn.",
  "Tienes ventaja en salvaciones contra ser encantado o asustado. Cuando cualquier criatura a 60 pies supere una salvación contra ser encantada o asustada, puedes usar tu reacción para redirigir el efecto a otro objetivo.": "You have advantage on saving throws against being charmed or frightened. In addition, whenever you or a creature you can see within 120 feet of you succeeds on a saving throw against being charmed or frightened, you can use your reaction to force a different creature you can see within 120 feet of you to make a Wisdom saving throw or be charmed or frightened for 1 minute.",
  "Puedes lanzar el conjuro Invocar Ser Feérico sin requerir concentración y gratis una vez por descanso largo.": "You know the spell Summon Fey; it doesn't count against the number of ranger spells you know, you can cast it without material components, you can cast it once per long rest without expending a spell slot, and whenever you start casting it you can modify it so that it doesn't require concentration (reducing its duration to 1 minute).",
  "Puedes lanzar Paso Brumoso sin gastar ranura de conjuro un número de veces igual a tu modificador de Sabiduría por cada descanso largo, y puedes llevar contigo a un aliado a 5 pies.": "You can cast Misty Step without expending a spell slot a number of times equal to your Wisdom modifier (minimum of once) per long rest, and whenever you cast Misty Step, you can bring along one willing creature you can see within 5 feet of you.",
  "Tus ataques desarmados infligen 1d6 de daño (1d8 a nv 5, 1d10 a nv 11, 1d12 a nv 17). Puedes usar Fuerza o Destreza. Puedes dar un golpe desarmado como acción adicional. Velocidad +5 pies x mitad de bonificador de competencia sin armadura pesada ni escudo.": "Your unarmed strikes deal 1d6 damage (1d8 at 5th level, 1d10 at 11th level, 1d12 at 17th level), and you can use Strength or Dexterity for their attack and damage rolls. You can make one unarmed strike as a bonus action, and your speed increases by 5 feet times half your proficiency bonus while you aren't wearing heavy armor or wielding a shield.",
  "Sin armadura ni escudo, tu Clase de Armadura (CA) es igual a 13 + Modificador de Constitución.": "While you are not wearing any armor and not wielding a shield, your Armor Class (AC) equals 13 + your Constitution modifier.",
  "Ganas Puntos de Flujo al impactar o esquivar ataques (máximo igual a tu bono de competencia). Gastas flujo para Golpes de Poder (+1d6 daño por punto) o sumar a salvaciones fallidas como reacción.": "You gain Flow Points when you hit with or dodge attacks (up to a maximum equal to your proficiency bonus). You can spend Flow Points on Power Strikes (+1d6 damage per point spent) or add them to a failed saving throw as a reaction.",
  "Como acción adicional usas: Finta (ventaja en ataque), Guardia (+CA igual a mitad de competencia), Arremetida (+5 pies alcance desarmado) o Apresurarse (Correr/Dash). Ganas 1 Punto de Flujo al usar un truco.": "As a bonus action, you can use a Pugilist Trick: Feint (gain advantage on your next attack roll), Guard (gain a bonus to AC equal to half your proficiency bonus), Lunge (increase your unarmed reach by 5 feet), or Rush (take the Dash action). You gain 1 Flow Point when you use a trick.",
  "Reacción al recibir un golpe cuerpo a cuerpo: reduces el daño en 1d10 + Con + nivel de Pugilista. Si reduces el daño a 0, devuelves un ataque cuerpo a cuerpo inmediatamente.": "Reaction when hit by a melee attack: reduce the damage taken by 1d10 + your Constitution modifier + your Pugilist level. If you reduce the damage to 0, you can immediately make one unarmed strike against the attacker as part of the same reaction.",
  "Puedes atacar dos veces al usar la acción de Atacar en tu turno.": "You can attack twice, instead of once, whenever you take the Attack action on your turn.",
  "Reacción al recibir un golpe crítico: lo conviertes en un golpe normal y ganas 1 Punto de Flujo.": "Reaction when you suffer a critical hit: turn the critical hit into a normal hit and gain 1 Flow Point.",
  "Tus ataques desarmados cuentan como mágicos. Ganas 1 Punto de Flujo cada vez que superes con éxito una tirada de salvación.": "Your unarmed strikes count as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage. You also gain 1 Flow Point whenever you succeed on a saving throw.",
  "Ganas un bonificador de +1 a la CA mientras no vistas armadura pesada.": "You gain a +1 bonus to AC while you are not wearing heavy armor.",
  "Gastas 1 Punto de Flujo para averiguar la CA exacta de un rival, su bonificador de salvación o si está por debajo de la mitad de su vida.": "You can spend 1 Flow Point to learn an opponent's exact Armor Class, one of its saving throw bonuses, or whether it has fewer than half of its hit points remaining.",
  "Al tirar iniciativa al inicio del combate, comienzas de inmediato con 2 Puntos de Flujo generados.": "When you roll initiative at the start of combat, you immediately gain 2 Flow Points.",
  "Competencia en tiradas de salvación de Constitución, ventaja contra veneno y resistencia al daño de veneno.": "You gain proficiency in Constitution saving throws, advantage on saving throws against poison, and resistance to poison damage.",
  "Añades tu bonificador de competencia a las tiradas de salvación contra muerte. Si sacas 20 o más recuperas PG iguales al doble de tu nivel + Constitución.": "You add your proficiency bonus to death saving throws. If the total of your death saving throw is 20 or higher, you immediately regain hit points equal to twice your Pugilist level + your Constitution modifier.",
  "Obtienes resistencia pasiva permanente al daño contundente, perforante y cortante.": "You gain permanent passive resistance to bludgeoning, piercing, and slashing damage.",
  "Tus puntuaciones de Fuerza, Destreza y Constitución aumentan en 2, hasta un máximo de 22.": "Your Strength, Dexterity, and Constitution scores each increase by 2, to a maximum of 22.",
  "Ventaja en tiradas de Iniciativa. Levantarse de derribado como reacción gastando solo 5 pies de movimiento.": "You have advantage on initiative rolls, and when you are knocked prone, you can use your reaction to stand up by spending only 5 feet of movement.",
  "Cuando una criatura termina su turno a 5 pies de ti, puedes moverte hasta la mitad de tu velocidad como reacción sin provocar ataques de oportunidad.": "When a creature ends its turn within 5 feet of you, you can use your reaction to move up to half your speed without provoking opportunity attacks.",
  "Eliminas 1 nivel de agotamiento y ganas PG temporales iguales a tu nivel + Con tras un descanso corto.": "Whenever you finish a short rest, you reduce your exhaustion level by 1 and gain temporary hit points equal to your Pugilist level + your Constitution modifier.",
  "Tras ser alcanzado por un ataque, ganas +4 a la CA contra ataques subsiguientes de ese enemigo en el mismo turno.": "When a creature hits you with an attack, you gain a +4 bonus to AC against all subsequent attacks made by that creature for the rest of the turn.",
  "Puedes gastar 1 Punto de Flujo para ganar una reacción adicional en tu asalto.": "You can spend 1 Flow Point to take one additional reaction during the current round.",
  "Ventaja en tiradas de salvación para evitar ser empujado, arrastrado o derribado.": "You have advantage on ability checks and saving throws made to avoid being pushed, dragged, or knocked prone.",
  "Al golpear con Golpe de Poder, gastas 1 Punto de Flujo adicional para forzar salvación de Constitución o dejar al enemigo con desventaja en ataques y salvaciones de Destreza.": "When you hit a creature with a Power Strike, you can spend 1 additional Flow Point to force the target to succeed on a Constitution saving throw or have disadvantage on attack rolls and Dexterity saving throws until the end of your next turn.",
  "Cuentas como un tamaño Grande para capacidad de carga, agarre, empujar y arrollar.": "You count as one size larger (Large) when determining your carrying capacity and the size of creatures you can grapple, shove, or overrun.",
  "Al usar Golpe de Poder, tiras tu Dado de Pugilismo en lugar de d6s y puedes repetir las tiradas de 1 y 2 en los dados de daño.": "When you use Power Strike, you roll your Pugilism die instead of d6s for the extra damage, and you can reroll any 1 or 2 on the damage dice.",
  "Sumas tu bonificador de competencia a la Iniciativa. Tienes ventaja en el primer ataque del combate contra una criatura que aún no haya actuado (si impacta, es crítico automático).": "You add your proficiency bonus to your initiative rolls. On the first round of combat, you have advantage on your first attack roll against any creature that hasn't taken a turn yet, and if that attack hits, it is an automatic critical hit.",
  "Cuando estás por debajo de la mitad de tus PG máximos, gastas 1 Punto de Flujo para tener ventaja en todos tus ataques cuerpo a cuerpo hasta el final del turno (1/descanso corto).": "When you have fewer than half of your hit points remaining, you can spend 1 Flow Point to gain advantage on all melee attack rolls until the end of the current turn (1/short rest).",
  "Te otorgas puntos de golpe temporales iguales al triple de tu nivel de Pugilista (1/descanso largo).": "You can grant yourself temporary hit points equal to three times your Pugilist level (1/long rest).",
  "En el primer asalto de cualquier combate (si no estás sorprendido), tomas dos turnos completos: el primero en tu iniciativa normal y el segundo a iniciativa - 10.": "During the first round of any combat in which you aren't surprised, you can take two full turns: your first turn at your normal initiative and your second turn at your initiative minus 10.",
  "Imbuyes una chispa de magia en pequeños objetos mundanos para hacerlos emitir luz tenue de 5 pies, reproducir un mensaje grabado, emitir olor o mostrar imágenes estáticas.": "You learn how to invest a spark of magic into mundane objects, touching a Tiny nonmagical object as an action to make it shed bright light in a 5-foot radius, play a recorded 6-second message, emit an odor or nonverbal sound, or display a static visual effect.",
  "Lanzas conjuros de artífice mediante herramientas artesanales como foco. Puedes preparar una cantidad de conjuros igual a tu mod de Int + la mitad de tu nivel de artífice.": "You cast artificer spells using thieves' tools or artisan's tools as a spellcasting focus. You can prepare a number of artificer spells equal to your Intelligence modifier + half your artificer level (rounded down).",
  "Aprendes a imbuir objetos mundanos con magia permanente: armas mágicas +1, armaduras defensivas +1, mente enfocada, o réplicas de objetos maravillosos como Bolsa de Contención o Botas Aladas.": "You gain the ability to imbue mundane items with certain magical infusions, turning nonmagical objects into magic items such as a +1 Enhanced Weapon, +1 Enhanced Defense armor, Mind Sharpener, or Replicate Magic Item (such as a Bag of Holding or Winged Boots).",
  "Eliges tu especialización: Alquimista, Armero, Artillero o Herrero de Batalla, desbloqueando rasgos únicos a niveles 3, 5, 9 y 15.": "You choose the type of specialist you are: Alchemist, Armorer, Artillerist, or Battle Smith, each of which grants you special features at 3rd, 5th, 9th, and 15th level.",
  "Puedes manifestar mágicamente cualquier juego de herramientas de artesano que necesites tras 1 hora de trabajo concentrado.": "You've learned how to produce exactly the tool you need: with thieves' tools or artisan's tools in hand, you can magically create one set of artisan's tools in an unoccupied space within 5 feet of you after 1 hour of uninterrupted work.",
  "Aumentas una característica en 2, dos en 1, o seleccionas una Dote oficial de D&D 5e.": "You can increase one ability score of your choice by 2, increase two ability scores of your choice by 1, or take an official D&D 5e Feat.",
  "Obtienes un nuevo rasgo otorgado por tu especialización elegida (Ataque Adicional o bonificador a conjuros).": "You gain a new feature granted by your Artificer Specialist choice (such as Extra Attack or a bonus to spell damage and healing).",
  "Tu bonificador de competencia se duplica para cualquier prueba de característica que emplee tu competencia con cualquier herramienta.": "Your proficiency bonus is doubled for any ability check you make that uses your proficiency with a tool.",
  "Como reacción cuando tú o una criatura que puedas ver a 30 pies haga una prueba de característica o salvación, puedes sumar tu modificador de Inteligencia a la tirada (Int mod veces/descanso largo).": "When you or another creature you can see within 30 feet of you makes an ability check or a saving throw, you can use your reaction to add your Intelligence modifier to the roll (Intelligence modifier uses per long rest).",
  "Obtienes una mejora de combate o potencia curativa de tu especialización.": "You gain an advanced combat or restorative feature from your Artificer Specialist.",
  "Puedes sintonizarte con hasta 4 objetos mágicos simultáneamente y fabricar objetos mágicos comunes y poco comunes en una cuarta parte del tiempo normal.": "You can attune to up to four magic items at once, and if you craft a magic item with a rarity of common or uncommon, it takes you a quarter of the normal time, and it costs you half as much of the usual gold.",
  "Puedes imbuir un conjuro de nivel 1 o 2 en un arma o foco: cualquier criatura que lo sostenga puede usar una acción para lanzar ese conjuro hasta un número de veces igual al doble de tu modificador de Inteligencia.": "Whenever you finish a long rest, you can touch one simple or martial weapon or one item that you can use as a spellcasting focus, storing a 1st- or 2nd-level artificer spell that requires 1 action in it; any creature holding the object can use an action to produce the spell's effect up to twice your Intelligence modifier times.",
  "Puedes sintonizarte con hasta 5 objetos mágicos a la vez e ignoras todos los requisitos de clase, raza, conjuro y nivel para sintonizarte con ellos.": "You can attune to up to five magic items at once, and you ignore all class, race, spell, and level requirements on attuning to or using a magic item.",
  "Desbloqueas el rasgo final legendario de tu especialización de artífice.": "You unlock the final capstone feature of your Artificer Specialist.",
  "Puedes sintonizarte con hasta 6 objetos mágicos simultáneamente.": "You can now attune to up to six magic items at once.",
  "Ganas un bonificador de +1 a todas tus tiradas de salvación por cada objeto mágico con el que estés sintonizado (hasta +6). Además, si caes a 0 PG puedes usar tu reacción para destruir una infusión y quedar a 1 PG en su lugar.": "You gain a +1 bonus to all saving throws per magic item you are currently attuned to (up to +6). In addition, if you're reduced to 0 hit points but not killed outright, you can use your reaction to end one of your artificer infusions, causing you to drop to 1 hit point instead of 0.",
  "Ganas competencia con suministros de alquimista y puedes fabricar pociones el doble de rápido.": "You gain proficiency with alchemist's supplies, or another type of artisan's tools if you already have this proficiency.",
  "Tienes una lista de conjuros siempre preparados que no cuentan contra tu límite de preparación diaria: Nivel 3: Palabra de curación, Rayo de enfermedad. Nivel 5: Flecha ácida de Melf, Esfera flamígera. Nivel 9: Forma gaseosa, Palabra de curación en masa. Nivel 13: Marchitar, Ojo arcano. Nivel 17: Nube aniquiladora, Revivir a los muertos.": "You always have certain spells prepared after you reach particular levels in this class, and they don't count against the number of artificer spells you prepare: 3rd Level: Healing Word, Ray of Sickness. 5th Level: Flaming Sphere, Melf's Acid Arrow. 9th Level: Gaseous Form, Mass Healing Word. 13th Level: Blight, Death Ward. 17th Level: Cloudkill, Raise Dead.",
  "Al terminar un descanso largo creas elixires mágicos al azar en frascos vacíos (1 a nivel 3, 2 a nivel 6, 3 a nivel 15). Tira 1d6: 1. Curación (2d4 + Int PG), 2. Velocidad (+10 pies de velocidad durante 1 hora), 3. Resiliencia (+1 CA durante 10 min), 4. Valentía (10 PG temporales), 5. Vuelo (10 pies de velocidad de vuelo durante 10 min), o 6. Transformación (efecto del conjuro Alterar el propio ser durante 10 min). Puedes gastar una ranura de conjuro de nivel 1+ para crear elixires adicionales eligiendo el efecto.": "Whenever you finish a long rest, you can magically produce experimental elixirs in empty flasks you touch (1 at 3rd level, 2 at 6th level, 3 at 15th level). Roll 1d6 for each elixir's effect: 1. Healing (regain 2d4 + your Intelligence modifier HP), 2. Swiftness (walking speed increases by 10 feet for 1 hour), 3. Resilience (+1 bonus to AC for 10 minutes), 4. Boldness (add 1d4 to attack rolls and saving throws for 1 minute), 5. Flight (gain a 10-foot flying speed for 10 minutes), or 6. Transformation (gain the effect of the Alter Self spell for 10 minutes). You can expend a spell slot of 1st level or higher to create an additional elixir and choose its effect.",
  "Al lanzar un conjuro a través de tus suministros de alquimista que inflija daño de ácido, fuego, necrótico o veneno, o cure puntos de golpe, sumas tu modificador de Inteligencia al resultado.": "Whenever you cast a spell using your alchemist's supplies as the spellcasting focus, you gain a bonus to one roll of the spell that restores hit points or deals acid, fire, necrotic, or poison damage equal to your Intelligence modifier (minimum of +1).",
  "Las criaturas que beben tus elixires ganan 2d6 + Int en puntos de golpe temporales. Además, puedes lanzar Restauración Menor gratis sin gastar ranuras (Int mod veces/descanso largo).": "Whenever a creature drinks an experimental elixir you created, the creature gains temporary hit points equal to 2d6 + your Intelligence modifier. In addition, you can cast Lesser Restoration without expending a spell slot and without preparing the spell (Intelligence modifier uses per long rest).",
  "Ganas resistencia al daño de ácido y veneno e inmunidad a la condición Envenenado. Puedes lanzar Sanar y Restauración Mayor gratis una vez por descanso largo sin gastar ranuras ni componentes materiales.": "You gain resistance to acid damage and poison damage, and you are now immune to the poisoned condition. In addition, you can use your alchemist's supplies to cast Greater Restoration and Heal without expending a spell slot, without preparing the spell, and without material components, once each per long rest.",
  "Tienes una lista de conjuros siempre preparados que no cuentan contra tu límite de preparación diaria: Nivel 3: Proyectil mágico, Onda atronadora. Nivel 5: Imagen múltiple, Hacer añicos. Nivel 9: Patrón hipnótico, Relámpago. Nivel 13: Escudo de fuego, Invisibilidad mayor. Nivel 17: Atravesar paredes, Muro de fuerza.": "You always have certain spells prepared after you reach particular levels in this class, and they don't count against the number of artificer spells you prepare: 3rd Level: Magic Missile, Thunderwave. 5th Level: Mirror Image, Shatter. 9th Level: Hypnotic Pattern, Lightning Bolt. 13th Level: Fire Shield, Greater Invisibility. 17th Level: Passwall, Wall of Force.",
  "Como acción transformas una armadura que lleves en tu Armadura Arcana: cubre todo tu cuerpo, no impone penalización por Fuerza, no da desventaja en sigilo y no te la pueden quitar contra tu voluntad. Puedes usarla como foco de lanzamiento de tus conjuros de artífice.": "As an action, you can turn a suit of armor you are wearing into Arcane Armor: if the armor normally has a Strength requirement, the arcane armor lacks this requirement for you, you can use the arcane armor as a spellcasting focus for your artificer spells, it attaches to you and can't be removed against your will, and it expands to cover your entire body and replaces any missing limbs.",
  "Eliges el modo de tu armadura tras cada descanso corto o largo: Guardián (Guanteletes de Trueno de 1d8 que fuerzan al enemigo a tener desventaja en ataques contra otros objetivos hasta tu próximo turno, y Campo Defensivo con acción adicional para ganar PG temporales iguales a tu nivel de artífice PB veces/descanso largo) o Infiltrador (Lanza-Relámpagos a distancia de 90/300 pies que inflige 1d6 daño eléctrico más 1d6 extra 1 vez por turno, +5 pies de velocidad de movimiento y ventaja en pruebas de Destreza [Sigilo]).": "You can customize your Arcane Armor into one of two models whenever you finish a short or long rest: Guardian (Thunder Gauntlets that deal 1d8 thunder damage and impose disadvantage on the target's attack rolls against creatures other than you until your next turn, plus Defensive Field as a bonus action to gain temporary hit points equal to your artificer level, proficiency bonus uses per long rest) or Infiltrator (Lightning Launcher ranged weapon with a 90/300-foot range that deals 1d6 lightning damage plus an extra 1d6 once per turn, +5 feet to walking speed, and advantage on Dexterity [Stealth] checks).",
  "Puedes atacar dos veces en lugar de una al tomar la acción de Atacar en tu turno.": "You can attack twice, rather than once, whenever you take the Attack action on your turn.",
  "Tu armadura cuenta como 4 piezas separadas (peto, botas, casco y arma especial del modelo), permitiéndote infundir dos objetos adicionales siempre que pertenezcan a tu armadura.": "Your Arcane Armor now counts as separate items for the purposes of your Infuse Items feature: armor (the chest piece), boots, helmet, and the armor's special weapon. In addition, the maximum number of items you can infuse at once increases by 2, but those extra items must be part of your Arcane Armor.",
  "Modelo Guardián: como reacción cuando una criatura Grande o menor termina su turno a 30 pies o menos, la obligas a hacer una tirada de salvación de Fuerza; si falla, es arrastrada mágicamente hasta 5 pies de ti y la golpeas con un ataque cuerpo a cuerpo (PB veces/descanso largo). Modelo Infiltrador: cualquier objetivo dañado por tu Lanza-Relámpagos emite luz mágica: el siguiente ataque contra él tiene ventaja y sufre 1d6 de daño relámpago extra.": "Guardian Model: When a Huge or smaller creature you can see ends its turn within 30 feet of you, you can use your reaction to magically force it to make a Strength saving throw; on a failed save, you pull the creature up to 25 feet toward you to an unoccupied space within 5 feet of you and can make a melee weapon attack against it as part of this reaction (proficiency bonus uses per long rest). Infiltrator Model: Any creature that takes lightning damage from your Lightning Launcher glimmers with magical light until the start of your next turn, shedding dim light, suffering disadvantage on attack rolls against you, and granting advantage on the next attack roll against it (which deals an extra 1d6 lightning damage on a hit).",
  "Ganas competencia con herramientas de tallador de madera y armas de fuego si la campaña las incluye.": "You gain proficiency with woodcarver's tools, or another type of artisan's tools if you already have this proficiency.",
  "Tienes una lista de conjuros siempre preparados que no cuentan contra tu límite de preparación diaria: Nivel 3: Escudo, Onda atronadora. Nivel 5: Rayo abrasador, Hacer añicos. Nivel 9: Bola de fuego, Muro de viento. Nivel 13: Tormenta de hielo, Muro de fuego. Nivel 17: Cono de frío, Muro de fuerza.": "You always have certain spells prepared after you reach particular levels in this class, and they don't count against the number of artificer spells you prepare: 3rd Level: Shield, Thunderwave. 5th Level: Scorching Ray, Shatter. 9th Level: Fireball, Wind Wall. 13th Level: Ice Storm, Wall of Fire. 17th Level: Cone of Cold, Wall of Force.",
  "Como acción creas un cañón mágico Diminuto (en tu mano) o Pequeño (con patas mecánicas) con CA 18 y PG iguales a 5 veces tu nivel de artífice: Balista de Fuerza (120 pies, 2d8 daño de fuerza y empuja 5 pies), Lanzallamas (cono de 15 pies, 2d8 daño de fuego, salvación Destreza mitad), o Protector (1d8 + mod Int en puntos de golpe temporales a todos los aliados a 10 pies cada turno). Puedes moverlo 15 pies y dispararlo con tu acción adicional. Creas 1 gratis/descanso largo o gastando una ranura de conjuro de nivel 1+.": "As an action, you can magically create a Small or Tiny Eldritch Cannon with AC 18 and hit points equal to five times your artificer level: Flamethrower (exhales fire in a 15-foot cone for 2d8 fire damage, Dexterity save for half), Force Ballista (ranged spell attack up to 120 feet for 2d8 force damage and pushes the target 5 feet away), or Protector (grants 1d8 + your Intelligence modifier temporary hit points to itself and each creature of your choice within 10 feet of it). On each of your turns, you can take a bonus action to activate the cannon and direct it to walk or climb up to 15 feet. You can create one cannon for free per long rest, or by expending a spell slot of 1st level or higher.",
  "Tallas runas en una varita, bastón o cetro para convertirlo en tu arma de fuego arcana. Al lanzar un conjuro de artífice a través de él sumas 1d8 adicional a una de las tiradas de daño.": "At the end of a long rest, you can use woodcarver's tools to carve special sigils into a wand, staff, or rod and turn it into your arcane firearm. You can use your arcane firearm as a spellcasting focus for your artificer spells, and when you cast an artificer spell through the firearm, roll a d8 and add the number rolled to one of the spell's damage rolls.",
  "El daño de todos tus cañones eldritch aumenta en 1d8 (hasta 3d8). Además, puedes autodetonar tu cañón como acción a 60 pies para infligir 3d8 de daño de fuerza en un radio de 20 pies (salvación Destreza mitad).": "Every Eldritch Cannon you create is now more destructive: the cannon's damage rolls all increase by 1d8 (to 3d8). In addition, as an action, you can command the cannon to detonate if you are within 60 feet of it, destroying the cannon and forcing each creature within 20 feet of it to make a Dexterity saving throw, taking 3d8 force damage on a failed save or half as much on a successful one.",
  "Tu cañón concede cobertura media (+2 CA y salvaciones de Destreza) a todos los aliados a 10 pies. Además, puedes manifestar dos cañones eldritch simultáneamente y disparar ambos con una sola acción adicional.": "You and your allies have half cover (+2 bonus to AC and Dexterity saving throws) while within 10 feet of a cannon you create with Eldritch Cannon. In addition, you can now have two cannons at the same time, and you can activate both of them with the same bonus action.",
  "Tienes una lista de conjuros siempre preparados que no cuentan contra tu límite de preparación diaria: Nivel 3: Heroísmo, Escudo. Nivel 5: Castigo marcado, Vínculo de protección. Nivel 9: Aura de vitalidad, Conjurar descarga. Nivel 13: Aura de pureza, Castigo fulgurante. Nivel 17: Castigo desterrador, Curar heridas en masa.": "You always have certain spells prepared after you reach particular levels in this class, and they don't count against the number of artificer spells you prepare: 3rd Level: Heroism, Shield. 5th Level: Branding Smite, Warding Bond. 9th Level: Aura of Vitality, Conjure Barrage. 13th Level: Aura of Purity, Fire Shield. 17th Level: Banishing Smite, Mass Cure Wounds.",
  "Cuando atacas con un arma mágica, puedes usar tu modificador de Inteligencia en lugar de Fuerza o Destreza para las tiradas de ataque y daño.": "You gain proficiency with martial weapons, and when you attack with a magic weapon, you can use your Intelligence modifier, instead of Strength or Dexterity modifier, for the attack and damage rolls.",
  "Creas un leal compañero mecánico cuadrúpedo o bípedo que lucha a tu lado: CA 15 (17 a Nv 15), PG = 2 + Int mod + (5 × tu nivel de artífice), dados de golpe d8 iguales a tu nivel. Comparte tu iniciativa y actúa inmediatamente después de ti. Con tu acción adicional puedes ordenarle usar Golpe Contundente (1d8 + PB daño de fuerza) o Reparar (restaura 2d8 + PB PG, 3/descanso largo). Como reacción usa Desviar Ataque para imponer desventaja a ataques contra criaturas adyacentes a él (infligiendo 1d4 + Int daño de fuerza al atacante a Nv 15).": "Your tinkering has borne you a faithful mechanical companion, a Steel Defender: AC 15 (17 at 15th level), HP = 2 + your Intelligence modifier + five times your artificer level, and d8 Hit Dice equal to your artificer level. It shares your initiative and takes its turn immediately after yours. Using your bonus action, you can command it to use Force-Empowered Rend (1d8 + proficiency bonus force damage) or Repair (restores 2d8 + proficiency bonus HP, 3/day). As a reaction, it can use Deflect Attack to impose disadvantage on the attack roll of one creature it can see within 5 feet of it (also dealing 1d4 + your Intelligence modifier force damage to the attacker at 15th level).",
  "Cuando tú o tu Defensor de Acero impactéis con un ataque, puedes canalizar energía mágica para infligir 2d6 de daño de fuerza adicional o curar 2d6 puntos de golpe a una criatura a 30 pies (Int mod veces/descanso largo).": "When either you hit a target with a magic weapon attack or your Steel Defender hits a target, you can channel magical energy through the strike to deal an extra 2d6 force damage to the target or restore 2d6 hit points to one creature or object of your choice within 30 feet of the target (Intelligence modifier uses per long rest).",
  "El daño y curación de tu Sacudida Arcana aumenta a 4d6. Además, tu Defensor de Acero gana +2 a su Clase de Armadura (CA 17) y cuando usa Desviar Ataque inflige 1d4 + Int de daño de fuerza al atacante.": "The extra damage and the healing of your Arcane Jolt both increase to 4d6. In addition, your Steel Defender gains a +2 bonus to Armor Class (AC 17), and whenever your Steel Defender uses its Deflect Attack, the attacker takes force damage equal to 1d4 + your Intelligence modifier.",
  "Los humanos poseen una prodigiosa adaptabilidad e ingenio en cualquier disciplina o profesión.": "Humans possess prodigious adaptability and ingenuity in any discipline or profession.",
  "Puedes hablar, leer y escribir Común y un idioma adicional a tu elección.": "You can speak, read, and write Common and one extra language of your choice.",
  "Dos puntuaciones de característica diferentes a tu elección aumentan en +1.": "Two different ability scores of your choice increase by +1.",
  "Ganas una Dote oficial de D&D 5e a tu elección desde el inicio de la campaña.": "You gain one official D&D 5e Feat of your choice from the start of the campaign.",
  "Ganas competencia en una habilidad a tu elección.": "You gain proficiency in one skill of your choice.",
  "Puedes ver en la penumbra a 60 pies como si hubiera luz brillante, y en la oscuridad como en penumbra.": "You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light.",
  "Añades un dado 1d4 a tus pruebas de Sabiduría (Percepción) y Sabiduría (Supervivencia).": "You add a 1d4 die to your Wisdom (Perception) and Wisdom (Survival) checks.",
  "Puedes lanzar Fuego Feérico una vez por descanso largo. A nivel 3 lanzas Localizar Animales o Plantas como ritual (Sabiduría).": "You can cast Faerie Fire once per long rest. At 3rd level, you can cast Locate Animals or Plants as a ritual (Wisdom).",
  "Añades 1d4 a tus pruebas de Sabiduría (Trato con Animales) e Inteligencia (Naturaleza).": "You add 1d4 to your Wisdom (Animal Handling) and Intelligence (Nature) checks.",
  "Puedes lanzar Amistad con Animales y Hablar con Animales una vez por descanso largo cada uno.": "You can cast Animal Friendship and Speak with Animals once per long rest each.",
  "Puedes elegir como objetivo de Amistad con Animales y Hablar con Animales a una Monstruosidad si su INT es 3 o menor.": "You can target a Monstrosity with Animal Friendship and Speak with Animals if its INT is 3 or lower.",
  "Añades 1d4 a tus pruebas de Inteligencia (Conocimiento Arcano) y pruebas con herramientas de artesano.": "You add 1d4 to your Intelligence (Arcana) checks and ability checks with artisan's tools.",
  "Ganas competencia con un tipo de herramientas de artesano a tu elección.": "You gain proficiency with one type of artisan's tools of your choice.",
  "Como acción, tocas un objeto no mágico: un arma gana +1 al ataque y daño, o una armadura gana +1 a la CA durante 1 hora (1/descanso largo).": "As an action, you touch a nonmagical object: a weapon gains +1 to attack and damage rolls, or a suit of armor gains +1 to AC for 1 hour (1/long rest).",
  "Tu velocidad base al caminar aumenta a 35 pies.": "Your base walking speed increases to 35 feet.",
  "Añades 1d4 a tus pruebas de Destreza (Acrobacias) y pruebas para operar o montar vehículos terrestres.": "You add 1d4 to your Dexterity (Acrobatics) checks and ability checks to operate or ride land vehicles.",
  "Puedes lanzar el conjuro Paso Brumoso (Misty Step) una vez por descanso largo (Destreza).": "You can cast the Misty Step spell once per long rest (Dexterity).",
  "Añades 1d4 a tus pruebas de Sabiduría (Perspicacia) y Sabiduría (Percepción).": "You add 1d4 to your Wisdom (Insight) and Wisdom (Perception) checks.",
  "Puedes lanzar el conjuro Escudo (Shield) una vez por descanso largo.": "You can cast the Shield spell once per long rest.",
  "Cuando una criatura a 5 pies de ti recibe un ataque, puedes usar tu reacción para intercambiar lugares con ella y recibir el impacto en su lugar.": "When a creature within 5 feet of you is hit by an attack, you can use your reaction to swap places with it and take the hit instead.",
  "Tu velocidad base al caminar es de 35 pies.": "Your base walking speed is 35 feet.",
  "Ganas competencia en la habilidad Supervivencia.": "You gain proficiency in the Survival skill.",
  "Ganas competencia en la habilidad Atletismo o Persuasión.": "You gain proficiency in the Athletics or Persuasion skill.",
  "Tus puntos de golpe máximos aumentan en +1, y aumentan en +1 cada vez que subes de nivel.": "Your hit point maximum increases by +1, and it increases by +1 every time you gain a level.",
  "Ganas competencia en la habilidad Intimidación o Atletismo.": "You gain proficiency in the Intimidation or Athletics skill.",
  "Tienes competencia en la habilidad Percepción.": "You have proficiency in the Perception skill.",
  "Tienes ventaja en tiradas de salvación contra ser hechizado y la magia no puede dormirte.": "You have advantage on saving throws against being charmed, and magic cannot put you to sleep.",
  "No necesitas dormir; meditas profundamente durante 4 horas al día para obtener los beneficios de un descanso largo.": "You do not need to sleep; instead, you meditate deeply for 4 hours a day to gain the benefits of a long rest.",
  "Competencia con espada larga, espada corta, arco corto y arco largo.": "Proficiency with the longsword, shortsword, shortbow, and longbow.",
  "Conoces un truco de tu elección de la lista de conjuros de Mago. La Inteligencia es tu aptitud mágica para este truco.": "You know one cantrip of your choice from the Wizard spell list. Intelligence is your spellcasting ability for it.",
  "Puedes intentar esconderte incluso cuando solo estás ligeramente oscurecido por follaje, lluvia o nieve.": "You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, or falling snow.",
  "Tu visión en la oscuridad tiene un radio de 120 pies.": "Your darkvision has a radius of 120 feet.",
  "Tienes desventaja en ataques y percepción cuando estás bajo luz solar directa.": "You have disadvantage on attack rolls and Perception checks when you or your target are in direct sunlight.",
  "Conoces el truco Luces Danzantes (Dancing Lights). A partir del nivel 3 lanzas Fuego Feérico (Faerie Fire). A partir del nivel 5 lanzas Oscuridad (Darkness). Carisma es tu aptitud mágica.": "You know the Dancing Lights cantrip. Starting at 3rd level, you can cast Faerie Fire. Starting at 5th level, you can cast Darkness. Charisma is your spellcasting ability.",
  "Como acción adicional te teletransportas mágicamente hasta 30 pies a un espacio desocupado (usos = bono de competencia por descanso largo).": "As a bonus action, you can magically teleport up to 30 feet to an unoccupied space (uses equal to your proficiency bonus per long rest).",
  "Tienes una velocidad de nado de 30 pies y puedes respirar tanto aire como agua.": "You have a swimming speed of 30 feet, and you can breathe both air and water.",
  "Puedes comunicar ideas sencillas a cualquier bestia con velocidad de nado.": "You can communicate simple ideas with any beast that has a swimming speed.",
  "Como acción adicional te teletransportas hasta 30 pies a un espacio desocupado. A partir de nivel 3 ganas resistencia a todo daño hasta el inicio de tu siguiente turno.": "As a bonus action, you teleport up to 30 feet to an unoccupied space. Starting at 3rd level, you gain resistance to all damage until the start of your next turn.",
  "Tienes ventaja en todas las pruebas de Perspicacia y de Investigación.": "You have advantage on all Insight and Investigation checks.",
  "Como acción adicional te teletransportas hasta 30 pies a un espacio desocupado que veas (usos = bono de competencia).": "As a bonus action, you can teleport up to 30 feet to an unoccupied space you can see (uses equal to your proficiency bonus).",
  "Conoces un truco entre Luz Sagrada, Saeta de Fuego o Luces Danzantes a tu elección.": "You know one cantrip of your choice from Sacred Flame, Fire Bolt, or Dancing Lights.",
  "Añades 1d4 a tus pruebas de Destreza (Sigilo) y Carisma (Interpretación).": "You add 1d4 to your Dexterity (Stealth) and Charisma (Performance) checks.",
  "Conoces el truco Ilusión Menor. A nivel 3 puedes lanzar Invisibilidad una vez por descanso largo (Carisma).": "You know the Minor Illusion cantrip. At 3rd level, you can cast Invisibility once per long rest (Charisma).",
  "Posees una velocidad de vuelo de 30 pies. No puedes volar si vistes armadura media o pesada.": "You have a flying speed of 30 feet. You cannot use this flying speed if you are wearing medium or heavy armor.",
  "Conoces un truco de la lista de conjuros de Druida a tu elección (Sabiduría).": "You know one cantrip of your choice from the Druid spell list (Wisdom).",
  "Competencia con lanza, jabalina, arco corto y red.": "Proficiency with the spear, javelin, shortbow, and net.",
  "Ventaja en salvaciones contra veneno y resistencia al daño por veneno.": "Advantage on saving throws against poison, and resistance to poison damage.",
  "Competencia con hacha de guerra, hacha de mano, martillo ligero y martillo de guerra.": "Proficiency with the battleaxe, handaxe, light hammer, and warhammer.",
  "Añades el doble de tu bonificador de competencia a pruebas de Historia relacionadas con albañilería o piedra.": "You add double your proficiency bonus to History checks related to the origin of stonework.",
  "Tu máximo de puntos de golpe aumenta en 1, y aumenta en 1 cada vez que subes de nivel.": "Your hit point maximum increases by 1, and it increases by 1 every time you gain a level.",
  "Tu visión en la oscuridad tiene un alcance de 120 pies.": "Your darkvision has a range of 120 feet.",
  "Tienes ventaja en tiradas de salvación contra ilusiones, parálisis y ser hechizado.": "You have advantage on saving throws against illusions and against being charmed or paralyzed.",
  "Desventaja en ataques y percepción en luz solar directa.": "Disadvantage on attack rolls and Perception checks in direct sunlight.",
  "Añades 1d4 a tus pruebas de Inteligencia (Investigación) y pruebas con herramientas de ladrón.": "You add 1d4 to your Intelligence (Investigation) checks and ability checks with thieves' tools.",
  "Puedes lanzar Alarma como ritual. A nivel 3 puedes lanzar Armadura de Agathys una vez por descanso largo (Inteligencia).": "You can cast Alarm as a ritual. At 3rd level, you can cast Armor of Agathys once per long rest (Intelligence).",
  "Ventaja en pruebas de característica para diseñar o reparar mecanismos.": "Advantage on ability checks made to design or repair mechanisms.",
  "Cuando saques un 1 natural en un d20 para tirada de ataque, prueba o salvación, puedes volver a tirar el dado y usar el nuevo resultado.": "When you roll a natural 1 on the d20 for an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll.",
  "Puedes moverte a través del espacio de cualquier criatura que sea de un tamaño mayor que el tuyo.": "You can move through the space of any creature that is of a size larger than yours.",
  "Puedes intentar esconderte incluso cuando solo estás tapado por una criatura al menos un tamaño mayor que tú.": "You can attempt to hide even when you are obscured only by a creature that is at least one size larger than you.",
  "Ventaja en salvaciones contra veneno y resistencia al daño de veneno.": "Advantage on saving throws against poison, and resistance to poison damage.",
  "Puedes hablar telepáticamente con cualquier criatura a 30 pies de ti que comparta al menos un idioma contigo.": "You can speak telepathically to any creature within 30 feet of you that shares at least one language with you.",
  "No dejas rastros al viajar por terreno natural boscoso y el terreno difícil natural no te ralentiza.": "You leave no tracks when traveling through natural wooded terrain, and nonmagical difficult terrain does not slow your travel.",
  "Añades 1d4 a tus pruebas de Sabiduría (Medicina) y Destreza (Juego de Manos).": "You add 1d4 to your Wisdom (Medicine) and Dexterity (Sleight of Hand) checks.",
  "Puedes lanzar Curar Heridas una vez por descanso largo. A nivel 3 lanzas Restablecimiento Menor (Sabiduría).": "You can cast Cure Wounds once per long rest. At 3rd level, you can cast Lesser Restoration (Wisdom).",
  "Añades 1d4 a tus pruebas de Carisma (Persuasión) y pruebas con útiles de cocinero o cervecería.": "You add 1d4 to your Charisma (Persuasion) checks and ability checks with cook's utensils or brewer's supplies.",
  "Conoces el truco Prestidigitación. Puedes lanzar Purificar Comida y Bebida o Buenas Bayas una vez por descanso largo (Carisma).": "You know the Prestidigitation cantrip. You can cast Purify Food and Drink or Goodberry once per long rest (Charisma).",
  "Conoces Taumaturgia. A nivel 3 lanzas Reprensión Infernal y a nivel 5 Oscuridad.": "You know Thaumaturgy. At 3rd level, you can cast Hellish Rebuke, and at 5th level, Darkness.",
  "Conoces Taumaturgia. A nivel 3 lanzas Rayo de Enfermedad y a nivel 5 Corona de Locura.": "You know Thaumaturgy. At 3rd level, you can cast Ray of Sickness, and at 5th level, Crown of Madness.",
  "Conoces Taumaturgia. A nivel 3 lanzas Disfrazarse y a nivel 5 Detectar Pensamientos.": "You know Thaumaturgy. At 3rd level, you can cast Disguise Self, and at 5th level, Detect Thoughts.",
  "Conoces Amigos. A nivel 3 lanzas Hechizar Persona y a nivel 5 Sugestión.": "You know Friends. At 3rd level, you can cast Charm Person, and at 5th level, Suggestion.",
  "Conoces Ilusión Menor. A nivel 3 lanzas Disfrazarse y a nivel 5 Invisibilidad.": "You know Minor Illusion. At 3rd level, you can cast Disguise Self, and at 5th level, Invisibility.",
  "Conoces Rayo de Escarcha. A nivel 3 lanzas Armadura de Agathys y a nivel 5 Oscuridad.": "You know Ray of Frost. At 3rd level, you can cast Armor of Agathys, and at 5th level, Darkness.",
  "Conoces Mano de Mago. A nivel 3 lanzas Disco Flotante de Tenser y a nivel 5 Cierre Arcano.": "You know Mage Hand. At 3rd level, you can cast Tenser's Floating Disk, and at 5th level, Arcane Lock.",
  "Conoces Mano de Mago. A nivel 3 lanzas Manos Ardientes y a nivel 5 Hoja Llameante.": "You know Mage Hand. At 3rd level, you can cast Burning Hands, and at 5th level, Flame Blade.",
  "Conoces Taumaturgia. A nivel 3 lanzas Castigo Abrasador y a nivel 5 Castigo Marcador.": "You know Thaumaturgy. At 3rd level, you can cast Searing Smite, and at 5th level, Branding Smite.",
  "Tienes una velocidad de vuelo de 30 pies mientras no lleves armadura pesada (reemplaza el legado de conjuros).": "You have a flying speed of 30 feet while not wearing heavy armor (replaces your spellcasting legacy).",
  "Tus puntos de golpe máximos aumentan en la mitad de tu nivel de personaje (mínimo 1).": "Your hit point maximum increases by half your character level (minimum 1).",
  "En cada descanso largo tiras 1d6 para determinar qué truco y conjuro puedes lanzar durante ese día.": "At the end of each long rest, you roll 1d6 to determine which cantrip and spell you can cast during that day.",
  "Tienes resistencia al tipo de daño asociado a tu ancestro dracónico.": "You have resistance to the damage type associated with your draconic ancestry.",
  "Fuego - Cono 15 pies (Salvación DES).": "Fire - 15-foot cone (DEX save).",
  "Relámpago - Línea 30x5 pies (Salvación DES).": "Lightning - 5 by 30-foot line (DEX save).",
  "Ácido - Línea 30x5 pies (Salvación DES).": "Acid - 5 by 30-foot line (DEX save).",
  "Fuego - Línea 30x5 pies (Salvación DES).": "Fire - 5 by 30-foot line (DEX save).",
  "Fuerza - Ráfaga telequinética y resistencia al daño de Fuerza.": "Force - Telekinetic blast and resistance to force damage.",
  "Radiante - Cono de 15 pies y resistencia al daño radiante.": "Radiant - 15-foot cone and resistance to radiant damage.",
  "Psíquico - Cono de 15 pies y resistencia al daño psíquico.": "Psychic - 15-foot cone and resistance to psychic damage.",
  "Trueno - Cono de 15 pies y resistencia al daño de trueno.": "Thunder - 15-foot cone and resistance to thunder damage.",
  "Necrótico - Cono de 15 pies y resistencia al daño necrótico.": "Necrotic - 15-foot cone and resistance to necrotic damage.",
  "Posees visión en la oscuridad de 60 pies.": "You have darkvision out to 60 feet.",
  "Cuando una criatura a tu alcance te daña, puedes usar tu reacción para atacarla con un arma cuerpo a cuerpo (1/descanso corto).": "When a creature within your reach deals damage to you, you can use your reaction to make one melee weapon attack against it (1/short rest).",
  "Puedes usar tus alas para no sufrir daño de caída y planear 2 pies horizontalmente por cada pie descendido.": "You can use your wings to negate falling damage and glide 2 feet horizontally for every 1 foot you descend.",
  "Ganas competencia en la habilidad Intimidación.": "You gain proficiency in the Intimidation skill.",
  "Cuando te reduzcan a 0 puntos de golpe pero no mueras instantáneamente, puedes reducirte a 1 punto de golpe en su lugar (1 vez por descanso largo).": "When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead (once per long rest).",
  "Cuando consigas un impacto crítico con un arma cuerpo a cuerpo, tiras uno de los dados de daño del arma adicionalmente y lo sumas.": "When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage.",
  "Mantienes todas las facultades de aguante salvaje e intimidación innata del manual del jugador.": "Retains all the classic Relentless Endurance and Menacing traits from the Player's Handbook.",
  "Añades 1d4 a tus pruebas de Sabiduría (Percepción) y Sabiduría (Supervivencia).": "You add 1d4 to your Wisdom (Perception) and Wisdom (Survival) checks.",
  "Puedes lanzar Fuego Feérico una vez por descanso largo. A nivel 3 lanzas Localizar Animales o Plantas como ritual.": "You can cast Faerie Fire once per long rest. At 3rd level, you can cast Locate Animals or Plants as a ritual.",
  "Ventaja en salvaciones contra ser hechizado y la magia no puede dormirte.": "Advantage on saving throws against being charmed, and magic cannot put you to sleep.",
  "Tu velocidad al caminar aumenta a 35 pies, o puedes intentar esconderte cuando estás ligeramente oscurecido por follaje o clima.": "Your walking speed increases to 35 feet, or you can attempt to hide when lightly obscured by foliage or weather.",
  "Conoces un truco de la lista de conjuros de Mago a tu elección (usa Inteligencia).": "You know one cantrip of your choice from the Wizard spell list (uses Intelligence).",
  "Conoces el truco Luces Danzantes. A nivel 3 lanzas Fuego Feérico y a nivel 5 Oscuridad.": "You know the Dancing Lights cantrip. At 3rd level, you can cast Faerie Fire, and at 5th level, Darkness.",
  "Posees una velocidad de nado de 30 pies.": "You have a swimming speed of 30 feet.",
  "Añades 1d4 a tus pruebas de Inteligencia (Investigación) y Sabiduría (Perspicacia).": "You add 1d4 to your Intelligence (Investigation) and Wisdom (Insight) checks.",
  "Puedes lanzar Detectar Magia y Detectar Venenos como rituales. A nivel 3 lanzas Ver lo Invisible (Sabiduría).": "You can cast Detect Magic and Detect Poison and Disease as rituals. At 3rd level, you can cast See Invisibility (Wisdom).",
  "Añades 1d4 a tus pruebas de Destreza (Acrobacias) y pruebas con herramientas de navegante.": "You add 1d4 to your Dexterity (Acrobatics) checks and ability checks with navigator's tools.",
  "Conoces el truco Ráfaga (Gust). Puedes lanzar Ráfaga de Viento (Gust of Wind) a nivel 3 (Carisma).": "You know the Gust cantrip. You can cast Gust of Wind at 3rd level (Charisma).",
  "Tienes ventaja en todas las tiradas de salvación de Inteligencia, Sabiduría y Carisma contra magia.": "You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic.",
  "Doble competencia en Historia sobre objetos mágicos u orfebrería mecánica.": "Double proficiency bonus on History checks related to magic items or clockwork craft.",
  "Puedes crear juguetes mecánicos, encendedores y cajas de música funcionales.": "You can construct functional clockwork toys, fire starters, and music boxes.",
  "Puedes comunicar ideas sencillas a bestias de tamaño Pequeño o menor.": "You can communicate simple ideas with Small or smaller beasts.",
  "Tienes ventaja en todas las pruebas de Destreza (Sigilo) para esconderte en terreno rocoso o subterráneo.": "You have advantage on all Dexterity (Stealth) checks made to hide in rocky or underground terrain.",
  "Añades 1d4 a tus pruebas de Inteligencia (Historia) y pruebas con herramientas de calígrafo.": "You add 1d4 to your Intelligence (History) checks and ability checks with calligrapher's supplies.",
  "Conoces el truco Mensaje (Message). Puedes lanzar Comprender Idiomas como ritual. A nivel 3 lanzas Mensaje Arcano (Carisma).": "You know the Message cantrip. You can cast Comprehend Languages as a ritual. At 3rd level, you can cast Illusory Script (Charisma).",
  "Puedes sumar un dado 1d4 a cualquier tirada de ataque, prueba de característica o salvación (usos = bono de competencia).": "You can add a 1d4 die to any attack roll, ability check, or saving throw (uses equal to your proficiency bonus).",
  "CA base de 13 + Destreza.": "Base AC of 13 + Dexterity.",
  "El truco Remendar (Mending) te permite gastar un dado de golpe para recuperar puntos de golpe.": "When the Mending cantrip is cast on you, you can spend a Hit Die to regain hit points.",
  "Conserva el dominio de escape ágil y furia sorpresiva clásica.": "Retains the classic Nimble Escape and Fury of the Small traits.",
  "Puedes comunicar ideas sencillas a bestias de tamaño Pequeño o menor a través de sonidos y gestos.": "You can communicate simple ideas with Small or smaller beasts through sounds and gestures.",
  "Tienes competencia con dos armas marciales a tu elección y con armadura ligera.": "You have proficiency with two martial weapons of your choice and with light armor.",
  "Si fallas una tirada, puedes sumar un bono igual al número de aliados que veas a 30 pies (máximo +5). 1/descanso corto.": "If you miss with an attack roll or fail an ability check or saving throw, you can gain a bonus equal to the number of allies you can see within 30 feet of you (maximum +5). 1/short rest.",
  "Puedes usar la acción de Ayuda como acción adicional (usos = bono de competencia). Otorga ventajas secundarias como velocidad o PG temporales.": "You can take the Help action as a bonus action (uses equal to your proficiency bonus). Grants secondary benefits such as extra speed or temporary HP.",
  "Bono a tiradas falladas según aliados a 30 pies (máximo +3).": "Bonus to failed rolls based on allies within 30 feet (maximum +3).",
  "Conserva todas las facultades clásicas de emboscada contundente y brazos extensibles.": "Retains all the classic Surprise Attack and Long-Limbed traits.",
  "Pequeños reptiles con sangre de sierpes ancestrales.": "Small reptiles with the blood of ancient wyrms.",
  "Tienes ventaja en tiradas de ataque si al menos un aliado está a 5 pies del objetivo.": "You have advantage on attack rolls against a creature if at least one of your allies is within 5 feet of the creature.",
  "Como acción distraes a los enemigos a 10 pies para que tus aliados tengan ventaja al atacarlos (1/descanso corto).": "As an action, you distract enemies within 10 feet of you, granting your allies advantage on attack rolls against them (1/short rest).",
  "Como acción adicional emites un rugido: tú y tus aliados tienen ventaja en ataques contra enemigos a 10 pies hasta el final de tu siguiente turno (usos = bono de competencia).": "As a bonus action, you let out a draconic cry: you and your allies have advantage on attack rolls against enemies within 10 feet of you until the start of your next turn (uses equal to your proficiency bonus).",
  "Conoces un truco de Hechicero (Carisma) o tienes ventaja en salvaciones contra estar Asustado.": "You know one Sorcerer cantrip of your choice (Charisma), or you have advantage on saving throws against being frightened.",
  "Como acción adicional puedes moverte hasta tu velocidad directamente hacia una criatura hostil que veas.": "As a bonus action, you can move up to your speed directly toward a hostile creature you can see.",
  "Cuentas como Grande para capacidad de carga y levantamiento.": "You count as Large for carrying and lifting capacity.",
  "Competencia en la habilidad Intimidación.": "Proficiency in the Intimidation skill.",
  "Al caer a 0 PG pero no morir, te quedas en 1 PG en su lugar (1/descanso largo).": "When reduced to 0 HP without being killed outright, you drop to 1 HP instead (1/long rest).",
  "Añades 1d4 a tus pruebas de Sabiduría (Supervivencia) e Intuición.": "You add 1d4 to your Wisdom (Survival) and Insight checks.",
  "Al realizar un impacto crítico con un arma cuerpo a cuerpo, tiras un dado adicional de daño.": "When you score a critical hit with a melee weapon attack, you roll one additional weapon damage die.",
  "Tienes ventaja en todas las tiradas de salvación contra conjuros y otros efectos mágicos.": "You have advantage on all saving throws against spells and other magical effects.",
  "Conoces el truco Rociada de Veneno (Poison Spray). Puedes lanzar Sugestión a nivel 3 (1/descanso largo).": "You know the Poison Spray cantrip. You can cast Suggestion at 3rd level (1/long rest).",
  "Eres completamente inmune al daño por veneno y a la condición de Envenenado.": "You are completely immune to poison damage and the poisoned condition.",
  "Puedes comunicarte telepáticamente con serpientes no mágicas sin límite.": "You can communicate telepathically with nonmagical snakes at will.",
  "Tienes resistencia al daño por veneno y ventaja en salvaciones contra la condición de envenenado.": "You have resistance to poison damage and advantage on saving throws against the poisoned condition.",
  "Ataque desarmado natural que inflige 1d6 + Fuerza de daño perforante.": "Natural unarmed strike that deals 1d6 + Strength piercing damage.",
  "Sin armadura, tu CA es igual a 13 + Destreza.": "While unarmored, your AC equals 13 + Dexterity.",
  "Puedes aguantar la respiración hasta por 15 minutos.": "You can hold your breath for up to 15 minutes at a time.",
  "Puedes fabricar escudos, garrotes, jabalinas y dardos con huesos y pieles de presas muertas.": "You can craft shields, clubs, javelins, and darts from the bones and hides of slain prey.",
  "Ganas competencia en la habilidad Naturaleza o Supervivencia y resistencia al daño por veneno.": "You gain proficiency in the Nature or Survival skill and resistance to poison damage.",
  "Como acción tocas a una criatura y restauras tantos PG como tu nivel de personaje (1 vez por descanso largo).": "As an action, you can touch a creature and restore a number of HP equal to your character level (once per long rest).",
  "Tienes resistencia tanto al daño necrótico como al daño radiante.": "You have resistance to both necrotic damage and radiant damage.",
  "Como acción desatas alas luminosas durante 1 minuto: obtienes vuelo de 30 pies e infliges daño radiante extra igual a tu nivel en un ataque por turno (1/descanso largo).": "As an action, you unleash luminous wings for 1 minute: you gain a flying speed of 30 feet and deal extra radiant damage equal to your level once per turn on an attack or spell (1/long rest).",
  "Como acción emites un aura abrasadora de 10 pies durante 1 minuto: al final de tu turno tú sufres daño radiante igual a la mitad de tu nivel y las demás criaturas sufren daño radiante igual a tu nivel.": "As an action, you emit a searing 10-foot aura for 1 minute: at the end of each of your turns, you take radiant damage equal to half your level, and other creatures in the aura take radiant damage equal to your level.",
  "Como acción te rodeas de oscuridad espectral: las criaturas a 10 pies deben superar salvación de Carisma o quedan Asustadas. Infliges daño necrótico extra igual a tu nivel.": "As an action, you shroud yourself in spectral gloom: creatures within 10 feet must succeed on a Charisma saving throw or become Frightened. You deal extra necrotic damage equal to your level.",
  "A partir de nivel 3 como acción adicional desatas tu forma divina por 1 minuto, causando daño celestial extra y vuelo feérico.": "Starting at 3rd level, you can use a bonus action to unleash your celestial revelation for 1 minute, dealing extra celestial damage and gaining spectral flight.",
  "Cuentas como un tamaño Grande para capacidad de carga, empujar, levantar y arrastrar.": "You count as one size larger (Large) when determining your carrying capacity and the weight you can push, drag, or lift.",
  "Tienes competencia en la habilidad Atletismo.": "You have proficiency in the Athletics skill.",
  "Tienes resistencia al daño por frío y estás aclimatado a altitudes extremas.": "You have resistance to cold damage and are naturally acclimated to high altitudes.",
  "Como acción adicional te teletransportas mágicamente hasta 30 pies a un espacio desocupado que veas (usos = bono de competencia por descanso largo).": "As a bonus action, you magically teleport up to 30 feet to an unoccupied space you can see (uses equal to your proficiency bonus per long rest).",
  "Cuando golpeas a una criatura con un ataque, infliges 1d10 daño de fuego adicional (usos = bono de competencia).": "When you hit a creature with an attack, you can deal an extra 1d10 fire damage (uses equal to your proficiency bonus).",
  "Cuando golpeas a una criatura, infliges 1d6 daño de frío adicional y reduces su velocidad en 10 pies hasta el inicio de tu siguiente turno.": "When you hit a creature, you can deal an extra 1d6 cold damage and reduce its speed by 10 feet until the start of your next turn.",
  "Cuando golpeas a una criatura Grande o menor, puedes derribarla inmediatamente (usos = bono de competencia).": "When you hit a Large or smaller creature, you can immediately knock it prone (uses equal to your proficiency bonus).",
  "Como reacción cuando recibes daño, el atacante sufre 1d8 daño de trueno (usos = bono de competencia).": "As a reaction when you take damage, the attacker takes 1d8 thunder damage (uses equal to your proficiency bonus).",
  "Ataques desarmados causan 1d4 + Fue/Des de daño cortante y posees velocidad de trepar de 20 pies.": "Your unarmed strikes deal 1d4 + STR/DEX slashing damage, and you have a climbing speed of 20 feet.",
  "Tienes competencia en las habilidades Percepción y Sigilo.": "You have proficiency in the Perception and Stealth skills.",
  "Conserva la velocidad y garras clásicas de Volo.": "Retains the classic Volo's Guide feline agility and claws.",
  "Tus garras infligen 1d6 + Fue daño cortante y tu velocidad de trepar es de 30 pies.": "Your claws deal 1d6 + STR slashing damage, and your climbing speed is 30 feet.",
  "Como acción te refugias dentro de tu caparazón: ganas +4 a la CA y ventaja en salvaciones de Fuerza y Constitución. Velocidad 0 hasta salir.": "As an action, you can withdraw into your shell: you gain a +4 bonus to AC and advantage on Strength and Constitution saving throws. Your speed is 0 until you emerge.",
  "Ataques desarmados con garras causan 1d4 + Fuerza daño cortante.": "Unarmed strikes with your claws deal 1d4 + Strength slashing damage.",
  "Puedes aguantar la respiración hasta por 1 hora.": "You can hold your breath for up to 1 hour at a time.",
  "Competencia en la habilidad Supervivencia.": "Proficiency in the Survival skill.",
  "Posees velocidad de nado de 30 pies y competencia en Naturaleza.": "You have a swimming speed of 30 feet and proficiency in Nature.",
  "Ventaja en pruebas para duplicar documentos, caligrafía ajena y sellos.": "Advantage on all checks made to produce forgeries or duplicate existing objects, handwriting, and seals.",
  "Competencia en dos habilidades entre Acrobacias, Engaño, Sigilo o Juego de Manos.": "Proficiency in two skills of your choice from Acrobatics, Deception, Stealth, and Sleight of Hand.",
  "Conserva el mimetismo clásico de Volo.": "Retains the classic Volo's Guide mimicry traits.",
  "Cuando haces una prueba de característica en la que tengas competencia, sumas 1d4 al resultado (usos = bono de competencia).": "When you make an ability check using a skill in which you have proficiency, you can give yourself advantage or add 1d4 to the check (uses equal to your proficiency bonus).",
  "Puedes lanzar Detectar Magia y Disfrazarse (Sabiduría) 1/descanso corto o largo cada uno.": "You can cast Detect Magic and Disguise Self (Wisdom) once per short or long rest each.",
  "Las bestias y plantas entienden tus palabras y tienes ventaja en pruebas de Carisma para interactuar con ellas.": "Beasts and plants can understand your words, and you have advantage on all Charisma checks you make to influence them.",
  "Conserva la magia innata clásica de Volo.": "Retains the classic Volo's Guide Firbolg Magic.",
  "Paso Oculto tiene usos iguales a tu bonificador de competencia por descanso largo.": "Hidden Step has a number of uses equal to your proficiency bonus per long rest.",
  "Portas la sangre de los genios elementales primordiales.": "You carry the blood of the primordial elemental genies.",
  "Ves en la oscuridad hasta 60 pies en tonos rojos.": "You can see in darkness out to 60 feet in shades of red.",
  "Conoces el truco Producir Llama (Produce Flame). A partir del nivel 3, puedes lanzar Manos Ardientes (Burning Hands). A partir del nivel 5, puedes lanzar Hoja de Fuego (Flame Blade) sin componentes materiales. Una vez lanzas cualquiera de ellos con este rasgo, no puedes volver a hacerlo hasta terminar un descanso largo (o usando espacios de conjuro). Inteligencia, Sabiduría o Carisma es tu aptitud mágica para estos conjuros (a elegir al seleccionar esta raza).": "You know the Produce Flame cantrip. Starting at 3rd level, you can cast Burning Hands. Starting at 5th level, you can cast Flame Blade without material components. Once you cast either spell with this trait, you can't cast that spell with it again until you finish a long rest (or you can cast them using spell slots). Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you select this race).",
  "Puedes respirar tanto aire como agua.": "You can breathe both air and water.",
  "Tienes una velocidad de nado de 30 pies.": "You have a swimming speed of 30 feet.",
  "Conoces el truco Salpicadura Ácida (Acid Splash). A partir del nivel 3, puedes lanzar Crear o Destruir Agua (Create or Destroy Water). A partir del nivel 5, puedes lanzar Caminar sobre las Aguas (Water Walk) sin componentes materiales. Una vez lanzas cualquiera de ellos con este rasgo, no puedes volver a hacerlo hasta terminar un descanso largo (o usando espacios de conjuro). Inteligencia, Sabiduría o Carisma es tu aptitud mágica para estos conjuros (a elegir al seleccionar esta raza).": "You know the Acid Splash cantrip. Starting at 3rd level, you can cast Create or Destroy Water. Starting at 5th level, you can cast Water Walk without material components. Once you cast either spell with this trait, you can't cast that spell with it again until you finish a long rest (or you can cast them using spell slots). Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you select this race).",
  "Puedes contener la respiración indefinidamente mientras no estés incapacitado.": "You can hold your breath indefinitely while you're not incapacitated.",
  "Conoces el truco Agarre Electrizante (Shocking Grasp). A partir del nivel 3, puedes lanzar Caída de Pluma (Feather Fall) sin componentes materiales. A partir del nivel 5, puedes lanzar Levitar (Levitate) sin componentes materiales. Una vez lanzas cualquiera de ellos con este rasgo, no puedes volver a hacerlo hasta terminar un descanso largo (o usando espacios de conjuro). Inteligencia, Sabiduría o Carisma es tu aptitud mágica para estos conjuros (a elegir al seleccionar esta raza).": "You know the Shocking Grasp cantrip. Starting at 3rd level, you can cast Feather Fall without material components. Starting at 5th level, you can cast Levitate without material components. Once you cast either spell with this trait, you can't cast that spell with it again until you finish a long rest (or you can cast them using spell slots). Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you select this race).",
  "Puedes moverte por terreno difícil de tierra o roca sin coste adicional de movimiento si estás usando tu velocidad caminando.": "You can move across difficult terrain made of earth or stone without spending extra movement if you are using your walking speed.",
  "Conoces el truco Protección contra las Armas (Blade Ward). Puedes lanzarlo como una acción normal, y también como acción adicional tantas veces como tu bonificador por competencia, recuperando todos los usos al finalizar un descanso largo. A partir del nivel 5, puedes lanzar el conjuro Pasar sin Rastro (Pass Without Trace) con este rasgo, sin requerir componentes materiales. Una vez lanzado con este rasgo, no puedes volver a hacerlo hasta terminar un descanso largo. También puedes lanzarlo usando cualquier espacio de conjuro que tengas de nivel 2 o superior. Inteligencia, Sabiduría o Carisma es tu aptitud mágica para estos conjuros (a elegir al seleccionar esta raza).": "You know the Blade Ward cantrip. You can cast it as normal, and you can also cast it as a bonus action a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest. Starting at 5th level, you can cast the Pass without Trace spell with this trait, without requiring a material component. Once you cast that spell with this trait, you can't do so again until you finish a long rest. You can also cast that spell using any spell slots you have of 2nd level or higher. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you select this race).",
  "Puedes comunicar conceptos simples a cualquier bestia con velocidad de nado.": "You can communicate simple concepts to any beast that has a swimming speed.",
  "Resistencia al frío e inmunidad a la presión abisal.": "Resistance to cold damage and immunity to deep-ocean pressure.",
  "Conserva el lanzamiento innato clásico.": "Retains the classic innate spellcasting.",
  "Puedes lanzar tus conjuros raciales con ranuras de conjuro de cualquier clase que poseas.": "You can also cast your racial spells using any spell slots you have of the appropriate level.",
  "Como acción cambias tu apariencia física y voz. Puedes adoptar la forma de cualquier humanoide que hayas visto (tu equipo no cambia).": "As an action, you can change your physical appearance and your voice. You can adopt the form of any humanoid you have seen (your equipment does not change).",
  "Competencia en dos habilidades entre Engaño, Perspicacia, Intimidación o Persuasión.": "Proficiency in two skills of your choice from Deception, Insight, Intimidation, and Persuasion.",
  "Conserva la versatilidad de la farsa de identidades múltiples.": "Retains the classic Shapechanger versatility of multiple identities.",
  "Al cambiar de forma puedes decidir si tu tamaño es Pequeño o Mediano.": "When you change your appearance, you can also change your size between Medium and Small.",
  "Ventaja en salvaciones contra veneno, resistencia al veneno, inmunidad a enfermedades, no necesitas comer, beber ni respirar.": "Advantage on saving throws against poison, resistance to poison damage, immunity to disease, and you don't need to eat, drink, or breathe.",
  "No necesitas dormir; descansas inmóvil 6 horas manteniendo la consciencia activa.": "You don't need to sleep; instead, you rest in an inactive, motionless state for 6 hours while remaining fully conscious.",
  "Ganas un bonificador permanente de +1 a tu Clase de Armadura.": "You gain a permanent +1 bonus to your Armor Class.",
  "Ganas competencia en una habilidad y un conjunto de herramientas a tu elección.": "You gain proficiency in one skill and one tool of your choice.",
  "Tus ataques desarmados infligen 1d6 + Fuerza de daño contundente.": "Your unarmed strikes deal 1d6 + Strength bludgeoning damage.",
  "Ganas competencia en Atletismo y tu capacidad de carga se duplica.": "You gain proficiency in Athletics, and your carrying capacity is doubled.",
  "Una herramienta a tu elección está instalada en tu cuerpo y duplicas tu bonificador de competencia al usarla.": "One tool of your choice is integrated into your body, and your proficiency bonus is doubled for any ability check you make with it.",
  "Tus garras infligen 1d4 + Fuerza daño cortante en ataques desarmados.": "Your talons deal 1d4 + Strength slashing damage on unarmed strikes.",
  "Velocidad de vuelo de 50 pies sin vestir armadura media ni pesada.": "Flying speed of 50 feet while not wearing medium or heavy armor.",
  "Velocidad de vuelo igual a tu velocidad al caminar (30 pies) sin armadura pesada.": "Flying speed equal to your walking speed (30 feet) while not wearing heavy armor.",
  "A nivel 3 puedes lanzar Ráfaga de Viento (Gust of Wind) usando Sabiduría.": "Starting at 3rd level, you can cast the Gust of Wind spell using Wisdom.",
  "Tu tipo de criatura es Feérico (Fey), inmune a conjuros que afecten solo a humanoides.": "Your creature type is Fey, rendering you immune to spells that affect only humanoids.",
  "Velocidad de vuelo de 30 pies mientras no lleves armadura pesada.": "Flying speed of 30 feet while not wearing heavy armor.",
  "Conoces Druidcraft. A nivel 3 lanzas Fuego Feérico y a nivel 5 Agrandar/Reducir.": "You know the Druidcraft cantrip. At 3rd level, you can cast Faerie Fire, and at 5th level, Enlarge/Reduce.",
  "Puedes deslizarte por aberturas de hasta 1 pulgada sin apretarte.": "You can squeeze through a space as narrow as 1 inch wide.",
  "Ventaja en pruebas de Trato con Animales con criaturas de tamaño Pequeño o menor.": "Advantage on Animal Handling checks with Small or smaller creatures.",
  "Añades tu bonificador de competencia a todas tus tiradas de Iniciativa.": "You can add your proficiency bonus to your initiative rolls.",
  "Como acción adicional saltas 5 pies x tu bono de competencia sin provocar ataques de oportunidad (usos = bono comp).": "As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks (uses equal to your proficiency bonus).",
  "Si fallas una salvación de Destreza, puedes usar tu reacción para sumar 1d4 al total.": "When you fail a Dexterity saving throw, you can use your reaction to roll a d4 and add it to the save.",
  "Conserva todas las facultades oficiales de salto y reflejos de liebre.": "Retains all the official Rabbit Hop and Lucky Footwork traits.",
  "Velocidad de excavar de 10 pies a través de tierra suelta o arena.": "Burrowing speed of 10 feet through loose earth or sand.",
  "Tu tipo de criatura es Feérico en lugar de Humanoide.": "Your creature type is Fey, rather than Humanoid.",
  "Ataques desarmados con pezuñas causan 1d4 + Fuerza daño contundente.": "Unarmed strikes with your hooves deal 1d4 + Strength bludgeoning damage.",
  "Si te mueves al menos 30 pies en línea recta hacia un objetivo e impactas, puedes atacar con tus pezuñas como acción adicional.": "If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves.",
  "Cuentas como Grande para capacidad de carga; trepar cuesta 4 pies por pie recorrido.": "You count as Large for carrying capacity; any climb that requires hands and feet costs 4 feet of movement for every 1 foot climbed.",
  "Tus pezuñas infligen 1d6 + Fuerza de daño contundente.": "Your hooves deal 1d6 + Strength bludgeoning damage.",
  "Ataques desarmados con cuernos causan 1d6 + Fuerza daño perforante.": "Unarmed strikes with your horns deal 1d6 + Strength piercing damage.",
  "Tras correr al menos 20 pies con Dash, puedes atacar con tus cuernos como acción adicional.": "Immediately after you use the Dash action on your turn and move at least 20 feet, you can make one melee attack with your horns as a bonus action.",
  "Tras golpear con un ataque cuerpo a cuerpo, puedes usar tu acción adicional para empujar al objetivo hasta 10 pies.": "Immediately after you hit a creature with a melee attack as part of the Attack action on your turn, you can use a bonus action to attempt to shove that target up to 10 feet away from you.",
  "Competencia en Intimidación o Persuasión.": "Proficiency in the Intimidation or Persuasion skill.",
  "Siempre recuerdas la dirección en la que viajaste y tienes ventaja en pruebas de Supervivencia para no perderte.": "You always recall the direction you have traveled, and you have advantage on Survival checks made to avoid getting lost.",
  "Tu tipo de criatura es Feérico.": "Your creature type is Fey.",
  "Tus cuernos infligen 1d4 + Fuerza daño contundente en ataques desarmados.": "Your horns deal 1d4 + Strength bludgeoning damage on unarmed strikes.",
  "Al hacer un salto de longitud o altura, tiras 1d8 y sumas el resultado a la distancia.": "Whenever you make a long jump or a high jump, you can roll a d8 and add the number rolled to the number of feet you cover, even when making a standing jump.",
  "Competencia en Interpretación, Persuasión y un instrumento musical a elección.": "Proficiency in Performance, Persuasion, and one musical instrument of your choice.",
  "Ventaja en salvaciones contra ser encantado o asustado durante banquetes.": "Advantage on saving throws against being charmed or frightened during revels and feasts.",
  "Conoces el truco Mano de Mago (invisible) que manipulas psiónicamente.": "You know the Mage Hand cantrip, and the hand is invisible when you cast the cantrip with this trait.",
  "Competencia con espada corta, espada larga, espadón y armaduras ligeras y medias.": "Proficiency with the shortsword, longsword, greatsword, and light and medium armor.",
  "Al transformarte ganas 1d6 PG temporales adicionales y +1 a tu CA.": "Whenever you shift, you gain 1d6 additional temporary HP, and while shifted you have a +1 bonus to your AC.",
  "Competencia en la habilidad Atletismo.": "Proficiency in the Athletics skill.",
  "Como acción adicional al transformarte y turnos posteriores atacas con tus colmillos (1d6 + Fuerza perforante).": "When you shift and as a bonus action on your other turns while shifted, you can use your elongated fangs to make an unarmed strike (1d6 + Strength piercing damage).",
  "Al transformarte tu velocidad al caminar aumenta en 10 pies.": "While shifted, your walking speed increases by 10 feet.",
  "Como reacción cuando un enemigo termina su turno a 5 pies de ti, te mueves hasta 10 pies sin provocar ataques de oportunidad.": "As a reaction when an enemy ends its turn within 5 feet of you while you are shifted, you can move up to 10 feet without provoking opportunity attacks.",
  "Competencia en Acrobacias.": "Proficiency in the Acrobatics skill.",
  "Al transformarte tienes ventaja en pruebas de Sabiduría y ningún enemigo a 30 pies puede tener ventaja al atacarte.": "While shifted, you have advantage on Wisdom checks, and no creature within 30 feet of you can make an attack roll with advantage against you.",
  "Competencia en Supervivencia.": "Proficiency in the Survival skill.",
  "Tienes ventaja en todas las tiradas de salvación de Sabiduría.": "You have advantage on all Wisdom saving throws.",
  "Inmune a conjuros o efectos que manipulen sueños o requieran que sueñes.": "You are immune to spells and other effects that require you to dream or that manipulate dreams.",
  "Competencia en Perspicacia o Persuasión.": "Proficiency in the Insight or Persuasion skill.",
  "Competencia en Percepción o Sigilo.": "Proficiency in the Perception or Stealth skill.",
  "Ataques desarmados con garras infligen 1d4 + Fuerza daño cortante.": "Unarmed strikes with your claws deal 1d4 + Strength slashing damage.",
  "Competencia en Atletismo, Intimidación, Percepción o Supervivencia.": "Proficiency in one of the following skills of your choice: Athletics, Intimidation, Perception, or Survival.",
  "Conserva el rugido y sentidos tradicionales de Theros.": "Retains the traditional Theros Daunting Roar and Hunter's Instincts.",
  "Velocidad de 40 pies y competencia en Sigilo.": "Base walking speed of 40 feet and proficiency in Stealth.",
  "Puedes manipular herramientas, levantar hasta 5 veces tu Fuerza en peso, y hacer presas contra enemigos con tu trompa.": "You can grasp things with your trunk, lift a number of pounds equal to five times your Strength score, and use it to make unarmed strikes or grapple creatures.",
  "Tu piel gruesa te otorga una CA base de 12 + tu modificador de Constitución (puedes usar escudo).": "Your thick, leathery skin gives you a base AC of 12 + your Constitution modifier (you can still use a shield).",
  "Tienes ventaja en pruebas de Sabiduría (Percepción) e Investigación basadas en el olfato.": "You have advantage on Wisdom (Perception), Wisdom (Survival), and Intelligence (Investigation) checks that involve smell.",
  "Competencia con herramientas de albañil o carpintero.": "Proficiency with mason's tools or carpenter's tools.",
  "Competencia en la habilidad Historia.": "Proficiency in the History skill.",
  "Gracias a tu afición por recoger curiosidades, puedes sacar de tus bolsillos cualquier objeto mundano de 2 po o menos que quepa en tu mano una vez por descanso corto.": "Thanks to your fondness for picking up curiosities, you can pull any mundane item worth 2 gp or less that fits in your hand from your pockets once per short rest.",
  "Tienes una velocidad de vuelo igual a tu velocidad al caminar (30 pies). Para volar no puedes vestir armadura media ni pesada.": "You have a flying speed equal to your walking speed (30 feet). You can't use this flying speed if you're wearing medium or heavy armor.",
  "Ganas competencia en la habilidad Sigilo.": "You gain proficiency in the Stealth skill.",
  "Puedes pasar a través de cualquier abertura tan pequeña como de 1 pulgada de ancho sin apretarte, siempre que no lleves equipo ni armadura.": "You can move through a space as narrow as 1 inch wide without squeezing, provided you are wearing and carrying nothing.",
  "Tienes resistencia al daño por ácido y al daño por veneno, y tienes ventaja en salvaciones contra veneno.": "You have resistance to acid damage and poison damage, and you have advantage on saving throws against poison.",
  "Como acción adicional extiendes un pseudópodo de hasta 10 pies para manipular objetos, abrir puertas no trabadas o guardar cosas.": "As a bonus action, you can extrude a pseudopod that is up to 6 inches wide and 10 feet long to manipulate an object, open or close an unlocked door or container, or stow or retrieve an item.",
  "Puedes contener la respiración hasta por 1 hora.": "You can hold your breath for up to 1 hour.",
  "Posees dos brazos adicionales más pequeños con los que puedes manipular objetos ligeros, desenvainar o guardar armas ligeras, y blandir armas con la propiedad Ligera.": "You have two slightly smaller secondary arms below your primary pair of arms. They can manipulate an object, open or close a door or container, pick up or set down a Tiny object, or wield a weapon that has the Light property.",
  "Tu caparazón te otorga una CA base de 13 + Destreza. Puedes cambiar el color de tu caparazón para ganar ventaja en pruebas de Sigilo para esconderte.": "Your carapace gives you a base AC of 13 + your Dexterity modifier. As an action, you can change the color of your carapace to match your surroundings, giving you advantage on Dexterity (Stealth) checks made to hide.",
  "Puedes hablar telepáticamente con cualquier criatura a 120 pies sin importar los idiomas que comparta contigo.": "You can speak telepathically to any willing creature you can see within 120 feet of you, without needing to share a language with it.",
  "No necesitas dormir y la magia no puede dormirte. Obtienes descanso largo meditando 4 horas.": "You do not need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a torpid, motionless state.",
  "Cualquier criatura que te sujete en una presa o toque tu piel debe superar salvación de Con (CD 12) o queda Envenenada por 1 minuto. Puedes aplicar tu toxina a armas perforantes como acción adicional.": "Any creature that grapples you or otherwise comes into direct contact with your skin must succeed on a DC 12 Constitution saving throw or become Poisoned for 1 minute. As part of an attack or as a bonus action, you can apply this poison to any piercing weapon.",
  "Tu salto de longitud es de hasta 25 pies y tu salto de altura es de hasta 15 pies, con o sin carrerilla.": "Your long jump is up to 25 feet and your high jump is up to 15 feet, with or without a running start.",
  "Inmune al daño por veneno y a la condición de Envenenado.": "You are immune to poison damage and the Poisoned condition.",
  "Puedes respirar aire y agua. Debes sumergirte en agua al menos 1 hora al día o sufres un nivel de agotamiento.": "You can breathe air and water, but you need to be submerged in water at least once every 4 hours for 1 hour to avoid suffocating and taking 1 level of exhaustion.",
  "Eliges una mutación: Planeo de Manta Raya (no sufres daño de caída y planeas 2 pies por cada pie que caigas), Caparazón Acorazado (+1 a la CA), o Nado y Branquias (velocidad de nado 30 pies y respiras agua).": "Choose one adaptation at 1st level: Manta Glide (negate falling damage up to 100 feet and glide 2 feet horizontally per 1 foot descended), Carapace (+1 bonus to AC while not wearing heavy armor), or Nimble Climber / Underwater Adaptation (swimming speed of 30 feet and can breathe water).",
  "A nivel 5 eliges: Pinzas de Cangrejo (ataque desarmado 1d6 + Fuerza y presa como acción adicional), Escupitajo de Ácido (2d10 ácido a 30 pies), o Ojos Submarinos.": "At 5th level, choose a second adaptation: Grappling Appendages (1d6 + Strength unarmed strike and bonus-action grapple), Acid Spit (2d10 acid damage at 30 feet), or Aquatic Sight.",
  "Tienes competencia con todas las armas de fuego. Disparar un arma de fuego a 5 pies de un enemigo hostil no te impone desventaja y no sufres penalización por alcance largo.": "You have proficiency with all firearms. Being within 5 feet of a hostile creature doesn't impose disadvantage on your ranged attack rolls with firearms, and you ignore the loading or long-range penalty.",
  "Tienes ventaja en tiradas de salvación de Fuerza y pruebas de característica de Fuerza. Una vez por turno, cuando golpeas con un arma cuerpo a cuerpo, sumas tu bono de competencia al daño.": "You have advantage on Strength saving throws and Strength ability checks. Once per turn, when you hit a target with a melee weapon attack, you can add your proficiency bonus to the damage roll.",
  "Tienes ventaja en todas las tiradas de salvación de Inteligencia, Sabiduría y Carisma.": "You have advantage on all Intelligence, Wisdom, and Charisma saving throws.",
  "Ganas competencia en una habilidad de conocimiento (Arcano, Historia, Investigación, Medicina, Naturaleza o Religión) y una herramienta, y añades un dado 1d4 a las pruebas que hagas con ellas.": "You gain proficiency in one lore skill of your choice (Arcana, History, Investigation, Medicine, Nature, or Religion) and one tool of your choice, and you add 1d4 to any ability check you make using them.",
  "Puedes respirar bajo el agua hasta por 1 hora cada vez que te sumerges.": "You can hold your breath and breathe underwater for up to 1 hour each time you submerge.",
  "La adaptación a la vida en los barcos espaciales te ha dotado de una resistencia innata. Cuando recibes daño, puedes usar tu reacción para tirar 1d6 + tu bonificador de competencia y reducir el daño recibido en esa cantidad. Puedes usar este rasgo un número de veces igual a tu bonificador de competencia por cada descanso largo.": "Adapting to life aboard spelljamming ships has granted you innate resilience. When you take damage, you can use your reaction to roll 1d6 + your proficiency bonus and reduce the damage taken by that amount. You can use this trait a number of times equal to your proficiency bonus per long rest.",
  "Posees escamas gruesas y resbaladizas. Tu Clase de Armadura base es 12 + tu modificador de Destreza cuando no llevas armadura.": "You have thick, slippery scales. When you aren't wearing armor, your base Armor Class is 12 + your Dexterity modifier.",
  "Tienes competencia en las habilidades de Atletismo y Percepción.": "You have proficiency in the Athletics and Perception skills.",
  "Puedes respirar tanto aire como agua, pero necesitas sumergirte en agua al menos una vez cada 4 horas para evitar asfixiarte.": "You can breathe both air and water, but you need to be submerged in liquid water at least once every 4 hours to avoid suffocating.",
  "Puedes comunicarte mentalmente con cualquier criatura que puedas ver a 30 pies de ti. No necesitas compartir un idioma común para transmitir ideas, emociones e imágenes sencillas.": "You can communicate mentally with any creature you can see within 30 feet of you. You don't need to share a language with the creature to convey simple ideas, emotions, and images.",
  "Tienes competencia en la habilidad de Persuasión.": "You have proficiency in the Persuasion skill.",
  "Al alcanzar el 5º nivel, tu cuerpo experimenta un repentino estirón de crecimiento mutagénico: tu categoría de tamaño cambia permanentemente de Pequeño a Mediano.": "When you reach 5th level, your body undergoes a sudden mutagenic growth spurt: your size category permanently changes from Small to Medium.",
  "Vara de madera endurecida pulida, ideal para monjes, magos y aventureros prácticos.": "A polished staff of hardened wood, ideal for monks, wizards, and practical adventurers.",
  "Hoja corta y afilada fácil de ocultar en una bota o cinto. Permite usar Destreza o Fuerza.": "A short, sharp blade easy to conceal in a boot or belt. Can be wielded using Dexterity or Strength.",
  "Maza de madera tosca y maciza, económica y accesible para cualquier plebeyo.": "A crude, solid wooden bludgeon, inexpensive and accessible to any commoner.",
  "Tronco pesado o bate reforzado que requiere empuñarse con ambas manos para asestar golpes contundentes.": "A heavy log or reinforced bat that requires two hands to deliver bone-crushing blows.",
  "Hacha compacta y equilibrada que puede lanzarse con gran potencia o blandirse en parejas.": "A compact, balanced axe that can be thrown with great force or wielded in pairs.",
  "Herramienta agrícola curvada adoptada a menudo por druidas para recolectar muérdago o defenderse.": "A curved farming implement often adopted by druids for harvesting mistletoe or self-defense.",
  "Lanza delgada y aerodinámica diseñada para alcanzar objetivos a distancia antes del combate cuerpo a cuerpo.": "A slender, aerodynamic spear designed to strike targets from afar before closing to melee.",
  "Una de las armas más antiguas del mundo: letal con una mano junto a un escudo o a dos manos.": "One of the oldest weapons in the world: lethal wielded in one hand with a shield or in two hands.",
  "Herramienta de herrería forjada con precisión para golpear cráneos o arrojarse a la cabeza del enemigo.": "A precision-forged smithing hammer balanced for cracking skulls or hurling at an enemy's head.",
  "Cabeza de hierro o bronce estriada montada sobre un asta reforzada, el arma predilecta de clérigos.": "A flanged iron or bronze head mounted on a reinforced haft, the favored weapon of clerics.",
  "Arco compacto y manejable para cacería o escaramuzas en bosques y pasillos estrechos.": "A compact, maneuverable bow suited for hunting or skirmishing in forests and narrow corridors.",
  "Dispositivo mecánico de disparo certero impulsado por un resorte de acero con virotes punzantes.": "A mechanical ranged weapon powered by a steel prod that fires piercing bolts with pinpoint accuracy.",
  "Proyectil arrojadizo con aletas plumadas que aprovecha la agilidad del lanzador.": "A fletched throwing projectile that takes advantage of the thrower's agility or strength.",
  "Tira de cuero sencilla que lanza balines de plomo o guijarros a gran velocidad.": "A simple leather strap that hurls lead bullets or smooth stones at high velocity.",
  "Asta larga rematada por una cabeza de hacha con púa superior y gancho. Mantiene a los enemigos a raya.": "A long polearm topped with an axe blade, a top spike, and a rear hook. Keeps enemies at bay.",
  "Espada curva oriental de un solo filo, rápida y letal para combate con dos armas y cortes fluidos.": "A curved single-edged blade, swift and lethal for two-weapon fighting and fluid slashes.",
  "Arma noble y ligera de estocada precisa, favorita de pícaros y duelistas acrobáticos.": "A noble, lightweight thrusting sword of pinpoint precision, favored by rogues and acrobatic duelists.",
  "El icono por excelencia de los caballeros: hoja recta de doble filo, utilizable a una mano (1d8) o dos manos (1d10).": "The quintessential knightly weapon: a straight double-edged blade usable in one hand (1d8) or two hands (1d10).",
  "Una colosal espada de mando y guerra de dos manos; inflige 2d6 de daño cortante masivo y constante.": "A colossal two-handed sword of war; deals massive, reliable 2d6 slashing damage.",
  "Espada esbelta y flexible con guarnición de cazoleta. El arma sutil más potente (1d8) para luchadores de Destreza.": "A slender, flexible blade with a cup-hilt guard. The most damaging finesse weapon (1d8) for Dexterity fighters.",
  "Una tremenda hacha bárbara de doble filo capaz de hendir escudos y decapitar bestias de un solo tajo (1d12).": "A tremendous double-bitted barbarian axe capable of cleaving shields and decapitating beasts in a single swing (1d12).",
  "Pesado martillo de guerra a dos manos diseñado para machacar armaduras completas de placas como latas.": "A heavy two-handed warhammer designed to crush full plate armor like tin cans.",
  "Hoja curvada similar a una espada montada sobre un asta larga de fresno para golpear a 10 pies de distancia.": "A curved sword-like blade mounted on a long ash pole to strike foes 10 feet away.",
  "Arma tradicional de la infantería enana; versátil, sólida y destructiva con una o dos manos.": "The traditional weapon of dwarven infantry; versatile, solid, and destructive in one or two hands.",
  "Pesada lanza cónica de justa diseñada para cargas montadas arrolladoras.": "A heavy tapered jousting lance designed for devastating mounted charges.",
  "Tira de cuero trenzado que permite atacar a 10 pies de distancia empleando Destreza.": "A braided leather lash that allows Dexterity-based attacks from 10 feet away.",
  "Bola de hierro erizada de púas cónicas que desgarra cotas de malla y carne con fuerza bruta.": "A spiked iron ball mounted on a shaft that tears through chain mail and flesh with brute force.",
  "Martillo marcial con cabeza de impacto y púa perforante posterior, eficaz contra cualquier armadura.": "A martial hammer with a striking head and a rear armor-piercing spike, effective against any armor.",
  "Bola con púas unida por una cadena de eslabones al mango para envolver escudos enemigos.": "A spiked ball linked by a steel chain to a haft, designed to wrap around enemy shields.",
  "Lanza muy larga de infantería pesada para frenar en seco cargas de caballería o monstruos.": "An extra-long heavy infantry spear designed to stop cavalry or monster charges dead in their tracks.",
  "Pico militar puntiagudo templado para penetrar y abrir corazas de hierro y acero.": "A pointed military pick tempered to punch through iron and steel breastplates.",
  "Lanza de tres puntas de gladiadores o pueblos marinos con púas diseñadas para trabar y ensartar.": "A three-pronged spear favored by gladiators and seafaring folk, barbed to trap and impale.",
  "Arco de tejo de gran envergadura capaz de abatir objetivos a más de 180 metros con flechas pesadas.": "A tall yew bow capable of bringing down targets over 600 feet away with heavy arrows.",
  "Imponente mecanismo de asedio personal con arco de acero templado de impacto brutal (1d10).": "An imposing personal siege weapon with a tempered steel prod and brutal impact (1d10).",
  "Ballesta compacta de una sola mano, favorita de espías drow y tiradores de escaramuza.": "A compact one-handed crossbow, favored by drow spies and skirmishers.",
  "Tubo de caña hueco para disparar dardos diminutos impregnados de veneno con total silencio.": "A hollow reed tube used to fire tiny poison-tipped needles in complete silence.",
  "Red con plomos en los bordes para inmovilizar a un adversario en la arena o campo de batalla.": "A weighted mesh net used to restrain an adversary in the arena or on the battlefield.",
  "Arma tradicional de los elfos Valenar de Eberron. Ambas puntas del mango poseen hojas curvas afiladas.": "The traditional weapon of the Valenar elves of Eberron. Both ends of the haft bear curved, razor-sharp blades.",
  "Asta clásica de los kenders de Dragonlance con una horquilla de honda en un extremo y una punta metálica en el otro.": "The classic staff-sling of Dragonlance kender, with a sling fork at one end and a metal spike at the other.",
  "Lanza corta tradicional de los guerreros de Chult con una hoja ancha de acero de 18 pulgadas montada en un mango de madera dura.": "The traditional short spear of Chultan warriors, featuring an 18-inch broad steel blade mounted on a hardwood shaft.",
  "Arma curvada de madera aerodinámica. En manos entrenadas regresa trazando un arco perfecto si no impacta al objetivo.": "An aerodynamic curved wooden throwing weapon. In trained hands, it returns in a graceful arc if it misses its target.",
  "Espada de mano y media del Manual del Armero. Ofrece la contundencia de un espadón pudiendo empuñarse a una mano con suficiente fuerza.": "A hand-and-a-half bastard sword from the Armorer's Handbook. Offers the striking power of a greatsword while usable in one hand with sufficient strength.",
  "Espada curva pesada de un solo filo del Manual del Armero. Su centro de gravedad adelantado descarga tajos devastadores con fluidez marcial.": "A heavy single-edged curved sword from the Armorer's Handbook. Its forward-weighted blade delivers devastating chops with martial fluidity.",
  "Daga con cruceta reforzada y gavilanes curvados diseñada para desviar estocadas enemigas en duelos a dos manos.": "A parrying dagger with a reinforced crossguard and curved quillions designed to deflect enemy thrusts in two-weapon duels.",
  "Hoja curvada cóncava sobre asta reforzada. Su diseño en gancho permite enganchar extremidades y derribar enemigos al suelo.": "A concave curved blade mounted on a reinforced pole. Its hooked edge can snag limbs and trip enemies prone.",
  "Lanza militar pesada de infantería de línea del Manual del Armero con punta acorazada para frenar cargas enemigas.": "A heavy line-infantry spear from the Armorer's Handbook with a reinforced armor-piercing head built to halt enemy charges.",
  "Daga de empuje con empuñadura en forma de H transversal. Transmite todo el peso del puñetazo en una perforación brutal.": "A punch dagger with a transverse H-shaped grip. Channels the full weight of a punch into a brutal piercing strike.",
  "Arma de fuego renacentista del Manual del Dungeon Master. Dispara balas de plomo con pólvora negra a corta distancia con tremenda potencia.": "A Renaissance firearm from the Dungeon Master's Guide. Fires lead balls with black powder at close range with tremendous stopping power.",
  "Cañón largo estriado del Manual del Dungeon Master que dispara proyectiles de plomo con alcance y perforación demoledores.": "A long-barreled firearm from the Dungeon Master's Guide that fires lead bullets with devastating range and armor penetration.",
  "Capas de tela y lino acolchado; económica pero ruidosa al moverse.": "Quilted layers of cloth and batting; inexpensive, but warm and noisy when moving.",
  "Cuero curtido que protege sin entorpecer el sigilo. CA: 11 + Des.": "Stiffened, cured leather that protects vital areas without hindering stealth. AC: 11 + DEX.",
  "La mejor armadura ligera: cuero flexible reforzado con remaches de acero. CA: 12 + Des.": "The finest light armor: supple leather reinforced with close-set steel rivets. AC: 12 + DEX.",
  "Capas gruesas de piel y pelaje de oso o lobo. CA: 12 + Des (máx 2).": "Thick layers of crude furs and pelts from bears or wolves. AC: 12 + DEX (max 2).",
  "Cota de anillas entretejida que se viste discretamente bajo ropas. CA: 13 + Des (máx 2).": "Interlocking metal rings worn discreetly between layers of clothing or leather. AC: 13 + DEX (max 2).",
  "Escamas de metal superpuestas como las de un dragón o pez. CA: 14 + Des (máx 2).": "Overlapping metal scales resembling those of a dragon or fish. AC: 14 + DEX (max 2).",
  "Placa de acero sobre el pecho y espalda que ofrece sólida protección sin ruido. CA: 14 + Des (máx 2).": "Fitted steel chest and back plates that offer solid protection without stealth penalties. AC: 14 + DEX (max 2).",
  "La armadura media más protectora del juego. Placas de metal en casi todo el cuerpo. CA: 15 + Des (máx 2).": "The most protective medium armor in the game, featuring shaped metal plates covering most of the body. AC: 15 + DEX (max 2).",
  "Armadura pesada tradicional de anillas de acero entrelazadas. Requiere Fza 13. CA fija: 16.": "Traditional heavy armor made of interlocking steel rings over a padded tunic. Requires STR 13. Fixed AC: 16.",
  "Tiras verticales de acero remachadas sobre cuero con cota interior. Requiere Fza 15. CA fija: 17.": "Narrow vertical strips of steel riveted to a leather backing over chain mail. Requires STR 15. Fixed AC: 17.",
  "La cúspide de la protección medieval: placas de acero anatómicas articuladas. Requiere Fza 15. CA fija: 18.": "The pinnacle of medieval protection: interlocking, anatomically shaped steel plates. Requires STR 15. Fixed AC: 18.",
  "Escudo de madera o acero empuñado en una mano. Otorga un bono de +2 a la CA mientras esté equipado.": "A wooden or steel shield carried in one hand. Grants a +2 bonus to AC while wielded.",
  "Armadura media enana de cuero y placas erizadas de púas de acero (Costa de la Espada). Permite realizar ataques cuerpo a cuerpo con púas que infligen 1d4 de daño perforante.": "Dwarven medium armor made of leather and plates bristling with steel spikes (Sword Coast Adventurer's Guide). Allows bonus-action melee spike attacks dealing 1d4 piercing damage.",
  "Gran escudo rectangular de infantería pesada del Manual del Armero. Otorga +3 a la CA pero requiere Fuerza 15 e impone desventaja en pruebas de Sigilo.": "A massive rectangular heavy-infantry pavise from the Armorer's Handbook. Grants +3 to AC but requires Strength 15 and imposes disadvantage on Stealth checks.",
  "Escudo pequeño y ágil de puño o antebrazo del Manual del Armero. Otorga +1 a la CA dejando la mano libre para sostener objetos pequeños o realizar componentes somáticos de conjuros.": "A small, agile fist or forearm buckler from the Armorer's Handbook. Grants +1 to AC while leaving the hand free to hold light items or perform somatic spell components.",
  "Tira en esta tabla al comienzo de cada uno de tus turnos durante el próximo minuto, ignorando este resultado en tiradas posteriores.": "Roll on this table at the start of each of your turns for the next minute, ignoring this result on subsequent rolls.",
  "Visión de lo Invisible": "See Invisibility",
  "Durante el próximo minuto, puedes ver cualquier criatura invisible si tienes una línea de visión sin obstrucciones hacia ella.": "For the next minute, you can see any invisible creature if you have line of sight to it.",
  "Aparición de Modron": "Modron Summons",
  "Un modron elegido y controlado por el DM aparece en un espacio desocupado a 5 pies o menos de ti, y desaparece 1 minuto después.": "A modron chosen and controlled by the DM appears in an unoccupied space within 5 feet of you, then disappears 1 minute later.",
  "Bola de Fuego Involuntaria": "Accidental Fireball",
  "Lanzas Bola de Fuego (Fireball) como un conjuro de 3.er nivel centrado en ti mismo (8d6 de daño de fuego, salvación de Destreza CD 8 + mod CAR + bono competencia para mitad).": "You cast Fireball as a 3rd-level spell centered on yourself (8d6 fire damage, DEX save DC 8 + CHA mod + proficiency bonus for half damage).",
  "Proyectil Mágico de 5.° Nivel": "5th-Level Magic Missile",
  "Lanzas Proyectil Mágico (Magic Missile) como un conjuro de 5.° nivel (disparas 7 proyectiles que infligen 1d4 + 1 de daño de fuerza cada uno).": "You cast Magic Missile as a 5th-level spell (firing 7 glowing darts that deal 1d4 + 1 force damage each).",
  "Alteración de Estatura": "Height Shift",
  "Tira 1d10. Tu altura cambia en un número de pulgadas igual al resultado. Si la tirada es impar, encoges; si es par, creces.": "Roll a d10. Your height changes by a number of inches equal to the roll. If the roll is odd, you shrink. If the roll is even, you grow.",
  "Confusión Espontánea": "Spontaneous Confusion",
  "Lanzas Confusión (Confusion) centrado en ti mismo afectando a todas las criaturas en un radio de 10 pies.": "You cast Confusion centered on yourself, affecting all creatures within a 10-foot radius.",
  "Regeneración Rápida": "Rapid Regeneration",
  "Durante el próximo minuto, recuperas 5 puntos de golpe al comienzo de cada uno de tus turnos.": "For the next minute, you regain 5 hit points at the start of each of your turns.",
  "Barba de Plumas": "Feather Beard",
  "Te crece una larga barba hecha de plumas que permanece hasta que estornudas, momento en el cual las plumas explotan cómicamente de tu cara.": "You grow a long beard made of feathers that remains until you sneeze, at which point the feathers explode out from your face.",
  "Lanzas Grasa (Grease) centrado en ti mismo (área de 10 pies de lado se vuelve resbaladiza).": "You cast Grease centered on yourself (a 10-foot square area becomes slick with grease).",
  "Vulnerabilidad Mágica Enemiga": "Enemy Magical Vulnerability",
  "Las criaturas tienen desventaja en la tirada de salvación contra el próximo conjuro que lances en el próximo minuto que requiera una salvación.": "Creatures have disadvantage on saving throws against the next spell you cast in the next minute that involves a saving throw.",
  "Pigmentación Azul": "Blue Skin Pigmentation",
  "Tu piel adquiere un vibrante tono azulado. Un conjuro de Restablecimiento Menor (Lesser Restoration) puede devolverte tu color de piel normal.": "Your skin turns a vibrant shade of blue. A Remove Curse or Lesser Restoration spell can end this effect and restore your normal skin color.",
  "Un ojo aparece en tu frente durante el próximo minuto. Tienes ventaja en pruebas de Sabiduría (Percepción) basadas en la vista.": "An eye appears on your forehead for the next minute. During that time, you have advantage on Wisdom (Perception) checks that rely on sight.",
  "Aceleración Mágica": "Magical Acceleration",
  "Durante el próximo minuto, todos tus conjuros con un tiempo de lanzamiento de 1 acción pueden lanzarse como una acción adicional.": "For the next minute, all your spells with a casting time of 1 action have a casting time of 1 bonus action.",
  "Te teletransportas de inmediato hasta 60 pies a un espacio desocupado que puedas ver.": "You teleport up to 60 feet to an unoccupied space of your choice that you can see.",
  "Eres transportado al Plano Astral hasta el final de tu próximo turno, momento en el que regresas al espacio que ocupabas o al más cercano desocupado.": "You are transported to the Astral Plane until the end of your next turn, after which time you return to the space you previously occupied or the nearest unoccupied space if that space is occupied.",
  "Potencia Dañina Máxima": "Maximum Spell Damage",
  "Maximiza el daño del próximo conjuro de daño que lances en el próximo minuto (inflige el daño más alto posible sin tirar dados).": "Maximize the damage of the next damaging spell you cast within the next minute (it deals the highest possible damage without rolling dice).",
  "Fluctuación Temporal de Edad": "Temporal Age Fluctuation",
  "Tira 1d10. Tu edad cambia en ese número de años. Si la tirada es impar, te vuelves más joven (mínimo 1 año). Si es par, envejeces.": "Roll a d10. Your age changes by a number of years equal to the roll. If the roll is odd, you get younger (minimum 1 year old). If the roll is even, you get older.",
  "1d6 palomas o mariposas ilusorias aparecen y revolotean en el área a 10 pies de ti durante 1 minuto.": "1d6 illusory doves or butterflies appear and flutter in the air within 10 feet of you for 1 minute.",
  "Recuperas 2d10 puntos de golpe de forma instantánea.": "You regain 2d10 hit points immediately.",
  "Planta en Maceta": "Potted Plant",
  "Te conviertes en una planta en maceta hasta el inicio de tu próximo turno. Mientras eres planta, estás incapacitado y tienes vulnerabilidad a todo el daño. Si caes a 0 PG, la maceta se rompe y recuperas tu forma original.": "You turn into a potted plant until the start of your next turn. While a plant, you are incapacitated and have vulnerability to all damage. If you drop to 0 hit points, your pot breaks, and your form reverts.",
  "Paso Etéreo Constante": "Constant Ethereal Step",
  "Durante el próximo minuto, puedes teletransportarte hasta 20 pies como una acción adicional en cada uno de tus turnos.": "For the next minute, you can teleport up to 20 feet as a bonus action on each of your turns.",
  "Levitación Forzada": "Forced Levitation",
  "Aparición de Unicornio": "Unicorn Appearance",
  "Un unicornio controlado por el DM aparece en un espacio a 5 pies de ti y desaparece 1 minuto después.": "A unicorn controlled by the DM appears in a space within 5 feet of you, then disappears 1 minute later.",
  "No puedes hablar durante el próximo minuto. Cuando intentas hablar, brotan burbujas rosadas de tu boca.": "You can't speak for the next minute. Whenever you try, pink bubbles float out of your mouth.",
  "Escudo Espectral Defensivo": "Defensive Spectral Shield",
  "Un escudo espectral flota a tu alrededor durante 1 minuto, otorgándote un bonificador de +2 a la CA e inmunidad a Proyectil Mágico.": "A spectral shield hovers near you for the next minute, granting you a +2 bonus to AC and immunity to Magic Missile.",
  "Sobriedad Mágica Inmune": "Magical Sobriety",
  "Eres inmune a quedar intoxicado por el alcohol durante los próximos 5d6 días.": "You are immune to being intoxicated by alcohol for the next 5d6 days.",
  "Caída de Cabello": "Sudden Hair Loss",
  "Tu cabello se cae por completo, pero vuelve a crecer con normalidad dentro de las próximas 24 horas.": "Your hair falls out but grows back within 24 hours.",
  "Toque Ígneo Incontrolable": "Uncontrollable Fiery Touch",
  "Durante el próximo minuto, cualquier objeto inflamable que toques que no esté siendo llevado o empuñado por otra criatura estalla en llamas.": "For the next minute, any flammable object you touch that isn't being worn or carried by another creature bursts into flame.",
  "Recuperación de Ranura de Conjuro": "Spell Slot Recovery",
  "Recuperas tu ranura de conjuro gastada de menor nivel.": "You regain your lowest-level expended spell slot.",
  "Durante el próximo minuto, debes gritar con toda tu fuerza cada vez que hables.": "For the next minute, you must shout when you speak.",
  "Lanzas Niebla Nubosa (Fog Cloud) centrado en ti mismo (esfera de 20 pies de radio de visibilidad nula).": "You cast Fog Cloud centered on yourself (a 20-foot-radius sphere of heavily obscured fog).",
  "Descarga Eléctrica Triple": "Triple Lightning Discharge",
  "Hasta 3 criaturas de tu elección a 30 pies o menos de ti sufren 4d10 de daño de relámpago cada una.": "Up to three creatures you choose within 30 feet of you take 4d10 lightning damage.",
  "Terror Súbito": "Sudden Terror",
  "Quedas asustado (condición Asustado) respecto a la criatura más cercana a ti hasta el final de tu próximo turno.": "You are frightened by the nearest creature until the end of your next turn.",
  "Cada criatura a 30 pies o menos de ti se vuelve invisible durante 1 minuto. La invisibilidad termina en una criatura si ataca o lanza un conjuro.": "Each creature within 30 feet of you becomes invisible for the next minute. The invisibility ends on a creature when it attacks or casts a spell.",
  "Obtienes resistencia a todo el daño durante el próximo minuto.": "You gain resistance to all damage for the next minute.",
  "Una criatura aleatoria a 60 pies o menos de ti queda envenenada durante 1d4 horas.": "A random creature within 60 feet of you becomes poisoned for 1d4 hours.",
  "Emanas luz tenue en un radio de 30 pies durante el próximo minuto. Cualquier criatura que termine su turno a 5 pies de ti queda cegada hasta el final de su próximo turno.": "You glow with bright light in a 30-foot radius for the next minute. Any creature that ends its turn within 5 feet of you is blinded until the end of its next turn.",
  "Lanzas Polimorfar (Polymorph) sobre ti mismo. Si fallas la salvación de Sabiduría, te conviertes en una oveja durante la duración del conjuro (1 hora).": "You cast Polymorph on yourself. If you fail the saving throw, you turn into a sheep for the spell's duration (1 hour).",
  "Aura de Pétalos Ilusorios": "Aura of Illusory Petals",
  "Mariposas ilusorias y pétalos de flores revolotean a tu alrededor a 10 pies durante el próximo minuto.": "Illusory butterflies and flower petals flutter in the air within 10 feet of you for the next minute.",
  "Impulso de Acción Adicional": "Bonus Action Surge",
  "Puedes realizar una acción adicional inmediatamente en este turno.": "You can take one additional action immediately.",
  "Drenaje Necrótico Vital": "Vital Necrotic Drain",
  "Cada criatura a 30 pies o menos de ti sufre 1d10 de daño necrótico. Recuperas puntos de golpe iguales a la suma de todo el daño infligido.": "Each creature within 30 feet of you takes 1d10 necrotic damage. You regain hit points equal to the sum of the necrotic damage dealt.",
  "Lanzas Volar (Fly) sobre una criatura elegida al azar a 60 pies o menos de ti.": "You cast Fly on a random creature within 60 feet of you.",
  "Te vuelves invisible durante el próximo minuto y las criaturas no pueden oírte. La invisibilidad termina prematuramente si atacas o lanzas un conjuro.": "You become invisible for the next minute. During that time, other creatures can't hear you. The invisibility ends if you attack or cast a spell.",
  "Seguro de Reencarnación": "Reincarnation Insurance",
  "Si mueres durante el próximo minuto, regresas inmediatamente a la vida como si hubieras recibido el conjuro Reencarnación (Reincarnate).": "If you die within the next minute, you immediately come back to life as if by the Reincarnate spell.",
  "Agrandamiento Físico": "Physical Enlargement",
  "Tu tamaño aumenta en una categoría de tamaño durante el próximo minuto (como por el conjuro Agrandar/Reducir, ganas ventaja en pruebas/salvaciones de Fuerza y +1d4 de daño con armas).": "Your size increases by one size category for the next minute (as if by the Enlarge/Reduce spell, granting advantage on Strength checks and Strength saving throws and +1d4 weapon damage).",
  "Fragilidad Perforante": "Piercing Fragility",
  "Tú y todas las criaturas a 30 pies o menos de ti adquieren vulnerabilidad al daño perforante durante el próximo minuto.": "You and all creatures within 30 feet of you gain vulnerability to piercing damage for the next minute.",
  "Música Celestial y Etérea": "Faint Ethereal Music",
  "Estás rodeado de una tenue y hermosa música celestial que sólo tú y quienes estén a 10 pies pueden escuchar durante el próximo minuto.": "You are surrounded by faint, ethereal music for the next minute, audible to you and creatures within 10 feet of you.",
  "Plenitud Arcana (Todos los PH)": "Arcane Fullness (All Sorcery Points)",
  "¡El flujo cósmico te inunda! Recuperas de inmediato todos tus Puntos de Hechicería gastados.": "Cosmic energy floods through you! You regain all expended Sorcery Points immediately.",
  "Cuando lanzas un conjuro que requiera tirada de salvación, puedes proteger a un número de criaturas de tu elección hasta tu modificador de Carisma. Dichas criaturas tienen éxito automático en la tirada de salvación.": "When you cast a spell that forces other creatures to make a saving throw, you can protect some of those creatures from the spell's full force (up to your Charisma modifier). A chosen creature automatically succeeds on its saving throw against the spell.",
  "Cuando lanzas un conjuro con alcance de 5 pies o más, puedes duplicar su alcance. Cuando lanzas un conjuro con alcance de toque, puedes hacer que tenga un alcance de 30 pies.": "When you cast a spell that has a range of 5 feet or greater, you can double the range of the spell. When you cast a spell that has a range of touch, you can make the range of the spell 30 feet.",
  "Cuando tires el daño de un conjuro, puedes relanzar un número de dados de daño hasta tu modificador de Carisma (mínimo 1). Debes usar las nuevas tiradas. Se puede usar incluso si ya aplicaste otra opción de metamagia.": "When you roll damage for a spell, you can reroll a number of the damage dice up to your Charisma modifier (minimum of one). You must use the new rolls. You can use Empowered Spell even if you have already used a different Metamagic option during the casting of the spell.",
  "Cuando lanzas un conjuro con duración de 1 minuto o superior, puedes duplicar su duración hasta un máximo de 24 horas.": "When you cast a spell that has a duration of 1 minute or longer, you can double its duration, to a maximum duration of 24 hours.",
  "Cuando lanzas un conjuro que requiere tirada de salvación, puedes hacer que un objetivo sufra desventaja en su primera tirada de salvación contra el conjuro.": "When you cast a spell that forces a creature to make a saving throw to resist its effects, you can spend 3 Sorcery Points to give one target of the spell disadvantage on its first saving throw made against the spell.",
  "Cuando lanzas un conjuro cuyo tiempo de lanzamiento sea 1 acción, puedes cambiarlo a 1 acción adicional para ese lanzamiento.": "When you cast a spell that has a casting time of 1 action, you can spend 2 Sorcery Points to change the casting time to 1 bonus action for this casting.",
  "Puedes lanzar un conjuro sin componentes verbales ni somáticos, evitando que sea detectado o interrumpido por Contramagia.": "When you cast a spell, you can spend 1 Sorcery Point to cast it without any somatic or verbal components, preventing it from being detected or interrupted by Counterspell.",
  "Cuando lanzas un conjuro que solo tiene como objetivo a una criatura y no tiene alcance personal, puedes hacer que tenga como objetivo a una segunda criatura dentro de su alcance gastando tantos puntos como el nivel del conjuro (1 punto si es un truco).": "When you cast a spell that targets only one creature and doesn't have a range of self, you can spend a number of Sorcery Points equal to the spell's level (1 Sorcery Point if the spell is a cantrip) to target a second creature in range with the same spell.",
  "Cuando lanzas un conjuro que inflige daño de ácido, frío, fuego, relámpago, veneno o trueno, puedes cambiar el tipo de daño a cualquiera de los otros elementos mencionados.": "When you cast a spell that deals a type of damage from the following list, you can spend 1 Sorcery Point to change that damage type to one of the other listed types: acid, cold, fire, lightning, poison, thunder.",
  "Si fallas una tirada de ataque con un conjuro, puedes relanzar el d20. Debes usar el nuevo resultado.": "If you make an attack roll for a spell and miss, you can spend 2 Sorcery Points to reroll the d20, and you must use the new roll.",
  "Cuando lanzas Descarga Sobrenatural (Eldritch Blast), sumas tu modificador de Carisma al daño que inflige cada rayo que impacte.": "When you cast Eldritch Blast, add your Charisma modifier to the damage it deals on a hit.",
  "Cuando impactas a una criatura con Descarga Sobrenatural, puedes empujarla hasta 10 pies de distancia en línea recta lejos de ti.": "When you hit a creature with Eldritch Blast, you can push the creature up to 10 feet away from you in a straight line.",
  "Puedes ver con total claridad tanto en la oscuridad normal como en la oscuridad mágica hasta una distancia de 120 pies.": "You can see normally in darkness, both magical and nonmagical, to a distance of 120 feet.",
  "Puedes lanzar Armadura de Mago sobre ti mismo a voluntad, sin gastar ranuras de conjuro ni componentes materiales.": "You can cast Mage Armor on yourself at will, without expending a spell slot or material components.",
  "Puedes lanzar Falsa Vida sobre ti mismo a voluntad como conjuro de 1.er nivel (obteniendo 1d4+4 puntos de golpe temporales).": "You can cast False Life on yourself at will as a 1st-level spell, without expending a spell slot or material components (gaining 1d4 + 4 temporary hit points).",
  "Puedes leer y comprender cualquier sistema de escritura y texto en el multiverso.": "You can read all writing.",
  "Puedes lanzar Hablar con los Animales a voluntad, sin gastar ranuras de conjuro.": "You can cast Speak with Animals at will, without expending a spell slot.",
  "Ganas competencia en las habilidades de Engaño y Persuasión.": "You gain proficiency in the Deception and Persuasion skills.",
  "Tu arma de pacto puede ser un arco o ballesta, gana un bonificador de +1 al ataque y daño, y sirve como foco de lanzamiento para tus conjuros.": "You can use any weapon you summon with your Pact of the Blade feature as a spellcasting focus for your warlock spells, it gains a +1 bonus to its attack and damage rolls, and the weapon can be a shortbow, longbow, light crossbow, or heavy crossbow.",
  "Puedes inscribir y lanzar cualquier conjuro con la etiqueta ritual de cualquier lista de clase en tu Libro de las Sombras.": "You can inscribe ritual spells from any class's spell list into your Book of Shadows and cast them as rituals.",
  "Puedes comunicarte telepáticamente con tu familiar a cualquier distancia y percibir a través de sus sentidos.": "You can communicate telepathically with your familiar and perceive through your familiar's senses as long as you are on the same plane of existence.",
  "Puedes atacar con tu arma de pacto dos veces en lugar de una cuando realizas la acción de Atacar en tu turno.": "You can attack with your pact weapon twice, instead of once, whenever you take the Attack action on your turn.",
  "Puedes lanzar Polimorfia una vez usando una ranura de conjuro de brujo. Recuperas este uso tras un descanso largo.": "You can cast Polymorph once using a warlock spell slot. You can't do so again until you finish a long rest.",
  "Cuando lanzas Descarga Sobrenatural, su alcance aumenta a 300 pies.": "When you cast Eldritch Blast, its range is 300 feet.",
  "Una vez por turno al impactar a una criatura con tu arma de pacto, puedes gastar una ranura de conjuro de brujo para infligir 1d8 de daño de fuerza adicional más 1d8 por nivel de ranura, y puedes derribar a la criatura si es de tamaño Enorme o menor.": "Once per turn when you hit a creature with your pact weapon, you can expend a warlock spell slot to deal an extra 1d8 force damage to the target, plus another 1d8 per level of the spell slot, and you can knock the target prone if it is Huge or smaller.",
  "Como reacción al recibir daño, te encierras en hielo ganando 10 puntos de golpe temporales por nivel de brujo que absorben el daño desencadenante. Se recarga en descanso corto.": "As a reaction when you take damage, you can entomb yourself in ice, gaining 10 temporary hit points per warlock level, which take as much of the triggering damage as possible. Recharges on a short or long rest.",
  "Puedes ver la forma real de cualquier metamorfo o criatura oculta por magia de ilusión o transmutación a 30 pies de ti.": "You can see the true form of any shapechanger or creature concealed by illusion or transmutation magic while the creature is within 30 feet of you and within line of sight.",
  "Puedes lanzar Retener Monstruo a voluntad sin gastar ranuras de conjuro contra un celestial, infernal o elemental. Una criatura específica solo puede ser afectada una vez por descanso largo.": "You can cast Hold Monster at will—targeting a celestial, fiend, or elemental—without expending a spell slot or material components. You must finish a long rest before you can use this invocation on the same creature again.",
  "Quien porte tu talismán añade 1d4 a cualquier tirada de salvación que falle.": "While someone is wearing your talisman, they can roll a d4 and add the number rolled to any saving throw they fail.",
  "Puedes crear un arma cuerpo a cuerpo mágica en tu mano vacía como acción. Eres competente con ella mientras la empuñes y cuenta como mágica.": "You can use your action to create a pact weapon in your empty hand. You are proficient with it while you wield it, and this weapon counts as magical for the purpose of overcoming resistance and immunity.",
  "Tu patrón te entrega el Libro de las Sombras. Elige 3 trucos de cualquier lista de conjuros de clase: cuentan como trucos de brujo para ti y no cuentan contra tu límite.": "Your patron gives you a grimoire called a Book of Shadows. When you gain this feature, choose three cantrips from any class's spell list; while the book is on your person, you can cast those cantrips at will, and they don't count against your number of cantrips known.",
  "Aprendes el conjuro Encontrar Familiar como ritual. Puedes elegir formas sobrenaturales especiales para tu familiar: Diablillo, Quasit, Pseudodragón o Duendecillo.": "You learn the Find Familiar spell and can cast it as a ritual. When you cast the spell, you can choose one of the normal forms for your familiar or one of the following special forms: Imp, Pseudodragon, Quasit, or Sprite.",
  "Tu patrón te entrega un amuleto especial. Quien lo porte puede sumar 1d4 a una prueba de característica fallida tantas veces al día como tu bonificador de competencia.": "Your patron gives you a special amulet, a Talisman. When the wearer fails an ability check, they can add a d4 to the roll, potentially turning the roll into a success, a number of times per long rest equal to your proficiency bonus.",
  "Suma el dado de superioridad al daño; si el objetivo falla salvación de Fuerza, cae derribado al suelo.": "Add the superiority die to the attack's damage roll, and if the target is Large or smaller, it must succeed on a Strength saving throw or be knocked prone.",
  "Reacción cuando fallen un ataque cuerpo a cuerpo contra ti para contratacar sumando el dado de superioridad al daño.": "When a creature misses you with a melee attack, you can use your reaction and expend one superiority die to make a melee weapon attack against the creature, adding the superiority die to the attack's damage roll on a hit.",
  "Reacción cuando recibas daño cuerpo a cuerpo para reducir el daño en 1 dado de superioridad + modificador de Destreza.": "When another creature damages you with a melee attack, you can use your reaction and expend one superiority die to reduce the damage by the number you roll on your superiority die + your Dexterity modifier.",
  "Suma el dado de superioridad a tu tirada de ataque para asegurar el impacto.": "When you make a weapon attack roll against a creature, you can expend one superiority die to add it to the roll.",
  "Suma el dado al daño y asusta al objetivo hasta el final de tu próximo turno si falla salvación de Sabiduría.": "Add the superiority die to the attack's damage roll, and the target must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn.",
  "Suma el dado al daño y obliga a soltar un objeto sostenido si falla salvación de Fuerza.": "Add the superiority die to the attack's damage roll, and the target must succeed on a Strength saving throw or drop one object of your choice that it's holding.",
  "Suma el dado al daño y empuja al objetivo hasta 15 pies lejos de ti si falla salvación de Fuerza.": "Add the superiority die to the attack's damage roll, and if the target is Large or smaller, it must succeed on a Strength saving throw or be pushed up to 15 feet away from you.",
  "Suma el dado al daño y permite a un aliado moverse la mitad de su velocidad sin provocar ataques de oportunidad.": "Add the superiority die to the attack's damage roll, and choose a friendly creature who can see or hear you; that creature can use its reaction to move up to half its speed without provoking opportunity attacks from the target of your attack.",
  "Acción adicional para ganar ventaja en tu siguiente tirada de ataque y sumar el dado de superioridad al daño.": "You can expend one superiority die and use a bonus action on your turn to feint, gaining advantage on your next attack roll against a chosen creature within 5 feet this turn and adding the superiority die to the attack's damage roll on a hit.",
  "Gasta el dado de superioridad mientras te mueves para sumar el resultado a tu CA hasta detenerte.": "When you move, you can expend one superiority die, rolling the die and adding the number rolled to your AC until you stop moving.",
  "Suma el dado al daño y da ventaja al siguiente ataque de un aliado contra ese enemigo.": "Add the superiority die to the attack's damage roll, and the next attack roll against the target by an attacker other than you has advantage if the attack is made before the start of your next turn.",
  "Si impactas, inflige el resultado del dado de superioridad a una criatura adyacente adicional.": "When you hit a creature with a melee weapon attack, you can expend one superiority die to deal damage equal to the number rolled to another creature within 5 feet of the original target and within your reach.",
  "Puedes usar tu acción para controlar brevemente las fuerzas elementales cercanas, creando efectos inofensivos: encender/apagar una pequeña llama, enfriar/calentar 1 libra de material, esculpir 1 pie cúbico de tierra/humo o crear una suave brisa.": "You can use your action to briefly control elemental forces nearby, causing a harmless sensory effect: ignite or snuff out a small flame, chill or warm up to 1 pound of nonliving material, cause earth, fire, water, or mist that can fit within a 1-foot cube to shape itself into a crude form, or create a harmless gust of wind.",
  "Cuando realizas la acción de Atacar en tu turno, puedes gastar 1 punto de Ki para hacer que zarcillos de llamas broten de tus puños y pies. Tu alcance desarmado aumenta en 10 pies para ese turno y tus impactos infligen daño de fuego en lugar de contundente. Además, si impactas, puedes gastar 1 Ki extra para infligir 1d10 de daño de fuego adicional.": "When you use the Attack action on your turn, you can spend 1 Ki point to cause tendrils of flame to stretch out from your fists and feet. Your reach with your unarmed strikes increases by 10 feet for that action, as well as the rest of the turn, and a hit with such an attack deals fire damage instead of bludgeoning damage. In addition, if you spend 1 Ki point when the attack hits, it also deals an extra 1d10 fire damage.",
  "Como acción, gastas 2 puntos de Ki para crear un látigo de agua que azota a una criatura a 30 pies o menos que puedas ver. La criatura debe hacer una salvación de Destreza. Si falla, sufre 3d10 de daño contundente (más 1d10 por cada Ki adicional gastado) y puedes derribarla o arrastrarla hasta 25 pies hacia ti. Si tiene éxito, sufre la mitad de daño y no es movida.": "As an action, you can spend 2 Ki points to create a whip of water that shoves and pulls a creature you can see within 30 feet of you. The creature must make a Dexterity saving throw. On a failed save, the creature takes 3d10 bludgeoning damage, plus an extra 1d10 bludgeoning damage for each additional Ki point you spend, and you can either knock it prone or pull it up to 25 feet closer to you. On a successful save, the creature takes half as much damage, and you don't pull it or knock it prone.",
  "Como acción, gastas 2 puntos de Ki y convocas una potente ráfaga de aire comprimido contra una criatura a 30 pies. Debe hacer una salvación de Fuerza; si falla sufre 3d10 de daño contundente (más 1d10 por cada Ki adicional) y es empujada hasta 20 pies lejos de ti y derribada. Si tiene éxito, sufre la mitad y no es empujada.": "As an action, you can spend 2 Ki points and choose a creature within 30 feet of you, creating a blast of compressed air. The creature must make a Strength saving throw. On a failed save, the creature takes 3d10 bludgeoning damage, plus an extra 1d10 bludgeoning damage for each additional Ki point you spend, and you can push the creature up to 20 feet away from you and knock it prone. On a successful save, the creature takes half as much damage, and you don't push it or knock it prone.",
  "Puedes gastar 2 puntos de Ki para lanzar el conjuro Onda Atronadora (Thunderwave) como acción.": "You can spend 2 Ki points to cast the Thunderwave spell as an action.",
  "Puedes gastar 2 puntos de Ki para lanzar el conjuro Manos Ardientes (Burning Hands) como acción.": "You can spend 2 Ki points to cast the Burning Hands spell as an action.",
  "Puedes gastar 2 puntos de Ki para lanzar el conjuro Ráfaga de Viento (Gust of Wind) como acción.": "You can spend 2 Ki points to cast the Gust of Wind spell as an action.",
  "Como acción, gastas 1 punto de Ki para elegir un área de hielo o agua de no más de 30 pies de lado a 120 pies de ti. Puedes congelar el agua en hielo sólido o derretir el hielo en agua, alterando el terreno de combate a tu antojo.": "As an action, you can spend 1 Ki point to choose an area of ice or water no larger than 30 feet on a side within 120 feet of you. You can change water to ice within the area and vice versa, and you can reshape ice in the area in any manner you choose.",
  "Puedes gastar 3 puntos de Ki para lanzar el conjuro Retener Persona (Hold Person) como acción, paralizando a un humanoide en el aire gélido.": "You can spend 3 Ki points to cast the Hold Person spell as an action.",
  "Puedes gastar 3 puntos de Ki para lanzar el conjuro Hacer Añicos (Shatter) como acción, resonando con fuerza telúrica destructiva.": "You can spend 3 Ki points to cast the Shatter spell as an action.",
  "Puedes gastar 4 puntos de Ki para lanzar el conjuro Forma Gaseosa (Gaseous Form) sobre ti mismo como acción, transformándote en vapor espectral.": "You can spend 4 Ki points to cast the Gaseous Form spell on yourself as an action.",
  "Puedes gastar 4 puntos de Ki para lanzar el conjuro Volar (Fly) sobre ti mismo como acción, sustentándote en corrientes ascendentes de aire.": "You can spend 4 Ki points to cast the Fly spell on yourself as an action.",
  "Puedes gastar 4 puntos de Ki para lanzar el conjuro Bola de Fuego (Fireball) como acción, desatando una llamarada ígnea masiva de 20 pies de radio.": "You can spend 4 Ki points to cast the Fireball spell as an action, unleashing a massive 20-foot-radius fiery explosion.",
  "Puedes gastar 5 puntos de Ki para lanzar el conjuro Piel Pétrea (Stoneskin) sobre ti mismo como acción, endureciendo tu piel como granito impenetrable.": "You can spend 5 Ki points to cast the Stoneskin spell on yourself as an action, hardening your skin like impenetrable granite.",
  "Puedes gastar 6 puntos de Ki para lanzar el conjuro Cono de Frío (Cone of Cold) como acción, exhalando un torrente polar de 60 pies.": "You can spend 6 Ki points to cast the Cone of Cold spell as an action, exhaling a 60-foot cone of freezing air.",
  "Puedes gastar 5 puntos de Ki para lanzar el conjuro Muro de Fuego (Wall of Fire) como acción, alzando una barrera abrasadora de llamas primordiales.": "You can spend 5 Ki points to cast the Wall of Fire spell as an action, raising a blazing barrier of primordial flames.",
  "Puedes gastar 6 puntos de Ki para lanzar el conjuro Muro de Piedra (Wall of Stone) como acción, moldeando la roca del suelo en un baluarte permanente.": "You can spend 6 Ki points to cast the Wall of Stone spell as an action, shaping solid rock into a permanent bulwark.",
  "Arma cuerpo a cuerpo versátil marcial (1d8/1d10). Se convierte en arma de monje y escala con Artes Marciales.": "Martial versatile melee weapon (1d8/1d10). Counts as a monk weapon and scales with your Martial Arts die.",
  "Arma cuerpo a cuerpo sutil marcial (1d8 perforante). Excelente precisión con Destreza.": "Martial finesse melee weapon (1d8 piercing). Excellent precision with Dexterity.",
  "Arma ligera sutil marcial (1d6 cortante). Gran fluidez en combate rápido.": "Martial light finesse melee weapon (1d6 slashing). Great fluidity in fast-paced combat.",
  "Arma versátil marcial (1d8/1d10 cortante). Golpes contundentes y brutales.": "Martial versatile melee weapon (1d8/1d10 slashing). Heavy, brutal strikes.",
  "Arma versátil marcial (1d8/1d10 contundente). Aplasta armaduras enemigas.": "Martial versatile melee weapon (1d8/1d10 bludgeoning). Crushes enemy armor.",
  "Arma marcial a distancia (1d8 perforante, alcance 150/600 pies). Letalidad a distancia extrema.": "Martial ranged weapon (1d8 piercing, range 150/600 feet). Lethal at extreme range.",
  "Arma simple a distancia (1d6 perforante, alcance 80/320 pies). Ligero y versátil.": "Simple ranged weapon (1d6 piercing, range 80/320 feet). Light and versatile.",
  "Arma simple a distancia (1d8 perforante, alcance 80/320 pies).": "Simple ranged weapon (1d8 piercing, range 80/320 feet).",
  "Arma marcial cuerpo a cuerpo (1d8 contundente). Desvía guardias enemigas.": "Martial melee weapon (1d8 bludgeoning). Sweeps past enemy guards.",
  "Arma marcial versátil arrojadiza (1d6/1d8 perforante).": "Martial versatile thrown melee weapon (1d6/1d8 piercing).",
  "Herramientas artísticas para meditar pintando paisajes y símbolos espirituales.": "Artistic tools used for meditation by painting landscapes and spiritual symbols.",
  "Pinceles, tinta y pergamino para transcribir poemas sagrados y pergaminos marciales.": "Brushes, ink, and parchment used to transcribe sacred poems and martial scrolls.",
  "La lengua sagrada y ancestral de los dragones cromáticos y metálicos.": "The ancient, sacred language of chromatic and metallic dragons.",
  "El lenguaje de los planos superiores y los seres angélicos.": "The language of the Upper Planes and angelic beings.",
  "El lenguaje preciso y estricto de los Nueve Infiernos de Baator.": "The precise, strict language of the Nine Hells of Baator.",
  "El dialecto caótico y resonante de las infinitas capas del Abismo.": "The chaotic, resonant dialect of the infinite layers of the Abyss.",
  "El melodioso lenguaje del Feywild y las criaturas feéricas.": "The melodic language of the Feywild and fey creatures.",
  "El lenguaje elemental de los cuatro planos interiores.": "The elemental language of the four Inner Planes.",
  "La lengua fluida y poética de los elfos.": "The fluid, poetic language of the elves.",
  "El idioma robusto y antiguo de las fortalezas enanas.": "The hardy, ancient language of dwarven strongholds.",
  "En furia tienes resistencia a todos los tipos de daño excepto daño psíquico. Conviértete en un baluarte invencible.": "While raging, you have resistance to all damage except psychic damage. Your spirit makes you tough enough to stand up to any punishment.",
  "En furia puedes usar Correr como acción adicional en cada turno, y las criaturas enemigas sufren desventaja en ataques de oportunidad contra ti.": "While raging, other creatures have disadvantage on opportunity attack rolls against you, and you can use the Dash action as a bonus action on your turn.",
  "En furia tus compañeros tienen ventaja en tiradas de ataque cuerpo a cuerpo contra cualquier criatura enemiga a 5 pies de ti.": "While raging, your friends have advantage on melee attack rolls against any creature within 5 feet of you that is hostile to you.",
  "En furia tu velocidad de movimiento a pie aumenta en 15 pies adicionales. Te desplazas como una estampida implacable.": "While you are raging and aren't wearing heavy armor, your walking speed increases by 15 feet.",
  "En furia la distancia de tu salto de longitud aumenta en 10 pies y tu salto de altura aumenta en 3 pies.": "While raging, you can add 10 feet to your long jump distance and 3 feet to your high jump distance.",
  "Tu capacidad de carga (incluyendo peso máximo levantado y arrastrado) se duplica, y tienes ventaja en pruebas de Fuerza realizadas para empujar, tirar, levantar o romper objetos.": "Your carrying capacity (including maximum load and maximum lift) is doubled, and you have advantage on Strength checks made to push, pull, lift, or break objects.",
  "Puedes ver con total claridad hasta a 1 milla de distancia sin dificultad, y la luz tenue no impone desventaja en tus pruebas de Sabiduría (Percepción).": "You gain the eyesight of an eagle. You can see up to 1 mile away with no difficulty, able to discern even fine details as though looking at something no more than 100 feet away, and dim light doesn't impose disadvantage on your Wisdom (Perception) checks.",
  "Ganas los sentidos de caza de un lobo. Puedes rastrear a otras criaturas mientras viajas a paso rápido, y puedes moverte sigilosamente a un ritmo normal.": "You gain the hunting sensibilities of a wolf. You can track other creatures while traveling at a fast pace, and you can move stealthily while traveling at a normal pace.",
  "Tanto si viajas a pie como montado, puedes duplicar la velocidad de viaje de hasta diez compañeros contigo si no estás en combate.": "Whether mounted or on foot, your travel pace is doubled, as is the travel pace of up to ten companions while they're within 60 feet of you and you're not incapacitated.",
  "En furia, cualquier enemigo a 5 pies de ti tiene desventaja en tiradas de ataque contra cualquier objetivo que no seas tú.": "While you're raging, any creature within 5 feet of you that's hostile to you has disadvantage on attack rolls against targets other than you or another character with this feature.",
  "En furia tienes una velocidad de vuelo igual a tu velocidad a pie actual. Caes si terminas tu turno en el aire sin nada que te sostenga.": "While raging, you have a flying speed equal to your current walking speed. This benefit works only in short bursts; you fall if you end your turn in the air and nothing else is holding you aloft.",
  "En furia, al golpear a una criatura Grande o menor con un ataque de arma cuerpo a cuerpo, puedes usar tu acción adicional para derribarla.": "While you're raging, you can use a bonus action on your turn to knock a Large or smaller creature prone when you hit it with melee weapon attack.",
  "En furia, puedes usar una acción adicional en tu turno para moverte a través del espacio de una criatura Grande o menor, infligiendo 1d12 + Fuerza de daño contundente y derribándola si falla salvación de Fuerza (CD 8 + prof + Fuerza).": "While raging, you can use a bonus action during your move to pass through the space of a Large or smaller creature. That creature must succeed on a Strength saving throw (DC 8 + your proficiency bonus + your Strength modifier) or be knocked prone and take bludgeoning damage equal to 1d12 + your Strength modifier.",
  "Si te mueves al menos 20 pies en línea recta hacia un objetivo antes de hacer un ataque con arma cuerpo a cuerpo, puedes usar tu acción adicional para hacer un ataque cuerpo a cuerpo adicional contra él.": "While you're raging, if you move at least 20 feet in a straight line toward a Large or smaller target right before making a melee weapon attack against it, you can use a bonus action to make an additional melee weapon attack against it.",
  "Calmar animales asustados o agresivos y dirigir monturas bajo tensión.": "Calm frightened or aggressive animals and control mounts under stress.",
  "Escalar superficies difíciles, saltar grietas anchas y maniobras de empujar o derribar.": "Climb difficult surfaces, leap across wide chasms, and perform grappling or shoving maneuvers.",
  "Infundir terror en adversarios mediante tu presencia física imponente.": "Instill fear in adversaries through your imposing physical presence.",
  "Conocimiento de flora, fauna, clima y ciclos de la naturaleza salvaje.": "Knowledge of flora, fauna, weather, and cycles of the natural world.",
  "Agudeza sensorial para detectar emboscadas, peligros ocultos y sonidos sutiles.": "Keen sensory awareness to spot ambushes, hidden dangers, and subtle sounds.",
  "Rastrear presas, encontrar comida/agua, orientarse en la espesura y predecir el clima.": "Track quarry, forage for food and water, navigate the wilderness, and predict the weather.",
  "Ganas competencia en pruebas de Atletismo por la agilidad felina del tigre.": "You gain proficiency in the Athletics skill through the feline agility of the tiger.",
  "Ganas competencia en pruebas de Acrobacia, manteniendo el equilibrio y destreza física.": "You gain proficiency in the Acrobatics skill, maintaining balance and physical grace.",
  "Ganas competencia en Sigilo, acechando en silencio como un depredador natural.": "You gain proficiency in the Stealth skill, stalking silently like a natural predator.",
  "Ganas competencia en Supervivencia, reconociendo huellas y rastros en la intemperie.": "You gain proficiency in the Survival skill, recognizing tracks and trails in the wild.",
  "Tu furia arde con la luz purificadora de deidades sagradas de la justicia, el sol o la creación. Tu primer impacto en cada turno en furia inflige 1d6 + la mitad de tu nivel de bárbaro de daño radiante.": "Your rage burns with the purifying light of sacred deities of justice, the sun, or creation. Your first weapon hit on each of your turns while raging deals extra radiant damage equal to 1d6 + half your barbarian level.",
  "Tu furia canaliza la energía funesta y destructiva de dioses de la muerte, el inframundo o la guerra implacable. Tu primer impacto en cada turno en furia inflige 1d6 + la mitad de tu nivel de bárbaro de daño necrótico.": "Your rage channels the grim, destructive energy of gods of death, the underworld, or relentless war. Your first weapon hit on each of your turns while raging deals extra necrotic damage equal to 1d6 + half your barbarian level.",
  "Tu mandíbula muta en colmillos bestiales. Inflige 1d8 de daño perforante + Fuerza. Una vez por turno, si tienes menos de la mitad de tus puntos de golpe máximos, recuperas puntos de golpe iguales a tu bonificador de competencia al impactar.": "Your mouth transforms into a bestial muzzle or great mandibles. It deals 1d8 piercing damage + your Strength modifier on a hit. Once on each of your turns when you damage a creature with this bite, you regain a number of hit points equal to your proficiency bonus, provided you have less than half your hit points when you hit.",
  "Tus manos se transforman en garras temibles. Inflige 1d6 de daño cortante + Fuerza. Una vez en cada uno de tus turnos, cuando atacas con una garra usando la acción de Atacar, puedes realizar un ataque adicional con tus garras como parte de la misma acción.": "Each of your hands transforms into a claw, which you can use as a weapon if it's empty. It deals 1d6 slashing damage + your Strength modifier on a hit. Once on each of your turns when you attack with a claw using the Attack action, you can make one additional claw attack as part of the same action.",
  "Te brota una cola musculosa y espinosa con alcance de 10 pies. Inflige 1d8 de daño perforante + Fuerza. Como reacción cuando una criatura a 10 pies o menos te impacte con un ataque, puedes tirar 1d8 y sumarlo a tu CA para ese ataque, pudiendo hacer que falle.": "You grow a lashing, spiny tail with a reach of 10 feet, which deals 1d8 piercing damage + your Strength modifier on a hit. If a creature you can see within 10 feet of you hits you with an attack roll, you can use your reaction to swipe your tail and roll a d8, applying a bonus to your AC equal to the number rolled, potentially causing the attack to miss you.",
  "Desarrollas branquias y membranas: obtienes una velocidad de nado igual a tu velocidad a pie y puedes respirar bajo el agua indefinidamente.": "You gain a swimming speed equal to your walking speed, and you can breathe underwater.",
  "Tus extremidades se adhieren a cualquier superficie: obtienes una velocidad de escalada igual a tu velocidad a pie y puedes escalar superficies difíciles, incluyendo moverte boca abajo por techos, sin necesidad de realizar pruebas de característica.": "You gain a climbing speed equal to your walking speed, and you can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check.",
  "Tus piernas concentran una fuerza colosal: cuando realizas un salto, puedes hacer una prueba de Fuerza (Atletismo) y extender la distancia del salto en un número de pies igual al total de tu tirada.": "When you jump, you can make a Strength (Athletics) check and extend your jump by a number of feet equal to the check's total. You can make this special check only once per turn.",
  "Canalizas el fuego implacable de las dunas. Aura (10 pies): acción adicional inflige daño de fuego (2 a Nv 3, 3 a Nv 5, 4 a Nv 10, 5 a Nv 15, 6 a Nv 20) a las criaturas a 10 pies. Nv 6: resistencia al fuego y confort en calor extremo. Nv 10: otorgas resistencia al fuego a aliados en tu aura. Nv 14: reacción al recibir daño para infligir la mitad de tu nivel de bárbaro en fuego al atacante.": "You channel the relentless fire of the desert. Aura (10 feet): bonus action deals fire damage (2 at 3rd, 3 at 5th, 4 at 10th, 5 at 15th, 6 at 20th level) to all other creatures in your aura. 6th Level: fire resistance and immunity to extreme heat. 10th Level: allies in your aura gain fire resistance. 14th Level: reaction when hit by a creature in your aura to force a Dexterity save or deal fire damage equal to half your barbarian level.",
  "Canalizas el rugido del océano y el rayo. Aura (10 pies): acción adicional obliga a una criatura a 10 pies a superar salvación de Destreza o sufrir 1d6 daño de relámpago (2d6 a Nv 10, 3d6 a Nv 15, 4d6 a Nv 20). Nv 6: resistencia a relámpago, respiras agua y 30 pies de nado. Nv 10: otorgas resistencia eléctrica a aliados. Nv 14: derribas al objetivo al impactarlo en tu aura (salva FUE).": "You channel the roar of the sea and lightning. Aura (10 feet): bonus action forces one creature in your aura to make a Dexterity save or take 1d6 lightning damage (2d6 at 10th, 3d6 at 15th, 4d6 at 20th level). 6th Level: lightning resistance, underwater breathing, and 30-foot swimming speed. 10th Level: allies in your aura gain lightning resistance. 14th Level: reaction when you hit a creature in your aura to force a Strength save or knock it prone.",
  "Canalizas el frío glacial y la resistencia del hielo eterno. Aura (10 pies): acción adicional concede 2 PG temporales a aliados a 10 pies (3 a Nv 5, 4 a Nv 10, 5 a Nv 15, 6 a Nv 20). Nv 6: resistencia al frío y confort en frío extremo. Nv 10: otorgas resistencia a frío a aliados. Nv 14: congelas a un rival en tu aura reduciendo su velocidad a 0 pies si falla salvación de Fuerza.": "You channel the icy chill and endurance of the tundra. Aura (10 feet): bonus action grants 2 temporary hit points to each creature of your choice in your aura (3 at 5th, 4 at 10th, 5 at 15th, 6 at 20th level). 6th Level: cold resistance and immunity to extreme cold. 10th Level: allies in your aura gain cold resistance. 14th Level: whenever your aura is activated, force a creature in your aura to make a Strength save or have its speed reduced to 0.",
  "Tu arma emana llamas abrasadoras. Inflige +1d6 de daño de fuego adicional (+2d6 a Nivel 14). Gana la propiedad arrojadiza (alcance 20/60 pies) y regresa mágicamente a tu mano inmediatamente tras el ataque.": "Your weapon wreathes itself in blazing flames, dealing an extra 1d6 fire damage (+2d6 at 14th level). It gains the thrown property (range 20/60 feet) and reappears in your hand immediately after an attack.",
  "Tu arma se cubre de carámbanos glaciales. Inflige +1d6 de daño de frío adicional (+2d6 a Nivel 14). Gana la propiedad arrojadiza (alcance 20/60 pies) y regresa instantáneamente a tu mano.": "Your weapon is coated in glacial frost, dealing an extra 1d6 cold damage (+2d6 at 14th level). It gains the thrown property (range 20/60 feet) and reappears in your hand immediately after an attack.",
  "Tu arma chisporrotea con arcos eléctricos. Inflige +1d6 de daño de relámpago adicional (+2d6 a Nivel 14). Gana la propiedad arrojadiza (alcance 20/60 pies) y retorna mágicamente al instante.": "Your weapon crackles with arcs of lightning, dealing an extra 1d6 lightning damage (+2d6 at 14th level). It gains the thrown property (range 20/60 feet) and reappears in your hand immediately after an attack.",
  "Tu arma retumba con ondas de choque sísmicas. Inflige +1d6 de daño de trueno adicional (+2d6 a Nivel 14). Gana la propiedad arrojadiza (alcance 20/60 pies) y regresa a tu mano al instante.": "Your weapon booms with seismic shockwaves, dealing an extra 1d6 thunder damage (+2d6 at 14th level). It gains the thrown property (range 20/60 feet) and reappears in your hand immediately after an attack.",
  "Tu arma rezuma jugos corrosivos primordiales. Inflige +1d6 de daño de ácido adicional (+2d6 a Nivel 14). Gana la propiedad arrojadiza (alcance 20/60 pies) y regresa a tu mano al instante.": "Your weapon drips with primordial corrosive acid, dealing an extra 1d6 acid damage (+2d6 at 14th level). It gains the thrown property (range 20/60 feet) and reappears in your hand immediately after an attack.",
  "Pasiva: Ventaja en pruebas de Juego de Manos y Engaño. Activa: Como reacción al impactarte a ti o a un aliado a 30 pies, rediriges el ataque a otra criatura a 30 pies (1/descanso corto o largo).": "Passive: Advantage on Dexterity (Sleight of Hand) and Charisma (Deception) checks. Active: When you or a creature you can see within 30 feet is hit by an attack roll, you can use your reaction to choose a different creature within 30 feet of you (other than the attacker) to become the target of the attack instead (1/short or long rest).",
  "Pasiva: Doblas tu competencia en pruebas con herramientas. Activa: Al impactar con un arma, convocas grilletes ígneos que infligen 2d6 fuego y apresan al rival (salvación Fuerza cada turno) (1/descanso corto o largo).": "Passive: Your proficiency bonus is doubled for any ability check you make that uses your proficiency with a tool. Active: When you hit a creature with a weapon attack, you can summon fiery shackles: the target takes an extra 2d6 fire damage and must succeed on a Strength saving throw or be restrained for 1 minute, taking 2d6 fire damage at the start of each of its turns (1/short or long rest).",
  "Pasiva: Ventaja en pruebas de Trato con Animales e Intimidación. Activa: Acción adicional para sumar +2 a todas tus pruebas y salvaciones de Fuerza y Constitución durante 10 minutos (1/descanso corto o largo).": "Passive: Advantage on Wisdom (Animal Handling) and Charisma (Intimidation) checks. Active: As a bonus action, you gain a +2 bonus to all ability checks and saving throws using Strength or Constitution for 10 minutes (1/short or long rest).",
  "Pasiva: Ventaja en Perspicacia y visión en la oscuridad de 120 pies. Activa: Reacción cuando un enemigo termine su turno a 30 pies para sumirlo en un letargo hipnótico (incapacitado) si falla salvación de Sabiduría (1/descanso corto o largo).": "Passive: Advantage on Wisdom (Insight) checks, and you gain darkvision out to a range of 120 feet. Active: When a creature you can see ends its turn within 30 feet of you, you can use your reaction to force it to make a Wisdom saving throw; on a failed save, it is charmed by you for 1 minute, incapacitated, and has a speed of 0 (1/short or long rest).",
  "Pasiva: Ventaja en salvaciones contra veneno y resistencia al daño de veneno. Activa: Acción adicional para ganar resistencia al daño contundente, perforante y cortante durante 1 minuto (1/descanso corto o largo).": "Passive: Advantage on saving throws against being poisoned, and you have resistance to poison damage. Active: As a bonus action, you gain resistance to bludgeoning, piercing, and slashing damage for 1 minute (1/short or long rest).",
  "Pasiva: Ventaja en pruebas de Arcanos y no puedes ser sorprendido. Activa: Durante 1 minuto puedes usar tu reacción cada turno para otorgar ventaja o desventaja en cualquier d20 a 60 pies (1/descanso corto o largo).": "Passive: Advantage on Intelligence (Arcana) checks, and you can't be surprised while you aren't incapacitated. Active: As a bonus action, you enter a prophetic state for 1 minute; during that time, when you or another creature you can see within 60 feet makes an attack roll, saving throw, or ability check, you can use your reaction to cause the roll to have advantage or disadvantage (1/short or long rest).",
  "Al impactar, obligas al objetivo a hacer salvación de Carisma o ser desterrado temporalmente al plano Feywild hasta el final de su siguiente turno.": "On a hit, the target must succeed on a Charisma saving throw or be banished to a harmless demiplane in the Feywild until the end of its next turn.",
  "Al impactar con la flecha, detona en una onda expansiva de fuerza que inflige 2d6 de daño de fuerza adicional al objetivo y a todas las criaturas a 10 pies.": "Immediately after the arrow hits the creature, the target and all other creatures within 10 feet of it take 2d6 force damage each.",
  "Zarcillos espinosos aprisionan a la víctima: sufre 2d6 de daño de veneno, su velocidad se reduce en 10 pies y sufre 2d6 de daño cortante cada vez que se mueva.": "The creature hit by the arrow takes an extra 2d6 poison damage, its speed is reduced by 10 feet, and it takes 2d6 slashing damage the first time on each turn it moves 1 foot or more without teleporting.",
  "La flecha se transforma en una línea etérea de 30 pies de largo y 1 pie de ancho que atraviesa objetos y criaturas, forzando salvación de Destreza.": "The arrow transforms into an ethereal lance that passes harmlessly through objects in a line 1 foot wide and 30 feet long, forcing each creature in that line to make a Dexterity saving throw or take damage as if hit by the arrow plus an extra 1d6 piercing damage.",
  "La flecha busca a su presa guiada por magia: ignora cobertura y no requiere línea de visión directa si sabes dónde está el objetivo.": "Choose one creature you have seen in the past minute; the arrow flies toward that creature, moving around corners if necessary and ignoring three-quarters cover and half cover, forcing a Dexterity saving throw.",
  "Magia de sombras teje ceguera sobre la víctima: sufre 2d6 de daño psíquico y no puede ver más allá de 5 pies hasta el final de tu siguiente turno si falla salvación de Sabiduría.": "Shadow magic occludes the target's vision: it takes an extra 2d6 psychic damage, and it must succeed on a Wisdom saving throw or be unable to see anything farther than 5 feet away until the start of your next turn.",
  "Magia nigromántica drena la vitalidad: 2d6 de daño necrótico y el daño de los ataques con arma del rival se reduce a la mitad si falla salvación de Constitución.": "Necromantic magic saps the target's strength: the creature takes an extra 2d6 necrotic damage, and it must succeed on a Constitution saving throw or the damage dealt by its weapon attacks is halved until the start of your next turn.",
  "Hechiza al objetivo: sufre 2d6 de daño psíquico y no puede atacar a uno de tus aliados a tu elección hasta el final de su siguiente turno.": "Enchantment magic infuses the arrow: the creature hit takes an extra 2d6 psychic damage, and it must succeed on a Wisdom saving throw or be charmed by one of your allies within 30 feet of it until the start of your next turn.",
  "Afinidad con el Fuego abrasador. A nivel 6 sumas tu Carisma al daño de conjuros de fuego y ganas resistencia al fuego gastando 1 punto de hechicería.": "Affinity with scorching Fire. At 6th level, you add your Charisma modifier to fire spell damage and can spend 1 Sorcery Point to gain resistance to fire damage.",
  "Afinidad con el Fuego purificador y la justicia dorada. Resistencia y potencia ígnea.": "Affinity with purifying Fire and golden justice. Grants fire damage bonus and resistance.",
  "Afinidad con el Fuego ardiente del desierto. Resistencia y potencia ígnea.": "Affinity with the blazing Fire of the desert. Grants fire damage bonus and resistance.",
  "Afinidad con el Relámpago y las tormentas de arena. Bonificador al daño de relámpago.": "Affinity with Lightning and desert storms. Grants lightning damage bonus and resistance.",
  "Afinidad con el Relámpago costero y marítimo. Resistencia y daño eléctrico.": "Affinity with coastal and maritime Lightning. Grants lightning damage bonus and resistance.",
  "Afinidad con el Frío polar implacable. Bonificador al daño de frío y resistencia ártica.": "Affinity with relentless polar Cold. Grants cold damage bonus and arctic resistance.",
  "Afinidad con el Frío noble y la escarcha celestial. Resistencia y daño de frío.": "Affinity with noble Cold and celestial frost. Grants cold damage bonus and resistance.",
  "Afinidad con el Ácido corrosivo de ciénagas oscuras. Bonificador al daño de ácido.": "Affinity with the corrosive Acid of dark swamps. Grants acid damage bonus and resistance.",
  "Afinidad con el Ácido y el ingenio terrenal. Resistencia y daño de ácido.": "Affinity with Acid and clever wit. Grants acid damage bonus and resistance.",
  "Afinidad con el Veneno engañoso de bosques primigenios. Daño y resistencia a veneno.": "Affinity with the deceitful Poison of primeval forests. Grants poison damage bonus and resistance.",
  "Afinidad con la benevolencia y la curación. Aprendes el conjuro Curar Heridas (Cure Wounds) de forma gratuita.": "Affinity with benevolence and healing. You learn the Cure Wounds spell for free.",
  "Afinidad con la perdición y la necrosis. Aprendes el conjuro Infligir Heridas (Inflict Wounds) de forma gratuita.": "Affinity with doom and necrosis. You learn the Inflict Wounds spell for free.",
  "Afinidad con el orden cósmico y la justicia. Aprendes el conjuro Bendición (Bless) de forma gratuita.": "Affinity with cosmic order and law. You learn the Bless spell for free.",
  "Afinidad con la entropía primordial y el destino cambiante. Aprendes el conjuro Saeta Guía (Guiding Bolt) de forma gratuita.": "Affinity with primordial chaos and shifting fate. You learn the Bane spell (or Guiding Bolt) for free.",
  "Afinidad con el equilibrio cósmico. Aprendes el conjuro Protección contra el Mal y el Bien de forma gratuita.": "Affinity with cosmic neutrality and balance. You learn the Protection from Evil and Good spell for free.",
  "Escuelas de Abjuración y Adivinación. Conjuro gratuito: Escudo de Fe. Ventaja en Investigación y Percepción.": "Schools of Abjuration and Divination. Free spell: Shield (or Shield of Faith). Advantage on Investigation and Perception checks.",
  "Escuelas de Ilusión y Nigromancia. Conjuro gratuito: Falsa Vida. Ventaja en Sigilo.": "Schools of Evocation and Necromancy (or Illusion and Necromancy). Free spell: Ray of Sickness (or False Life). Advantage on Stealth checks.",
  "Escuelas de Transmutación y Conjuración. Conjuro gratuito: Rayo de Enfermedad. Resistencia a daño radiante y necrótico.": "Schools of Illusion and Transmutation. Free spell: Color Spray (or Ray of Sickness). Resistance to necrotic and radiant damage.",
  "Conjuros siempre preparados: Nv 3 (Caminar sobre el Agua, Retener Persona), Nv 5 (Tormenta de Granizo, Ralentizar), Nv 7 (Libertad de Movimiento, Tormenta de Hielo), Nv 9 (Comunión con la Naturaleza, Cono de Frío).": "Always prepared spells: 3rd Level (Hold Person, Spike Growth), 5th Level (Sleet Storm, Slow), 7th Level (Freedom of Movement, Ice Storm), 9th Level (Commune with Nature, Cone of Cold).",
  "Conjuros siempre preparados: Nv 3 (Imagen Espejada, Paso Brumoso), Nv 5 (Caminar sobre el Agua, Respiración Acuática), Nv 7 (Controlar el Agua, Libertad de Movimiento), Nv 9 (Conjurar Elemental, Escudriñar).": "Always prepared spells: 3rd Level (Mirror Image, Misty Step), 5th Level (Water Breathing, Water Walk), 7th Level (Control Water, Freedom of Movement), 9th Level (Conjure Elemental, Scrying).",
  "Conjuros siempre preparados: Nv 3 (Borrón, Silencio), Nv 5 (Crear Comida y Agua, Protección contra la Energía), Nv 7 (Marchitar, Plaga de Insectos), Nv 9 (Muro de Piedra, Nube Mortal).": "Always prepared spells: 3rd Level (Blur, Silence), 5th Level (Create Food and Water, Protection from Energy), 7th Level (Blight, Hallucinatory Terrain), 9th Level (Insect Plague, Wall of Stone).",
  "Conjuros siempre preparados: Nv 3 (Piel Robusta, Trepar cual Arácnido), Nv 5 (Llamar al Relámpago, Crecimiento Vegetal), Nv 7 (Adivinación, Libertad de Movimiento), Nv 9 (Comunión con la Naturaleza, Reencarnar).": "Always prepared spells: 3rd Level (Barkskin, Spider Climb), 5th Level (Call Lightning, Plant Growth), 7th Level (Divination, Freedom of Movement), 9th Level (Commune with Nature, Tree Stride).",
  "Conjuros siempre preparados: Nv 3 (Invisibilidad, Pasar sin Huella), Nv 5 (Luz Diurna, Aceleración), Nv 7 (Adivinación, Libertad de Movimiento), Nv 9 (Pasacalles, Sueño Telúrico).": "Always prepared spells: 3rd Level (Invisibility, Pass without Trace), 5th Level (Daylight, Haste), 7th Level (Divination, Freedom of Movement), 9th Level (Dream, Insect Plague).",
  "Conjuros siempre preparados: Nv 3 (Trepar cual Arácnido, Salto), Nv 5 (Relámpago, Fundirse con la Piedra), Nv 7 (Piel Pétrea, Muro de Piedra), Nv 9 (Pasar Muro, Tormenta Glacial).": "Always prepared spells: 3rd Level (Spider Climb, Spike Growth), 5th Level (Lightning Bolt, Meld into Stone), 7th Level (Stone Shape, Stoneskin), 9th Level (Passwall, Wall of Stone).",
  "Conjuros siempre preparados: Nv 3 (Oscuridad, Flecha Ácida de Melf), Nv 5 (Caminar sobre el Agua, Nube Hedionda), Nv 7 (Marchitar, Localizar Criatura), Nv 9 (Plaga de Insectos, Escudriñar).": "Always prepared spells: 3rd Level (Darkness, Melf's Acid Arrow), 5th Level (Water Walk, Stinking Cloud), 7th Level (Freedom of Movement, Locate Creature), 9th Level (Insect Plague, Scrying).",
  "Conjuros siempre preparados: Nv 3 (Trepar cual Arácnido, Telaraña), Nv 5 (Forma Gaseosa, Luz Diurna), Nv 7 (Invisibilidad Mayor, Modelar Piedra), Nv 9 (Nube Mortal, Apariencia).": "Always prepared spells: 3rd Level (Spider Climb, Web), 5th Level (Gaseous Form, Stinking Cloud), 7th Level (Greater Invisibility, Stone Shape), 9th Level (Cloudkill, Insect Plague).",
  "Ventaja en pruebas de Supervivencia para rastrear y en Saber para recordar información sobre bestias.": "Advantage on Wisdom (Survival) checks to track beasts, as well as on Intelligence checks to recall information about them.",
  "Ventaja al rastrear y conocer duendes, ninfas, sátiros y seres del Feywild.": "Advantage on Survival checks to track and Intelligence checks to recall lore about sprites, nymphs, satyrs, and creatures of the Feywild.",
  "Ventaja contra quimeras, grifos, mantícoras y aberraciones híbridas.": "Advantage on Survival checks to track and Intelligence checks to recall lore about chimeras, griffons, manticores, and monstrosities.",
  "Ventaja contra esqueletos, zombis, vampiros, necrófagos y espectros.": "Advantage on Survival checks to track and Intelligence checks to recall lore about skeletons, zombies, vampires, ghouls, and wraiths.",
  "Ventaja contra dragones cromáticos, metálicos y sierpes legendarias.": "Advantage on Survival checks to track and Intelligence checks to recall lore about chromatic dragons, metallic dragons, and wyrms.",
  "Ventaja contra azotamentes, contempladores y entidades del Reino Lejano.": "Advantage on Survival checks to track and Intelligence checks to recall lore about mind flayers, beholders, and Far Realm entities.",
  "Ventaja contra demonios del Abismo y diablos de los Nueve Infiernos.": "Advantage on Survival checks to track and Intelligence checks to recall lore about demons of the Abyss and devils of the Nine Hells.",
  "Ventaja contra criaturas de Fuego, Agua, Tierra y Aire.": "Advantage on Survival checks to track and Intelligence checks to recall lore about creatures of Fire, Water, Earth, and Air.",
  "Ventaja contra ogros, trolls, gigantes de las colinas, escarcha, fuego y tormenta.": "Advantage on Survival checks to track and Intelligence checks to recall lore about ogres, trolls, and hill, frost, fire, and storm giants.",
  "El terreno difícil no ralentiza el viaje de tu grupo en la tundra y nieve. No puedes perderte salvo por medios mágicos.": "Difficult terrain doesn't slow your group's travel in arctic tundra and snow, and you can't become lost except by magical means.",
  "Ventaja y navegación perfecta en litorales marítimos y archipiélagos.": "Expert navigation, foraging, and uninhibited travel across coastal shores and archipelagos.",
  "Sobrevives sin penalizadores en dunas áridas, calor extremo y tormentas de arena.": "Expert survival, foraging, and uninhibited travel across arid dunes, extreme heat, and sandstorms.",
  "Movimiento sigiloso y comida abundante en arboledas densas y selvas.": "Stealthy movement, abundant foraging, and uninhibited travel through dense forests and jungles.",
  "Visión y rastreo ilimitados en llanuras abiertas y sabanas.": "Unmatched tracking, foraging, and swift travel across open plains and savannas.",
  "Escalada sin fatiga y paso seguro por riscos y cordilleras escarpadas.": "Sure-footed travel, foraging, and navigation across rugged cliffs and mountain ranges.",
  "Inmune al terreno enfangado y cenagoso de marismas y ciénagas.": "Unhindered travel, tracking, and foraging through muddy marshes, bogs, and swamps.",
  "Orientación infalible en la profunda red de cavernas subterráneas.": "Unerring orientation, stealth, and survival within the deep subterranean caverns of the Underdark.",
  "+2 a las tiradas de ataque con armas a distancia.": "You gain a +2 bonus to attack rolls you make with ranged weapons.",
  "+1 a tu Clase de Armadura mientras vistas armadura.": "While you are wearing armor, you gain a +1 bonus to AC.",
  "+2 al daño cuando empuñas un arma a una mano y ninguna otra.": "When you are wielding a melee weapon in one hand and no other weapons, you gain a +2 bonus to damage rolls with that weapon.",
  "Suma tu bonificador de característica al daño del ataque de acción adicional con la segunda arma.": "When you engage in two-weapon fighting, you can add your ability modifier to the damage of the second attack.",
  "Posees vista a ciegas con un radio de 10 pies. Puedes ver criaturas invisibles y en oscuridad total.": "You have blindsight with a range of 10 feet. Within that range, you can effectively see anything that isn't behind total cover, even if you're blinded or in darkness.",
  "Aprendes dos trucos a tu elección de la lista de conjuros de Druida. Cuentan como conjuros de explorador y usan tu Sabiduría.": "You learn two cantrips of your choice from the druid spell list. They count as ranger spells for you, and Wisdom is your spellcasting ability for them.",
  "Una vez por turno al impactar a una criatura con un arma, infliges +1d8 de daño adicional si la criatura está por debajo de sus puntos de golpe máximos.": "Once per turn, when you hit a creature with a weapon attack, the creature takes an extra 1d8 damage if it's below its hit point maximum.",
  "Una vez en cada uno de tus turnos al hacer un ataque de arma, puedes realizar otro ataque con la misma arma contra una criatura diferente a 5 pies de la original.": "Once on each of your turns when you make a weapon attack, you can make another attack with the same weapon against a different creature that is within 5 feet of the original target and within range of your weapon.",
  "Cuando una criatura Grande o mayor a 5 pies te ataque y falle, puedes usar tu reacción para atacarla de inmediato con un arma.": "When a Large or larger creature within 5 feet of you hits or misses you with an attack, you can use your reaction to attack that creature immediately after its attack, provided that you can see the creature.",
  "Las criaturas enemigas sufren desventaja en todas las tiradas de ataques de oportunidad contra ti.": "Opportunity attacks against you are made with disadvantage.",
  "Cuando una criatura te impacta con un ataque, ganas +4 a tu CA contra todos los ataques subsiguientes de esa criatura en el turno.": "When a creature hits you with an attack, you gain a +4 bonus to AC against all subsequent attacks made by that creature for the rest of the turn.",
  "Tienes ventaja en todas las tiradas de salvación contra el efecto de ser asustado.": "You have advantage on saving throws against being frightened.",
  "Como acción, realizas un ataque a distancia contra cualquier cantidad de criaturas en un radio de 10 pies de un punto visible dentro del alcance de tu arma.": "You can use your action to make a ranged attack against any number of creatures within 10 feet of a point you can see within your weapon's range.",
  "Como acción, realizas un ataque cuerpo a cuerpo contra cualquier número de criaturas a 5 pies de ti.": "You can use your action to make a melee attack against any number of creatures within 5 feet of you, with a separate attack roll for each target.",
  "Cuando sufres un efecto que requiere salvación de Destreza para mitigar el daño (ej. Bola de Fuego), no recibes daño si superas la tirada y solo la mitad si fallas.": "When you are subjected to an effect, such as a red dragon's fiery breath or a Lightning Bolt spell, that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw, and only half damage if you fail.",
  "Cuando un atacante visible te impacta con un ataque, puedes usar tu reacción para reducir a la mitad el daño que recibes.": "When an attacker that you can see hits you with an attack, you can use your reaction to halve the attack's damage against you.",
  "Cuando una criatura hostil falla un ataque cuerpo a cuerpo contra ti, puedes usar tu reacción para obligarla a repetir ese mismo ataque contra otro enemigo a 5 pies de ella.": "When a hostile creature misses you with a melee attack, you can use your reaction to force that creature to repeat the same attack against another creature (other than itself) of your choice.",
  "El drake emana llamas ardientes. Sus mordiscos infligen +1d6 daño de fuego y tiene inmunidad al fuego.": "The drake emanates fiery heat. Its bite deals an extra 1d6 fire damage, and it has immunity to fire damage.",
  "El drake irradia escarcha polar. Sus mordiscos infligen +1d6 daño de frío y tiene inmunidad al frío.": "The drake radiates polar frost. Its bite deals an extra 1d6 cold damage, and it has immunity to cold damage.",
  "El drake chisporrotea con arcos eléctricos. Sus mordiscos infligen +1d6 daño de relámpago y tiene inmunidad al relámpago.": "The drake crackles with electrical arcs. Its bite deals an extra 1d6 lightning damage, and it has immunity to lightning damage.",
  "El drake supura jugos corrosivos. Sus mordiscos infligen +1d6 daño de ácido y tiene inmunidad al ácido.": "The drake oozes corrosive acid. Its bite deals an extra 1d6 acid damage, and it has immunity to acid damage.",
  "El drake exuda toxinas letales. Sus mordiscos infligen +1d6 daño de veneno y tiene inmunidad al veneno.": "The drake exudes lethal toxins. Its bite deals an extra 1d6 poison damage, and it has immunity to poison damage.",
  "Conocimiento sobre linajes nobles, guerras legendarias y dinastías antiguas.": "Knowledge of noble lineages, legendary wars, and ancient dynasties.",
  "Intuir las verdaderas intenciones y honor de tus interlocutores.": "Discern the true intentions and honor of those you speak with.",
  "Demostrar el porte marcial y ceremonias cortesanas ante la corte.": "Display martial poise and courtly ceremonies before nobility.",
  "Influir con cortesía implacable y diplomacia regia.": "Influence others through impeccable courtesy and royal diplomacy.",
  "Armadura o escudo: Otorga un bonificador de +1 a la Clase de Armadura mientras se lleve puesta o empuñe. A nivel 10 de artífice, el bonificador aumenta a +2.": "Armor or shield: A creature gains a +1 bonus to Armor Class while wearing (armor) or wielding (shield) the infused item. The bonus increases to +2 when you reach 10th level in this class.",
  "Arma simple o marcial: Otorga un bonificador de +1 a las tiradas de ataque y daño con ella. A nivel 10 de artífice, el bonificador aumenta a +2.": "Simple or martial weapon: This magic weapon grants a +1 bonus to attack and damage rolls made with it. The bonus increases to +2 when you reach 10th level in this class.",
  "Vara, báculo o varita: Otorga un bonificador de +1 a las tiradas de ataque de conjuro del portador e ignora la cobertura media. A nivel 10 de artífice, el bonificador aumenta a +2.": "Rod, staff, or wand (requires attunement): While holding this item, a creature gains a +1 bonus to spell attack rolls and ignores half cover when making a spell attack. The bonus increases to +2 when you reach 10th level in this class.",
  "Arma a distancia con propiedad de munición: Otorga +1 a las tiradas de ataque y daño, ignora la propiedad de recarga y produce mágicamente su propia munición infinita si no se carga proyectil.": "Simple or martial weapon with the ammunition property (requires attunement): This magic weapon grants a +1 bonus to attack and damage rolls made with it when it's used to make a ranged attack, and it ignores the loading property. If you load no ammunition in the weapon, it produces its own, automatically creating one piece of magic ammunition when you make a ranged attack with it.",
  "Arma simple o marcial arrojadiza: Otorga +1 a las tiradas de ataque y daño cuando se arroja, y vuela inmediatamente de regreso a la mano del portador tras el impacto o fallo.": "Simple or martial weapon with the thrown property: This magic weapon grants a +1 bonus to attack and damage rolls made with it, and it returns to the wielder's hand immediately after it is used to make a ranged attack.",
  "Traje de armadura (requiere sintonización): Posee 6 cargas. Permite gastar 1 carga para sumar la Inteligencia a cualquier prueba o salvación de Fuerza, y usar una reacción para evitar caer derribado al suelo.": "Suit of armor (requires attunement): The armor has 6 charges. The wearer can expend 1 charge to add a bonus equal to their Intelligence modifier to a Strength check or a Strength saving throw, or use their reaction when they would be knocked prone to expend 1 charge and not be knocked prone.",
  "Traje de armadura o túnica: Posee 4 cargas. Cuando el portador falla una salvación de Constitución para mantener la concentración en un conjuro, puede usar su reacción para gastar 1 carga y superarla automáticamente.": "Suit of armor or robes: The infused item has 4 charges. When the wearer fails a Constitution saving throw to maintain concentration on a spell, the wearer can use their reaction to expend 1 of the item's charges to succeed instead.",
  "Gema o cristal de 100 po: Creas un autómata volador leal (CA 13, vuela 30 pies) que actúa en tu turno con tu acción adicional para realizar un ataque de Golpe de Fuerza o canalizar un conjuro tuyo de toque.": "Gem or crystal worth at least 100 gp: You create a loyal mechanical Homunculus Servant (AC 13, fly 30 feet) that acts on your turn; you can use a bonus action to command it to make a Force Strike attack or channel a touch spell you cast.",
  "Bolsa no mágica: Contenedor extradimensional que almacena hasta 500 lb y 64 pies cúbicos, pesando siempre 15 lb.": "Bag of Holding: An extradimensional container that holds up to 500 pounds (not exceeding a volume of 64 cubic feet) while always weighing 15 pounds.",
  "Lentes: Otorga visión en la oscuridad en un radio de 60 pies (o suma +60 pies al alcance existente).": "Goggles of Night: While wearing these dark lenses, you have darkvision out to a range of 60 feet (or increase your existing darkvision range by 60 feet).",
  "Jarra cerámica: Produce líquidos a diario (ácido, cerveza, agua dulce, vino, aceite, veneno básico).": "Alchemy Jug: A ceramic jug able to produce a chosen liquid each day (acid, beer, fresh water, mayonnaise, oil, vinegar, wine, or basic poison).",
  "Carcaj: Tres compartimentos extradimensionales para 60 flechas, 18 jabalinas y 6 arcos o bastones.": "Efficient Quiver: Each of the quiver's three extradimensional compartments connects to an extradimensional space, holding up to 60 arrows, 18 javelins, and 6 long objects such as bows or staffs.",
  "Cuerda de 60 pies: Se anuda, escala y desenreda siguiendo órdenes verbales a 30 pies.": "Rope of Climbing: A 60-foot length of silk rope that animates at your command, moving, knotting, and fastening itself to objects within 30 feet.",
  "Gorro: Permite respirar bajo el agua indefinidamente creando una burbuja de aire constante.": "Cap of Water Breathing: While wearing this cap underwater, you can speak its command word as an action to create a bubble of air around your head, allowing you to breathe normally underwater.",
  "Varita: 3 cargas. Revela puertas secretas y trampas en un radio de 30 pies.": "Wand of Secrets: The wand has 3 charges. While holding it, you can use an action to expend 1 of its charges, and if a secret door or trap is within 30 feet of you, the wand pulses and points at the one nearest to you.",
  "Amuleto: 1 vez al día, al atacar puedes elegir un 10 natural en el d20 en vez de tirar el dado.": "Clockwork Amulet: When you make an attack roll while wearing the amulet, you can forgo rolling the d20 to get a 10 on the die (1/day).",
  "Par de botas (requiere sintonización): Permite usar una acción adicional para teletransportarse mágicamente hasta 30 pies a un espacio desocupado donde hayas estado en algún momento durante el turno actual.": "Pair of boots (requires attunement): While wearing these boots, a creature can teleport up to 15 feet as a bonus action to an unoccupied space the creature can see, provided the creature has occupied that space at some point during the current turn.",
  "Arma simple o marcial (requiere sintonización): +1 ataque y daño. Emite luz brillante a 30 pies y, como reacción al recibir un impacto, puede cegar al atacante hasta el final del próximo turno de este (salvación Constitución CD artífice).": "Simple or martial weapon (requires attunement): Grants a +1 bonus to attack and damage rolls, sheds bright light in a 30-foot radius as a bonus action, and has 4 charges; as a reaction after being hit by an attack, the wielder can expend 1 charge to force the attacker to make a Constitution saving throw against your spell save DC or be blinded until the end of the attacker's next turn.",
  "Anillo (requiere sintonización): Como acción, permite a quien lo porte recuperar una ranura de conjuro gastada de nivel 3 o inferior (1 vez al día, recarga al amanecer).": "Ring (requires attunement): While wearing this ring, the creature can recover one expended spell slot as an action; the recovered slot can be of 3rd level or lower (once per day, recharges at dawn).",
  "Traje de armadura (requiere sintonización): Otorga resistencia a un tipo de daño elemental elegido al infundirla: ácido, frío, fuego, fuerza, relámpago, necrótico, veneno, psíquico, radiante o trueno.": "Suit of armor (requires attunement): While wearing this armor, a creature has resistance to one of the following damage types, which you choose when you infuse the item: acid, cold, fire, force, lightning, necrotic, poison, psychic, radiant, or thunder.",
  "Par de botas: Tus pasos no emiten sonido. Ventaja en pruebas de Destreza (Sigilo) para moverte en silencio.": "Boots of Elvenkind: While you wear these boots, your steps make no sound, regardless of the surface you are moving across, and you have advantage on Dexterity (Stealth) checks that rely on moving silently.",
  "Capa: Camuflaje óptico. Ventaja en Sigilo para esconderte y desventaja en Percepción ajena para verte.": "Cloak of Elvenkind (requires attunement): While you wear this cloak with its hood up, Wisdom (Perception) checks made to see you have disadvantage, and you have advantage on Dexterity (Stealth) checks made to hide.",
  "Lentes: Ventaja en Sabiduría (Percepción) visual y visión nítida a grandes distancias.": "Eyes of the Eagle (requires attunement): These crystal lenses fit over the eyes. While wearing them, you have advantage on Wisdom (Perception) checks that rely on sight, and in conditions of clear visibility, you can make out details of even extremely distant creatures and objects.",
  "Guantes: +5 a Destreza (Juego de Manos) y pruebas para forzar cerraduras con herramientas de ladrón.": "Gloves of Thievery: These gloves are invisible while worn. While wearing them, you gain a +5 bonus to Dexterity (Sleight of Hand) checks and Dexterity checks made to pick locks.",
  "Broche: Resistencia al daño de fuerza e inmunidad total al conjuro Proyectil Mágico.": "Brooch of Shielding (requires attunement): While wearing this brooch, you have resistance to force damage, and you have immunity to damage from the Magic Missile spell.",
  "Sombrero: Permite lanzar el conjuro Disfrazarse a voluntad sin gastar ranuras.": "Hat of Disguise (requires attunement): While wearing this hat, you can use an action to cast the Disguise Self spell from it at will.",
  "Flauta: 3 cargas. Tocarla asusta a criaturas a 30 pies si fallan salvación Sabiduría CD 15 durante 1 min.": "Pipes of Haunting: These pipes have 3 charges. You can use an action to play them and expend 1 charge to create an eerie, spellbinding tune: each creature within 30 feet that hears you play must succeed on a DC 15 Wisdom saving throw or become frightened of you for 1 minute.",
  "Casco (requiere sintonización): Otorga ventaja en todas las tiradas de iniciativa e inmunidad a ser sorprendido mientras permanezcas consciente.": "Helm (requires attunement): While wearing this helm, a creature has advantage on initiative rolls. In addition, the wearer can't be surprised, provided it isn't incapacitated.",
  "Par de botas (requiere sintonización): Otorga velocidad de vuelo igual a tu velocidad hasta 4 horas al día.": "Winged Boots (requires attunement): While you wear these boots, you have a flying speed equal to your walking speed for up to 4 hours.",
  "Capa (requiere sintonización): Otorga +1 a la Clase de Armadura y +1 a todas las tiradas de salvación.": "Cloak of Protection (requires attunement): You gain a +1 bonus to AC and saving throws while you wear this cloak.",
  "Guanteletes (requiere sintonización): Fijan tu Fuerza en 19 mientras los lleves puestos.": "Gauntlets of Ogre Power (requires attunement): Your Strength score is 19 while you wear these gauntlets.",
  "Diadema (requiere sintonización): Fija tu Inteligencia en 19 mientras la lleves puesta.": "Headband of Intellect (requires attunement): Your Intelligence score is 19 while you wear this headband.",
  "Anillo (requiere sintonización): Inmune a telepatía, lectura mental y detección de mentiras.": "Ring of Mind Shielding (requires attunement): While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type.",
  "Botas (requiere sintonización): Velocidad mínima de 30 pies y triplica tu distancia de salto.": "Boots of Striding and Springing (requires attunement): While you wear these boots, your walking speed becomes 30 feet (unless your walking speed is higher), your speed isn't reduced if you are encumbered or wearing heavy armor, and you can jump three times the normal distance.",
  "Zapatillas (requiere sintonización): Caminas por paredes y techos sin manos a velocidad normal.": "Slippers of Spider Climbing (requires attunement): While you wear these light shoes, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free, with a climbing speed equal to your walking speed.",
  "Medallón (requiere sintonización): 3 cargas. Permite lanzar Detectar Pensamientos (CD 13).": "Medallion of Thoughts (requires attunement): The medallion has 3 charges. While wearing it, you can use an action and expend 1 charge to cast the Detect Thoughts spell (save DC 13) from it.",
  "Amuleto (requiere sintonización): Fija tu Constitución en 19 mientras lo lleves puesto.": "Amulet of Health (requires attunement): Your Constitution score is 19 while you wear this amulet.",
  "Cinturón (requiere sintonización): Fija tu Fuerza en 21 (+5 mod) mientras lo lleves puesto.": "Belt of Hill Giant Strength (requires attunement): While wearing this belt, your Strength score changes to 21 (+5 modifier).",
  "Botas (requiere sintonización): Acción adicional: duplica tu velocidad y desventaja a ataques de oportunidad contra ti durante 10 min.": "Boots of Speed (requires attunement): While you wear these boots, you can use a bonus action to click the boots' heels together, doubling your walking speed and imposing disadvantage on opportunity attacks against you for up to 10 minutes.",
  "Capa (requiere sintonización): Ventaja en Sigilo, vuelo 40 pies en penumbra o polimorfia en murciélago.": "Cloak of the Bat (requires attunement): While wearing this cloak, you have advantage on Dexterity (Stealth) checks. In an area of dim light or darkness, you can grip the edges of the cloak with both hands and use it to fly at a speed of 40 feet, or cast Polymorph on yourself to transform into a bat once per day.",
  "Gema (requiere sintonización): 3 cargas. Concede Visión Verdadera 120 pies durante 10 minutos.": "Gem of Seeing (requires attunement): This gem has 3 charges. As an action, you can speak the gem's command word and expend 1 charge; for the next 10 minutes, you have truesight out to 120 feet when you peer through the gem.",
  "Anillo (requiere sintonización): Otorga +1 a la Clase de Armadura y +1 a todas tus tiradas de salvación.": "Ring of Protection (requires attunement): You gain a +1 bonus to AC and saving throws while wearing this ring.",
  "Anillo (requiere sintonización): Ignoras terreno difícil y eres inmune a ser Paralizado o retenido.": "Ring of Free Action (requires attunement): While you wear this ring, difficult terrain doesn't cost you extra movement, and magic can neither reduce your speed nor cause you to be paralyzed or restrained.",
  "Brazales (requiere sintonización): Competencia con arcos cortos y largos, y +2 al daño de ataques a distancia con ellos.": "Bracers of Archery (requires attunement): While wearing these bracers, you have proficiency with the longbow and shortbow, and you gain a +2 bonus to damage rolls on ranged attacks made with such weapons.",
  "Permite forjar y modificar armas de metal, armaduras pesadas y escudos.": "Allows you to forge, repair, and modify metal weapons, heavy armor, and shields.",
  "Permite elaborar pociones, elixires, ácidos, solventes y reactivos arcanos.": "Allows you to brew potions, elixirs, acids, alchemical fire, and arcane reagents.",
  "Permite reparar mecanismos arcanos, autómatas, relojes y dispositivos pequeños.": "Allows you to construct and repair arcane mechanisms, clockwork devices, automatons, and small gadgets.",
  "Permite engarzar gemas mágicas, tallar anillos y canalizadores arcanos.": "Allows you to cut and set magical gems, craft rings, and fashion arcane foci.",
  "Permite confeccionar armaduras de cuero, vainas y correajes reforzados.": "Allows you to craft and repair leather armor, scabbards, boots, and reinforced harnesses.",
  "Permite construir estructuras de madera, carretas, balistas y fortificaciones.": "Allows you to build wooden structures, wagons, siege engines, and fortifications.",
  "Permite moldear viales alquímicos, lentes arcanas, frascos y espejos.": "Allows you to blow and shape alchemical vials, arcane lenses, flasks, and mirrors.",
  "Permite esculpir piedra, detectar debilidades en murallas y abrir pasadizos.": "Allows you to carve stone, spot structural weaknesses in walls, and construct masonry.",
  "Permite moldear recipientes cerámicos estancos, jarras herméticas y crisoles.": "Allows you to shape watertight ceramic vessels, jugs, urns, and crucibles.",
  "Permite confeccionar túnicas arcanas, capas protectoras y vestimentas mágicas.": "Allows you to weave and mend arcane robes, protective cloaks, and fine garments.",
  "Permite transcribir pergaminos de conjuro, runas arcanas y glifos.": "Allows you to transcribe spell scrolls, arcane runes, sigils, and fine manuscripts.",
  "Permite trazar mapas topográficos exactos y registrar rutas subterráneas.": "Allows you to draft accurate topographic maps and chart overland or subterranean routes.",
  "Permite fermentar brebajes reconstituyentes, tónicos y estimulantes herbales.": "Allows you to brew ales, restorative draughts, tonics, and fermented beverages.",
  "Permite cocinar raciones nutritivas que mejoran los puntos de golpe en descansos.": "Allows you to prepare hearty, nourishing meals that bolster recovery during rests.",
  "Permite reforzar el calzado del grupo para evitar agotamiento en marchas forzadas.": "Allows you to mend and reinforce footwear to help prevent exhaustion during long marches.",
  "Optimizado para primera línea y protección. Guanteletes Atronadores (Thunder Gauntlets): arma simple cuerpo a cuerpo (1d8 de daño trueno usando mod Int); al golpear a un enemigo, este tiene desventaja en tiradas de ataque contra cualquiera que no seas tú hasta tu próximo turno. Campo Defensivo (Defensive Field): como acción adicional obtienes PG temporales iguales a tu nivel de artífice (usos = bonificador de competencia por descanso largo).": "Optimized for frontline defense and protection. Thunder Gauntlets: each of the armor's gauntlets counts as a simple melee weapon (1d8 thunder damage using your Intelligence modifier); a creature hit by the gauntlet has disadvantage on attack rolls against targets other than you until the start of your next turn. Defensive Field: as a bonus action, you gain temporary hit points equal to your level in this class (proficiency bonus uses per long rest).",
  "Optimizado para sigilo y combate táctico a distancia. Lanza-Relámpagos (Lightning Launcher): arma simple a distancia (alcance 90/300 pies) que inflige 1d6 de daño de relámpago con mod Int; una vez en cada uno de tus turnos, al golpear con ella puedes añadir 1d6 de daño relámpago extra. Pasos Potenciados (Powered Steps): +5 pies a tu velocidad de movimiento caminando. Campo Amortiguador (Dampening Field): ventaja en pruebas de Destreza (Sigilo).": "Optimized for stealth and ranged tactical combat. Lightning Launcher: a gemlike node counts as a simple ranged weapon (range 90/300 feet) that deals 1d6 lightning damage using your Intelligence modifier; once on each of your turns when you hit a creature with it, you can deal an extra 1d6 lightning damage to that target. Powered Steps: your walking speed increases by 5 feet. Dampening Field: you have advantage on Dexterity (Stealth) checks.",
  "Como acción adicional realizas un ataque de conjuro a distancia contra un objetivo a 120 pies o menos: inflige 2d8 de daño de fuerza (3d8 a Nv 9) y empuja al objetivo 5 pies lejos del cañón. Puede ser Diminuto (en tu mano) o Pequeño (con patas mecánicas y 15 pies de movimiento).": "As a bonus action, make a ranged spell attack originating from the cannon at one creature or object within 120 feet of it: on a hit, the target takes 2d8 force damage (3d8 at 9th level), and if the target is a creature, it is pushed up to 5 feet away from the cannon. Can be Tiny (held in one hand) or Small (with mechanical legs and a 15-foot walking/climbing speed).",
  "Como acción adicional emite una llamarada en cono de 15 pies: cada criatura en el área debe superar una salvación de Destreza contra tu CD de conjuros o sufrir 2d8 de daño de fuego (3d8 a Nv 9; mitad si supera). Prende fuego a objetos inflamables no portados.": "As a bonus action, the cannon exhales fire in an adjacent 15-foot cone that you designate: each creature in that area must make a Dexterity saving throw against your spell save DC, taking 2d8 fire damage (3d8 at 9th level) on a failed save or half as much damage on a successful one. The fire ignites any flammable objects in the area that aren't being worn or carried.",
  "Como acción adicional emite una onda protectora que concede a ti y a cada aliado a 10 pies o menos del cañón una cantidad de puntos de golpe temporales igual a 1d8 + tu modificador de Inteligencia cada turno.": "As a bonus action, the cannon emits a burst of positive energy that grants itself and each creature of your choice within 10 feet of it a number of temporary hit points equal to 1d8 + your Intelligence modifier (minimum of +1).",
  "Leal constructo mecánico de 4 patas. CA 15 (17 a Nv 15), PG = 2 + Int mod + (5 × nivel de artífice), dados de golpe d8 iguales a tu nivel. Acciones con tu acción adicional: Golpe Contundente (1d8 + PB daño de fuerza), Reparar (restaura 2d8 + PB PG, 3/descanso largo). Reacción: Desviar Ataque (desventaja al atacante contra aliados adyacentes; inflige 1d4 + Int daño fuerza a Nv 15). Listo para la Batalla: atacas con armas mágicas usando Inteligencia para ataque y daño.": "Loyal 4-legged mechanical construct. AC 15 (17 at 15th level), HP = 2 + Intelligence modifier + (5 × artificer level), d8 Hit Dice equal to your level. Bonus action commands: Force-Empowered Rend (1d8 + proficiency bonus force damage), Repair (restores 2d8 + proficiency bonus HP, 3/day). Reaction: Deflect Attack (imposes disadvantage on an attack roll against a creature within 5 feet; deals 1d4 + Intelligence modifier force damage at 15th level). Battle Ready: you can use your Intelligence modifier for magic weapon attack and damage rolls.",
  "Leal constructo humanoide de 2 piernas con chasis reforzado. CA 15 (17 a Nv 15), PG = 2 + Int mod + (5 × nivel de artífice), dados de golpe d8 iguales a tu nivel. Acciones con tu acción adicional: Golpe Contundente (1d8 + PB daño de fuerza), Reparar (restaura 2d8 + PB PG, 3/descanso largo). Reacción: Desviar Ataque. Listo para la Batalla: atacas con armas mágicas usando Inteligencia para ataque y daño.": "Loyal 2-legged humanoid mechanical construct with a reinforced chassis. AC 15 (17 at 15th level), HP = 2 + Intelligence modifier + (5 × artificer level), d8 Hit Dice equal to your level. Bonus action commands: Force-Empowered Rend (1d8 + proficiency bonus force damage), Repair (restores 2d8 + proficiency bonus HP, 3/day). Reaction: Deflect Attack. Battle Ready: you can use your Intelligence modifier for magic weapon attack and damage rolls.",
  "La criatura que lo bebe recupera una cantidad de puntos de golpe igual a 2d4 + tu modificador de Inteligencia.": "The drinker regains a number of hit points equal to 2d4 + your Intelligence modifier.",
  "La criatura que lo bebe obtiene un bonificador de +10 pies a su velocidad de movimiento caminando durante 1 hora.": "The drinker's walking speed increases by 10 feet for 1 hour.",
  "La criatura que lo bebe obtiene un bonificador de +1 a su Clase de Armadura durante 10 minutos.": "The drinker gains a +1 bonus to AC for 10 minutes.",
  "La criatura que lo bebe gana 10 puntos de golpe temporales. A nivel 9 se suman 2d6 + Int adicionales.": "The drinker can roll a d4 and add the number rolled to every attack roll and saving throw they make for the next minute (or gains 10 temporary hit points, plus 2d6 + your Intelligence modifier at 9th level).",
  "La criatura que lo bebe obtiene una velocidad de vuelo de 10 pies durante 10 minutos.": "The drinker gains a flying speed of 10 feet for 10 minutes.",
  "La criatura que lo bebe queda bajo los efectos del conjuro Alterar el Propio Ser (adaptación acuática, apariencia o armas naturales) durante 10 minutos.": "The drinker's body is transformed as if by the Alter Self spell (aquatic adaptation, change appearance, or natural weapons) for 10 minutes.",
  "Fiend (Diablo Menor), CA 13, PG 10, Vuelo 40 pies. Forma cambiante (rata, cuervo, araña). Invisibilidad mágica a voluntad. Aguijón venenoso (1d4+3 perforante + 3d6 veneno si falla salvación de Constitución). Resistencia mágica a conjuros. Visión en la oscuridad diabólica (120 pies, penetra oscuridad mágica).": "Fiend (Devil), AC 13, HP 10, Fly 40 ft. Shapechanger (rat, raven, spider). Invisibility at will. Venomous Sting (1d4 + 3 piercing + 3d6 poison damage on a failed DC 11 Constitution save, or half on a success). Magic Resistance. Devil's Sight (120-foot darkvision that penetrates magical darkness).",
  "Fiend (Demonio del Caos), CA 13, PG 7, Velocidad 40 pies. Forma cambiante (murciélago, ciempiés, sapo). Garra venenosa (1d4+3 cortante + envenenado por 1 minuto si falla salvación de Constitución CD 10). Miedo (1 vez al día asusta a criatura a 20 pies). Invisibilidad a voluntad y Resistencia mágica.": "Fiend (Demon), AC 13, HP 7, Speed 40 ft. Shapechanger (bat, centipede, toad). Claws (1d4 + 3 piercing + 2d4 poison damage and poisoned for 1 minute on a failed DC 10 Constitution save). Scare (1/day, frightens a creature within 20 feet). Invisibility at will and Magic Resistance.",
  "Dragón Diminuto, CA 13, PG 7, Vuelo 60 pies. Sentidos agudos (ventaja en Percepción), Percepción ciega 10 pies. Aguijón somnífero (1d4+2 perforante + veneno que duerme a la víctima). Telepatía de 100 pies y Resistencia mágica compartida.": "Tiny Dragon, AC 13, HP 7, Fly 60 ft. Keen Senses (advantage on Perception checks), Blindsight 10 ft. Sting (1d4 + 2 piercing + poison that poisons and renders the target unconscious on a failed DC 11 Constitution save). Limited Telepathy (100 feet) and shared Magic Resistance.",
  "Fey Diminuto, CA 15, PG 2, Vuelo 40 pies. Sentido del corazón (conoce el alineamiento y estado emocional de criaturas al tocarlas). Flechas del sueño a distancia. Invisibilidad a voluntad.": "Tiny Fey, AC 15, HP 2, Fly 40 ft. Heart Sight (knows a creature's current emotional state and alignment by touch). Shortbow ranged sleep arrows. Invisibility at will.",
  "El idioma universal hablado por casi todas las civilizaciones humanoides.": "The universal trade and everyday language spoken by nearly all humanoid civilizations.",
  "Lengua fluida y melodiosa con intrincadas inflexiones poéticas.": "A fluid, melodic language with intricate poetic inflections.",
  "Idioma gutural y resonante tallado en runas angulares.": "A guttural, resonant language carved in angular runes.",
  "Dialecto ancestral derivado del enano, hablado por gigantes y ogros.": "An ancient language using the Dwarvish script, spoken by giants and ogres.",
  "Lenguaje técnico, curioso y vivaz con amplio vocabulario académico.": "A technical, inquisitive, and lively language with a vast scholarly vocabulary.",
  "Habla áspera y rápida compartida por goblins, hobgoblins y osgos.": "A harsh, rapid tongue shared by goblins, hobgoblins, and bugbears.",
  "Lengua cálida y hospitalaria, rara vez escrita en libros formales.": "A warm, hospitable language of oral traditions, rarely written in formal books.",
  "Lenguaje contundente y marcial de fonética dura.": "A forceful, martial language with harsh phonetics.",
  "La lengua caótica y resonante de los demonios del Abismo.": "The chaotic, resonant language of the demons of the Abyss.",
  "Idioma sacro y majestuoso de los ángeles y planos superiores.": "The sacred, majestic language of angels and the Upper Planes.",
  "Uno de los idiomas más antiguos del multiverso, hablado por dragones y hechiceros.": "One of the oldest languages in the multiverse, spoken by dragons, dragonborn, and arcane scholars.",
  "Lengua alienígena y perturbadora de los azotamentes y el Reino Lejano.": "The alien, unsettling language of mind flayers, beholders, and Far Realm entities.",
  "La lengua legal y calculadora de los diablos de los Nueve Infiernos.": "The lawful, calculating language of the devils of the Nine Hells.",
  "El idioma de los elementales: incluye dialectos Áurico, Acuano, Ígneo y Terrano.": "The language of elementals, encompassing the Auran, Aquan, Ignan, and Terran dialects.",
  "La lengua mística y caprichosa de las hadas y seres del Feywild.": "The mystical, whimsical language of fey creatures and the Feywild.",
  "El idioma de intercambio del Inframundo (Underdark).": "The trade language of the subterranean Underdark.",
  "1d8 perforante, sutil (Finesse). Ideal para daño ágil con Destreza.": "1d8 piercing, finesse. Ideal for agile Dexterity-based combat.",
  "1d6 cortante, sutil, ligera. Permite combate con dos armas.": "1d6 slashing, finesse, light. Enables two-weapon fighting.",
  "1d6 perforante, sutil, ligera. Versátil y clásica.": "1d6 piercing, finesse, light. Versatile and classic.",
  "1d8 cortante (1d10 versátil). Estilo clásico de espadachín élfico a una mano.": "1d8 slashing (1d10 versatile). Classic elven bladesinger weapon.",
  "1d4 cortante, sutil, alcance 10 pies. Permite atacar fuera del alcance cuerpo a cuerpo del rival.": "1d4 slashing, finesse, reach (10 ft.). Allows striking from outside an opponent's melee reach.",
  "1d4 perforante, sutil, ligera, arrojadiza (20/60 pies).": "1d4 piercing, finesse, light, thrown (range 20/60 ft.).",
  "Cuando empuñas un arma cuerpo a cuerpo en una mano y ninguna otra arma, ganas un bonificador de +2 a las tiradas de daño con esa arma.": "When you are wielding a melee weapon in one hand and no other weapons, you gain a +2 bonus to damage rolls with that weapon.",
  "Cuando luchas con dos armas, puedes sumar tu modificador de característica al daño del segundo ataque realizado con tu acción adicional.": "When you engage in two-weapon fighting, you can add your ability modifier to the damage of the second attack.",
  "Mantener el equilibrio en superficies estrechas o resbaladizas y realizar maniobras gimnásticas.": "Stay on your feet in tricky situations, balance on narrow or slippery surfaces, and perform acrobatic stunts.",
  "Conocimiento sobre magia, conjuros, objetos mágicos, planos de existencia y tradiciones arcanas.": "Recall lore about spells, magic items, eldritch symbols, magical traditions, and the planes of existence.",
  "Escalar, saltar, nadar y realizar pruebas de fuerza física sostenida o agarres.": "Climb, jump, swim, grapple, and perform feats of sustained physical strength.",
  "Ocultar la verdad mediante mentiras convincentes, disfraces, medias verdades o intenciones veladas.": "Hide the truth, either verbally or through your actions, using convincing lies, disguises, or misdirection.",
  "Recordar hechos históricos, reinos legendarios, dinastías, guerras antiguas y civilizaciones caídas.": "Recall lore about historical events, legendary people, ancient kingdoms, past disputes, wars, and lost civilizations.",
  "Cautivar a un público mediante la música, el canto, la poesía, la danza o la oratoria teatral.": "Delight an audience with music, dance, acting, storytelling, or some other form of entertainment.",
  "Influir en otros mediante amenazas veladas, hostilidad física o demostraciones de poderío.": "Influence someone through overt threats, hostile actions, and physical violence.",
  "Hurtar bolsillos, ocultar pequeños objetos en la manga o realizar trucos de prestidigitación.": "Pick pockets, conceal small objects on your person, or perform acts of legerdemain and manual trickery.",
  "Diagnosticar enfermedades, estabilizar a aliados moribundos o identificar causas de muerte.": "Stabilize a dying companion, diagnose an illness, or determine the cause of death.",
  "Conocimiento sobre flora, fauna, ciclos biológicos, terrenos naturales y clima.": "Recall lore about terrain, plants and animals, the weather, and natural cycles.",
  "Detectar ruidos sutiles, emboscadas ocultas, olores y peligros sensoriales en el entorno.": "Spot, hear, or otherwise detect the presence of something, including hidden threats and subtle noises.",
  "Leer el lenguaje corporal ajeno, intuir verdaderas intenciones y detectar mentiras.": "Determine the true intentions of a creature, such as when searching out a lie or predicting someone's next move.",
  "Negociar con tacto, conseguir favores y apelar a la razón con simpatía y elocuencia.": "Influence someone or a group of people with tact, social graces, or good nature.",
  "Conocimiento sobre dioses, cultos, símbolos sagrados, plegarias y jerarquías eclesiásticas.": "Recall lore about deities, rites and prayers, religious hierarchies, holy symbols, and the practices of secret cults.",
  "Moverse sin hacer ruido y esconderse entre las sombras o coberturas sin ser detectado.": "Conceal yourself from enemies, slink past guards, and slip away without being noticed.",
  "Rastrear presas, hallar comida y agua en la espesura y predecir el clima silvestre.": "Follow tracks, hunt wild game, guide your group through wastelands, identify signs of nearby creatures, and predict the weather.",
  "Calmar bestias salvajes, controlar monturas y percibir intenciones de animales.": "Calm down a domesticated animal, keep a mount from getting spooked, or intuit an animal's intentions.",
  "Desarmar trampas complejas y forzar cerraduras. Tu bonificador de competencia se duplica para cualquier prueba con estas herramientas.": "Disarm traps and pick locks. Your proficiency bonus is doubled for any ability check you make that uses your proficiency with thieves' tools.",
  "Siempre alerta ante cualquier peligro inminente.": "Always on the lookout for danger, you gain the following benefits:",
  "+5 de bonificador a tus tiradas de Iniciativa.": "You can't be surprised while you are conscious.",
  "No puedes ser sorprendido mientras permanezcas consciente.": "You gain a +5 bonus to initiative.",
  "Otras criaturas no ganan ventaja en tiradas de ataque contra ti por el mero hecho de que no puedas verlas.": "Other creatures don't gain advantage on attack rolls against you as a result of being unseen by you.",
  "Maestría legendaria en el uso de armas a distancia.": "You have mastered ranged weapons and can make shots that others find impossible. You gain the following benefits:",
  "Atacar al alcance largo de un arma a distancia no te impone desventaja.": "Attacking at long range doesn't impose disadvantage on your ranged weapon attack rolls.",
  "Tus ataques con armas a distancia ignoran la cobertura media y tres cuartos.": "Your ranged weapon attacks ignore half and three-quarters cover.",
  "Antes de hacer un ataque con un arma a distancia con la que seas competente, puedes elegir sufrir un penalizador de -5 a la tirada de ataque; si impactas, sumas +10 al daño.": "Before you make an attack with a ranged weapon that you are proficient with, you can choose to take a -5 penalty to the attack roll. If that attack hits, you add +10 to the attack's damage.",
  "Aprovechas la inercia devastadora de tus armas a dos manos.": "You've learned to put the weight of a weapon to your advantage, letting its momentum empower your strikes. You gain the following benefits:",
  "En tu turno, cuando consigas un impacto crítico con un arma cuerpo a cuerpo o reduzcas a una criatura a 0 PG con ella, puedes realizar un ataque cuerpo a cuerpo como acción adicional.": "On your turn, when you score a critical hit with a melee weapon or reduce a creature to 0 hit points with one, you can make one melee weapon attack as a bonus action.",
  "Antes de hacer un ataque cuerpo a cuerpo con un arma pesada competente, puedes elegir sufrir -5 a la tirada de ataque; si impactas, sumas +10 al daño.": "Before you make a melee attack with a heavy weapon that you are proficient with, you can choose to take a -5 penalty to the attack roll. If the attack hits, you add +10 to the attack's damage.",
  "Entrenado para lanzar conjuros en medio de la tormenta del combate cuerpo a cuerpo.": "You have practiced casting spells in the midst of combat, learning techniques that grant you the following benefits:",
  "Capacidad para lanzar al menos un conjuro": "The ability to cast at least one spell",
  "Tienes ventaja en tiradas de salvación de Constitución para mantener la concentración en un conjuro al recibir daño.": "You have advantage on Constitution saving throws that you make to maintain your concentration on a spell when you take damage.",
  "Puedes realizar los componentes somáticos de los conjuros incluso si empuñas armas o un escudo en una o ambas manos.": "You can perform the somatic components of spells even when you have weapons or a shield in one or both hands.",
  "Cuando el movimiento de una criatura hostil provoca un ataque de oportunidad por tu parte, puedes usar tu reacción para lanzarle un conjuro en lugar de atacar (el conjuro debe tener tiempo de lanzamiento de 1 acción y apuntar únicamente a esa criatura).": "When a hostile creature's movement provokes an opportunity attack from you, you can use your reaction to cast a spell at the creature, rather than making an opportunity attack. The spell must have a casting time of 1 action and must target only that creature.",
  "Tienes una suerte casi inexplicable que desafía las probabilidades.": "You have inexplicable luck that seems to kick in at just the right moment.\n\nYou have 3 luck points. Whenever you make an attack roll, an ability check, or a saving throw, you can spend one luck point to roll an additional d20. You can choose to spend one of your luck points after you roll the die, but before the outcome is determined. You choose which of the d20s is used for the attack roll, ability check, or saving throw.\n\nYou can also spend one luck point when an attack roll is made against you. Roll a d20 and then choose whether the attack uses the attacker's roll or yours.\n\nIf more than one creature spends a luck point to influence the outcome of a roll, the points cancel each other out; no additional dice are rolled.\n\nYou regain your expended luck points when you finish a long rest.",
  "Dominas técnicas para inmovilizar a tus enemigos e impedir su retirada.": "You have mastered techniques to take advantage of every drop in any enemy's guard, gaining the following benefits.",
  "Cuando impactas a una criatura con un ataque de oportunidad, su velocidad se reduce a 0 durante el resto del turno.": "When you hit a creature with an opportunity attack, the creature's speed becomes 0 for the rest of the turn.",
  "Las criaturas dentro de tu alcance provocan ataques de oportunidad por tu parte incluso si usan la acción de Destrabarse (Disengage).": "Creatures provoke opportunity attacks from you even if they take the Disengage action before leaving your reach.",
  "Cuando una criatura a 5 pies de ti ataca a un objetivo que no seas tú, puedes usar tu reacción para realizar un ataque cuerpo a cuerpo contra el atacante.": "When a creature within 5 feet of you makes an attack against a target other than you (and that target doesn't have this feat), you can use your reaction to make a melee weapon attack against the attacking creature.",
  "Extraordinariamente rápido y ágil para entrar y salir de la refriega.": "You are exceptionally speedy and agile. You gain the following benefits:",
  "Tu velocidad base aumenta en 10 pies.": "Your speed increases by 10 feet.",
  "Cuando usas la acción de Correr (Dash), el terreno difícil no te cuesta movimiento adicional en ese turno.": "When you use the Dash action, difficult terrain doesn't cost you extra movement on that turn.",
  "Cuando realizas un ataque cuerpo a cuerpo contra una criatura, no provocas ataques de oportunidad de esa criatura por el resto de tu turno, sin importar si el ataque acertó o falló.": "When you make a melee attack against a creature, you don't provoke opportunity attacks from that creature for the rest of the turn, whether you hit or not.",
  "Aguante físico y vitalidad que superan con creces los límites ordinarios.": "Your hit point maximum increases by an amount equal to twice your level when you gain this feat. Whenever you gain a level thereafter, your hit point maximum increases by an additional 2 hit points.",
  "Desarrollas una resistencia inquebrantable en una característica.": "Choose one ability score. You gain the following benefits:",
  "Aumentas la puntuación de la característica elegida en +1 (hasta un máximo de 20).": "Increase the chosen ability score by 1, to a maximum of 20.",
  "Ganas competencia en las tiradas de salvación de la característica elegida.": "You gain proficiency in saving throws using the chosen ability.",
  "Mantienes a raya a tus rivales con armas de gran alcance.": "You gain the following benefits:",
  "Cuando realizas la acción de Atacar únicamente con una alabarda, pica, bastón o lanza, puedes usar una acción adicional para golpear con el extremo opuesto (inflige 1d4 de daño contundente).": "When you take the Attack action and attack with only a glaive, halberd, quarterstaff, or spear, you can use a bonus action to make a melee attack with the opposite end of the weapon. This attack uses the same ability modifier as the primary attack. The weapon's damage die for this attack is a d4, and it deals bludgeoning damage.",
  "Mientras empuñas una alabarda, pica, bastón o lanza, otras criaturas provocan un ataque de oportunidad por tu parte cuando entran dentro de tu alcance.": "While you are wielding a glaive, halberd, pike, quarterstaff, or spear, other creatures provoke an opportunity attack from you when they enter the reach you have with that weapon.",
  "Maestría en blandir dos armas cuerpo a cuerpo al unísono.": "You master fighting with two weapons, gaining the following benefits:",
  "Ganas un bonificador de +1 a tu Clase de Armadura mientras sostengas un arma cuerpo a cuerpo distinta en cada mano.": "You gain a +1 bonus to AC while you are wielding a separate melee weapon in each hand.",
  "Puedes usar el combate con dos armas incluso cuando las armas de una mano que empuñas no tienen la propiedad ligera.": "You can use two-weapon fighting even when the one-handed melee weapons you are wielding aren't light.",
  "Puedes desenvainar o enfundar dos armas a la vez cuando normalmente solo podrías hacerlo con una.": "You can draw or stow two one-handed weapons when you would normally be able to draw or stow only one.",
  "Aprendes los secretos básicos de una tradición mágica ajena.": "Choose a class: bard, cleric, druid, sorcerer, warlock, or wizard. You learn two cantrips of your choice from that class's spell list.\n\nIn addition, choose one 1st-level spell to learn from that same list. Using this feat, you can cast the spell once at its lowest level, and you must finish a long rest before you can cast it in this way again.\n\nYour spellcasting ability for these spells depends on the class you chose: Charisma for bard, sorcerer, or warlock; Wisdom for cleric or druid; or Intelligence for wizard.",
  "Rápido para notar los detalles más sutiles a tu alrededor.": "Quick to notice details of your environment, you gain the following benefits:",
  "Aumentas tu Inteligencia o Sabiduría en +1 (máximo 20).": "Increase your Intelligence or Wisdom score by 1, to a maximum of 20.",
  "Si puedes ver la boca de una criatura mientras habla un idioma que conoces, puedes leer sus labios.": "If you can see a creature's mouth while it is speaking a language you understand, you can interpret what it's saying by reading its lips.",
  "Ganas un bonificador de +5 a tus puntuaciones pasivas de Sabiduría (Percepción) y de Inteligencia (Investigación).": "You have a +5 bonus to your passive Wisdom (Perception) and passive Intelligence (Investigation) scores.",
  "Disparas ballestas con una rapidez y precisión asombrosas.": "Thanks to extensive practice with the crossbow, you gain the following benefits:",
  "Ignoras la propiedad de recarga de las ballestas con las que tengas competencia.": "You ignore the loading quality of crossbows with which you are proficient.",
  "Estar a 5 pies o menos de una criatura hostil no impone desventaja a tus tiradas de ataque a distancia.": "Being within 5 feet of a hostile creature doesn’t impose disadvantage on your ranged attack rolls.",
  "Cuando usas la acción de Atacar y atacas con un arma a una mano, puedes usar una acción adicional para atacar con una ballesta de mano cargada que sostengas.": "When you use the Attack action and attack with a one handed weapon, you can use a bonus action to attack with a hand crossbow you are holding.",
  "Acondicionamiento físico intensivo para superar pruebas atléticas.": "You have undergone extensive physical training to gain the following benefits:",
  "Aumentas tu Fuerza o Destreza en +1 (máximo 20).": "Increase your Strength or Dexterity by 1, to a maximum of 20.",
  "Cuando estás derribado, ponerte de pie solo te cuesta 5 pies de movimiento en lugar de la mitad de tu velocidad.": "When you are prone, standing up uses only 5 feet of your movement.",
  "Trepar no te cuesta movimiento adicional.": "Climbing doesn't cost you extra movement.",
  "Solo necesitas moverte 5 pies a pie para realizar un salto de longitud o de altura con carrerilla.": "You can make a running long jump or a running high jump after moving only 5 feet on foot, rather than 10 feet.",
  "Habilidoso en la mímica, el engaño teatral y la impostura.": "Skilled at mimicry and dramatics, you gain the following benefits:",
  "Aumentas tu Carisma en +1 (máximo 20).": "Increase your Charisma score by 1, to a maximum of 20.",
  "Tienes ventaja en pruebas de Carisma (Engaño) y Carisma (Interpretación) cuando intentas hacerte pasar por otra persona.": "You have an advantage on Charisma (Deception) and Charisma (Performance) checks when trying to pass yourself off as a different person.",
  "Puedes imitar el habla de otra persona o los sonidos de otras criaturas tras escucharlas hablar durante al menos 1 minuto.": "You can mimic the speech of another person or the sounds made by other creatures. You must have heard the person speaking, or heard the creature make the sound, for at least 1 minute. A successful Wisdom (Insight) check contested by your Charisma (Deception) check allows a listener to determine that the effect is faked.",
  "El tiempo y la dedicación culinaria nutren el cuerpo y el espíritu.": "Time and effort spent mastering the culinary arts has paid off. You gain the following benefits:",
  "Aumentas tu Constitución o Sabiduría en +1 (máximo 20).": "Increase your Constitution or Wisdom score by 1, to a maximum of 20.",
  "Ganas competencia con las herramientas de cocinero.": "You gain proficiency with cook’s utensils if you don’t already have it.",
  "Durante un descanso corto, puedes preparar comida especial: cualquier aliado que gaste dados de golpe para curarse recupera 1d8 PG adicionales.": "As part of a short rest, you can cook special food, provided you have ingredients and cook's utensils on hand. You can prepare enough of this food for a number of creatures equal to 4 + your proficiency bonus. At the end of the short rest, any creature who eats the food and spends one or more Hit Dice to regain hit points regains an extra 1d8 hit points.",
  "Con 1 hora de trabajo o en un descanso largo puedes cocinar tantas golosinas como tu bono de competencia; comer una otorga PG temporales iguales a tu bono de competencia.": "With one hour of work or when you finish a long rest, you can cook a number of treats equal to your proficiency bonus. These special treats last 8 hours after being made. A creature can use a bonus action to eat one of those treats to gain temporary hit points equal to your proficiency bonus.",
  "Dominas la fuerza de los impactos contundentes para desplazar enemigos.": "You are practiced in the art of crushing your enemies, granting you the following benefits:",
  "Aumentas tu Fuerza o Constitución en +1 (máximo 20).": "Increase your Strength or Consititution score by 1, to a maximum of 20.",
  "Una vez por turno, cuando impactes a una criatura infligiéndole daño contundente, puedes empujarla 5 pies a un espacio desocupado si no es más de un tamaño mayor que tú.": "Once per turn, when you hit a creature with an attack that deals bludgeoning damage, you can move it 5 feet to an unoccupied space, provided the target is no more than one size larger than you.",
  "Cuando asestas un impacto crítico que inflige daño contundente, todas las tiradas de ataque contra esa criatura se hacen con ventaja hasta el inicio de tu próximo turno.": "When you score a critical hit that deals bludgeoning damage to a creature, attack rolls against that creature are made with advantage until the start of your next turn.",
  "Precisión mortal al clavar armas perforantes en puntos vulnerables.": "You have achieved a penetrating precision in combat, granting you the following benefits:",
  "Una vez por turno, cuando golpees a una criatura e inflijas daño perforante, puedes volver a tirar uno de los dados de daño del ataque y usar el nuevo resultado.": "Once per turn, when you hit a creature with an attack that deals piercing damage, you can re-roll one of the attack’s damage dice, and you must use the new roll.",
  "Cuando asestas un impacto crítico que inflige daño perforante, tiras un dado de daño adicional del arma al calcular el daño del crítico.": "When you score a critical hit that deals piercing damage to a creature, you can roll one additional damage die when determining the extra piercing damage the target takes.",
  "Cortas tendones y arterias para entorpecer los movimientos del rival.": "You've learned where to cut to have the greatest results, granting you the following benefits:",
  "Una vez por turno, cuando golpees e inflijas daño cortante, reduces la velocidad del objetivo en 10 pies hasta el inicio de tu siguiente turno.": "Once per turn when you hit a creature with an attack that deals slashing damage, you can reduce the speed of the target by 10 feet until the start of your next turn.",
  "Cuando asestas un impacto crítico que inflige daño cortante, la criatura sufre una herida grave: tiene desventaja en todas sus tiradas de ataque hasta el inicio de tu próximo turno.": "When you score a critical hit that deals slashing damage to a creature, you grievously wound it. Until the start of your next turn, the target has disadvantage on all attack rolls.",
  "Dominas el arte de disparar proyectiles mágicos a distancias extremas.": "You have learned techniques to enhance your attacks with certain kinds of spells, gaining the following benefits:",
  "Cuando lanzas un conjuro que requiere hacer una tirada de ataque, el alcance del conjuro se duplica.": "When you cast a spell that requires you to make an attack roll, the spell's range is doubled.",
  "Tus ataques de conjuro a distancia ignoran la cobertura media y tres cuartos.": "Your ranged spell attacks ignore half cover and three-quarters cover.",
  "Aprendes un truco que requiera una tirada de ataque de la lista de Bardo, Clérigo, Druida, Hechicero, Brujo o Mago.": "You learn one cantrip that requires an attack roll. Choose the cantrip from the bard, cleric, druid, sorcerer, warlock, or wizard spell list. Your spellcasting ability for this cantrip depends on the spell list you chose from: Charisma for bard, sorcerer, and warlock; Wisdom for cleric or druid; or Intelligence for wizard.",
  "Adoptas una doctrina marcial refinada de la orden de los guerreros.": "Your martial training has helped you develop a particular style of fighting. As a result, you learn one Fighting Style option of your choice from the fighter class. If you already have a style, the one you choose must be different.\n\nWhenever you reach a level that grants the Ability Score Improvement feature, you can replace this feat's fighting style with another one from the fighter class that you don't have.",
  "Competencia con un arma marcial": "Proficiency with a martial weapon",
  "Entrenamiento táctico en maniobras avanzadas de esgrima.": "You have martial training that allows you to perform special combat maneuvers. You gain the following benefits.",
  "Aprendes dos Maniobras a tu elección de la lista del arquetipo Maestro de Batalla del Guerrero.": "You learn two maneuvers of your choice from among those available to the Battle Master archetype in the fighter class. If a maneuver you use requires your target to make a saving throw to resist the maneuver's effects, the saving throw DC equals 8 + your proficiency bonus + your Strength or Dexterity modifier (your choice).",
  "Ganas 1 Dado de Superioridad (un d6) para alimentar estas maniobras, el cual recuperas tras un descanso corto o largo.": "You gain one superiority die, which is a d6 (this die is added to any superiority dice you have from another source). This die is used to fuel your maneuvers. A superiority die is expended when you use it. You regain your expended superiority dice when you finish a short or long rest.",
  "Aprendes a doblar y transformar las leyes del tejido mágico.": "You've learned how to exert your will on your spells to alter how they function:",
  "Rasgo de Conjuración o Magia del Pacto": "Spellcasting or Pact Magic feature",
  "Aprendes dos opciones de Metamagia a tu elección de la lista de la clase Hechicero.": "You learn two Metamagic options of your choice from the sorcerer class. You can use only one Metamagic option on a spell when you cast it, unless the option says otherwise. Whenever you reach a level that grants the Ability Score Improvement feature, you can replace one of these Metamagic options with another one from the sorcerer class.",
  "Ganas 2 Puntos de Hechicería para alimentar tu metamagia, los cuales recuperas tras un descanso largo.": "You gain 2 sorcery points to spend on Metamagic (these points are added to any sorcery points you have from another source but can be used only on Metamagic). You regain all spent sorcery points when you finish a long rest.",
  "Desbloqueas un fragmento de conocimiento oculto de las profundidades del cosmos.": "Studying occult lore, you learn one Eldritch Invocation option of your choice from the warlock class. Your spellcasting ability for the invocation is Intelligence, Wisdom, or Charisma (choose when you select this feat). If the invocation has a prerequisite of any kind, you can choose that invocation only if you’re a warlock who meets the prerequisite.\n\nWhenever you gain a level, you can replace the invocation with another one from the warlock class.",
  "Tu dominio sobre una fuerza elemental pura penetra las resistencias enemigas.": "Dote oficial de D&D 5e.",
  "Has dedicado tiempo a aprender una amplia variedad de artes prácticas y conocimientos.": "You gain proficiency in any combination of three skills or tools of your choice.",
  "Ganas competencia en 3 habilidades o herramientas a tu elección.": "You gain proficiency in any combination of three skills or tools of your choice.",
  "Perfeccionas tus talentos hasta alcanzar un grado extraordinario de maestría.": "You have honed your proficiency with particular skills, granting you the following benefits:",
  "Aumentas una puntuación de característica a tu elección en +1 (hasta un máximo de 20).": "Increase one ability score of your choice by 1, to a maximum of 20.",
  "Ganas pericia (doble competencia) en una habilidad en la que ya tengas competencia.": "Choose one skill in which you have proficiency. You gain expertise with that skill, which means your proficiency bonus is doubled for any ability check you make with it. The skill you choose must be one that isn't already benefiting from a feature, such as Expertise, that doubles your proficiency bonus.",
  "Infundes coraje y determinación en tus compañeros con discursos memorables.": "You can spend 10 minutes inspiring your companions, shoring up their resolve to fight. When you do so, choose up to six friendly creatures (which can include yourself) within 30 feet of you who can see or hear you and who can understand you. Each creature can gain temporary hit points equal to your level + your Charisma modifier. A creature can't gain temporary hit points from this feat again until it has finished a short or long rest.",
  "Carisma 13 o superior": "Charisma 13 or higher",
  "Médico de campo capaz de salvar vidas y vendar heridas en plena batalla.": "You are an able physician, allowing you to mend wounds quickly and get your allies back in the fight. You gain the following benefits:",
  "Cuando usas un estuche de curaciones para estabilizar a una criatura moribunda, esta recupera 1 punto de golpe en lugar de permanecer inconsciente a 0 PG.": "When you use a healer's kit to stabilize a dying creature, that creature also regains 1 hit point.",
  "Como acción puedes gastar un uso de un estuche de curaciones para atender a una criatura: recupera 1d6 + 4 PG, más tantos PG adicionales como el número de dados de golpe máximos de la criatura (1 vez por criatura por descanso corto o largo).": "As an action you can spend one use of a healer's kit to tend to a creature and restore 1d6 + 4 hit points to it, plus additional hit points equal to the creature's maximum number of Hit Dice. The creature can't regain hit points from this feat again until it finishes a short or long rest.",
  "Acostumbrado a peleas cuerpo a cuerpo con botellas rotas, sillas y puños limpios.": "Accustomed to the rough-and-tumble fighting using whatever weapons happen to be at hand, you gain the following benefits:",
  "Tienes competencia con armas improvisadas.": "You are proficient with improvised weapons.",
  "Tus ataques desarmados usan un d4 para el daño en lugar del 1 estándar.": "Your unarmed strike uses a d4 for damage.",
  "Cuando golpeas a una criatura con un ataque desarmado o arma improvisada en tu turno, puedes usar una acción adicional para intentar apresarla (Grapple).": "When you hit a creature with an unarmed strike or an improvised weapon on your turn, you can use a bonus action to attempt to grapple the target.",
  "Usas el grosor de las placas de acero para disipar la violencia de los golpes.": "You can use your armor to deflect strikes that would kill others. You gain the following benefits:",
  "Competencia con armadura pesada": "Proficiency with heavy armor",
  "Aumentas tu Fuerza en +1 (máximo 20).": "Increase your Strength score by 1, to a maximum of 20.",
  "Mientras lleves puesta una armadura pesada, el daño contundente, perforante y cortante que recibas proveniente de ataques no mágicos se reduce en 3 puntos.": "While you are wearing heavy armor, bludgeoning, piercing, and slashing damage that you take from nonmagical attacks is reduced by 3.",
  "Mueves armaduras de mallas y escamas con silenciosa presteza.": "You have practiced moving in medium armor to gain the following benefits:",
  "Competencia con armadura media": "Proficiency with medium armor",
  "Llevar armadura media no te impone desventaja en las pruebas de Destreza (Sigilo).": "Wearing medium armor doesn't impose disadvantage on your Dexterity (Stealth) checks.",
  "Cuando lleves armadura media, puedes sumar hasta +3 de tu modificador de Destreza a tu Clase de Armadura en lugar del tope estándar de +2.": "When you wear medium armor, you can add 3, rather than 2, to your AC if you have a Dexterity of 16 or higher.",
  "Despiertas la habilidad de mover materia con el mero poder de tu mente.": "You learn to move things with your mind, granting you the following benefits:",
  "Aumentas tu Inteligencia, Sabiduría o Carisma en +1 (máximo 20).": "Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20.",
  "Aprendes el truco Mano de Mago (invisible y con alcance ampliado en 30 pies si ya lo conoces).": "You learn the *mage hand* cantrip. You can cast it without verbal or somatic components, and you can make the spectral hand invisible. If you already know this spell, its range increases by 30 feet when you cast it. Its spellcasting ability is the ability increased by this feat.",
  "Como acción adicional puedes empujar o atraer telequinéticamente a una criatura a 30 pies hasta 5 pies hacia ti o lejos de ti (salvación de Fue contra CD 8 + bono de competencia + modificador de la característica elegida).": "As a bonus action, you can try to telekinetically shove one creature you can see within 30 feet of you. When you do so, the target must succeed on a Strength saving throw (DC 8 + your proficiency bonus + the ability modifier of the score increased by this feat) or be moved 5 feet toward or away from you. A creature can willingly fail this save.",
  "Proyectas tus pensamientos en las mentes ajenas y lees sus susurros.": "You awaken the ability to mentally connect with others, granting you the following benefits:",
  "Puedes hablar telepáticamente con cualquier criatura que veas a 60 pies o menos (entiende si comparte un idioma contigo).": "You can speak telepathically to any creature you can see within 60 feet of you. Your telepathic utterances are in a language you know, and the creature understands you only if it knows that language. Your communication doesn't give the creature the ability to respond to you telepathically.",
  "Puedes lanzar el conjuro Detectar Pensamientos sin gastar ranura de conjuro una vez por descanso largo.": "You can cast the Detect Thoughts spell, requiring no spell slot or components, and you must finish a long rest before you can cast it this way again. Your spellcasting ability for the spell is the ability increased by this feat. If you have spell slots of 2nd level or higher, you can cast this spell with them.",
  "Tu exposición a las Tierras de las Hadas te imbuye de magia feérica sutil.": "Your exposure to the Feywild's magic has changed you, granting you the following benefits:",
  "Tu contacto con el Páramo Sombrío te concede el poder de desvanecerte.": "Your exposure to the Shadowfell's magic has changed you, granting you the following benefits:",
  "Ojo clínico para detectar trampas mortales y puertas secretas en catacumbas.": "Alert to the hidden traps and secret doors found in many dungeons, you gain the following benefits:",
  "Tienes ventaja en pruebas de Sabiduría (Percepción) e Inteligencia (Investigación) para detectar puertas secretas.": "You have advantage on Wisdom (Perception) and Intelligence (Investigation) checks made to detect the presence of secret doors.",
  "Tienes ventaja en tiradas de salvación para evitar o resistir trampas.": "You have advantage on saving throws made to avoid or resist traps.",
  "Tienes resistencia al daño infligido por trampas.": "You have resistance to the damage dealt by traps.",
  "Puedes viajar a un ritmo de viaje rápido y seguir buscando trampas activamente.": "Travelling at a fast pace doesn't impose the normal -5 penalty on your passive Wisdom (Perception) score.",
  "Empleas tu escudo tanto para defensa impenetrable como para desestabilizar rivales.": "You use shields not just for protection but also for offense. You gain the following benefits while you are wielding a shield:",
  "Si realizas la acción de Atacar en tu turno, puedes usar una acción adicional para intentar empujar a una criatura a 5 pies de ti con tu escudo (derribarla o empujarla 5 pies).": "If you take the Attack action on your turn, you can use a bonus action to try to shove a creature within 5 feet of you with your shield.",
  "Si no estás incapacitado, puedes sumar el bonificador de CA de tu escudo a cualquier tirada de salvación de Destreza que realices contra un conjuro u otro efecto dañino dirigido únicamente a ti.": "If you aren't incapacitated, you can add your shield's AC bonus to any Dexterity saving throw you make against a spell or other harmful effect that targets only you.",
  "Si estás sometido a un efecto que te permita hacer una tirada de salvación de Destreza para sufrir solo la mitad del daño, puedes usar tu reacción para interponer tu escudo; si superas la salvación, no sufres daño alguno.": "If you are subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you can use your reaction to take no damage if you succeed on the saving throw, interposing your shield between yourself and the source of the effect.",
  "Desvías estocadas y cortes en el último instante con la punta de tu hoja.": "When you are wielding a finesse weapon with which you are proficient and another creature hits you with a melee attack, you can use your reaction to add your proficiency bonus to your AC for that attack, potentially causing the attack to miss you.",
  "Destreza 13 o superior": "Dexterity 13 or higher",
  "Cuando empuñas un arma sutil con la que eres competente y otra criatura te impacta con un ataque cuerpo a cuerpo, puedes usar tu reacción para sumar tu bonificador de competencia a tu CA para ese ataque, lo que potencialmente puede hacer que el ataque falle.": "When you are wielding a finesse weapon with which you are proficient and another creature hits you with a melee attack, you can use your reaction to add your proficiency bonus to your AC for that attack, potentially causing the attack to miss you.",
  "Entrenado rigurosamente en técnicas especializadas para abatir hechiceros y arcanistas.": "You have practiced techniques in melee combat against spellcasters, gaining the following benefits.",
  "Cuando una criatura a 5 pies o menos de ti lance un conjuro, puedes usar tu reacción para realizar un ataque con arma cuerpo a cuerpo contra esa criatura.": "When a creature within 5 feet of you casts a spell, you can use your reaction to make a melee weapon attack against that creature.",
  "Cuando inflijas daño a una criatura que se esté concentrando en un conjuro, esa criatura tiene desventaja en la tirada de salvación de Constitución que realice para mantener la concentración.": "When you damage a creature that is concentrating on a spell, that creature has disadvantage on the saving throw it makes to maintain its concentration.",
  "Tienes ventaja en todas las tiradas de salvación contra conjuros lanzados por criaturas que se encuentren a 5 pies o menos de ti.": "You have advantage on saving throws against spells cast by creatures within 5 feet of you.",
  "Experto en fundirse con las sombras y cazar desde la más absoluta penumbra.": "You are an expert at slinking through shadows. You gain the following benefits:",
  "Puedes intentar esconderte cuando estés solo ligeramente oscurecido desde el punto de vista de la criatura de la que te ocultas.": "You can try to hide when you are lightly obscured from the creature from which you are hiding.",
  "Cuando estés oculto de una criatura y falles una tirada de ataque con arma a distancia, hacer el ataque no revela tu posición oculta.": "When you are hidden from a creature and miss it with a ranged weapon attack, making the attack doesn't reveal your position.",
  "La luz tenue no te impone desventaja en las pruebas de Sabiduría (Percepción) basadas en la vista.": "Dim light doesn't impose disadvantage on your Wisdom (Perception) checks relying on sight.",
  "Has adquirido un grimorio ritual que te permite desatar magia ceremonial sin gastar ranuras.": "You have learned a number of spells that you can cast as rituals. These spells are written in a ritual book, which you must have in hand while casting one of them.",
  "Inteligencia o Sabiduría 13 o superior": "Intelligence or Wisdom 13 or higher",
  "Adquieres un libro de rituales con dos conjuros de nivel 1 con la etiqueta de ritual de la clase que elijas (Bardo, Clérigo, Druida, Hechicero, Brujo o Mago).": "When you choose this feat, you acquire a ritual book holding two 1st-level spells of your choice with the ritual tag from a chosen class list (bard, cleric, druid, sorcerer, warlock, or wizard).",
  "Puedes lanzar conjuros de tu libro como rituales si tienen la etiqueta de ritual y su nivel no supera la mitad de tu nivel de personaje (redondeado hacia arriba).": "Your spellcasting ability for these ritual spells is the same as the chosen class (Charisma for bard, sorcerer, or warlock; Wisdom for cleric or druid; Intelligence for wizard).",
  "Si encuentras nuevos conjuros rituales en pergaminos o libros, puedes transcribirlos a tu libro (requiere 2 horas y 50 po por nivel de conjuro).": "If you come across a spell in written form (such as a spell scroll or a wizard's spellbook), you might be able to add it to your ritual book if it is on the spell list for the class you chose, the spell's level can be no higher than half your level (rounded up), and it has the ritual tag (2 hours and 50 gp per level of the spell).",
  "Técnicas avanzadas de lucha cuerpo a cuerpo para inmovilizar a cualquier oponente.": "You've developed the skills necessary to hold your own in close-quarters grappling. You gain the following benefits:",
  "Fuerza 13 o superior": "Strength 13 or higher",
  "Tienes ventaja en las tiradas de ataque contra cualquier criatura a la que tengas apresada (grappled).": "You have advantage on attack rolls against a creature you are grappling.",
  "Puedes usar tu acción para intentar inmovilizar a una criatura apresada por ti. Realiza otra prueba de presa; si tienes éxito, tanto tú como la criatura adquieren la condición de Inmovilizado (Restrained) hasta que finalice la presa.": "You can use your action to try to pin a creature grappled by you. To do so, make another grapple check. If you succeed, you and the creature are both restrained until the grapple ends.",
  "Posees una memoria fotográfica prodigiosa y una orientación espacial infalible.": "You have a mind that can track time, direction, and detail with uncanny precision. You gain the following benefits.",
  "Aumentas tu Inteligencia en +1 (hasta un máximo de 20).": "Increase your Intelligence score by 1, to a maximum of 20.",
  "Siempre sabes en qué dirección está el norte.": "You always know which way is north.",
  "Siempre sabes con exactitud el número de horas que faltan para el próximo amanecer o atardecer.": "You always know the number of hours left before the next sunrise or sunset.",
  "Puedes recordar con absoluta precisión cualquier cosa que hayas visto u oído en el último mes.": "You can accurately recall anything you have seen or heard within the past month.",
  "Maestro de la filología, lenguas antiguas y criptografía hermética.": "You have studied languages and codes, gaining the following benefits:",
  "Aprendes tres idiomas adicionales a tu elección.": "You learn three languages of your choice.",
  "Puedes crear códigos y cifras escritos prácticamente indescifrables. Otros no pueden descifrarlo a menos que superen una prueba de Inteligencia (Investigación) con CD 8 + tu bono de competencia + tu modificador de Inteligencia.": "You can ably create written ciphers. Others can't decipher a code you create unless you teach them, they succeed on an Intelligence check (DC equal to your Intelligence score + your proficiency bonus), or they use magic to decipher it.",
  "Entrenamiento intensivo en el manejo marcial de diversas armas de guerra.": "You've learned to put the weight of a weapon to your advantage, letting its momentum empower your strikes. You gain the following benefits:",
  "Aumentas tu Fuerza o Destreza en +1 (hasta un máximo de 20).": "Increase your Strength or Dexterity score by 1, to a maximum of 20.",
  "Ganas competencia con cuatro armas simples o marciales a tu elección.": "Before you make a melee attack with a heavy weapon that you are proficient with, you can choose to take a -5 penalty to the attack roll. If the attack hits, you add +10 to the attack's damage.",
  "Te entrenas en vestir protecciones de cuero y tachones sin entorpecer tu agilidad.": "You have trained to master the use of light armor, gaining the following benefits.",
  "Ganas competencia con armaduras ligeras.": "You gain proficiency with light armor.",
  "Dominas la colocación y el porte de cotas de malla, corazas y escudos de acero.": "You have trained to master the use of medium armor and shields, gaining the following benefits:",
  "Competencia con armadura ligera": "Proficiency with light armor",
  "Ganas competencia con armaduras medias y con escudos.": "You gain proficiency with medium armor and shields.",
  "Soportas el tremendo peso de armaduras de placas completas sin perder solidez.": "You have trained to master the use of heavy armor, gaining the following benefits:",
  "Aumentas tu Fuerza en +1 (hasta un máximo de 20).": "Increase your Strength score by 1, to a maximum of 20.",
  "Ganas competencia con armaduras pesadas.": "You gain proficiency with heavy armor.",
  "Elaboras toxinas fulminantes e ignoras las resistencias convencionales al veneno.": "You can prepare and deliver deadly poisons, gaining the following benefits:",
  "Posees un talento sobrenatural para absorber artes, oficios y ciencias con suma facilidad.": "You have a knack for learning new things. You gain the following benefits:",
  "Humano, Semielfo o Semiorco": "Half-Elf, Half-Orc or Human",
  "La gracia mística de los elfos guía tus ataques hacia puntos críticos imposibles.": "Souce: Xanathar's Guide to Everything\n\nThe accuracy of elves is legendary, especially that of elf archers and spellcasters. You have uncanny aim with attacks that rely on precision rather than brute force. You gain the following benefits:",
  "Elfo o Semielfo": "Elf or Half-Elf",
  "Aumentas tu Destreza, Inteligencia, Sabiduría o Carisma en +1 (hasta un máximo de 20).": "Increase your Dexterity, Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20",
  "Siempre que tengas ventaja en una tirada de ataque que use Destreza, Inteligencia, Sabiduría o Carisma, puedes relanzar uno de los dados una vez.": "Whenever you have advantage on an attack roll using Dexterity, Intelligence, Wisdom, or Charisma, you can reroll one of the dice once.",
  "La sangre de la montaña revitaliza tus heridas en pleno intercambio de golpes.": "You have the blood of dwarf heroes flowing through your veins. You gain the following benefits:",
  "Enano": "Dwarf",
  "Aumentas tu Constitución en +1 (hasta un máximo de 20).": "Increase your Constitution score by 1, up to a maximum of 20.",
  "Siempre que uses la acción de Esquivar (Dodge) en combate, puedes gastar uno de tus Dados de Golpe para curarte: tiras el dado, sumas tu modificador de Constitución y recuperas esa cantidad de puntos de golpe.": "Whenever you take the Dodge action in combat, you can spend one Hit Die to heal yourself. Roll the die, add your Constitution modifier, and regain a number of hit points equal to the total (minimum of 1).",
  "Tu sangre demoníaca repele los fríos más extremos y los venenos más letales.": "Fiendish blood runs strong in you, unlocking a resilience akin to that possessed by some fiends. You gain the following benefits:",
  "Tiefling": "Tiefling",
  "Ganas resistencia al daño de frío y al daño de veneno.": "You have resistance to cold damage and poison damage.",
  "Tienes ventaja en las tiradas de salvación contra ser envenenado.": "You have advantage on saving throws against being poisoned.",
  "Tu aura de buena fortuna protege a tus aliados de desastres catastróficos.": "Your people have extraordinary luck, which you have learned to mystically lend to your companions whenever you see them falter. You're not sure how you do it, you just wish it, and it happens. Surely a sign of fortune's favor!",
  "Mediano": "Halfling",
  "Has absorbido magia primordial que te otorga un eco del poder colosal de los gigantes. Al elegir esta dote, seleccionas uno de los seis beneficios listados a continuación. Una vez por turno, cuando golpeas a un objetivo con un ataque de arma cuerpo a cuerpo o un ataque de arma a distancia usando un arma arrojadiza, puedes imbuir el ataque con un efecto adicional dependiendo del beneficio elegido.\n\nLa CD de las tiradas de salvación para estos efectos es igual a 8 + tu bonificador de competencia + tu modificador de Fuerza o Constitución. Puedes usar esta dote un número de veces igual a tu bonificador de competencia, y recuperas todos los usos gastados al completar un descanso largo.": "You have absorbed primeval magic that gives you an echo of the might of giants. When you take this feat, choose one of the benefits listed below. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect depending on the benefit you chose:",
  "Competencia con armas marciales o trasfondo Expósito de los Gigantes (Giant Foundling)": "Martial Weapon Proficiency or Giant Foundling Background",
  "Has estudiado la antigua magia rúnica de los gigantes. Aprendes el conjuro Comprender Idiomas (Comprehend Languages) y puedes lanzarlo como ritual sin gastar espacio de conjuro. Además, grabas runas mágicas en tu equipo tras cada descanso largo, permitiéndote lanzar los conjuros vinculados a cada runa una vez por descanso largo sin gastar espacios de conjuro.": "You’ve studied the magic of Giant runes, granting you the following benefits:",
  "Rasgo de Conjurador o trasfondo Grabador de Runas (Rune Carver)": "Spellcasting Feature or Rune Carver Background",
  "Te has entrenado al servicio de los venerables Caballeros de Solamnia. Has aprendido a montar con destreza inigualable y a canalizar el entrenamiento militar para asestar golpes devastadores.": "Your training in the ways of the Knights of Solamnia grants you these benefits:",
  "Trasfondo Caballero de Solamnia o competencia con armadura intermedia y armas marciales": "Dragonlance Campaign, Fighter or Paladin Class or Knight of Solamnia Background",
  "Montar o desmontar de una montura te cuesta solo 5 pies de movimiento en lugar de la mitad de tu velocidad.": "**Mount Up.** Mounting or dismounting costs you only 5 feet of movement.",
  "Ataque Preciso: Un número de veces igual a tu bonificador de competencia por descanso largo, cuando haces una tirada de ataque con arma y tienes ventaja, puedes añadir 1d8 al daño de impacto. Si el ataque falla, no gastas el uso.": "**Precise Strike.** Once per turn, when you make a weapon attack roll against a creature, you can cause the attack roll to have advantage. If the attack hits, you roll a d8 and add the number rolled as a bonus to the attack's damage roll. You can use this benefit a number of times equal to your proficiency bonus, but a use is expended only if the attack hits. You regain all expended uses when you finish a long rest.",
  "Has sido iniciado en los secretos arcanos de las tres lunas de Krynn (Solinari la Blanca, Lunitari la Roja o Nuitari la Negra), vinculando tu magia a su órbita divina.": "You've received training from magic-users affiliated with the Mages of High Sorcery.\n\nChoose one of the three moons of Krynn to influence your magic: the black moon, Nuitari; the red moon, Lunitari; or the white moon Solinari. You learn one cantrip of your choice from the Wizard spell list and two 1st-level spells based on the moon you choose, as specified in the Lunar Spells table.\n\n| Lunar Spells |\n\n| Moon | 1st-Level Spell |\n\n| Nuitari | Choose two from Dissonant Whispers, False Life, Hex, and Ray of Sickness |\n\n| Lunitari | Choose two from Color Spray, Disguise Self, Feather Fall, and Longstrider |\n\n| Solinari | Choose two from Comprehend Languages, Detect Evil and Good, Protection from Evil and Good, and Shield |\n\nYou can cast each of the chosen 1st-level spells without a spell slot, and you must finish a long rest before you can cast it in this way again. You can also cast the spells using any spell slots you have.\n\nYour spellcasting ability for this feat’s spells is Intelligence, Wisdom, or Charisma (choose when you select this feat).",
  "Trasfondo Mago de la Alta Hechicería o rasgo de lanzamiento de conjuros": "Dragonlance Campaign, Sorcerer or Wizard Class or Mage of High Sorcery Background",
  "Estás sintonizado con las energías cósmicas de los Planos Exteriores del multiverso, absorbiendo su magia y adquiriendo resistencia a sus energías primordiales.": "Your connection to an Outer Plane infuses you with the energy there. Choose a type of plane listed in the Planar Infusion Table. Your choice gives you a resistance to a damage type and the ability to cast a cantrip, as specified in the table. You can cast this cantrip without material components, and your spellcasting ability for it is Intelligence, Wisdom or Charisma (choose when you select this feat).\n\n| Plane | Resistance | Cantrip |\n\n| Chaotic Outer Plane | Poison | Minor Illusion |\n\n| Evil Outer Plane | Necrotic | Chill Touch |\n\n| Good Outer Plane | Radiant | Sacred Flame |\n\n| Lawful Outer Plane | Force | Guidance |\n\n| The Outlands | Psychic | Mage Hand |",
  "Trasfondo Guardián del Portal o Filósofo Planar": "Planescape Campaign.",
  "Has completado tu primer año de estudios en la célebre universidad arcana de Strixhaven, aprendiendo las disciplinas fundamentales de uno de sus cinco colegios.": "You have studied some magical theory and have learned a few spells associated with Strixhaven University.\n\nChoose one of Strixhaven's colleges: Lorehold, Prismari. Quandrix, Silverquill, or Witherbloom. You learn two cantrips and one 1st-level spell based on the college you choose, as specified in the Strixhaven Spells table.\n\nYou can cast the chosen 1st-level spell without a spell slot, and you must finish a long rest before you can cast it in this way again. You can also cast the spell using any spell slots you have.\n\nYour spellcasting ability for this feat's spells is Intelligence, Wisdom, or Charisma (choose when you select this feat).\n\n| Strixhaven Spells |\n\n| College | Cantrips | 1st-Level Spell |\n\n| Lorehold | Choose two from Light, Sacred Flame, and Thaumaturgy. | Choose one 1st-level Cleric or Wizard spell. |\n\n| Prismari | Choose two from Fire Bolt, Prestidigitation, and Ray of Frost. | Choose one 1st-level Bard or Sorcerer spell. |\n\n| Quandrix | Choose two from Druidcraft, Guidance, and Mage Hand. | Choose one 1st-level Druid or Wizard spell. |\n\n| Silverquill | Choose two from Sacred Flame, Thaumaturgy, and Vicious Mockery. | Choose one 1st-level Bard or Cleric spell. |\n\n| Witherbloom | Choose two from Chill Touch, Druidcraft, and Spare the Dying. | Choose one 1st-level Druid or Wizard spell. |",
  "Manifestando la magia ilusoria y la niebla de los gigantes de las nubes, puedes desvanecerte en el aire cuando eres atacado y escapar sin dejar rastro.": "You’ve manifested the confounding magic emblematic of cloud giants, granting you the following benefits:",
  "Nivel 4, Dote Golpe de los Gigantes (Golpe de las Nubes)": "4th Level, Strike of the Giants (Cloud Strike) Feat",
  "Aumenta tu puntuación de Fuerza, Constitución o Carisma en +1 (hasta un máximo de 20).": "**Ability Score Increase.** Increase your Strength, Constitution, or Wisdom score by 1, to a maximum of 20.",
  "Escape Nuboso (Misty Flee): Cuando recibes daño de un ataque, puedes usar tu reacción para volverte invisible mágicamente y teletransportarte hasta 30 pies a un espacio desocupado que puedas ver. La invisibilidad dura hasta el inicio de tu siguiente turno o hasta que hagas un ataque o lances un conjuro. Puedes usar este rasgo un número de veces igual a tu PB por descanso largo.": "**Cloudy Escape.** When a creature you can see hits you with an attack roll, you can use your reaction to give yourself resistance to that attack’s damage. You then teleport to an unoccupied space that you can see within 30 feet of yourself. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.",
  "Has adoptado la resistencia glacial del invierno eterno de los gigantes de escarcha, castigando a quienes se atreven a golpearte congelando sus articulaciones.": "You’ve manifested the icy might emblematic of frost giants, granting you the following benefits:",
  "Nivel 4, Dote Golpe de los Gigantes (Golpe de Escarcha)": "4th Level, Strike of the Giants (Frost Strike) Feat",
  "Aumenta tu puntuación de Fuerza, Constitución o Sabiduría en +1 (hasta un máximo de 20).": "**Ability Score Increase.** Increase your Strength, Constitution, or Wisdom score by 1, to a maximum of 20.",
  "Hijo del Frío: Ganas resistencia al daño de frío.": "**Born of Ice.** You have resistance to cold damage.",
  "Represalia Frígida: Cuando una criatura a 30 pies o menos te inflige daño, puedes usar tu reacción para obligarla a hacer una salvación de Constitución (CD 8 + PB + mod elegido). Si falla, recibe 1d8 + tu PB de daño de frío y su velocidad se reduce a 0 hasta el inicio de su siguiente turno. Puedes usarlo PB veces por descanso largo.": "**Frigid Retaliation.** Immediately after a creature you can see within 30 feet of you hits you with an attack roll and deals damage, you can use your reaction to retaliate with a conjured blast of ice. The creature must make a Constitution saving throw (DC equals 8 + your proficiency bonus + the modifier of the ability increased by this feat). On a failed save, the creature takes cold damage equal to 1d8 + your proficiency bonus, and its speed is reduced to 0 until the end of its next turn. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.",
  "Imbuido de la fuerza descomunal y la voracidad inquebrantable de los gigantes de las colinas, tu cuerpo se vuelve una masa inconmovible de resistencia física.": "You’ve manifested the resilience emblematic of hill giants, granting you the following benefits:",
  "Nivel 4, Dote Golpe de los Gigantes (Golpe de la Colina)": "4th Level, Strike of the Giants (Hill Strike) Feat",
  "Inamovible como la Colina: Si un efecto te derribaría o te movería contra tu voluntad a lo largo del suelo, puedes usar tu reacción para no ser movido ni derribado.": "**Bulwark.** When you are subjected to an effect that would move you at least 5 feet or give you the prone condition, you can use your reaction to steady yourself. You aren’t moved and don’t have the prone condition.",
  "Vitalidad Colosal: Siempre que recuperes puntos de golpe usando uno o más dados de golpe (por ejemplo en un descanso corto), añades tu bonificador de competencia a la cantidad de PG recuperados por cada dado de golpe gastado.": "**Iron Stomach.** Whenever you eat food as part of a short rest and spend one or more Hit Dice to regain hit points, you regain additional hit points equal to your Constitution modifier + your proficiency bonus.",
  "El calor del magma y las forjas volcánicas arden en tus venas, permitiéndote resistir las llamas más intensas y cegar a tus enemigos con estallidos de brasas incandescentes.": "You’ve manifested the fiery combat emblematic of fire giants, granting you the following benefits:",
  "Nivel 4, Dote Golpe de los Gigantes (Golpe de Fuego)": "4th Level, Strike of the Giants (Fire Strike) Feat",
  "Nacido del Fuego: Ganas resistencia al daño de fuego.": "**Born of Flame.** You have resistance to fire damage.",
  "Ignición Abrasadora: Como acción adicional, desatas una lluvia de brasas en un radio de 15 pies centrado en ti. Cada criatura a tu elección en esa área debe hacer una salvación de Destreza (CD 8 + PB + mod elegido): si falla, sufre 1d8 + PB de daño de fuego y queda cegada hasta el inicio de tu siguiente turno; si tiene éxito, sufre la mitad del daño y no queda cegada (PB veces por descanso largo).": "**Searing Ignition.** When you take the Attack action on your turn, you can replace a single attack with a magical burst of flame. Each creature of your choice in a 15-foot-radius sphere centered on you must make a Dexterity saving throw (DC equals 8 + your proficiency bonus + the modifier of the ability increased by this feat). On a failed save, a creature takes fire damage equal to 1d8 + your proficiency bonus, and it has the blinded condition until the start of your next turn. On a successful save, the creature takes half as much damage only. You can use your Searing Ignition a number of times equal to your proficiency bonus (but no more than once per turn), and you regain all expended uses when you finish a long rest.",
  "Heredas la visión pétrea y la puntería infalible de los gigantes de piedra, convirtiendo cualquier roca en un proyectil devastador de fuerza elemental.": "You’ve manifested the physical talents emblematic of stone giants, granting you the following benefits:",
  "Nivel 4, Dote Golpe de los Gigantes (Golpe de Piedra)": "4th Level, Strike of the Giants (Stone Strike) Feat",
  "Visión en la Oscuridad a 60 pies (o añade 60 pies adicionales si ya la tenías).": "**Cavernous Sight.** You gain darkvision with a range of 60 feet. If you already have darkvision from another source, its range increases by 60 feet.",
  "Lanzamiento de Roca: Como acción adicional, tomas una piedra o escombro pequeño e imbuyes de magia tu lanzamiento. Haces un ataque de arma a distancia (alcance 60 pies) que inflige 1d10 + mod Fuerza de daño de fuerza. Si el objetivo es de tamaño Grande o menor, debe superar una salvación de Fuerza o caerá derribado (PB veces por descanso largo).": "**Stone Throw.** As a bonus action, you can take a rock and make a magical attack with it. The attack is a ranged spell attack with a range of 60 feet that uses the ability score you increased with this feat as the spellcasting ability. On a hit, the rock deals 1d10 force damage, and the target must succeed on a Strength saving throw (DC equals 8 + your proficiency bonus + the spellcasting ability modifier) or have the prone condition. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.",
  "Canalizas los vientos huracanados y los truenos de los gigantes de la tormenta, creando un vórtice a tu alrededor que desvía proyectiles y frena el avance enemigo.": "You’ve manifested the tempest magic emblematic of storm giants, granting you the following benefits:",
  "Nivel 4, Dote Golpe de los Gigantes (Golpe de la Tormenta)": "4th Level, Strike of the Giants (Storm Strike) Feat",
  "Posees una mano firme y una puntería prodigiosa con armas de fuego, permitiéndote disparar y recargar a quemarropa con velocidad sobrehumana.": "You have a quick hand and keen eye when employing firearms, granting you the following benefits:",
  "Aumenta tu puntuación de Destreza en +1 (hasta un máximo de 20).": "Increase your Dexterity score by 1, to a maximum of 20.",
  "Ganas competencia con armas de fuego.": "You gain proficiency with firearms (see “Firearms” in the *Dungeon Master’s Guide*).",
  "Ignoras la propiedad de recarga (loading) de las armas de fuego.": "You ignore the loading property of firearms.",
  "Estar a 5 pies de una criatura hostil no impone desventaja en tus tiradas de ataque a distancia.": "Being within 5 feet of a hostile creature doesn't impose disadvantage on your ranged attack rolls.",
  "Has manifestado la esencia elemental despiadada de los dragones cromáticos (rojo, azul, verde, negro, blanco) para imbuir tus armas y resistir sus alientos.": "You’ve manifested some of the power of chromatic dragons, granting you the following benefits:",
  "Infusión Cromática: Como acción adicional tocas un arma sencilla o marcial. Durante 1 minuto, esa arma inflige 1d4 de daño adicional del tipo elegido (ácido, frío, fuego, relámpago o veneno) en cada impacto (1/descanso largo).": "**Chromatic Infusion.** As a bonus action, you can touch a simple or martial weapon and infuse it with one of the following damage types: acid, cold, fire, lightning, or poison. For the next minute, the weapon deals an extra 1d4 damage of the chosen type when it hits. After you use this bonus action, you can’t do so again until you finish a long rest.",
  "Resistencia Reactiva: Cuando recibes daño de ácido, frío, fuego, relámpago o veneno, puedes usar tu reacción para ganar resistencia contra esa instancia de daño (PB veces por descanso largo).": "**Reactive Resistance.** When you take acid, cold, fire, lightning, or poison damage, you can use your reaction to give yourself resistance to that instance of damage. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.",
  "Bendecido con la nobleza y compasión de los dragones metálicos (oro, plata, bronce, cobre, latón), puedes proteger a tus aliados con alas espectrales y curar heridas.": "You’ve manifested some of the power of metallic dragons, granting you the following benefits:",
  "Sanación Dracónica: Aprendes el conjuro Curar Heridas (Cure Wounds) y puedes lanzarlo una vez por descanso largo sin gastar ranura de conjuro (o usando tus ranuras normales). Característica de conjuro: Int, Sab o Car.": "**Draconic Healing.** You learn the Cure Wounds spell. You can cast this spell without expending a spell slot. Once you cast this spell in this way, you can’t do so again until you finish a long rest. You can also cast this spell using spell slots you have. The spell’s spellcasting ability is Intelligence, Wisdom, or Charisma when you cast it with this feat (choose when you gain the feat).",
  "Alas Protectoras: Como reacción cuando tú o una criatura a 5 pies sois impactados por un ataque, manifiestas un par de alas espectrales que suman tu bonificador de competencia a la CA contra ese ataque (PB veces por descanso largo).": "**Protective Wings.** You can manifest protective wings that can shield you or others. When you or another creature you can see within 5 feet of you is hit by an attack roll, you can use your reaction to manifest spectral wings from your back for a moment. You grant a bonus to the target’s AC equal to your proficiency bonus against that attack roll, potentially causing it to miss. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.",
  "Imbuido de la mente psiónica de los dragones gema (amatista, esmeralda, zafiro, topacio, cristal), puedes repeler violentamente a quienes se atrevan a golpearte.": "You’ve manifested some of the power of gem dragons, granting you the following benefits:",
  "Aumenta tu puntuación de Inteligencia, Sabiduría o Carisma en +1 (hasta un máximo de 20).": "**Ability Score Increase.** Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20.",
  "Repulsión Telequinética: Cuando recibes daño de una criatura a 10 pies de ti, puedes usar tu reacción para liberar una onda psiónica. El atacante debe superar una tirada de salvación de Fuerza (CD 8 + PB + mod elegido) o sufrirá 2d8 de daño de fuerza y será empujado 10 pies en línea recta lejos de ti (PB veces por descanso largo).": "**Telekinetic Reprisal.** When you take damage from a creature that is within 10 feet of you, you can use your reaction to emanate telekinetic energy. The creature that dealt damage to you must make a Strength saving throw (DC equals 8 + your proficiency bonus + the ability modifier of the score increased by this feat). On a failed save, the creature takes 2d8 force damage and is pushed up to 10 feet away from you. On a successful save, the creature takes half as much damage and isn’t pushed. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.",
  "Eres un jinete consumado que domina el campo de batalla a lomos de tu montura, usando tu altura y velocidad para superar a cualquier rival a pie.": "You are a dangerous foe to face while mounted. While you are mounted and aren't incapacitated, you gain the following benefits:",
  "Tienes ventaja en tiradas de ataque cuerpo a cuerpo contra cualquier criatura no montada que sea de tamaño inferior a tu montura.": "You have advantage on melee attack rolls against any unmounted creature that is smaller than your mount.",
  "Puedes obligar a que cualquier ataque dirigido a tu montura te tome a ti como objetivo en su lugar.": "You can force an attack targeted at your mount to target you instead.",
  "Si tu montura sufre un efecto que permite una tirada de salvación de Destreza para recibir la mitad del daño, no recibe daño si supera la salvación y solo la mitad si falla.": "If your mount is subjected to an effect that allows it to make Dexterity saving throw to take only half damage, it instead takes no damage if it succeeds on the saving throw, and only half damage if it fails.",
  "Te arrojas contra el enemigo a una velocidad aterradora, transformando el impulso de tu carrera en una fuerza demoledora que aplasta o derriba.": "When you use your action to Dash, you can use a bonus action to make one melee weapon attack or to shove a creature. If you move at least 10 feet in a straight line immediately before taking this bonus action, you either gain a +5 bonus to the attack’s damage roll (if you chose to make a melee attack and hit) or push the target up to 10 feet away from you (if you chose to shove and you succeed).",
};

