export function translateWeaponOrItemName(name: string): string {
  if (!name) return '';
  const trimmed = name.trim();
  if (WEAPON_AND_ARMOR_NAMES_EN[trimmed]) return WEAPON_AND_ARMOR_NAMES_EN[trimmed];
  if (DIRECT_TITLE_MAP_EN[trimmed]) return DIRECT_TITLE_MAP_EN[trimmed];
  const parenMatch = trimmed.match(/^.+?\(([^)]+)\)$/);
  if (parenMatch && !/[áéíóúñ]/i.test(parenMatch[1])) {
    return parenMatch[1].trim();
  }
  return translateDndTitle(trimmed);
}

export function translateWeaponProperty(prop: string): string {
  if (!prop) return '';
  const trimmed = prop.trim();
  return trimmed
    .replace(/^Sutil$/i, 'Finesse')
    .replace(/^Ligera$/i, 'Light')
    .replace(/^Pesada$/i, 'Heavy')
    .replace(/^A dos manos$/i, 'Two-Handed')
    .replace(/^Carga$/i, 'Loading')
    .replace(/^Recarga$/i, 'Reload')
    .replace(/^Especial$/i, 'Special')
    .replace(/^Alcance(?:\s*\(([^)]+)\))?$/i, (_, r) => (r ? `Reach (${r.replace(/pies/gi, 'ft.')})` : 'Reach'))
    .replace(/^Arrojadiza(?:\s*\(([^)]+)\))?$/i, (_, r) => (r ? `Thrown (${r.replace(/pies/gi, 'ft.')})` : 'Thrown'))
    .replace(/^Versátil(?:\s*\(([^)]+)\))?$/i, (_, r) => (r ? `Versatile (${r})` : 'Versatile'))
    .replace(/^Munición(?:\s*\(([^)]+)\))?$/i, (_, r) => (r ? `Ammunition (${r.replace(/pies/gi, 'ft.')})` : 'Ammunition'))
    .replace(/Cuerpo a cuerpo/gi, 'Melee')
    .replace(/A distancia/gi, 'Ranged')
    .replace(/pies/gi, 'ft.');
}

export function translateDamageType(dmg: string): string {
  if (!dmg) return '';
  return dmg
    .replace(/Perforante/gi, 'Piercing')
    .replace(/Cortante/gi, 'Slashing')
    .replace(/Contundente/gi, 'Bludgeoning')
    .replace(/Radiante/gi, 'Radiant')
    .replace(/Necrótico/gi, 'Necrotic')
    .replace(/Fuego/gi, 'Fire')
    .replace(/Frío/gi, 'Cold')
    .replace(/Relámpago/gi, 'Lightning')
    .replace(/Trueno/gi, 'Thunder')
    .replace(/Ácido/gi, 'Acid')
    .replace(/Veneno/gi, 'Poison')
    .replace(/Psíquico/gi, 'Psychic')
    .replace(/Fuerza/gi, 'Force');
}

export function translateDndText(text: string): string {
  if (!text) return '';
  const trimmed = text.trim();
  if (EXACT_DESCRIPTION_MAP_EN[trimmed]) return EXACT_DESCRIPTION_MAP_EN[trimmed];
  if (DIRECT_TITLE_MAP_EN[trimmed]) return DIRECT_TITLE_MAP_EN[trimmed];
  let out = text;
  for (const [pattern, replacement] of DND_PHRASE_REPLACEMENTS) {
    if (typeof pattern === 'string') {
      out = out.replaceAll(pattern, replacement);
    } else {
      out = out.replace(pattern, replacement);
    }
  }
  return out;
}

