export function translateLanguageList(langs: string[]): string {
  if (!langs || langs.length === 0) return 'Common and 1 additional language';
  return langs
    .map((l) => LANGUAGE_NAMES_EN[l] || translateDndText(l))
    .join(', ');
}

// Spell metadata translators
export const SPELL_SCHOOL_MAP_EN: Record<string, string> = {
  'Abjuración': 'Abjuration',
  'Conjuración': 'Conjuration',
  'Adivinación': 'Divination',
  'Encantamiento': 'Enchantment',
  'Evocación': 'Evocation',
  'Ilusión': 'Illusion',
  'Nigromancia': 'Necromancy',
  'Transmutación': 'Transmutation',
};

export function translateSpellSchool(school: string): string {
  if (!school) return '';
  for (const [es, en] of Object.entries(SPELL_SCHOOL_MAP_EN)) {
    if (school.toLowerCase().includes(es.toLowerCase())) return en;
  }
  return school;
}

export function translateSpellMeta(val: string): string {
  if (!val) return '';
  return val
    .replace(/1 acción adicional/gi, '1 Bonus Action')
    .replace(/1 acción/gi, '1 Action')
    .replace(/1 reacción/gi, '1 Reaction')
    .replace(/1 minuto/gi, '1 Minute')
    .replace(/10 minutos/gi, '10 Minutes')
    .replace(/1 hora/gi, '1 Hour')
    .replace(/8 horas/gi, '8 Hours')
    .replace(/24 horas/gi, '24 Hours')
    .replace(/Personal/gi, 'Self')
    .replace(/Toque/gi, 'Touch')
    .replace(/Ilimitado/gi, 'Unlimited')
    .replace(/Vista/gi, 'Sight')
    .replace(/Especial/gi, 'Special')
    .replace(/Instantánea/gi, 'Instantaneous')
    .replace(/Instantáneo/gi, 'Instantaneous')
    .replace(/Concentración, hasta/gi, 'Concentration, up to')
    .replace(/Hasta ser disipado/gi, 'Until dispelled')
    .replace(/pies/gi, 'ft.')
    .replace(/millas/gi, 'miles')
    .replace(/milla/gi, 'mile')
    .replace(/radio/gi, 'radius')
    .replace(/cono/gi, 'cone')
    .replace(/cubo/gi, 'cube')
    .replace(/esfera/gi, 'sphere')
    .replace(/línea/gi, 'line')
    .replace(/minutos/gi, 'minutes')
    .replace(/minuto/gi, 'minute')
    .replace(/horas/gi, 'hours')
    .replace(/hora/gi, 'hour')
    .replace(/asaltos/gi, 'rounds')
    .replace(/asalto/gi, 'round')
    .replace(/días/gi, 'days')
    .replace(/día/gi, 'day');
}

