export function translateCharacterClassName(className: string): string {
  if (!className) return 'No Class';
  if (CHARACTER_CLASS_MAP_EN[className]) return CHARACTER_CLASS_MAP_EN[className];
  // Handle "Mago (Wizard)" -> "Wizard"
  const parenMatch = className.match(/^.+?\(([^)]+)\)$/);
  if (parenMatch && !parenMatch[1].toLowerCase().includes('homebrew')) {
    return parenMatch[1].trim();
  }
  return translateDndTitle(className);
}

