export function translateCharacterRaceName(raceName: string): string {
  if (!raceName) return 'Unknown Species';
  if (CHARACTER_RACE_MAP_EN[raceName]) return CHARACTER_RACE_MAP_EN[raceName];
  let out = raceName;
  for (const [es, en] of Object.entries(CHARACTER_RACE_MAP_EN)) {
    out = out.replaceAll(es, en);
  }
  return translateDndTitle(out);
}

export function translateCharacterBackgroundName(bgName: string): string {
  if (!bgName) return 'Adventurer';
  if (DIRECT_TITLE_MAP_EN[bgName]) return DIRECT_TITLE_MAP_EN[bgName];
  return translateDndTitle(bgName);
}

