  "Al finalizar un descanso largo, has consultado las fórmulas arcanas inscritas en tu grimorio. Puedes sustituir 1 truco de mago que conozcas por otro truco de la lista de conjuros de mago.": "Whenever you finish a long rest, you can consult the arcane formulas inscribed in your spellbook to replace one wizard cantrip you know with another cantrip from the wizard spell list.",
