  "[Nivel 3] Fórmulas de Trucos (Cantrip Formulas - Opcional): Inscritas en el libro de conjuros. Permite reemplazar 1 truco tras cada descanso largo.": "[Level 3] Cantrip Formulas (Optional): Inscribed in your spellbook. Allows replacing 1 cantrip after each long rest.",
  "[Nivel 20] Campeón Primitivo (Primal Champion): +4 a Fuerza y +4 a Constitución (máximo aumentado a 24). Usos de Furia ilimitados.": "[Level 20] Primal Champion: +4 to Strength and +4 to Constitution (maximum increased to 24). Unlimited Rages.",
  "Reglas Oficiales D&D 5e: continúa en tu clase o desbloquea una nueva clase multiclase.": "Official D&D 5e Rules: continue in your current class or unlock a new multiclass.",
  "selecciona cuál sube +1 nivel": "select which class gains +1 level",
