  "Requisitos oficiales de multiclase (PHB p. 163):": "Official multiclassing prerequisites (PHB p. 163):",
  "* Nota: Según las reglas oficiales necesitas 13+ en las características clave. Si tu DM lo permite excepcionalmente en su mesa, puedes continuar.": "* Note: Official rules require a score of 13+ in the key abilities. If your DM makes a house-rule exception at your table, you may proceed.",
