export function localizeString(str: string, isSpanish: boolean): string {
  if (isSpanish || !str) return str;
  const match = str.match(/^(\s*)([\s\S]*?)(\s*)$/);
  if (!match) return str;
  const [, leading, core, trailing] = match;
  if (!core) return str;

  const normCore = core.replace(/\s+/g, ' ');

  if (SHEET_UI_EXACT_MAP_EN[core]) {
    return `${leading}${SHEET_UI_EXACT_MAP_EN[core]}${trailing}`;
  }
  if (SHEET_UI_EXACT_MAP_EN[normCore]) {
    return `${leading}${SHEET_UI_EXACT_MAP_EN[normCore]}${trailing}`;
  }
  if (DIRECT_TITLE_MAP_EN[core]) {
    return `${leading}${DIRECT_TITLE_MAP_EN[core]}${trailing}`;
  }
  if (DIRECT_TITLE_MAP_EN[normCore]) {
    return `${leading}${DIRECT_TITLE_MAP_EN[normCore]}${trailing}`;
  }
  if (EXACT_DESCRIPTION_MAP_EN[core]) {
    return `${leading}${EXACT_DESCRIPTION_MAP_EN[core]}${trailing}`;
  }
  if (EXACT_DESCRIPTION_MAP_EN[normCore]) {
    return `${leading}${EXACT_DESCRIPTION_MAP_EN[normCore]}${trailing}`;
  }
  if (WEAPON_AND_ARMOR_NAMES_EN[core]) {
    return `${leading}${WEAPON_AND_ARMOR_NAMES_EN[core]}${trailing}`;
  }
  if (SKILL_NAMES_EN[core]) {
    return `${leading}${SKILL_NAMES_EN[core]}${trailing}`;
  }

  let out = normCore;
  for (const [pattern, replacement] of SHEET_PHRASE_REPLACEMENTS_EN) {
    if (typeof pattern === 'string') {
      out = out.replaceAll(pattern, replacement);
    } else {
      out = out.replace(pattern, replacement);
    }
  }
  out = translateDndText(out);
  return `${leading}${out}${trailing}`;
}

export function localizeReactNode(node: React.ReactNode, isSpanish: boolean): React.ReactNode {
  if (isSpanish || node == null || typeof node === 'boolean' || typeof node === 'number') {
    return node;
  }
  if (typeof node === 'string') {
    return localizeString(node, false);
  }
  if (Array.isArray(node)) {
    // Coalesce consecutive string/number primitives (skipping null/undefined/boolean) so JSX expressions like
    // "Recuperación Arcana ({maxRecovery} niveles)" are localized as a single complete phrase.
    const coalesced: React.ReactNode[] = [];
    let textBuffer = '';
    let hasText = false;

    const flushBuffer = () => {
      if (hasText) {
        coalesced.push(localizeString(textBuffer, false));
        textBuffer = '';
        hasText = false;
      }
    };

    for (const child of node) {
      if (child == null || typeof child === 'boolean') {
        continue;
      }
      if (typeof child === 'string' || typeof child === 'number') {
        textBuffer += String(child);
        hasText = true;
      } else {
        flushBuffer();
        const localized = localizeReactNode(child, false);
        if (React.isValidElement(localized) && localized.key == null) {
          coalesced.push(React.cloneElement(localized, { key: coalesced.length }));
        } else {
          coalesced.push(localized);
        }
      }
    }
    flushBuffer();

    if (coalesced.length === 1 && typeof coalesced[0] === 'string') {
      return coalesced[0];
    }
    return coalesced;
  }
  if (React.isValidElement(node)) {
    const props = node.props as Record<string, any>;
    const nextProps: Record<string, any> = {};
    let changed = false;

    for (const propKey of ['title', 'placeholder', 'subtitle', 'label', 'alt']) {
      if (typeof props[propKey] === 'string') {
        const locVal = localizeString(props[propKey], false);
        if (locVal !== props[propKey]) {
          nextProps[propKey] = locVal;
          changed = true;
        }
      }
    }

    if (props.children !== undefined) {
      const locChildren = localizeReactNode(props.children, false);
      if (locChildren !== props.children) {
        return React.cloneElement(node, nextProps, locChildren);
      }
    }

    if (changed) {
      return React.cloneElement(node, nextProps);
    }
  }
  return node;
}
